window.WORDS = [{"id":1,"topic":"env","w":"pollution","ipa":"/pəˈluːʃn/","pos":"n.","cn":"污染","pun":"泼露身","story":"脏水「泼」到「露」出来的「身」上，这就是污染。","ex":"Air pollution has become a serious problem in many large cities.","exCn":"空气污染在许多大城市已成为严重问题。","col":["air / water pollution","reduce pollution","a major source of pollution"]},{"id":2,"topic":"env","w":"sustainable","ipa":"/səˈsteɪnəbl/","pos":"adj.","cn":"可持续的","pun":"撒得能播","story":"「撒」下的种子明年还「能播」，年年有收成，就是可持续。","ex":"Governments should invest in sustainable energy sources such as wind and solar power.","exCn":"政府应投资风能、太阳能等可持续能源。","col":["sustainable development","sustainable energy","environmentally sustainable"]},{"id":3,"topic":"env","w":"deforestation","ipa":"/diːˌfɒrɪˈsteɪʃn/","pos":"n.","cn":"森林砍伐","pun":"弟把森林砍得省","story":"de- 表示「去掉」，forest 是森林：把森林去掉 = 砍伐森林。记成「弟」（de）把 forest 砍了想「省」（-tion）钱。","ex":"Deforestation is one of the main causes of climate change.","exCn":"森林砍伐是气候变化的主要原因之一。","col":["large-scale deforestation","combat deforestation","deforestation in the Amazon"]},{"id":4,"topic":"env","w":"emission","ipa":"/ɪˈmɪʃn/","pos":"n.","cn":"排放（物）","pun":"一米深","story":"工厂烟囱冒出「一米深」的黑烟，那就是排放。","ex":"Countries have agreed to cut carbon emissions by 40% before 2030.","exCn":"各国同意在 2030 年前减少 40% 的碳排放。","col":["carbon emissions","greenhouse gas emissions","cut / reduce emissions"]},{"id":5,"topic":"env","w":"renewable","ipa":"/rɪˈnjuːəbl/","pos":"adj.","cn":"可再生的","pun":"日纽阿宝","story":"re（再）+ new（新）+ able（能）= 能再变新。太阳「日」「纽」约每天升起，永远用不完。","ex":"Renewable energy now accounts for a growing share of electricity production.","exCn":"可再生能源在发电中的占比正在增长。","col":["renewable energy / resources","switch to renewables"]},{"id":6,"topic":"env","w":"conserve","ipa":"/kənˈsɜːv/","pos":"v.","cn":"保护；节约（资源）","pun":"啃瑟夫","story":"宁可「啃」干粮、冻得「瑟瑟」发抖，也要把暖气关了节约能源。","ex":"We must conserve water during the dry season.","exCn":"旱季我们必须节约用水。","col":["conserve energy / water","conserve natural resources","conservation (n.)"]},{"id":7,"topic":"env","w":"ecosystem","ipa":"/ˈiːkəʊsɪstəm/","pos":"n.","cn":"生态系统","pun":"一口系统","story":"大鱼「一口」吃小鱼，小鱼一口吃虾米，这一口口吃出来的「系统」就是生态系统。","ex":"Plastic waste is destroying marine ecosystems.","exCn":"塑料垃圾正在破坏海洋生态系统。","col":["fragile ecosystem","marine ecosystem","damage the ecosystem"]},{"id":8,"topic":"env","w":"drought","ipa":"/draʊt/","pos":"n.","cn":"干旱","pun":"抓土","story":"干旱的时候地里没水，一伸手只能「抓」到干「土」。","ex":"The region has suffered from severe drought for three consecutive years.","exCn":"该地区已连续三年遭受严重干旱。","col":["severe / prolonged drought","drought-stricken areas"]},{"id":9,"topic":"env","w":"contaminate","ipa":"/kənˈtæmɪneɪt/","pos":"v.","cn":"污染；弄脏","pun":"啃它米内特","story":"「啃」了「它」的「米」，「内」脏「特」别难受——米被污染了。","ex":"Chemical waste from the factory has contaminated the river.","exCn":"工厂的化学废料污染了这条河。","col":["contaminated water / food","contamination (n.)"]},{"id":10,"topic":"env","w":"habitat","ipa":"/ˈhæbɪtæt/","pos":"n.","cn":"栖息地","pun":"哈比它","story":"「哈比」人住的那个特别的地方，就是「它」的栖息地。","ex":"Urban expansion is destroying the natural habitat of many species.","exCn":"城市扩张正在破坏许多物种的自然栖息地。","col":["natural habitat","habitat loss / destruction","wildlife habitat"]},{"id":11,"topic":"env","w":"climate","ipa":"/ˈklaɪmət/","pos":"n.","cn":"气候","pun":"克赖美特","story":"「克赖美特」是个气象员，每天克制着不抱怨，专门记录一个地方长年的气候。","ex":"Scientists warn that the global climate is changing faster than previously predicted.","exCn":"科学家警告，全球气候的变化速度比先前预测的更快。","col":["climate change","climate crisis","climatic"]},{"id":12,"topic":"env","w":"greenhouse","ipa":"/ˈɡriːnhaʊs/","pos":"n.","cn":"温室","pun":"格林好死","story":"green（绿）+ house（房子）：绿色的玻璃房子把热量捂在里面，「格林好死」热，这就是温室效应。","ex":"Greenhouse gases trap heat in the atmosphere and cause global temperatures to rise.","exCn":"温室气体把热量困在大气中，导致全球气温上升。","col":["greenhouse gas","greenhouse effect","greenhouse emissions"]},{"id":13,"topic":"env","w":"carbon","ipa":"/ˈkɑːbən/","pos":"n.","cn":"碳","pun":"卡本","story":"烧煤时黑烟「卡」在「本」子上，全是黑色的碳。","ex":"Many countries have pledged to reduce their carbon output by 2050.","exCn":"许多国家承诺到2050年减少碳排放量。","col":["carbon dioxide","carbon footprint","low-carbon"]},{"id":14,"topic":"env","w":"footprint","ipa":"/ˈfʊtprɪnt/","pos":"n.","cn":"足迹；碳足迹","pun":"福特扑印","story":"foot（脚）+ print（印）：开着福特车扑通一路留下的黑印子，就是你的碳足迹。","ex":"Individuals can shrink their carbon footprint by flying less and eating less meat.","exCn":"个人可以通过少乘飞机、少吃肉来减少碳足迹。","col":["carbon footprint","ecological footprint","reduce one's footprint"]},{"id":15,"topic":"env","w":"fossil","ipa":"/ˈfɒsl/","pos":"n.","cn":"化石","pun":"佛手","story":"挖出一只「佛手」形状的石头，原来是几亿年前的化石。","ex":"Burning fossil fuels remains the largest single source of greenhouse gases.","exCn":"燃烧化石燃料仍是温室气体最大的单一来源。","col":["fossil fuel","fossil record","fossilised"]},{"id":16,"topic":"env","w":"fuel","ipa":"/ˈfjuːəl/","pos":"n./v.","cn":"燃料；加剧","pun":"飞油","story":"飞机的油叫「飞油」，就是燃料；油越多火越旺，所以也能表示「加剧」。","ex":"Cheap fuel has fuelled the growth of private car ownership in developing countries.","exCn":"廉价燃料助长了发展中国家私家车拥有量的增长。","col":["fuel consumption","fossil fuel","fuel-efficient"]},{"id":17,"topic":"env","w":"solar","ipa":"/ˈsəʊlə(r)/","pos":"adj.","cn":"太阳的；太阳能的","pun":"扫啦","story":"太阳一出来，云都被「扫啦」，屋顶的太阳能板开始发电。","ex":"Solar panels have become far cheaper, making solar power competitive with coal.","exCn":"太阳能板已大幅降价，使太阳能发电与煤电具有竞争力。","col":["solar power","solar panel","solar energy"]},{"id":18,"topic":"env","w":"turbine","ipa":"/ˈtɜːbaɪn/","pos":"n.","cn":"涡轮机；风力机","pun":"特拜","story":"风来了，风车「特」别快地转，人们「拜」它发电，这就是风力涡轮机。","ex":"Offshore wind turbines can generate electricity for thousands of homes.","exCn":"海上风力涡轮机可以为数千户家庭发电。","col":["wind turbine","gas turbine","turbine blade"]},{"id":19,"topic":"env","w":"hydroelectric","ipa":"/ˌhaɪdrəʊɪˈlektrɪk/","pos":"adj.","cn":"水力发电的","pun":"害捉一来电","story":"hydro（水）+ electric（电）：水一「来」就「电」，害得鱼被捉——水力发电。","ex":"Large hydroelectric dams provide clean power but can displace local communities.","exCn":"大型水电站提供清洁电力，但可能使当地居民搬迁。","col":["hydroelectric power","hydroelectric dam","hydropower"]},{"id":20,"topic":"env","w":"nuclear","ipa":"/ˈnjuːkliə(r)/","pos":"adj.","cn":"核的；核能的","pun":"牛可裂","story":"「牛可裂」——原子核像牛一样有劲，一裂开就释放核能。","ex":"Nuclear power produces little carbon but raises concerns about radioactive waste.","exCn":"核能几乎不产生碳，但引发对放射性废料的担忧。","col":["nuclear power","nuclear plant","nuclear waste"]},{"id":21,"topic":"env","w":"geothermal","ipa":"/ˌdʒiːəʊˈθɜːml/","pos":"adj.","cn":"地热的","pun":"就欧瑟摸","story":"geo（地）+ thermal（热）：「就欧洲人瑟瑟地摸」地面，发现地下是热的——地热能。","ex":"Iceland heats most of its homes with geothermal energy from beneath the ground.","exCn":"冰岛大部分家庭用来自地下的地热能取暖。","col":["geothermal energy","geothermal power","geothermal heating"]},{"id":22,"topic":"env","w":"biomass","ipa":"/ˈbaɪəʊmæs/","pos":"n.","cn":"生物质；生物燃料","pun":"拜欧妈死","story":"bio（生物）+ mass（质量）：把「欧妈」家死掉的秸秆、木屑烧掉发电，这就是生物质能。","ex":"Biomass such as crop waste can be burned to generate electricity.","exCn":"农作物废料等生物质可以燃烧发电。","col":["biomass energy","biomass fuel","biofuel"]},{"id":23,"topic":"env","w":"combustion","ipa":"/kəmˈbʌstʃən/","pos":"n.","cn":"燃烧","pun":"肯爆声","story":"「肯爆声」——只要肯点火，就会有爆的声音，这就是燃烧。","ex":"The combustion of coal releases sulphur dioxide and other harmful gases.","exCn":"煤的燃烧会释放二氧化硫和其他有害气体。","col":["combustion engine","internal combustion","combustible"]},{"id":24,"topic":"env","w":"exhaust","ipa":"/ɪɡˈzɔːst/","pos":"n./v.","cn":"尾气；耗尽","pun":"一个咒死","story":"汽车尾气像「一个咒」，咒得人喘不过气，也把资源都耗尽了。","ex":"Vehicle exhaust is a major contributor to poor air quality in large cities.","exCn":"汽车尾气是大城市空气质量差的主要原因之一。","col":["exhaust fumes","exhaust pipe","exhaust natural resources"]},{"id":25,"topic":"env","w":"smog","ipa":"/smɒɡ/","pos":"n.","cn":"烟雾；雾霾","pun":"死抹哥","story":"smoke（烟）+ fog（雾）：雾霾像被「死抹」在天上的一层灰，怎么擦也擦不掉。","ex":"Thick smog forced schools in the capital to close for several days.","exCn":"浓重的雾霾迫使首都的学校停课数日。","col":["heavy smog","smog alert","photochemical smog"]},{"id":26,"topic":"env","w":"ozone","ipa":"/ˈəʊzəʊn/","pos":"n.","cn":"臭氧","pun":"欧宗","story":"「欧宗」是地球的宗族长老，站在高空替大家挡紫外线——臭氧层。","ex":"The hole in the ozone layer has begun to shrink since harmful chemicals were banned.","exCn":"自有害化学品被禁以来，臭氧层空洞已开始缩小。","col":["ozone layer","ozone depletion","ozone hole"]},{"id":27,"topic":"env","w":"atmosphere","ipa":"/ˈætməsfɪə(r)/","pos":"n.","cn":"大气层；气氛","pun":"艾特摸死飞儿","story":"「艾特」一只飞鸟，它摸着天空往上飞，飞到大气层顶就飞不动了。","ex":"Carbon dioxide can remain in the atmosphere for hundreds of years.","exCn":"二氧化碳可以在大气中停留数百年。","col":["upper atmosphere","atmospheric","release into the atmosphere"]},{"id":28,"topic":"env","w":"glacier","ipa":"/ˈɡlæsiə(r)/","pos":"n.","cn":"冰川","pun":"格拉西儿","story":"「格拉西儿」是个北方姑娘，家门口那条慢慢流动的大冰河，就是冰川。","ex":"Glaciers in the Himalayas are retreating at an alarming rate.","exCn":"喜马拉雅山的冰川正以惊人的速度消退。","col":["melting glacier","glacier retreat","glacial"]},{"id":29,"topic":"env","w":"thaw","ipa":"/θɔː/","pos":"v./n.","cn":"融化；解冻","pun":"嗦","story":"天暖了，冰块「嗦」的一下化成水——解冻。","ex":"As permafrost begins to thaw, it releases methane trapped for thousands of years.","exCn":"永久冻土开始融化时，会释放封存了数千年的甲烷。","col":["begin to thaw","spring thaw","thaw out"]},{"id":30,"topic":"env","w":"heatwave","ipa":"/ˈhiːtweɪv/","pos":"n.","cn":"热浪","pun":"嘿特喂","story":"heat（热）+ wave（浪）：一波热浪扑来，人热得直喊「嘿，特别热，喂！」","ex":"Heatwaves are expected to become longer and more frequent as the planet warms.","exCn":"随着地球变暖，热浪预计会持续更久、更加频繁。","col":["severe heatwave","during a heatwave","heatwave warning"]},{"id":31,"topic":"env","w":"flood","ipa":"/flʌd/","pos":"n./v.","cn":"洪水；淹没","pun":"弗拉的","story":"大水「弗拉」一声冲进村子，整条街都被洪水淹了。","ex":"Coastal cities face a growing risk of flooding as sea levels rise.","exCn":"随着海平面上升，沿海城市面临越来越大的洪水风险。","col":["flash flood","flood defences","flood-prone"]},{"id":32,"topic":"env","w":"hurricane","ipa":"/ˈhʌrɪkən/","pos":"n.","cn":"飓风","pun":"哈瑞肯","story":"「哈瑞肯」是个大力士，一吹气屋顶全飞，这就是大西洋上的飓风。","ex":"Warmer oceans provide more energy for hurricanes, making them more destructive.","exCn":"更温暖的海洋为飓风提供更多能量，使其更具破坏性。","col":["hurricane season","category five hurricane","hit by a hurricane"]},{"id":33,"topic":"env","w":"typhoon","ipa":"/taɪˈfuːn/","pos":"n.","cn":"台风","pun":"台风","story":"这个词本来就从中文「台风」借去的，读起来几乎一样，太平洋西部的大风暴。","ex":"The typhoon caused widespread damage to crops and infrastructure across the region.","exCn":"台风对该地区的农作物和基础设施造成了大范围破坏。","col":["typhoon warning","powerful typhoon","struck by a typhoon"]},{"id":34,"topic":"env","w":"tornado","ipa":"/tɔːˈneɪdəʊ/","pos":"n.","cn":"龙卷风","pun":"拖内兜","story":"龙卷风一来，连衣服「内兜」里的东西都被「拖」上了天。","ex":"Tornadoes can form within minutes and destroy entire neighbourhoods.","exCn":"龙卷风可以在几分钟内形成并摧毁整个街区。","col":["tornado warning","tornado alley","hit by a tornado"]},{"id":35,"topic":"env","w":"earthquake","ipa":"/ˈɜːθkweɪk/","pos":"n.","cn":"地震","pun":"饿死快克","story":"earth（地）+ quake（震）：地一震，「饿死」的人赶紧「快克」服困难逃出去。","ex":"Buildings in earthquake zones must be designed to withstand strong tremors.","exCn":"地震带上的建筑必须设计成能承受强烈震动。","col":["powerful earthquake","earthquake-resistant","earthquake strikes"]},{"id":36,"topic":"env","w":"tsunami","ipa":"/tsuːˈnɑːmi/","pos":"n.","cn":"海啸","pun":"粗那米","story":"海啸卷来的浪又「粗」又高，「那」股水把稻米全冲走了。","ex":"An early warning system could have saved thousands of lives when the tsunami struck.","exCn":"海啸来袭时，一套预警系统本可以挽救数千人的生命。","col":["tsunami warning","devastating tsunami","tsunami waves"]},{"id":37,"topic":"env","w":"wildfire","ipa":"/ˈwaɪldfaɪə(r)/","pos":"n.","cn":"野火；山火","pun":"歪的发儿","story":"wild（野）+ fire（火）：风一「歪」，火就「发」到了整座山——山火。","ex":"Prolonged dry weather has increased the frequency of wildfires in Australia.","exCn":"长期干燥天气增加了澳大利亚野火的发生频率。","col":["spread like wildfire","wildfire season","devastating wildfire"]},{"id":38,"topic":"env","w":"eruption","ipa":"/ɪˈrʌpʃn/","pos":"n.","cn":"火山喷发；爆发","pun":"一拉扑深","story":"e（出）+ rupt（破）：火山口一「拉」开，岩浆「扑」向深处的村庄——喷发。","ex":"The volcanic eruption sent a cloud of ash several kilometres into the sky.","exCn":"火山喷发把火山灰云送上了数公里高空。","col":["volcanic eruption","erupt","major eruption"]},{"id":39,"topic":"env","w":"landslide","ipa":"/ˈlændslaɪd/","pos":"n.","cn":"山体滑坡","pun":"烂的死赖的","story":"land（土地）+ slide（滑）：大雨把山泡「烂」了，土「死赖」着往下滑——滑坡。","ex":"Heavy rainfall triggered a landslide that buried the mountain road.","exCn":"暴雨引发山体滑坡，掩埋了山路。","col":["trigger a landslide","landslide risk","mudslide"]},{"id":40,"topic":"env","w":"famine","ipa":"/ˈfæmɪn/","pos":"n.","cn":"饥荒","pun":"翻民","story":"地里颗粒无收，「翻民」们翻遍田地也找不到吃的——饥荒。","ex":"Crop failures caused by extreme weather can lead to famine in vulnerable regions.","exCn":"极端天气导致的歉收可能在脆弱地区引发饥荒。","col":["famine relief","widespread famine","famine-stricken"]},{"id":41,"topic":"env","w":"erosion","ipa":"/ɪˈrəʊʒn/","pos":"n.","cn":"侵蚀；水土流失","pun":"一柔准","story":"水「一」点点「柔」柔地冲，「准」把岩石磨没——侵蚀。","ex":"Removing trees leaves hillsides exposed to soil erosion.","exCn":"砍掉树木会让山坡暴露在水土流失之下。","col":["soil erosion","coastal erosion","erode"]},{"id":42,"topic":"env","w":"desertification","ipa":"/dɪˌzɜːtɪfɪˈkeɪʃn/","pos":"n.","cn":"沙漠化","pun":"地泽提飞开身","story":"desert（沙漠）+ -ification（变成）：「地」上的「泽」水提前飞开了，土地就变成沙漠。","ex":"Overgrazing and deforestation are accelerating desertification in northern Africa.","exCn":"过度放牧和毁林正在加速北非的沙漠化。","col":["combat desertification","desertification process","turn to desert"]},{"id":43,"topic":"env","w":"degradation","ipa":"/ˌdeɡrəˈdeɪʃn/","pos":"n.","cn":"退化；恶化","pun":"得个呆身","story":"de（向下）+ grade（等级）：土地越来越差，「得个呆」板的身子——环境退化。","ex":"Environmental degradation threatens the livelihoods of millions of farmers.","exCn":"环境退化威胁着数百万农民的生计。","col":["environmental degradation","land degradation","degrade"]},{"id":44,"topic":"env","w":"depletion","ipa":"/dɪˈpliːʃn/","pos":"n.","cn":"耗尽；枯竭","pun":"地劈里深","story":"de（去掉）+ plete（满）：把「地」劈到里面很深，资源全被掏空——枯竭。","ex":"The depletion of fish stocks has forced many fishermen to abandon the trade.","exCn":"鱼类资源的枯竭迫使许多渔民放弃这一行业。","col":["resource depletion","ozone depletion","deplete"]},{"id":45,"topic":"env","w":"precipitation","ipa":"/prɪˌsɪpɪˈteɪʃn/","pos":"n.","cn":"降水","pun":"扑西批太深","story":"雨往「西」边「扑」，一「批」雨下得太深，这就是降水量。","ex":"Changes in precipitation patterns will affect crop yields across Asia.","exCn":"降水模式的变化将影响整个亚洲的作物产量。","col":["annual precipitation","heavy precipitation","precipitation levels"]},{"id":46,"topic":"env","w":"humidity","ipa":"/hjuːˈmɪdəti/","pos":"n.","cn":"湿度","pun":"休米的踢","story":"梅雨天「休米」家的墙都在滴水，湿度太高了。","ex":"High humidity combined with heat makes tropical cities increasingly uncomfortable.","exCn":"高湿度加上高温使热带城市越来越令人不适。","col":["high humidity","relative humidity","humid"]},{"id":47,"topic":"env","w":"monsoon","ipa":"/mɒnˈsuːn/","pos":"n.","cn":"季风；雨季","pun":"闷孙","story":"「闷孙」在雨季天天闷在家里，因为季风带来的雨下个不停。","ex":"A weak monsoon can devastate agriculture in South Asia.","exCn":"季风减弱可能重创南亚农业。","col":["monsoon season","monsoon rains","monsoon flooding"]},{"id":48,"topic":"env","w":"evaporate","ipa":"/ɪˈvæpəreɪt/","pos":"v.","cn":"蒸发","pun":"一挖破锐特","story":"e（出）+ vapor（蒸汽）：锅盖「一挖」破，水汽「锐」利地冲出来——蒸发。","ex":"As temperatures rise, more water evaporates from lakes and reservoirs.","exCn":"随着气温上升，更多水从湖泊和水库蒸发。","col":["evaporate quickly","evaporation","water evaporates"]},{"id":49,"topic":"env","w":"arid","ipa":"/ˈærɪd/","pos":"adj.","cn":"干旱的","pun":"啊热的","story":"「啊，热的！」——地面烫脚，一滴水也没有，干旱的土地。","ex":"Arid regions are likely to receive even less rainfall in the coming decades.","exCn":"干旱地区在未来几十年可能降雨更少。","col":["arid land","arid climate","semi-arid"]},{"id":50,"topic":"env","w":"barren","ipa":"/ˈbærən/","pos":"adj.","cn":"贫瘠的；不毛的","pun":"白人","story":"地「白」得像没「人」种过一样，寸草不生——贫瘠的。","ex":"Years of intensive farming have left the soil barren and unproductive.","exCn":"多年的集约化耕作使土壤变得贫瘠且无法生产。","col":["barren land","barren landscape","become barren"]},{"id":51,"topic":"env","w":"fertile","ipa":"/ˈfɜːtaɪl/","pos":"adj.","cn":"肥沃的","pun":"服它哦","story":"这块地种啥长啥，农民都「服它哦」——肥沃的土地。","ex":"River deltas are among the most fertile farmland in the world.","exCn":"河流三角洲是世界上最肥沃的农田之一。","col":["fertile soil","fertile land","fertility"]},{"id":52,"topic":"env","w":"lush","ipa":"/lʌʃ/","pos":"adj.","cn":"茂盛的；葱郁的","pun":"拉屎","story":"牛在草地上「拉屎」施肥，草长得又绿又茂盛。","ex":"The lush vegetation of the rainforest supports countless species.","exCn":"雨林葱郁的植被养育着无数物种。","col":["lush vegetation","lush green","lush forest"]},{"id":53,"topic":"env","w":"recycle","ipa":"/ˌriːˈsaɪkl/","pos":"v.","cn":"回收利用","pun":"瑞塞口","story":"re（再）+ cycle（循环）：小「瑞」把空瓶「塞」进回收「口」，让它再循环一次。","ex":"Only a small proportion of plastic waste is actually recycled in most countries.","exCn":"在大多数国家，实际被回收的塑料垃圾只占很小比例。","col":["recycle waste","recycling scheme","recyclable"]},{"id":54,"topic":"env","w":"landfill","ipa":"/ˈlændfɪl/","pos":"n.","cn":"垃圾填埋场","pun":"烂的肥哦","story":"land（地）+ fill（填）：把地填满「烂的」垃圾，臭得像「肥」料——填埋场。","ex":"Sending waste to landfill produces methane, a powerful greenhouse gas.","exCn":"把垃圾送去填埋会产生甲烷，一种强效温室气体。","col":["landfill site","send to landfill","landfill tax"]},{"id":55,"topic":"env","w":"disposable","ipa":"/dɪˈspəʊzəbl/","pos":"adj.","cn":"一次性的","pun":"地死抛的宝","story":"「地死抛的宝」——用完就往地上抛的东西，一次性的。","ex":"Disposable cups and cutlery account for a large share of urban waste.","exCn":"一次性杯子和餐具占城市垃圾的很大比例。","col":["disposable products","disposable packaging","single-use"]},{"id":56,"topic":"env","w":"dispose","ipa":"/dɪˈspəʊz/","pos":"v.","cn":"处理；丢弃","pun":"地死抛死","story":"dis（分开）+ pose（放）：把垃圾从家里「抛」出去，分开放好——处理掉。","ex":"Households must dispose of batteries separately because they contain heavy metals.","exCn":"家庭必须单独处理电池，因为它们含有重金属。","col":["dispose of","waste disposal","disposal site"]},{"id":57,"topic":"env","w":"biodegradable","ipa":"/ˌbaɪəʊdɪˈɡreɪdəbl/","pos":"adj.","cn":"可生物降解的","pun":"拜欧地格瑞的宝","story":"bio（生物）+ degrade（分解）：「欧」家的塑料袋埋在地里，被微生物慢慢分解——可降解。","ex":"Supermarkets are switching to biodegradable bags made from corn starch.","exCn":"超市正在改用玉米淀粉制成的可降解袋子。","col":["biodegradable packaging","biodegradable plastic","non-biodegradable"]},{"id":58,"topic":"env","w":"compost","ipa":"/ˈkɒmpɒst/","pos":"n./v.","cn":"堆肥","pun":"抗剖死特","story":"厨余「抗」在院子里，剖开发酵到「死」，就变成了「特」好的堆肥。","ex":"Food scraps can be turned into compost instead of being sent to landfill.","exCn":"食物残渣可以变成堆肥，而不是被送去填埋。","col":["compost heap","compost food waste","composting"]},{"id":59,"topic":"env","w":"packaging","ipa":"/ˈpækɪdʒɪŋ/","pos":"n.","cn":"包装","pun":"拍开进","story":"「拍开」层层盒子才能「进」到东西——过度包装。","ex":"Excessive packaging is one of the main reasons household waste keeps growing.","exCn":"过度包装是家庭垃圾不断增加的主要原因之一。","col":["plastic packaging","excessive packaging","packaging waste"]},{"id":60,"topic":"env","w":"litter","ipa":"/ˈlɪtə(r)/","pos":"n./v.","cn":"垃圾；乱扔","pun":"里特","story":"公园「里」「特」别多的纸屑瓶子，都是游客乱扔的垃圾。","ex":"Fines for dropping litter have helped keep the city streets clean.","exCn":"对乱扔垃圾的罚款帮助保持了城市街道的清洁。","col":["drop litter","litter bin","littering"]},{"id":61,"topic":"env","w":"sewage","ipa":"/ˈsuːɪdʒ/","pos":"n.","cn":"污水；下水道污物","pun":"苏一只","story":"「苏」州河里漂来「一只」拖鞋，全是下水道排出的污水。","ex":"Untreated sewage is still discharged directly into rivers in many cities.","exCn":"许多城市仍将未经处理的污水直接排入河流。","col":["sewage treatment","raw sewage","sewage system"]},{"id":62,"topic":"env","w":"toxic","ipa":"/ˈtɒksɪk/","pos":"adj.","cn":"有毒的","pun":"套克西克","story":"「套克西克」——戴着毒气面罩的克西克大叔，专门清理有毒垃圾。","ex":"Toxic chemicals from the factory leaked into the local water supply.","exCn":"工厂的有毒化学物质泄漏进了当地供水系统。","col":["toxic waste","toxic fumes","toxicity"]},{"id":63,"topic":"env","w":"hazardous","ipa":"/ˈhæzədəs/","pos":"adj.","cn":"危险的；有害的","pun":"害则得死","story":"hazard（危险）+ -ous：碰了它就「害」，则「得死」——有害物质。","ex":"Hazardous waste must be stored and transported under strict regulations.","exCn":"危险废物必须在严格规定下储存和运输。","col":["hazardous waste","hazardous materials","hazard"]},{"id":64,"topic":"env","w":"discard","ipa":"/dɪˈskɑːd/","pos":"v.","cn":"丢弃","pun":"地死卡的","story":"dis（去掉）+ card（卡片）：把没用的卡片往「地」上一扔——丢弃。","ex":"Millions of tonnes of discarded fishing nets pollute the oceans every year.","exCn":"每年有数百万吨被丢弃的渔网污染海洋。","col":["discard waste","discarded plastic","throw away"]},{"id":65,"topic":"env","w":"scrap","ipa":"/skræp/","pos":"n./v.","cn":"废料；废弃","pun":"死刮破","story":"铁皮被「刮」得「破」烂，只能当废料卖掉。","ex":"Scrap metal from old vehicles can be melted down and reused.","exCn":"旧车的废金属可以熔化后再利用。","col":["scrap metal","scrap yard","scrap a plan"]},{"id":66,"topic":"env","w":"incinerate","ipa":"/ɪnˈsɪnəreɪt/","pos":"v.","cn":"焚烧","pun":"因心呢锐特","story":"in（进）+ ciner（灰）：垃圾扔进炉子，「因」为火太「锐」，全烧成了灰。","ex":"Some cities incinerate waste to generate electricity rather than burying it.","exCn":"一些城市焚烧垃圾来发电，而不是将其填埋。","col":["incinerate waste","incinerator","incineration plant"]},{"id":67,"topic":"env","w":"dump","ipa":"/dʌmp/","pos":"v./n.","cn":"倾倒；垃圾场","pun":"当扑","story":"卡车「当」的一声把垃圾「扑」倒在地——倾倒。","ex":"Illegal dumping of industrial waste has poisoned the local soil.","exCn":"非法倾倒工业废料毒害了当地土壤。","col":["dump waste","rubbish dump","illegal dumping"]},{"id":68,"topic":"env","w":"debris","ipa":"/ˈdebriː/","pos":"n.","cn":"碎片；残骸","pun":"呆不理","story":"台风过后满地碎片，人们「呆」在那儿「不理」——一堆残骸。","ex":"Plastic debris has been found in the stomachs of seabirds thousands of miles from land.","exCn":"在离陆地数千英里的海鸟胃里发现了塑料碎片。","col":["plastic debris","marine debris","clear debris"]},{"id":69,"topic":"env","w":"pesticide","ipa":"/ˈpestɪsaɪd/","pos":"n.","cn":"杀虫剂；农药","pun":"拍死它塞的","story":"pest（害虫）+ -cide（杀）：害虫「拍死它」，再「塞」一瓶药——农药。","ex":"Heavy use of pesticides has been linked to the decline of bee populations.","exCn":"农药的大量使用与蜜蜂数量减少有关。","col":["pesticide use","chemical pesticide","pesticide residue"]},{"id":70,"topic":"env","w":"fertiliser","ipa":"/ˈfɜːtəlaɪzə(r)/","pos":"n.","cn":"化肥","pun":"服它来泽","story":"fertile（肥沃）+ -iser：撒一把化肥，庄稼「服它」，田地「来」了「泽」——肥沃了。","ex":"Chemical fertilisers washed into rivers cause algae to grow uncontrollably.","exCn":"冲入河流的化肥导致藻类失控生长。","col":["chemical fertiliser","organic fertiliser","fertilise"]},{"id":71,"topic":"env","w":"residue","ipa":"/ˈrezɪdjuː/","pos":"n.","cn":"残留物","pun":"热渍丢","story":"锅烧「热」后留下一圈「渍」，怎么也「丢」不掉——残留物。","ex":"Tests found pesticide residue on more than half of the fruit samples.","exCn":"检测发现超过一半的水果样本有农药残留。","col":["pesticide residue","chemical residue","residual"]},{"id":72,"topic":"env","w":"leak","ipa":"/liːk/","pos":"v./n.","cn":"泄漏","pun":"漓渴","story":"水管「漓」漓地漏，人却「渴」得没水喝——泄漏。","ex":"A leak in the pipeline released thousands of litres of oil into the river.","exCn":"管道泄漏使数千升石油流入河中。","col":["gas leak","leak into","leakage"]},{"id":73,"topic":"env","w":"spill","ipa":"/spɪl/","pos":"n./v.","cn":"溢出；泄漏","pun":"死劈儿","story":"油桶被「死劈」了一道口子，黑油哗哗溢出来——漏油。","ex":"The oil spill killed thousands of seabirds and devastated the coastal fishing industry.","exCn":"漏油事件杀死了数千只海鸟，重创了沿海渔业。","col":["oil spill","chemical spill","spill over"]},{"id":74,"topic":"env","w":"radiation","ipa":"/ˌreɪdiˈeɪʃn/","pos":"n.","cn":"辐射","pun":"瑞迪爱神","story":"「瑞迪」爱上了核电站的「神」，结果全身都是辐射。","ex":"Areas near the damaged reactor remain contaminated by radiation decades later.","exCn":"受损反应堆附近的区域几十年后仍受辐射污染。","col":["nuclear radiation","radiation exposure","radioactive"]},{"id":75,"topic":"env","w":"acidic","ipa":"/əˈsɪdɪk/","pos":"adj.","cn":"酸性的","pun":"额西滴克","story":"「额西滴克」——额头滴了一滴酸雨，克得皮肤发疼，酸性的。","ex":"Oceans are becoming more acidic as they absorb carbon dioxide from the air.","exCn":"海洋吸收空气中的二氧化碳后正变得更加酸性。","col":["acidic water","acid rain","acidification"]},{"id":76,"topic":"env","w":"purify","ipa":"/ˈpjʊərɪfaɪ/","pos":"v.","cn":"净化","pun":"飘瑞发","story":"pure（纯净）+ -ify（使）：脏水经过过滤，「飘」着的「瑞」气都「发」出来了——净化。","ex":"Simple filters can purify river water enough for drinking in rural areas.","exCn":"简单的过滤器可以把农村河水净化到能喝的程度。","col":["purify water","water purification","purifier"]},{"id":77,"topic":"env","w":"filter","ipa":"/ˈfɪltə(r)/","pos":"n./v.","cn":"过滤器；过滤","pun":"费儿特","story":"「费儿特」——滤网费了特别大劲，把脏东西全拦住了。","ex":"Factories are required to filter emissions before releasing them into the air.","exCn":"工厂被要求在排放前过滤废气。","col":["water filter","filter out","filtration"]},{"id":78,"topic":"env","w":"irrigation","ipa":"/ˌɪrɪˈɡeɪʃn/","pos":"n.","cn":"灌溉","pun":"一粒给深","story":"给每「一粒」种子都「给深」水，这就是灌溉。","ex":"Inefficient irrigation wastes huge amounts of water in agricultural regions.","exCn":"低效的灌溉在农业地区浪费了大量水资源。","col":["irrigation system","drip irrigation","irrigate"]},{"id":79,"topic":"env","w":"reservoir","ipa":"/ˈrezəvwɑː(r)/","pos":"n.","cn":"水库","pun":"热泽娃","story":"「热」天里「泽」水被存进大池子，「娃」们都去边上乘凉——水库。","ex":"The reservoir supplying the city has dropped to a third of its normal level.","exCn":"供应该市的水库水位已降到正常水平的三分之一。","col":["water reservoir","build a reservoir","reservoir levels"]},{"id":80,"topic":"env","w":"scarcity","ipa":"/ˈskeəsəti/","pos":"n.","cn":"稀缺；短缺","pun":"死开死踢","story":"scarce（稀少）+ -ity：为了抢一桶水，人们「死开」打、「死踢」——水资源稀缺。","ex":"Water scarcity already affects more than two billion people worldwide.","exCn":"水资源短缺已影响全球二十多亿人。","col":["water scarcity","scarcity of resources","scarce"]},{"id":81,"topic":"env","w":"shortage","ipa":"/ˈʃɔːtɪdʒ/","pos":"n.","cn":"短缺","pun":"少踢只","story":"short（短、少）+ -age：粮食「少」得连一「只」鸡都得省着吃——短缺。","ex":"Prolonged dry seasons have caused severe food shortages in the region.","exCn":"漫长的旱季在该地区造成了严重的粮食短缺。","col":["water shortage","food shortage","energy shortage"]},{"id":82,"topic":"env","w":"consumption","ipa":"/kənˈsʌmpʃn/","pos":"n.","cn":"消耗；消费","pun":"肯桑深","story":"consume（消耗）+ -tion：「肯」这么用电，「桑」树都被砍得很「深」——过度消耗。","ex":"Reducing energy consumption is the cheapest way to cut carbon output.","exCn":"减少能源消耗是削减碳排放最便宜的方式。","col":["energy consumption","consumption of resources","consume"]},{"id":83,"topic":"env","w":"extraction","ipa":"/ɪkˈstrækʃn/","pos":"n.","cn":"开采；提取","pun":"一克死拽克深","story":"ex（出）+ tract（拉）：把矿「死拽」出地面很「深」的地方——开采。","ex":"Oil extraction in the Arctic poses serious risks to fragile environments.","exCn":"北极的石油开采对脆弱环境构成严重风险。","col":["resource extraction","oil extraction","extract"]},{"id":84,"topic":"env","w":"mining","ipa":"/ˈmaɪnɪŋ/","pos":"n.","cn":"采矿","pun":"卖宁","story":"矿工「卖」命挖矿，换来一点安「宁」——采矿业。","ex":"Open-pit mining leaves huge scars on the landscape that take decades to heal.","exCn":"露天采矿在地表留下需要数十年才能恢复的巨大伤疤。","col":["coal mining","mining industry","mine"]},{"id":85,"topic":"env","w":"quarry","ipa":"/ˈkwɒri/","pos":"n.","cn":"采石场","pun":"扩瑞","story":"「扩瑞」——为了扩建，瑞哥把整座山炸成了采石场。","ex":"Abandoned quarries can be turned into lakes and nature reserves.","exCn":"废弃采石场可以改造成湖泊和自然保护区。","col":["stone quarry","quarry site","quarrying"]},{"id":86,"topic":"env","w":"timber","ipa":"/ˈtɪmbə(r)/","pos":"n.","cn":"木材","pun":"停吧","story":"伐木工喊「停吧」，可树已经倒下，变成了一根根木材。","ex":"Demand for cheap timber drives illegal logging in tropical forests.","exCn":"对廉价木材的需求推动了热带森林的非法采伐。","col":["timber industry","timber production","illegal timber"]},{"id":87,"topic":"env","w":"logging","ipa":"/ˈlɒɡɪŋ/","pos":"n.","cn":"伐木","pun":"劳给","story":"log（原木）：「劳」工把树砍成原木「给」老板——伐木。","ex":"Illegal logging destroys thousands of hectares of rainforest each year.","exCn":"非法伐木每年毁掉数千公顷雨林。","col":["illegal logging","logging company","logging ban"]},{"id":88,"topic":"env","w":"groundwater","ipa":"/ˈɡraʊndwɔːtə(r)/","pos":"n.","cn":"地下水","pun":"哥让的沃特","story":"ground（地面）+ water（水）：藏在地面下面的「沃特」，就是地下水。","ex":"Farmers are pumping groundwater faster than rain can replace it.","exCn":"农民抽取地下水的速度快于雨水补充的速度。","col":["groundwater levels","groundwater contamination","groundwater supply"]},{"id":89,"topic":"env","w":"aquifer","ipa":"/ˈækwɪfə(r)/","pos":"n.","cn":"含水层","pun":"艾克为佛","story":"aqua（水）：「艾克」为了取水，像佛一样耐心往下挖，终于挖到含水层。","ex":"The aquifer beneath the plains has been dangerously depleted by irrigation.","exCn":"平原下方的含水层已因灌溉而危险地枯竭。","col":["underground aquifer","aquifer depletion","recharge an aquifer"]},{"id":90,"topic":"env","w":"sediment","ipa":"/ˈsedɪmənt/","pos":"n.","cn":"沉积物；泥沙","pun":"塞地们特","story":"泥沙「塞」在河「地」上，「们」多得「特」别厚——沉积物。","ex":"Dams trap sediment that would otherwise replenish the river delta.","exCn":"水坝拦截了本可补充河口三角洲的泥沙。","col":["river sediment","sediment build-up","sedimentary"]},{"id":91,"topic":"env","w":"topsoil","ipa":"/ˈtɒpsɔɪl/","pos":"n.","cn":"表土","pun":"塌破扫油","story":"top（顶）+ soil（土）：最上面那层「油」润的土被大风一「扫」全「塌破」了——表土流失。","ex":"Intensive farming strips away topsoil faster than nature can rebuild it.","exCn":"集约化农业剥去表土的速度快于自然重建的速度。","col":["loss of topsoil","fertile topsoil","topsoil erosion"]},{"id":92,"topic":"env","w":"nutrient","ipa":"/ˈnjuːtriənt/","pos":"n.","cn":"养分；营养物","pun":"牛吹恩特","story":"「牛吹」牛说它的粪便「恩」情特别大，给土壤带来了养分。","ex":"Repeated harvesting removes nutrients from the soil unless they are replaced.","exCn":"反复收割会带走土壤养分，除非加以补充。","col":["soil nutrients","essential nutrients","nutrient-rich"]},{"id":93,"topic":"env","w":"microplastic","ipa":"/ˌmaɪkrəʊˈplæstɪk/","pos":"n.","cn":"微塑料","pun":"麦克抛普拉斯提克","story":"micro（微小）+ plastic（塑料）：「麦克」抛的塑料袋碎成小颗粒，被鱼吃进肚子——微塑料。","ex":"Microplastics have been detected in drinking water, salt and even human blood.","exCn":"饮用水、食盐甚至人体血液中都检测到了微塑料。","col":["microplastic pollution","microplastic particles","microplastics in the ocean"]},{"id":94,"topic":"env","w":"single-use","ipa":"/ˌsɪŋɡl ˈjuːs/","pos":"adj.","cn":"一次性使用的","pun":"星狗又死","story":"single（单）+ use（用）：「星狗」用一次就扔，东西又「死」了——一次性的。","ex":"Several countries have banned single-use plastic bags and straws.","exCn":"多个国家已禁止一次性塑料袋和吸管。","col":["single-use plastic","single-use items","ban single-use"]},{"id":95,"topic":"env","w":"biodiversity","ipa":"/ˌbaɪəʊdaɪˈvɜːsəti/","pos":"n.","cn":"生物多样性","pun":"拜欧带我洗地","story":"bio（生物）+ diversity（多样）：「拜欧」带我去洗地，地上蹦出上百种虫子——生物多样性。","ex":"Protecting biodiversity is essential for maintaining healthy food chains.","exCn":"保护生物多样性对维持健康的食物链至关重要。","col":["loss of biodiversity","biodiversity hotspot","rich in biodiversity"]},{"id":96,"topic":"env","w":"species","ipa":"/ˈspiːʃiːz/","pos":"n.","cn":"物种","pun":"死逼洗死","story":"「死逼洗死」——生物学家逼着每个物种都洗干净再分类。","ex":"Around one million species are at risk of extinction within decades.","exCn":"约一百万个物种面临在几十年内灭绝的风险。","col":["endangered species","rare species","species diversity"]},{"id":97,"topic":"env","w":"endangered","ipa":"/ɪnˈdeɪndʒəd/","pos":"adj.","cn":"濒危的","pun":"因丹皂的","story":"en（使）+ danger（危险）：「因」为「丹皂」水太脏，鱼都快死光了——濒危的。","ex":"The giant panda was removed from the endangered list after decades of protection.","exCn":"经过数十年的保护，大熊猫已从濒危名单上移除。","col":["endangered species","critically endangered","endanger"]},{"id":98,"topic":"env","w":"extinct","ipa":"/ɪkˈstɪŋkt/","pos":"adj.","cn":"灭绝的","pun":"一颗死听克","story":"ex（出）+ stinct（刺）：最后「一颗」恐龙蛋死了，只能「听」故事——灭绝的。","ex":"Several species of frog have become extinct since the 1980s.","exCn":"自二十世纪八十年代以来，多种青蛙已经灭绝。","col":["become extinct","extinct species","go extinct"]},{"id":99,"topic":"env","w":"extinction","ipa":"/ɪkˈstɪŋkʃn/","pos":"n.","cn":"灭绝","pun":"一颗死听克深","story":"extinct + -ion：物种「一颗」颗死去，故事「听」得很「深」——灭绝。","ex":"Habitat loss is the leading cause of extinction among mammals.","exCn":"栖息地丧失是哺乳动物灭绝的主要原因。","col":["mass extinction","face extinction","on the brink of extinction"]},{"id":100,"topic":"env","w":"poaching","ipa":"/ˈpəʊtʃɪŋ/","pos":"n.","cn":"偷猎","pun":"剖亲","story":"偷猎者「剖」开大象的「亲」人取象牙——偷猎。","ex":"Poaching for ivory has cut the African elephant population by a third.","exCn":"为获取象牙的偷猎使非洲象数量减少了三分之一。","col":["illegal poaching","poacher","poach"]},{"id":101,"topic":"env","w":"sanctuary","ipa":"/ˈsæŋktʃuəri/","pos":"n.","cn":"保护区；避难所","pun":"三克丘瑞","story":"「三克」重的小鸟飞到「丘」上的「瑞」园，谁也不能抓它——保护区。","ex":"The wildlife sanctuary provides a safe home for injured and orphaned animals.","exCn":"野生动物保护区为受伤和失去父母的动物提供安全的家。","col":["wildlife sanctuary","bird sanctuary","seek sanctuary"]},{"id":102,"topic":"env","w":"reserve","ipa":"/rɪˈzɜːv/","pos":"n./v.","cn":"保护区；储备","pun":"日热无","story":"re（回）+ serve（保留）：「日」子再「热」也「无」人打扰，那片地留给动物——自然保护区。","ex":"The government has created a marine reserve covering thousands of square kilometres.","exCn":"政府设立了一个覆盖数千平方公里的海洋保护区。","col":["nature reserve","oil reserves","reserve land"]},{"id":103,"topic":"env","w":"wildlife","ipa":"/ˈwaɪldlaɪf/","pos":"n.","cn":"野生动植物","pun":"歪的赖夫","story":"wild（野）+ life（生命）：树「歪」了，「赖」在上面的「夫」妇是两只野猫——野生动物。","ex":"Urban expansion is pushing wildlife out of its natural surroundings.","exCn":"城市扩张正把野生动物赶出其自然环境。","col":["wildlife protection","wildlife trade","native wildlife"]},{"id":104,"topic":"env","w":"predator","ipa":"/ˈpredətə(r)/","pos":"n.","cn":"捕食者","pun":"扑来的它","story":"「扑来的它」——扑过来的那只狮子，就是捕食者。","ex":"Removing top predators such as wolves can upset the entire food chain.","exCn":"移除狼等顶级捕食者可能打乱整个食物链。","col":["natural predator","top predator","predatory"]},{"id":105,"topic":"env","w":"prey","ipa":"/preɪ/","pos":"n./v.","cn":"猎物；捕食","pun":"扑累","story":"狮子「扑」得太「累」，猎物跑掉了。","ex":"As their prey disappears, snow leopards are forced to attack livestock.","exCn":"随着猎物消失，雪豹被迫攻击牲畜。","col":["prey on","fall prey to","predator and prey"]},{"id":106,"topic":"env","w":"migration","ipa":"/maɪˈɡreɪʃn/","pos":"n.","cn":"迁徙","pun":"买个雷神","story":"候鸟「买个雷神」当向导，一起飞去南方——迁徙。","ex":"Climate change is disrupting the migration patterns of birds and whales.","exCn":"气候变化正在扰乱鸟类和鲸鱼的迁徙模式。","col":["bird migration","migration route","migrate"]},{"id":107,"topic":"env","w":"breed","ipa":"/briːd/","pos":"v./n.","cn":"繁殖；品种","pun":"不理的","story":"动物园里两只熊猫「不理」饲养员，只顾着谈恋爱——繁殖。","ex":"Zoos breed endangered animals in captivity before releasing them into the wild.","exCn":"动物园在圈养环境中繁殖濒危动物，然后放归野外。","col":["breed in captivity","breeding season","breeding programme"]},{"id":108,"topic":"env","w":"captivity","ipa":"/kæpˈtɪvəti/","pos":"n.","cn":"圈养；囚禁","pun":"开普踢我踢","story":"cap（抓）：「开普」被关在笼子里，天天踢栏杆——圈养状态。","ex":"Animals born in captivity often struggle to survive when released.","exCn":"圈养出生的动物被放归后往往难以生存。","col":["in captivity","bred in captivity","captive"]},{"id":109,"topic":"env","w":"flora","ipa":"/ˈflɔːrə/","pos":"n.","cn":"植物群","pun":"弗洛拉","story":"「弗洛拉」是花神，她管的全是植物——植物群。","ex":"The island is home to unique flora found nowhere else on Earth.","exCn":"这座岛屿拥有地球上其他地方没有的独特植物群。","col":["flora and fauna","native flora","local flora"]},{"id":110,"topic":"env","w":"fauna","ipa":"/ˈfɔːnə/","pos":"n.","cn":"动物群","pun":"佛呐","story":"「佛呐」——佛陀身边围着一群动物听经，就是动物群。","ex":"Introduced species pose a serious threat to the native fauna of Australia.","exCn":"引入物种对澳大利亚本土动物群构成严重威胁。","col":["flora and fauna","marine fauna","native fauna"]},{"id":111,"topic":"env","w":"vegetation","ipa":"/ˌvedʒəˈteɪʃn/","pos":"n.","cn":"植被","pun":"喂几台深","story":"「喂几台」割草机都割不完，草长得太「深」——茂密的植被。","ex":"Dense vegetation along riverbanks helps prevent soil from washing away.","exCn":"河岸的茂密植被有助于防止土壤被冲走。","col":["dense vegetation","natural vegetation","vegetation cover"]},{"id":112,"topic":"env","w":"wetland","ipa":"/ˈwetlənd/","pos":"n.","cn":"湿地","pun":"喂特烂的","story":"wet（湿）+ land（地）：这块地湿得「特烂」，却是候鸟的天堂——湿地。","ex":"Wetlands act as natural sponges, absorbing floodwater and filtering pollutants.","exCn":"湿地像天然海绵一样吸收洪水、过滤污染物。","col":["coastal wetland","wetland conservation","drain wetlands"]},{"id":113,"topic":"env","w":"marsh","ipa":"/mɑːʃ/","pos":"n.","cn":"沼泽","pun":"马湿","story":"「马湿」——马一走进去腿就湿了，全是泥水——沼泽。","ex":"Many marshes have been drained to create farmland and housing.","exCn":"许多沼泽已被排干以开辟农田和住房。","col":["salt marsh","marshland","marshy"]},{"id":114,"topic":"env","w":"reef","ipa":"/riːf/","pos":"n.","cn":"珊瑚礁；暗礁","pun":"利夫","story":"「利夫」潜水时被珊瑚礁划破了腿——礁石很锋利。","ex":"Rising sea temperatures are bleaching coral reefs around the world.","exCn":"海水温度上升正使全球珊瑚礁白化。","col":["coral reef","reef fish","reef bleaching"]},{"id":115,"topic":"env","w":"mangrove","ipa":"/ˈmæŋɡrəʊv/","pos":"n.","cn":"红树林","pun":"猛哥肉屋","story":"「猛哥」在海边树根缝里盖了「肉屋」，树根泡在海水里——红树林。","ex":"Mangroves protect coastlines from storms and store large amounts of carbon.","exCn":"红树林保护海岸免受风暴侵袭，并储存大量的碳。","col":["mangrove forest","mangrove swamp","plant mangroves"]},{"id":116,"topic":"env","w":"rainforest","ipa":"/ˈreɪnfɒrɪst/","pos":"n.","cn":"雨林","pun":"润佛瑞斯特","story":"rain（雨）+ forest（森林）：天天下雨的森林，湿「润」得像「佛」堂——雨林。","ex":"The Amazon rainforest produces a significant share of the oxygen we breathe.","exCn":"亚马逊雨林产生了我们呼吸的相当一部分氧气。","col":["tropical rainforest","rainforest destruction","Amazon rainforest"]},{"id":117,"topic":"env","w":"canopy","ipa":"/ˈkænəpi/","pos":"n.","cn":"树冠层；顶篷","pun":"看呢皮","story":"抬头「看呢」，一层「皮」一样的树叶把天全遮住了——树冠层。","ex":"Most rainforest animals live high in the canopy rather than on the forest floor.","exCn":"大多数雨林动物生活在高高的树冠层，而非林地。","col":["forest canopy","tree canopy","canopy cover"]},{"id":118,"topic":"env","w":"organism","ipa":"/ˈɔːɡənɪzəm/","pos":"n.","cn":"生物；有机体","pun":"哦跟你怎","story":"「哦，跟你怎么说呢」——显微镜下每个小东西都是活的生物体。","ex":"Even tiny organisms in the soil play a role in recycling nutrients.","exCn":"即使是土壤中的微小生物也在养分循环中发挥作用。","col":["living organism","marine organism","micro-organism"]},{"id":119,"topic":"env","w":"organic","ipa":"/ɔːˈɡænɪk/","pos":"adj.","cn":"有机的；不用化肥的","pun":"哦干泥克","story":"「哦，干泥」里不撒化肥，只用粪肥「克」虫——有机种植。","ex":"Organic farming avoids synthetic chemicals but often produces lower yields.","exCn":"有机农业不用合成化学品，但产量往往较低。","col":["organic farming","organic food","organic matter"]},{"id":120,"topic":"env","w":"fragile","ipa":"/ˈfrædʒaɪl/","pos":"adj.","cn":"脆弱的；易碎的","pun":"弗拉这哦","story":"「弗拉这哦」——轻轻一拉就碎了，太脆弱。","ex":"Coral reefs are extremely fragile and can be destroyed by a single careless anchor.","exCn":"珊瑚礁极其脆弱，一次粗心的下锚就可能将其摧毁。","col":["fragile ecosystem","fragile environment","fragility"]},{"id":121,"topic":"env","w":"vulnerable","ipa":"/ˈvʌlnərəbl/","pos":"adj.","cn":"易受伤害的","pun":"我呢若不","story":"「我呢，若不」躲进洞里，狼一来就完了——易受攻击的。","ex":"Low-lying island nations are the most vulnerable to rising sea levels.","exCn":"低洼岛国最容易受到海平面上升的影响。","col":["vulnerable to","vulnerable species","vulnerability"]},{"id":122,"topic":"env","w":"resilient","ipa":"/rɪˈzɪliənt/","pos":"adj.","cn":"有韧性的；能恢复的","pun":"日贼里恩特","story":"re（回）+ sil（跳）：野草被踩倒，第二「日」又「贼」精神地跳回来——有韧性。","ex":"Cities must become more resilient to floods and storms through better planning.","exCn":"城市必须通过更好的规划来增强抵御洪水和风暴的韧性。","col":["resilient to","climate-resilient","resilience"]},{"id":123,"topic":"env","w":"adapt","ipa":"/əˈdæpt/","pos":"v.","cn":"适应；改造","pun":"额呆普特","story":"ad（去）+ apt（合适）：北极熊「额」头呆呆地想：怎么才能适应变暖的天气？","ex":"Some species may adapt to a warmer climate, but many will not be able to.","exCn":"有些物种可能适应更暖的气候，但许多物种无法适应。","col":["adapt to","adaptation","adaptable"]},{"id":124,"topic":"env","w":"thrive","ipa":"/θraɪv/","pos":"v.","cn":"茁壮成长；繁荣","pun":"死赖夫","story":"「死赖夫」——那株草死赖在石缝里不走，最后长得比谁都旺。","ex":"Since the ban on fishing, marine life in the reserve has begun to thrive.","exCn":"自禁渔以来，保护区内的海洋生物开始繁盛。","col":["thrive in","thriving","thrive on"]},{"id":125,"topic":"env","w":"flourish","ipa":"/ˈflʌrɪʃ/","pos":"v.","cn":"繁荣；茂盛","pun":"弗拉瑞需","story":"flor（花）：「弗拉瑞」需要的只是阳光和水，花就开满了院子——茂盛。","ex":"Wildlife flourished after the wetland was restored to its natural state.","exCn":"湿地恢复自然状态后，野生动物繁衍兴旺。","col":["flourish in","begin to flourish","flourishing"]},{"id":126,"topic":"env","w":"dwindle","ipa":"/ˈdwɪndl/","pos":"v.","cn":"逐渐减少","pun":"对温斗","story":"「对温斗」——鱼群跟水温斗，斗一年少一半，越来越少。","ex":"Fish stocks in the North Sea have dwindled to a fraction of their former size.","exCn":"北海的鱼类资源已减少到原来的一小部分。","col":["dwindle away","dwindling numbers","dwindling resources"]},{"id":127,"topic":"env","w":"diminish","ipa":"/dɪˈmɪnɪʃ/","pos":"v.","cn":"减少；缩小","pun":"底迷你需","story":"di（向下）+ mini（小）：水池「底」都露出来了，水越来越「迷你」——减少。","ex":"The forest cover has diminished by half over the past century.","exCn":"过去一个世纪，森林覆盖面积减少了一半。","col":["diminish rapidly","diminishing returns","diminished"]},{"id":128,"topic":"env","w":"invasive","ipa":"/ɪnˈveɪsɪv/","pos":"adj.","cn":"入侵的","pun":"因为死武","story":"in（进）+ vade（走）：外来的鱼「因为死武」功高强，进来就把本地鱼打光了——入侵物种。","ex":"Invasive species such as the cane toad have devastated native wildlife in Australia.","exCn":"甘蔗蟾蜍等入侵物种重创了澳大利亚的本土野生动物。","col":["invasive species","invasive plant","invade"]},{"id":129,"topic":"env","w":"coexist","ipa":"/ˌkəʊɪɡˈzɪst/","pos":"v.","cn":"共存","pun":"扣一个贼死特","story":"co（一起）+ exist（存在）：人和熊互相「扣」着，谁也不「贼」谁，一起过日子——共存。","ex":"Farmers and elephants can coexist if crops are protected by fences.","exCn":"如果作物有围栏保护，农民和大象可以共存。","col":["coexist peacefully","coexist with","coexistence"]},{"id":130,"topic":"env","w":"pollinate","ipa":"/ˈpɒləneɪt/","pos":"v.","cn":"授粉","pun":"抛了内特","story":"蜜蜂把花粉「抛」到「内」部，花才结果——授粉。","ex":"Bees pollinate roughly a third of the crops that humans eat.","exCn":"蜜蜂为人类食用的大约三分之一的作物授粉。","col":["pollinate crops","pollination","pollinator"]},{"id":131,"topic":"env","w":"overfishing","ipa":"/ˌəʊvəˈfɪʃɪŋ/","pos":"n.","cn":"过度捕捞","pun":"欧我费行","story":"over（过度）+ fishing（捕鱼）：「欧」船长天天出海，鱼都被捞光了——过度捕捞。","ex":"Overfishing has pushed several tuna species to the edge of collapse.","exCn":"过度捕捞已把几种金枪鱼推到崩溃边缘。","col":["overfishing of","combat overfishing","overfished"]},{"id":132,"topic":"env","w":"marine","ipa":"/məˈriːn/","pos":"adj.","cn":"海洋的","pun":"么淋","story":"「么淋」——海浪淋了我一身，全是海洋的味道。","ex":"Plastic waste is one of the greatest threats to marine life today.","exCn":"塑料垃圾是当今海洋生物面临的最大威胁之一。","col":["marine life","marine reserve","marine biology"]},{"id":133,"topic":"env","w":"aquatic","ipa":"/əˈkwætɪk/","pos":"adj.","cn":"水生的","pun":"额夸踢克","story":"aqua（水）：「额」头夸张地踢水，鱼虾青蛙都是水生的。","ex":"Fertiliser run-off reduces oxygen levels and kills aquatic animals.","exCn":"化肥径流降低氧气含量，导致水生动物死亡。","col":["aquatic life","aquatic plants","aquatic environment"]},{"id":134,"topic":"env","w":"coastal","ipa":"/ˈkəʊstl/","pos":"adj.","cn":"沿海的","pun":"扣死头","story":"coast（海岸）：海边的风把帽子「扣」在「死头」上吹不掉——沿海的。","ex":"Coastal communities are already relocating due to rising sea levels.","exCn":"沿海社区已因海平面上升开始搬迁。","col":["coastal areas","coastal erosion","coastline"]},{"id":135,"topic":"env","w":"polar","ipa":"/ˈpəʊlə(r)/","pos":"adj.","cn":"极地的","pun":"抛啦","story":"pole（极点）：把温度计「抛啦」，两极冷得不用看——极地的。","ex":"Polar ice caps are shrinking, threatening the survival of polar bears.","exCn":"极地冰盖正在缩小，威胁北极熊的生存。","col":["polar ice","polar regions","polar bear"]},{"id":136,"topic":"env","w":"tropical","ipa":"/ˈtrɒpɪkl/","pos":"adj.","cn":"热带的","pun":"绰皮扣","story":"热带太热，「绰」起衣服「皮」都扣不上——热带的。","ex":"Tropical forests are being cleared for palm oil and cattle at an alarming rate.","exCn":"热带森林正以惊人的速度被砍伐用于棕榈油和养牛。","col":["tropical rainforest","tropical climate","the tropics"]},{"id":137,"topic":"env","w":"legislation","ipa":"/ˌledʒɪsˈleɪʃn/","pos":"n.","cn":"立法；法律","pun":"累鸡死累深","story":"legis（法律）：议员为了写环保法「累」得像「鸡」，「死累」得很「深」——立法。","ex":"Strict legislation is needed to stop factories dumping waste into rivers.","exCn":"需要严格的立法来阻止工厂向河流倾倒废物。","col":["introduce legislation","environmental legislation","legislate"]},{"id":138,"topic":"env","w":"regulate","ipa":"/ˈreɡjuleɪt/","pos":"v.","cn":"监管；调节","pun":"瑞哥累特","story":"regul（规则）：「瑞哥」当环保局长，管得「累」得「特」惨——监管排放。","ex":"Governments must regulate industries that produce large amounts of waste.","exCn":"政府必须监管产生大量废物的行业。","col":["regulate emissions","regulation","regulatory"]},{"id":139,"topic":"env","w":"ban","ipa":"/bæn/","pos":"v./n.","cn":"禁止；禁令","pun":"扮","story":"「扮」演警察的人一挥手：塑料袋不准用——禁令。","ex":"Many cities have banned diesel cars from their centres to improve air quality.","exCn":"许多城市禁止柴油车进入市中心以改善空气质量。","col":["impose a ban","ban on","total ban"]},{"id":140,"topic":"env","w":"subsidy","ipa":"/ˈsʌbsədi/","pos":"n.","cn":"补贴","pun":"傻不死地","story":"sub（下）+ sid（坐）：政府在下面托着，你「傻」也「不死」，「地」上有钱补——补贴。","ex":"Subsidies for solar panels have made clean energy affordable for ordinary households.","exCn":"太阳能板补贴使清洁能源对普通家庭来说变得可负担。","col":["government subsidy","fossil fuel subsidies","subsidise"]},{"id":141,"topic":"env","w":"levy","ipa":"/ˈlevi/","pos":"n./v.","cn":"征税；征收","pun":"累为","story":"「累为」——为了收环保税，税务员累得直不起腰——征收。","ex":"A levy on plastic bags cut their use by more than eighty per cent in a year.","exCn":"对塑料袋征税使其使用量在一年内减少了八成以上。","col":["levy a tax","carbon levy","impose a levy"]},{"id":142,"topic":"env","w":"incentive","ipa":"/ɪnˈsentɪv/","pos":"n.","cn":"激励；奖励措施","pun":"因三提夫","story":"in（内）+ cent（唱）：「因」为老板「三」次提「夫」人的工资，大家干劲十足——激励。","ex":"Tax incentives encourage companies to invest in cleaner technology.","exCn":"税收优惠鼓励企业投资更清洁的技术。","col":["financial incentive","provide an incentive","incentivise"]},{"id":143,"topic":"env","w":"penalty","ipa":"/ˈpenəlti/","pos":"n.","cn":"处罚；罚款","pun":"盆儿踢","story":"把「盆儿」踢翻了要罚款——处罚。","ex":"Heavier penalties for illegal dumping would deter companies from polluting.","exCn":"对非法倾倒加重处罚将阻止企业污染环境。","col":["impose a penalty","financial penalty","penalise"]},{"id":144,"topic":"env","w":"enforce","ipa":"/ɪnˈfɔːs/","pos":"v.","cn":"强制执行","pun":"因佛死","story":"en（使）+ force（力量）：「因」为「佛」也得「死」守规矩，法律一律强制执行。","ex":"Environmental laws are useless unless they are properly enforced.","exCn":"环保法律若不切实执行就毫无用处。","col":["enforce the law","strictly enforce","enforcement"]},{"id":145,"topic":"env","w":"treaty","ipa":"/ˈtriːti/","pos":"n.","cn":"条约","pun":"吹踢","story":"两国领导人一边「吹」牛一边「踢」皮球，最后签了条约。","ex":"The treaty commits signatory nations to limiting global warming to two degrees.","exCn":"该条约要求签约国把全球变暖控制在两度以内。","col":["sign a treaty","international treaty","climate treaty"]},{"id":146,"topic":"env","w":"protocol","ipa":"/ˈprəʊtəkɒl/","pos":"n.","cn":"议定书；协议","pun":"扑肉特扣","story":"proto（首先）：谈判时先「扑」向「肉」，「特」别「扣」细节——议定书。","ex":"The Kyoto Protocol was the first agreement to set binding targets for rich countries.","exCn":"《京都议定书》是首个为富裕国家设定约束性目标的协议。","col":["Kyoto Protocol","sign a protocol","follow protocol"]},{"id":147,"topic":"env","w":"summit","ipa":"/ˈsʌmɪt/","pos":"n.","cn":"峰会；顶峰","pun":"萨米特","story":"「萨米特」爬到山顶，发现各国领导人都在那儿开会——峰会。","ex":"World leaders gathered at the climate summit to negotiate new targets.","exCn":"世界领导人齐聚气候峰会，就新目标进行谈判。","col":["climate summit","hold a summit","summit meeting"]},{"id":148,"topic":"env","w":"pledge","ipa":"/pledʒ/","pos":"v./n.","cn":"承诺；保证","pun":"扑累纸","story":"领导人「扑」到桌前，「累」得在「纸」上签名保证——承诺减排。","ex":"The company pledged to become carbon neutral by 2030.","exCn":"该公司承诺到2030年实现碳中和。","col":["pledge to","make a pledge","pledge support"]},{"id":149,"topic":"env","w":"neutral","ipa":"/ˈnjuːtrəl/","pos":"adj.","cn":"中性的；中立的","pun":"牛出","story":"「牛出」多少气，就种多少树抵消，不多不少——碳中和。","ex":"Several countries aim to be carbon neutral by the middle of the century.","exCn":"多个国家的目标是在本世纪中叶实现碳中和。","col":["carbon neutral","remain neutral","neutralise"]},{"id":150,"topic":"env","w":"offset","ipa":"/ˈɒfset/","pos":"v./n.","cn":"抵消；补偿","pun":"哦夫塞特","story":"off（掉）+ set（放）：「哦，夫」君坐飞机排碳，就「塞」几棵树把碳抵消掉。","ex":"Airlines allow passengers to offset their flights by funding tree-planting projects.","exCn":"航空公司允许乘客通过资助植树项目来抵消飞行碳排放。","col":["carbon offset","offset emissions","offset the cost"]},{"id":151,"topic":"env","w":"mitigate","ipa":"/ˈmɪtɪɡeɪt/","pos":"v.","cn":"减轻；缓解","pun":"米提给特","story":"「米提给特」——把米提去给特困的灾民，减轻灾害的痛苦。","ex":"Planting trees in cities can help mitigate the effects of extreme heat.","exCn":"在城市植树有助于减轻极端高温的影响。","col":["mitigate the effects","mitigate climate change","mitigation"]},{"id":152,"topic":"env","w":"curb","ipa":"/kɜːb/","pos":"v./n.","cn":"控制；抑制","pun":"克不","story":"「克不」住的排放就得靠法律来控制——抑制。","ex":"New rules aim to curb the use of coal in power generation.","exCn":"新规旨在抑制发电中的煤炭使用。","col":["curb emissions","curb pollution","put a curb on"]},{"id":153,"topic":"env","w":"restrict","ipa":"/rɪˈstrɪkt/","pos":"v.","cn":"限制","pun":"日死追克特","story":"re（回）+ strict（拉紧）：「日」子过得死紧，追着克扣特权——限制。","ex":"Some cities restrict car use on days when air quality is poor.","exCn":"一些城市在空气质量差的日子限制汽车使用。","col":["restrict access","restriction","restrictive"]},{"id":154,"topic":"env","w":"impose","ipa":"/ɪmˈpəʊz/","pos":"v.","cn":"强制实行；征收","pun":"因剖死","story":"im（进）+ pose（放）：「因」为要「剖」开你的钱包放进税单——强制征税。","ex":"The government imposed a tax on companies that exceed their carbon limits.","exCn":"政府对超出碳限额的公司征税。","col":["impose a tax","impose restrictions","impose on"]},{"id":155,"topic":"env","w":"initiative","ipa":"/ɪˈnɪʃətɪv/","pos":"n.","cn":"倡议；举措","pun":"一泥舍踢夫","story":"init（开始）：「一」脚踢进「泥」里，「舍」不得停，「踢夫」带头开始了新计划——倡议。","ex":"The recycling initiative was launched to cut household waste by half.","exCn":"这项回收倡议旨在把家庭垃圾减半。","col":["launch an initiative","green initiative","take the initiative"]},{"id":156,"topic":"env","w":"campaign","ipa":"/kæmˈpeɪn/","pos":"n./v.","cn":"运动；宣传活动","pun":"看盆","story":"环保志愿者举着「看盆」的牌子，让大家看看装满垃圾的盆——宣传运动。","ex":"A nationwide campaign encouraged citizens to reduce their use of plastic.","exCn":"一项全国性运动鼓励公民减少塑料使用。","col":["launch a campaign","awareness campaign","campaign against"]},{"id":157,"topic":"env","w":"activist","ipa":"/ˈæktɪvɪst/","pos":"n.","cn":"活动人士；积极分子","pun":"爱克踢喂死特","story":"act（行动）：「爱克」举着牌子踢开大门喂动物，活动特别积极——活动人士。","ex":"Environmental activists have blocked roads to protest against the new coal mine.","exCn":"环保活动人士封堵道路，抗议新煤矿。","col":["environmental activist","climate activist","activism"]},{"id":158,"topic":"env","w":"awareness","ipa":"/əˈweənəs/","pos":"n.","cn":"意识；认识","pun":"额外呢死","story":"aware（意识到）+ -ness：「额外」多想一步就不会「死」于无知——环保意识。","ex":"Schools play a key role in raising environmental awareness among young people.","exCn":"学校在提高年轻人环保意识方面发挥关键作用。","col":["raise awareness","environmental awareness","public awareness"]},{"id":159,"topic":"env","w":"eco-friendly","ipa":"/ˌiːkəʊ ˈfrendli/","pos":"adj.","cn":"环保的","pun":"一口福润的李","story":"eco（生态）+ friendly（友好）：「一口福」都留给「润」土的「李」子树——对环境友好。","ex":"Consumers increasingly prefer eco-friendly products with minimal packaging.","exCn":"消费者越来越偏爱包装极少的环保产品。","col":["eco-friendly products","eco-friendly packaging","environmentally friendly"]},{"id":160,"topic":"env","w":"infrastructure","ipa":"/ˈɪnfrəstrʌktʃə(r)/","pos":"n.","cn":"基础设施","pun":"因弗拉死拽克车","story":"infra（下）+ structure（结构）：「因」为「弗拉」死拽着车过烂路，才知道基础设施多重要。","ex":"Investment in green infrastructure such as cycle lanes reduces traffic emissions.","exCn":"投资自行车道等绿色基础设施可以减少交通排放。","col":["green infrastructure","transport infrastructure","infrastructure investment"]},{"id":161,"topic":"env","w":"transition","ipa":"/trænˈzɪʃn/","pos":"n./v.","cn":"过渡；转型","pun":"穿子深","story":"trans（跨）：「穿」过「子」夜很「深」的隧道，从煤炭走向清洁能源——转型。","ex":"The transition to clean energy will create millions of new jobs.","exCn":"向清洁能源的转型将创造数百万新工作岗位。","col":["energy transition","transition to","transition period"]},{"id":162,"topic":"env","w":"threshold","ipa":"/ˈθreʃhəʊld/","pos":"n.","cn":"门槛；临界点","pun":"死累是后的","story":"跨过这道门槛才知道，「死累是后」面的事——临界点。","ex":"Scientists warn that warming beyond the 1.5-degree threshold could be irreversible.","exCn":"科学家警告，超过1.5度临界点的升温可能无法逆转。","col":["critical threshold","cross a threshold","threshold level"]},{"id":163,"topic":"env","w":"irreversible","ipa":"/ˌɪrɪˈvɜːsəbl/","pos":"adj.","cn":"不可逆转的","pun":"一日我死不","story":"ir（不）+ reverse（倒转）：「一日我死」了就「不」能回来——不可逆转。","ex":"Some of the damage to coral reefs may already be irreversible.","exCn":"对珊瑚礁的部分损害可能已经无法逆转。","col":["irreversible damage","irreversible change","reversible"]},{"id":164,"topic":"env","w":"catastrophe","ipa":"/kəˈtæstrəfi/","pos":"n.","cn":"大灾难","pun":"可太死绰飞","story":"「可太死」了，房子被大风「绰」起来「飞」走——大灾难。","ex":"Without urgent action, climate change could lead to a global catastrophe.","exCn":"如果不采取紧急行动，气候变化可能导致全球性灾难。","col":["environmental catastrophe","catastrophic","avert a catastrophe"]},{"id":165,"topic":"env","w":"devastate","ipa":"/ˈdevəsteɪt/","pos":"v.","cn":"摧毁；重创","pun":"得我死太特","story":"「得我死太特」——洪水一来，我的家死得太彻底——被摧毁。","ex":"The floods devastated farmland and left thousands without homes.","exCn":"洪水摧毁了农田，使数千人无家可归。","col":["devastate the region","devastating","devastation"]},{"id":166,"topic":"env","w":"vanish","ipa":"/ˈvænɪʃ/","pos":"v.","cn":"消失","pun":"完你需","story":"「完你需」要的东西都没了——冰川一夜之间消失。","ex":"Many small glaciers are expected to vanish entirely within thirty years.","exCn":"许多小冰川预计将在三十年内完全消失。","col":["vanish completely","vanish from","disappear"]},{"id":167,"topic":"env","w":"deteriorate","ipa":"/dɪˈtɪəriəreɪt/","pos":"v.","cn":"恶化","pun":"地铁里累特","story":"「地铁里累特」——空气在地铁里越来越差，人累得不行——恶化。","ex":"Air quality in the capital has deteriorated sharply over the past decade.","exCn":"过去十年，首都的空气质量急剧恶化。","col":["deteriorate rapidly","deteriorating conditions","deterioration"]},{"id":168,"topic":"env","w":"reverse","ipa":"/rɪˈvɜːs/","pos":"v./n.","cn":"逆转；扭转","pun":"日我死","story":"re（回）+ verse（转）：「日」子倒着过，我「死」也要把沙漠变回森林——逆转。","ex":"It may take generations to reverse the damage done to the soil.","exCn":"扭转对土壤造成的损害可能需要几代人的时间。","col":["reverse the trend","reverse the damage","reversal"]},{"id":169,"topic":"env","w":"restore","ipa":"/rɪˈstɔː(r)/","pos":"v.","cn":"恢复；修复","pun":"日死抖","story":"re（回）+ store（存）：「日」子过得「死抖」也要把河流修回原样——恢复。","ex":"Efforts to restore the wetland have brought back dozens of bird species.","exCn":"恢复湿地的努力让数十种鸟类重新回归。","col":["restore habitats","restoration","restore to"]},{"id":170,"topic":"env","w":"rehabilitate","ipa":"/ˌriːəˈbɪlɪteɪt/","pos":"v.","cn":"修复；使康复","pun":"瑞额比里特特","story":"re（再）+ habil（能力）：「瑞」把废矿区一「比」一「里」地种回草——修复土地。","ex":"Mining companies are now required to rehabilitate the land once extraction ends.","exCn":"矿业公司现在被要求在开采结束后修复土地。","col":["rehabilitate land","rehabilitate wildlife","rehabilitation"]},{"id":171,"topic":"env","w":"regenerate","ipa":"/rɪˈdʒenəreɪt/","pos":"v.","cn":"再生；复兴","pun":"日贼呢累特","story":"re（再）+ generate（产生）：森林烧了，「日」子一天天过，「贼」快地又长出来——再生。","ex":"Given time, forests can regenerate naturally without human intervention.","exCn":"假以时日，森林可以在没有人为干预的情况下自然再生。","col":["regenerate naturally","regeneration","regenerative farming"]},{"id":172,"topic":"env","w":"ecological","ipa":"/ˌiːkəˈlɒdʒɪkl/","pos":"adj.","cn":"生态的","pun":"一口拉几口","story":"eco（生态）+ logic（学）：吃「一口」就得「拉几口」还给大地，这就是生态平衡。","ex":"Draining the marsh caused an ecological disaster for local birds.","exCn":"排干沼泽给当地鸟类带来了生态灾难。","col":["ecological balance","ecological damage","ecology"]},{"id":173,"topic":"env","w":"environmentalist","ipa":"/ɪnˌvaɪrənˈmentəlɪst/","pos":"n.","cn":"环保主义者","pun":"因外人们特理死特","story":"environment（环境）+ -ist（者）：「因」为「外人们特」别不理环境，他们死也要管——环保主义者。","ex":"Environmentalists argue that economic growth should not come at the cost of nature.","exCn":"环保主义者认为经济增长不应以牺牲自然为代价。","col":["leading environmentalist","environmentalism","environmental"]},{"id":174,"topic":"env","w":"insulation","ipa":"/ˌɪnsjuˈleɪʃn/","pos":"n.","cn":"隔热；保温层","pun":"因修累深","story":"「因」为「修」墙「累」得很「深」，但屋子冬暖夏凉了——保温层。","ex":"Better home insulation could cut heating bills and energy use dramatically.","exCn":"更好的住宅隔热可以大幅降低取暖费用和能源消耗。","col":["home insulation","thermal insulation","insulate"]},{"id":175,"topic":"env","w":"exploit","ipa":"/ɪkˈsplɔɪt/","pos":"v.","cn":"开发；剥削","pun":"一颗死破一特","story":"ex（出）+ ploit（折叠）：把「一颗」地球「死破」了「一」层皮，特别狠地开采——过度开发。","ex":"Companies continue to exploit natural resources with little regard for the future.","exCn":"企业继续开发自然资源，很少考虑未来。","col":["exploit resources","over-exploit","exploitation"]},{"id":176,"topic":"edu","w":"curriculum","ipa":"/kəˈrɪkjələm/","pos":"n.","cn":"课程（体系）","pun":"课里可冷","story":"「课里可冷」了——课程排得满满的，教室里冷冰冰的。","ex":"Schools should include financial education in the national curriculum.","exCn":"学校应把理财教育纳入国家课程。","col":["the school curriculum","core curriculum","curriculum design"]},{"id":177,"topic":"edu","w":"compulsory","ipa":"/kəmˈpʌlsəri/","pos":"adj.","cn":"义务的；强制的","pun":"肯跑死你","story":"强制体育课：「肯」定「跑死你」，不跑也得跑。","ex":"In most countries, education is compulsory until the age of 16.","exCn":"在多数国家，16 岁之前的教育是义务性的。","col":["compulsory education","make sth compulsory","compulsory subjects"]},{"id":178,"topic":"edu","w":"literacy","ipa":"/ˈlɪtərəsi/","pos":"n.","cn":"读写能力","pun":"里特累死","story":"letter 是字母，literacy 就是认字母的能力。小「里特」学认字「累死」了。","ex":"Adult literacy rates have improved dramatically over the past decade.","exCn":"过去十年成人识字率显著提高。","col":["literacy rate","digital / financial literacy","illiteracy (n.) 文盲"]},{"id":179,"topic":"edu","w":"scholarship","ipa":"/ˈskɒləʃɪp/","pos":"n.","cn":"奖学金","pun":"死磕拉 ship","story":"scholar 是学者。「死磕」学习，才能「拉」到奖学金，坐上出国的「ship」。","ex":"She won a full scholarship to study abroad.","exCn":"她获得了出国留学的全额奖学金。","col":["win / receive a scholarship","full scholarship","scholarship programme"]},{"id":180,"topic":"edu","w":"tuition","ipa":"/tjuˈɪʃn/","pos":"n.","cn":"学费；讲授","pun":"丢一身","story":"交完学费，钱「丢」得「一身」轻，口袋全空。","ex":"Rising tuition fees have made university less accessible to poorer students.","exCn":"不断上涨的学费让贫困学生更难上大学。","col":["tuition fees","private tuition","free tuition"]},{"id":181,"topic":"edu","w":"discipline","ipa":"/ˈdɪsəplɪn/","pos":"n.","cn":"纪律；学科","pun":"弟死泼冷","story":"「弟」弟不守纪律，被老师「泼冷」水，「死」定了。","ex":"Strict discipline in schools does not necessarily lead to better results.","exCn":"学校里严格的纪律不一定带来更好的成绩。","col":["strict discipline","self-discipline","academic discipline 学科"]},{"id":182,"topic":"edu","w":"peer","ipa":"/pɪə(r)/","pos":"n.","cn":"同龄人；同伴","pun":"皮儿","story":"一群「皮」孩「儿」凑在一起，那就是同龄人。","ex":"Teenagers are heavily influenced by their peers.","exCn":"青少年深受同龄人影响。","col":["peer pressure 同伴压力","peer group","peer review"]},{"id":183,"topic":"edu","w":"motivation","ipa":"/ˌməʊtɪˈveɪʃn/","pos":"n.","cn":"动力；积极性","pun":"磨题为神","story":"为了「成神」拼命「磨题」，这股劲儿就是动力。","ex":"Lack of motivation is a common reason why students drop out.","exCn":"缺乏动力是学生辍学的常见原因。","col":["lack of motivation","motivate (v.)","motivated students"]},{"id":184,"topic":"edu","w":"plagiarism","ipa":"/ˈpleɪdʒərɪzəm/","pos":"n.","cn":"抄袭","pun":"不累这人","story":"写论文「不累」？「这人」肯定是抄的。","ex":"Universities use software to detect plagiarism in student essays.","exCn":"大学使用软件检测学生论文中的抄袭。","col":["commit plagiarism","plagiarise (v.)","accused of plagiarism"]},{"id":185,"topic":"edu","w":"vocational","ipa":"/vəʊˈkeɪʃənl/","pos":"adj.","cn":"职业的（培训）","pun":"我开训呢","story":"「我开」始职业培「训呢」——学的是能直接上岗的手艺。","ex":"Vocational training helps young people gain practical skills for work.","exCn":"职业培训帮助年轻人获得实用的工作技能。","col":["vocational training / education","vocational courses"]},{"id":186,"topic":"edu","w":"academic","ipa":"/ˌækəˈdemɪk/","pos":"adj./n.","cn":"学术的；学者","pun":"爱看得米课","story":"学者「爱看得米课」，一天不看学术课就像少吃了米饭。","ex":"Many parents believe that academic achievement is the only route to a successful career.","exCn":"许多家长认为学术成就是通往成功事业的唯一途径。","col":["academic performance","academic year","academia"]},{"id":187,"topic":"edu","w":"assessment","ipa":"/əˈsesmənt/","pos":"n.","cn":"评估；考核","pun":"额塞死门","story":"考核前把资料「额塞死门」缝，评估完才敢开门喘气。","ex":"Continuous assessment may reflect a student's ability more accurately than a single final exam.","exCn":"持续性评估可能比一次期末考更准确地反映学生的能力。","col":["continuous assessment","assessment criteria","assess (v.)"]},{"id":188,"topic":"edu","w":"syllabus","ipa":"/ˈsɪləbəs/","pos":"n.","cn":"教学大纲","pun":"洗了巴士","story":"老师把教学大纲贴在「洗了巴士」的车身上，学生一上车就知道学什么。","ex":"The new syllabus places greater emphasis on problem-solving than on memorising facts.","exCn":"新教学大纲更强调解决问题，而非死记硬背事实。","col":["follow the syllabus","exam syllabus","syllabus design"]},{"id":189,"topic":"edu","w":"pedagogy","ipa":"/ˈpedəɡɒdʒi/","pos":"n.","cn":"教学法；教育学","pun":"派的狗记","story":"教育学研究「派的狗记」多少：连狗都能记住，说明教学法有效。","ex":"Modern pedagogy encourages teachers to act as facilitators rather than lecturers.","exCn":"现代教学法鼓励教师担任引导者而非讲授者。","col":["pedagogical approach","child-centred pedagogy","pedagogue"]},{"id":190,"topic":"edu","w":"enrol","ipa":"/ɪnˈrəʊl/","pos":"v.","cn":"注册；入学","pun":"应肉","story":"报名入学要「应肉」：en（进入）+ rol（名册），把名字塞进花名册的肉里。","ex":"Record numbers of mature students have enrolled in evening courses this year.","exCn":"今年报名夜校课程的成年学生人数创下纪录。","col":["enrol in a course","enrol at a university","enrolment (n.)"]},{"id":191,"topic":"edu","w":"undergraduate","ipa":"/ˌʌndəˈɡrædʒuət/","pos":"n.","cn":"本科生","pun":"俺的怪橘挨特","story":"under（之下）+ graduate（毕业）：还在毕业线之下的「俺的怪橘」，就是本科生。","ex":"Undergraduate students are increasingly expected to complete internships before graduation.","exCn":"本科生越来越被期望在毕业前完成实习。","col":["undergraduate degree","undergraduate course","postgraduate"]},{"id":192,"topic":"edu","w":"postgraduate","ipa":"/ˌpəʊstˈɡrædʒuət/","pos":"n./adj.","cn":"研究生（的）","pun":"抛死特怪橘","story":"post（之后）+ graduate：毕业之后还「抛死特」地读书的怪橘，就是研究生。","ex":"A postgraduate qualification can significantly improve one's employment prospects.","exCn":"研究生学历能显著改善就业前景。","col":["postgraduate study","postgraduate degree","graduate school"]},{"id":193,"topic":"edu","w":"faculty","ipa":"/ˈfæklti/","pos":"n.","cn":"学院；全体教员","pun":"发课题","story":"学院里的教员天天「发课题」，发不完的课题就是他们的本职。","ex":"The faculty of engineering has attracted substantial research funding in recent years.","exCn":"工程学院近年来吸引了大量研究经费。","col":["faculty member","the Faculty of Arts","faculty meeting"]},{"id":194,"topic":"edu","w":"lecture","ipa":"/ˈlektʃə(r)/","pos":"n./v.","cn":"讲座；讲课","pun":"累客厅","story":"教授在「累客厅」讲课，一讲两小时，客厅里的人全听累了。","ex":"Large lectures offer little opportunity for students to interact with their professors.","exCn":"大课讲座几乎不给学生与教授互动的机会。","col":["attend a lecture","deliver a lecture","lecturer"]},{"id":195,"topic":"edu","w":"seminar","ipa":"/ˈsemɪnɑː(r)/","pos":"n.","cn":"研讨课","pun":"塞米哪","story":"研讨课上大家争论「塞米哪」：米该塞哪儿？小组讨论越吵越热闹。","ex":"Seminars allow students to debate ideas in a way that lectures cannot.","exCn":"研讨课让学生以讲座做不到的方式辩论观点。","col":["seminar group","hold a seminar","seminar discussion"]},{"id":196,"topic":"edu","w":"tutorial","ipa":"/tjuːˈtɔːriəl/","pos":"n.","cn":"辅导课；教程","pun":"丢到里哦","story":"辅导课把不懂的题「丢到里哦」，老师一对一捞出来讲清楚。","ex":"Weekly tutorials give students personalised feedback on their written work.","exCn":"每周辅导课为学生的书面作业提供个性化反馈。","col":["online tutorial","tutorial session","tutor (n.)"]},{"id":197,"topic":"edu","w":"dissertation","ipa":"/ˌdɪsəˈteɪʃn/","pos":"n.","cn":"学位论文","pun":"弟色特神","story":"弟弟写学位论文写得「弟色特神」：脸色特别难看，眼神特别呆滞。","ex":"Final-year students must submit a dissertation of around ten thousand words.","exCn":"毕业班学生须提交一篇约一万字的学位论文。","col":["write a dissertation","dissertation supervisor","thesis"]},{"id":198,"topic":"edu","w":"thesis","ipa":"/ˈθiːsɪs/","pos":"n.","cn":"论文；论点","pun":"细死死","story":"论文要「细死死」地改，每个论点都抠到细节，改得快要死。","ex":"A strong thesis statement guides the reader through the entire essay.","exCn":"一个清晰的中心论点引导读者读完整篇文章。","col":["thesis statement","PhD thesis","defend a thesis"]},{"id":199,"topic":"edu","w":"numeracy","ipa":"/ˈnjuːmərəsi/","pos":"n.","cn":"计算能力","pun":"牛么来睡","story":"数数「牛么来睡」：数了几头牛才能睡着，这就是基本计算能力。","ex":"Basic numeracy skills are essential for managing personal finances in adult life.","exCn":"基本计算能力对成年后管理个人财务至关重要。","col":["numeracy skills","literacy and numeracy","numerate (adj.)"]},{"id":200,"topic":"edu","w":"cognitive","ipa":"/ˈkɒɡnətɪv/","pos":"adj.","cn":"认知的","pun":"靠哥呢踢舞","story":"「靠哥呢踢舞」：哥哥靠认知能力学会了踢踏舞，脑子好使身体也跟上。","ex":"Early childhood education plays a crucial role in cognitive development.","exCn":"幼儿教育在认知发展中起着关键作用。","col":["cognitive development","cognitive skills","cognition (n.)"]},{"id":201,"topic":"edu","w":"memorise","ipa":"/ˈmeməraɪz/","pos":"v.","cn":"记住；背诵","pun":"没么赖死","story":"背单词「没么赖死」：没有偷懒，硬是把词都背到死记住。","ex":"Students who merely memorise facts often struggle to apply them in new contexts.","exCn":"只会死记事实的学生往往难以在新情境中运用。","col":["memorise vocabulary","memorise by heart","memory (n.)"]},{"id":202,"topic":"edu","w":"rote","ipa":"/rəʊt/","pos":"n.","cn":"死记硬背","pun":"肉特","story":"死记硬背就像啃「肉特」硬的干肉，嚼不烂也要硬吞。","ex":"Critics argue that rote learning discourages independent thought.","exCn":"批评者认为死记硬背抑制独立思考。","col":["rote learning","learn by rote","rote memorisation"]},{"id":203,"topic":"edu","w":"comprehension","ipa":"/ˌkɒmprɪˈhenʃn/","pos":"n.","cn":"理解；理解力","pun":"看不理很深","story":"阅读理解题「看不理很深」：看了看不懂，理不清，因为文章很深。","ex":"Reading comprehension tests measure how well students grasp the meaning of a text.","exCn":"阅读理解测试衡量学生对文本含义的把握程度。","col":["reading comprehension","comprehension skills","comprehend (v.)"]},{"id":204,"topic":"edu","w":"attainment","ipa":"/əˈteɪnmənt/","pos":"n.","cn":"成就；学业成绩","pun":"额太门特","story":"「额太门特」：学业成绩太高，额头都特别亮，站在门口都发光。","ex":"There remains a significant attainment gap between pupils from rich and poor families.","exCn":"贫富家庭学生之间仍存在显著的学业成绩差距。","col":["attainment gap","educational attainment","attain (v.)"]},{"id":205,"topic":"edu","w":"aptitude","ipa":"/ˈæptɪtjuːd/","pos":"n.","cn":"天资；才能","pun":"爱谱题图","story":"有天赋的孩子「爱谱题图」：爱画谱、爱做题、爱画图，样样有才能。","ex":"Aptitude tests are often used to identify students suited to particular careers.","exCn":"能力倾向测试常用于识别适合特定职业的学生。","col":["aptitude for languages","aptitude test","natural aptitude"]},{"id":206,"topic":"edu","w":"intellectual","ipa":"/ˌɪntəˈlektʃuəl/","pos":"adj./n.","cn":"智力的；知识分子","pun":"因特累客秋","story":"知识分子「因特累客秋」：因为特别累，客人在秋天来讨论智力问题。","ex":"University should nurture intellectual curiosity rather than simply prepare students for jobs.","exCn":"大学应培养求知欲，而非仅仅为学生就业做准备。","col":["intellectual development","intellectual property","intellect (n.)"]},{"id":207,"topic":"edu","w":"theoretical","ipa":"/ˌθɪəˈretɪkl/","pos":"adj.","cn":"理论的","pun":"西儿累踢口","story":"理论课听得「西儿累踢口」：西边的儿子累得踢开门口就跑。","ex":"Many graduates find that theoretical knowledge alone is insufficient in the workplace.","exCn":"许多毕业生发现仅有理论知识在职场中并不够用。","col":["theoretical knowledge","theoretical framework","theory (n.)"]},{"id":208,"topic":"edu","w":"practical","ipa":"/ˈpræktɪkl/","pos":"adj.","cn":"实践的；实用的","pun":"派克踢扣","story":"实践课用「派克踢扣」：拿派克笔踢扣子，动手才叫实用。","ex":"Schools should offer more practical subjects such as cookery and woodwork.","exCn":"学校应开设更多实践课程，如烹饪和木工。","col":["practical skills","practical experience","practice (n.)"]},{"id":209,"topic":"edu","w":"extracurricular","ipa":"/ˌekstrəkəˈrɪkjələ(r)/","pos":"adj.","cn":"课外的","pun":"艾克斯抓课累哭了","story":"extra（额外）+ curricular（课程）：额外抓课，孩子累哭了，课外活动太多。","ex":"Extracurricular activities help students develop teamwork and leadership skills.","exCn":"课外活动帮助学生培养团队合作和领导能力。","col":["extracurricular activities","extracurricular clubs","extracurricular programme"]},{"id":210,"topic":"edu","w":"boarding school","ipa":"/ˈbɔːdɪŋ skuːl/","pos":"n.","cn":"寄宿学校","pun":"包丁斯库","story":"寄宿学校「包丁斯库」：包吃包住，连丁点儿事都在库房似的校园里解决。","ex":"Some parents send their children to boarding school to foster independence.","exCn":"有些家长把孩子送进寄宿学校以培养独立性。","col":["attend boarding school","boarding school fees","boarder"]},{"id":211,"topic":"edu","w":"coeducational","ipa":"/ˌkəʊedʒuˈkeɪʃənl/","pos":"adj.","cn":"男女同校的","pun":"扣艾玖凯甚闹","story":"co（共同）+ educational：男女同校，「扣艾玖凯甚闹」，班里特别热闹。","ex":"Research suggests that coeducational schools better prepare pupils for adult life.","exCn":"研究表明男女同校更能让学生为成年生活做准备。","col":["coeducational school","co-ed (adj.)","single-sex school"]},{"id":212,"topic":"edu","w":"kindergarten","ipa":"/ˈkɪndəɡɑːtn/","pos":"n.","cn":"幼儿园","pun":"啃的嘎登","story":"幼儿园的小孩「啃的嘎登」响：啃饼干嘎嘣嘎嘣，老师在一旁登记。","ex":"Attending kindergarten helps young children develop essential social skills.","exCn":"上幼儿园帮助幼儿培养基本社交技能。","col":["kindergarten teacher","attend kindergarten","pre-school"]},{"id":213,"topic":"edu","w":"nursery","ipa":"/ˈnɜːsəri/","pos":"n.","cn":"托儿所；幼儿园","pun":"呢色瑞","story":"托儿所里小孩问「呢色瑞」：这颜色叫什么？老师一天答一百遍。","ex":"Affordable nursery places enable more mothers to return to work.","exCn":"可负担的托儿所名额让更多母亲能重返职场。","col":["nursery school","nursery place","nursery education"]},{"id":214,"topic":"edu","w":"mentor","ipa":"/ˈmentɔː(r)/","pos":"n./v.","cn":"导师；指导","pun":"门拓","story":"好导师帮你「门拓」：把你眼前的门拓宽，指导你走出去。","ex":"Pairing new teachers with an experienced mentor reduces staff turnover.","exCn":"为新教师配备经验丰富的导师能降低人员流失。","col":["act as a mentor","mentor a student","mentoring scheme"]},{"id":215,"topic":"edu","w":"tutor","ipa":"/ˈtjuːtə(r)/","pos":"n./v.","cn":"家教；辅导","pun":"丢它","story":"家教说：不会的题别「丢它」，一道一道辅导到会。","ex":"Wealthy families often hire private tutors to give their children an advantage.","exCn":"富裕家庭常聘请私人家教让孩子占得先机。","col":["private tutor","tutor a student","tutoring"]},{"id":216,"topic":"edu","w":"supervisor","ipa":"/ˈsuːpəvaɪzə(r)/","pos":"n.","cn":"导师；监督者","pun":"苏坡歪坐","story":"super（在上）+ vis（看）：导师在「苏坡歪坐」，坐得再歪也在上面看着你。","ex":"Doctoral students meet their supervisor regularly to discuss research progress.","exCn":"博士生定期与导师会面讨论研究进展。","col":["research supervisor","supervise (v.)","supervision (n.)"]},{"id":217,"topic":"edu","w":"diploma","ipa":"/dɪˈpləʊmə/","pos":"n.","cn":"文凭；毕业证","pun":"弟扑楼么","story":"弟弟拿到文凭「弟扑楼么」：兴奋得从楼上扑下来问：这就是毕业证么？","ex":"A vocational diploma can be just as valuable as a university degree.","exCn":"职业文凭可以和大学学位同样有价值。","col":["obtain a diploma","diploma course","diploma in nursing"]},{"id":218,"topic":"edu","w":"qualification","ipa":"/ˌkwɒlɪfɪˈkeɪʃn/","pos":"n.","cn":"资格；学历","pun":"跨了飞凯神","story":"拿到资格证书就「跨了飞凯神」：跨过门槛，飞起来像凯旋的神。","ex":"Employers increasingly value practical experience over formal qualifications.","exCn":"雇主越来越看重实践经验而非正式学历。","col":["academic qualification","gain a qualification","qualify (v.)"]},{"id":219,"topic":"edu","w":"credential","ipa":"/krəˈdenʃl/","pos":"n.","cn":"资历；证书","pun":"可累灯手","story":"证书拿多了「可累灯手」：手举着灯照证书都累了，资历一大堆。","ex":"Graduates with strong academic credentials find it easier to secure employment.","exCn":"学术资历过硬的毕业生更容易获得工作。","col":["academic credentials","credentials check","credentialism"]},{"id":220,"topic":"edu","w":"accredit","ipa":"/əˈkredɪt/","pos":"v.","cn":"认证；授权","pun":"额可累的它","story":"ac（加强）+ credit（信用）：给学校加信用，认证一遍「额可累的它」。","ex":"Only accredited institutions are permitted to award recognised degrees.","exCn":"只有经过认证的机构才被允许授予受认可的学位。","col":["accredited university","accreditation (n.)","accredited course"]},{"id":221,"topic":"edu","w":"institution","ipa":"/ˌɪnstɪˈtjuːʃn/","pos":"n.","cn":"机构；院校","pun":"因死踢丢神","story":"「因死踢丢神」：院校太严格，因为差点被踢出去，吓丢了魂。","ex":"Higher education institutions face growing pressure to demonstrate value for money.","exCn":"高等教育机构面临越来越大的证明性价比的压力。","col":["educational institution","academic institution","institutional"]},{"id":222,"topic":"edu","w":"campus","ipa":"/ˈkæmpəs/","pos":"n.","cn":"校园","pun":"看爬树","story":"校园里最有趣的事是「看爬树」：一群学生围着看谁爬树最快。","ex":"Living on campus allows students to participate fully in university life.","exCn":"住在校园里让学生能充分参与大学生活。","col":["on campus","campus life","university campus"]},{"id":223,"topic":"edu","w":"dormitory","ipa":"/ˈdɔːmətri/","pos":"n.","cn":"宿舍","pun":"到么吹","story":"宿舍里熄灯后「到么吹」：到点了么？还在吹牛，室友根本不睡。","ex":"Sharing a dormitory teaches students to compromise and respect others.","exCn":"合住宿舍教会学生妥协并尊重他人。","col":["dormitory room","university dormitory","dorm (n.)"]},{"id":224,"topic":"edu","w":"semester","ipa":"/sɪˈmestə(r)/","pos":"n.","cn":"学期","pun":"色没死他","story":"一个学期结束，脸「色没死他」：脸色没把他熬死，下学期继续。","ex":"Students typically take four or five modules per semester.","exCn":"学生每学期通常修四到五门课程。","col":["spring semester","semester exam","term"]},{"id":225,"topic":"edu","w":"alumni","ipa":"/əˈlʌmnaɪ/","pos":"n.","cn":"校友","pun":"饿懒奶","story":"校友聚会「饿懒奶」：饿了、懒了，还有奶喝，母校像老奶奶一样管饭。","ex":"Successful alumni often donate generously to their former universities.","exCn":"事业有成的校友常向母校慷慨捐赠。","col":["alumni network","alumni association","alumnus (sing.)"]},{"id":226,"topic":"edu","w":"pupil","ipa":"/ˈpjuːpl/","pos":"n.","cn":"小学生；学生","pun":"皮扑","story":"小学生「皮扑」：一个个调皮得扑来扑去，老师追都追不上。","ex":"Smaller class sizes allow teachers to give each pupil more attention.","exCn":"小班教学让老师能给每个学生更多关注。","col":["primary school pupil","pupil-teacher ratio","student"]},{"id":227,"topic":"edu","w":"adolescent","ipa":"/ˌædəˈlesnt/","pos":"n./adj.","cn":"青少年（的）","pun":"爱多累什么","story":"青少年被问「爱多累什么」：谈恋爱多累啊，你叛逆什么？","ex":"Adolescents are particularly vulnerable to pressure from social media.","exCn":"青少年尤其容易受到社交媒体压力的影响。","col":["adolescent behaviour","adolescence (n.)","teenager"]},{"id":228,"topic":"edu","w":"grade","ipa":"/ɡreɪd/","pos":"n./v.","cn":"分数；年级；评分","pun":"给累的","story":"老师「给累的」学生打分数：熬夜写作业累成这样，分数得给高点。","ex":"Some educators argue that grades create unnecessary competition among pupils.","exCn":"一些教育者认为分数在学生间制造了不必要的竞争。","col":["high grades","grade inflation","grading system"]},{"id":229,"topic":"edu","w":"criteria","ipa":"/kraɪˈtɪəriə/","pos":"n.","cn":"标准；准则","pun":"快提梯儿呀","story":"评分标准是「快提梯儿呀」：达到标准就快给你提个梯子往上爬。","ex":"Examiners apply strict criteria when marking IELTS writing tasks.","exCn":"考官在批改雅思写作时采用严格的评分标准。","col":["assessment criteria","meet the criteria","criterion (sing.)"]},{"id":230,"topic":"edu","w":"rubric","ipa":"/ˈruːbrɪk/","pos":"n.","cn":"评分细则","pun":"入不理课","story":"评分细则写着：「入不理课」，上课不听讲，进门就扣分。","ex":"A clear marking rubric helps students understand what is expected of them.","exCn":"清晰的评分细则帮助学生理解对他们的要求。","col":["marking rubric","scoring rubric","follow the rubric"]},{"id":231,"topic":"edu","w":"feedback","ipa":"/ˈfiːdbæk/","pos":"n.","cn":"反馈","pun":"废的拜客","story":"feed（喂）+ back（回来）：老师把你「废的拜客」作业喂回来，附上反馈。","ex":"Timely feedback is more effective than a grade alone in improving performance.","exCn":"及时反馈比单独打分更能有效提高成绩。","col":["constructive feedback","give feedback","receive feedback"]},{"id":232,"topic":"edu","w":"evaluate","ipa":"/ɪˈvæljueɪt/","pos":"v.","cn":"评价；评估","pun":"一玩就累","story":"评估结果：「一玩就累」，学生一玩手机就累，学习状态被评得很低。","ex":"Teachers should evaluate progress regularly rather than rely on final examinations.","exCn":"教师应定期评估进展，而不是依赖期末考试。","col":["evaluate performance","critically evaluate","evaluation (n.)"]},{"id":233,"topic":"edu","w":"standardised","ipa":"/ˈstændədaɪzd/","pos":"adj.","cn":"标准化的","pun":"死蛋的呆子","story":"标准化考试把学生考成「死蛋的呆子」：答案统一，人也变呆。","ex":"Standardised tests fail to capture creativity and other important qualities.","exCn":"标准化考试无法衡量创造力和其他重要素质。","col":["standardised test","standardised curriculum","standardise (v.)"]},{"id":234,"topic":"edu","w":"invigilate","ipa":"/ɪnˈvɪdʒɪleɪt/","pos":"v.","cn":"监考","pun":"因为几类","story":"监考老师盯着你：「因为几类」作弊手段我都见过，别想耍花样。","ex":"Teachers who invigilate examinations must remain alert to any signs of cheating.","exCn":"监考的教师必须对任何作弊迹象保持警觉。","col":["invigilate an exam","invigilator (n.)","exam supervision"]},{"id":235,"topic":"edu","w":"cram","ipa":"/kræm/","pos":"v.","cn":"临时抱佛脚；塞满","pun":"快啊么","story":"考前一晚「快啊么」：快点背啊，能塞多少塞多少，这就是临时抱佛脚。","ex":"Students who cram the night before an exam rarely retain the information.","exCn":"考前一晚临时抱佛脚的学生很少能记住知识。","col":["cram for an exam","cramming (n.)","cram school"]},{"id":236,"topic":"edu","w":"revise","ipa":"/rɪˈvaɪz/","pos":"v.","cn":"复习；修订","pun":"日歪子","story":"re（再）+ vise（看）：复习就是再看一遍，「日歪子」，把歪掉的知识扶正。","ex":"Pupils are advised to revise a little each day rather than all at once.","exCn":"建议学生每天复习一点，而不是一次性复习完。","col":["revise for an exam","revision (n.)","revise an essay"]},{"id":237,"topic":"edu","w":"procrastinate","ipa":"/prəʊˈkræstɪneɪt/","pos":"v.","cn":"拖延","pun":"抛可拉斯提内","story":"拖延症：作业「抛可拉斯提内」，抛到一边，拉到明天再提。","ex":"Students who procrastinate often produce rushed and poorly structured essays.","exCn":"拖延的学生常写出仓促且结构混乱的文章。","col":["procrastination (n.)","tend to procrastinate","put off"]},{"id":238,"topic":"edu","w":"deadline","ipa":"/ˈdedlaɪn/","pos":"n.","cn":"截止日期","pun":"带的赖","story":"dead（死）+ line（线）：过了这条死线就「带的赖」，赖也赖不掉。","ex":"Meeting deadlines is a skill that university prepares students for.","exCn":"按时完成任务是大学培养学生的一项技能。","col":["meet a deadline","miss the deadline","tight deadline"]},{"id":239,"topic":"edu","w":"assignment","ipa":"/əˈsaɪnmənt/","pos":"n.","cn":"作业；任务","pun":"额赛门特","story":"作业堆成「额赛门特」：额头顶着，赛过门那么高，特别多。","ex":"Written assignments develop the ability to construct a coherent argument.","exCn":"书面作业培养构建连贯论证的能力。","col":["complete an assignment","hand in an assignment","assign (v.)"]},{"id":240,"topic":"edu","w":"coursework","ipa":"/ˈkɔːswɜːk/","pos":"n.","cn":"课程作业","pun":"扣死沃克","story":"course（课程）+ work（作业）：平时作业「扣死沃克」，扣分扣得沃克想哭。","ex":"Coursework allows students to demonstrate skills that exams cannot measure.","exCn":"课程作业让学生展示考试无法衡量的技能。","col":["submit coursework","coursework deadline","assessed coursework"]},{"id":241,"topic":"edu","w":"cite","ipa":"/saɪt/","pos":"v.","cn":"引用","pun":"塞特","story":"写论文引用别人的话，要「塞特」别注明来源，塞进脚注。","ex":"Students must cite all sources correctly to avoid accusations of copying.","exCn":"学生必须正确引用所有来源以避免抄袭指控。","col":["cite a source","citation (n.)","cite evidence"]},{"id":242,"topic":"edu","w":"bibliography","ipa":"/ˌbɪbliˈɒɡrəfi/","pos":"n.","cn":"参考书目","pun":"逼不了哥拉飞","story":"biblio（书）+ graphy（写）：参考书目「逼不了哥拉飞」，书太多逼得哥想飞。","ex":"A comprehensive bibliography demonstrates the depth of a student's research.","exCn":"完整的参考书目显示学生研究的深度。","col":["compile a bibliography","annotated bibliography","reference list"]},{"id":243,"topic":"edu","w":"laboratory","ipa":"/ləˈbɒrətri/","pos":"n.","cn":"实验室","pun":"了不累吹","story":"实验室里「了不累吹」：做完实验一点不累，还能吹一波成果。","ex":"Well-equipped laboratories are essential for teaching practical science.","exCn":"设备完善的实验室对实践科学教学至关重要。","col":["science laboratory","laboratory experiment","lab (n.)"]},{"id":244,"topic":"edu","w":"analytical","ipa":"/ˌænəˈlɪtɪkl/","pos":"adj.","cn":"分析的","pun":"爱那里踢口","story":"分析型的人「爱那里踢口」：爱研究该从哪里踢出突破口。","ex":"University education develops the analytical skills employers value most.","exCn":"大学教育培养雇主最看重的分析能力。","col":["analytical skills","analytical approach","analyse (v.)"]},{"id":245,"topic":"edu","w":"critical thinking","ipa":"/ˌkrɪtɪkl ˈθɪŋkɪŋ/","pos":"n.","cn":"批判性思维","pun":"课题扣心肯","story":"批判性思维：对每个「课题扣心肯」，扣心自问，才肯相信。","ex":"Critical thinking should be taught explicitly from primary school onwards.","exCn":"批判性思维应从小学起就被明确教授。","col":["develop critical thinking","critical thinking skills","think critically"]},{"id":246,"topic":"edu","w":"reasoning","ipa":"/ˈriːzənɪŋ/","pos":"n.","cn":"推理；论证","pun":"日怎宁","story":"推理题「日怎宁」：日子怎么才能安宁？一步步推理才有答案。","ex":"Mathematics trains pupils in logical reasoning and precise thinking.","exCn":"数学训练学生的逻辑推理和精确思维。","col":["logical reasoning","line of reasoning","reason (v.)"]},{"id":247,"topic":"edu","w":"creativity","ipa":"/ˌkriːeɪˈtɪvəti/","pos":"n.","cn":"创造力","pun":"快诶踢我踢","story":"创造力：「快诶踢我踢」，踢来踢去把球踢出新花样。","ex":"Rigid examination systems tend to stifle creativity in young learners.","exCn":"僵化的考试制度往往扼杀年轻学习者的创造力。","col":["foster creativity","stifle creativity","creative (adj.)"]},{"id":248,"topic":"edu","w":"curiosity","ipa":"/ˌkjʊəriˈɒsəti/","pos":"n.","cn":"好奇心","pun":"可有奥赛题","story":"好奇心：「可有奥赛题」？孩子追着老师要奥数题，什么都想知道。","ex":"Good teachers spark curiosity rather than simply transmit information.","exCn":"好老师激发好奇心，而不是单纯传递信息。","col":["intellectual curiosity","satisfy curiosity","curious (adj.)"]},{"id":249,"topic":"edu","w":"inquiry","ipa":"/ɪnˈkwaɪəri/","pos":"n.","cn":"探究；询问","pun":"因快儿理","story":"探究式学习：「因快儿理」，因为想快点弄清道理，孩子自己问自己查。","ex":"Inquiry-based learning encourages pupils to ask their own questions.","exCn":"探究式学习鼓励学生提出自己的问题。","col":["inquiry-based learning","scientific inquiry","inquire (v.)"]},{"id":250,"topic":"edu","w":"interactive","ipa":"/ˌɪntərˈæktɪv/","pos":"adj.","cn":"互动的","pun":"应特爱克踢舞","story":"inter（相互）+ active：互动课堂「应特爱克踢舞」，师生一起踢踏舞。","ex":"Interactive whiteboards have transformed the way lessons are delivered.","exCn":"交互式白板改变了授课方式。","col":["interactive learning","interactive whiteboard","interact (v.)"]},{"id":251,"topic":"edu","w":"engage","ipa":"/ɪnˈɡeɪdʒ/","pos":"v.","cn":"吸引；参与","pun":"应给纸","story":"想让学生参与课堂，「应给纸」：给张纸让他们动手写，注意力就来了。","ex":"Teachers must find ways to engage students who find the subject dull.","exCn":"教师必须想办法吸引觉得这门课枯燥的学生。","col":["engage students","engage in discussion","engagement (n.)"]},{"id":252,"topic":"edu","w":"participate","ipa":"/pɑːˈtɪsɪpeɪt/","pos":"v.","cn":"参加；参与","pun":"怕踢死佩特","story":"参加足球课，「怕踢死佩特」：怕把佩特踢伤，但还是要参与。","ex":"Shy students may be reluctant to participate in class discussions.","exCn":"害羞的学生可能不愿参与课堂讨论。","col":["participate in","active participation","participant (n.)"]},{"id":253,"topic":"edu","w":"attentive","ipa":"/əˈtentɪv/","pos":"adj.","cn":"专注的；细心的","pun":"额疼踢舞","story":"上课专注到「额疼踢舞」：额头都疼了，脚还在桌下不自觉打拍子。","ex":"Attentive pupils absorb far more from a lesson than distracted ones.","exCn":"专注的学生从课堂中吸收的远比走神的多。","col":["attentive listener","pay attention","attention (n.)"]},{"id":254,"topic":"edu","w":"distraction","ipa":"/dɪˈstrækʃn/","pos":"n.","cn":"分心；干扰","pun":"弟死抓可神","story":"dis（分开）+ tract（拉）：注意力被拉开，「弟死抓可神」，弟弟死抓手机不放。","ex":"Smartphones are a major distraction in the modern classroom.","exCn":"智能手机是现代课堂上的主要干扰源。","col":["source of distraction","distract (v.)","distracted (adj.)"]},{"id":255,"topic":"edu","w":"concentration","ipa":"/ˌkɒnsnˈtreɪʃn/","pos":"n.","cn":"专注；专心","pun":"看深穿神","story":"专注到「看深穿神」：看得深，眼神快把书穿透了。","ex":"Regular breaks improve concentration and overall learning outcomes.","exCn":"定期休息能提高专注力和整体学习效果。","col":["lack of concentration","concentration span","concentrate (v.)"]},{"id":256,"topic":"edu","w":"absorb","ipa":"/əbˈzɔːb/","pos":"v.","cn":"吸收；理解","pun":"饿不揍","story":"学生「饿不揍」：饿了也不闹，专心吸收知识，像海绵吸水。","ex":"Young children absorb new languages far more easily than adults.","exCn":"幼儿学习新语言远比成人容易。","col":["absorb information","absorb knowledge","absorption (n.)"]},{"id":257,"topic":"edu","w":"retain","ipa":"/rɪˈteɪn/","pos":"v.","cn":"保留；记住","pun":"日忑","story":"re（回）+ tain（拿住）：记住知识就得「日忑」，每日忐忑地复习才不忘。","ex":"Learners retain more when they explain a concept to someone else.","exCn":"学习者向他人讲解概念时记住的更多。","col":["retain information","retention (n.)","retain staff"]},{"id":258,"topic":"edu","w":"recall","ipa":"/rɪˈkɔːl/","pos":"v./n.","cn":"回忆；记起","pun":"日靠","story":"re（回）+ call（叫）：回忆就是把记忆「日靠」着叫回来。","ex":"Frequent testing helps students recall facts more reliably.","exCn":"频繁测试帮助学生更可靠地回忆事实。","col":["recall information","total recall","recall a name"]},{"id":259,"topic":"edu","w":"reinforce","ipa":"/ˌriːɪnˈfɔːs/","pos":"v.","cn":"强化；加强","pun":"瑞因佛死","story":"re（再）+ in（进）+ force（力）：反复加力，「瑞因佛死」也要把知识强化进脑子。","ex":"Homework reinforces what pupils have learned in class.","exCn":"家庭作业强化学生在课堂上所学的内容。","col":["reinforce learning","positive reinforcement","reinforcement (n.)"]},{"id":260,"topic":"edu","w":"repetition","ipa":"/ˌrepəˈtɪʃn/","pos":"n.","cn":"重复","pun":"热破踢神","story":"重复练习：「热破踢神」，热身踢到破了鞋，踢到出神入化。","ex":"Language learning depends heavily on repetition and regular practice.","exCn":"语言学习高度依赖重复和定期练习。","col":["constant repetition","repeat (v.)","repetitive (adj.)"]},{"id":261,"topic":"edu","w":"drill","ipa":"/drɪl/","pos":"n./v.","cn":"反复操练","pun":"揪哦","story":"操练英语：老师「揪哦」：揪着一个句型练一百遍。","ex":"Grammar drills remain common in many Asian language classrooms.","exCn":"语法操练在许多亚洲语言课堂上仍很常见。","col":["grammar drill","drill students","drill and practice"]},{"id":262,"topic":"edu","w":"instil","ipa":"/ɪnˈstɪl/","pos":"v.","cn":"灌输；逐渐培养","pun":"因死踢哦","story":"in（进）+ stil（滴）：像滴水一样把价值观灌进去，「因死踢哦」，慢慢渗透。","ex":"Schools have a duty to instil respect for others in their pupils.","exCn":"学校有责任在学生中培养对他人的尊重。","col":["instil values","instil confidence","instil discipline"]},{"id":263,"topic":"edu","w":"nurture","ipa":"/ˈnɜːtʃə(r)/","pos":"v./n.","cn":"培养；养育","pun":"呢切","story":"培养孩子像种花：「呢切」，这里剪一下，那里浇点水。","ex":"Teachers play a vital role in nurturing children's talents.","exCn":"教师在培养儿童天赋方面起着至关重要的作用。","col":["nurture talent","nature versus nurture","nurturing environment"]},{"id":264,"topic":"edu","w":"foster","ipa":"/ˈfɒstə(r)/","pos":"v.","cn":"促进；培养","pun":"佛死他","story":"「佛死他」：佛都想拉他一把，促进他成长。","ex":"Group projects foster cooperation and mutual respect among students.","exCn":"小组项目促进学生之间的合作和相互尊重。","col":["foster creativity","foster a sense of","foster independence"]},{"id":265,"topic":"edu","w":"cultivate","ipa":"/ˈkʌltɪveɪt/","pos":"v.","cn":"培养；耕作","pun":"可踢喂它","story":"培养小狗：「可踢喂它」，可以踢球陪它玩，也要按时喂它，慢慢养成。","ex":"Reading widely helps cultivate a sophisticated writing style.","exCn":"广泛阅读有助于培养成熟的写作风格。","col":["cultivate a habit","cultivate skills","cultivation (n.)"]},{"id":266,"topic":"edu","w":"inspire","ipa":"/ɪnˈspaɪə(r)/","pos":"v.","cn":"激励；启发","pun":"因死拜儿","story":"in（进）+ spire（呼吸）：好老师把灵感吹进你心里，「因死拜儿」，感动得想拜他。","ex":"An inspiring teacher can change the course of a child's life.","exCn":"一位鼓舞人心的老师能改变孩子的人生轨迹。","col":["inspire students","inspiration (n.)","inspiring (adj.)"]},{"id":267,"topic":"edu","w":"stimulate","ipa":"/ˈstɪmjuleɪt/","pos":"v.","cn":"激发；刺激","pun":"死挺谬累","story":"激发兴趣：「死挺谬累」，再累也挺住，一激发就来劲。","ex":"Colourful classrooms stimulate young children's interest in learning.","exCn":"色彩丰富的教室激发幼儿的学习兴趣。","col":["stimulate interest","stimulating (adj.)","stimulus (n.)"]},{"id":268,"topic":"edu","w":"competence","ipa":"/ˈkɒmpɪtəns/","pos":"n.","cn":"能力；胜任","pun":"看陪疼死","story":"有能力的人「看陪疼死」：看着难题陪到底，疼死也能搞定。","ex":"Teacher training should focus on developing classroom competence.","exCn":"教师培训应侧重于培养课堂教学能力。","col":["professional competence","competent (adj.)","core competencies"]},{"id":269,"topic":"edu","w":"expertise","ipa":"/ˌekspɜːˈtiːz/","pos":"n.","cn":"专业知识","pun":"爱可死泼踢子","story":"专家「爱可死泼踢子」：爱把专业知识泼给弟子，泼到死也不停。","ex":"Universities benefit from the expertise of visiting scholars from abroad.","exCn":"大学受益于海外访问学者的专业知识。","col":["technical expertise","area of expertise","expert (n.)"]},{"id":270,"topic":"edu","w":"mastery","ipa":"/ˈmɑːstəri/","pos":"n.","cn":"精通；掌握","pun":"妈死特瑞","story":"「妈死特瑞」：妈妈盯着特瑞练琴，练到精通为止。","ex":"True mastery of a language requires years of consistent effort.","exCn":"真正精通一门语言需要多年的持续努力。","col":["mastery of","achieve mastery","master (v.)"]},{"id":271,"topic":"edu","w":"aspiration","ipa":"/ˌæspəˈreɪʃn/","pos":"n.","cn":"抱负；志向","pun":"爱死不累神","story":"有抱负的人「爱死不累神」：为了志向爱学到死也不累，像神一样。","ex":"Schools in deprived areas should raise the aspirations of their pupils.","exCn":"贫困地区的学校应提升学生的志向。","col":["career aspirations","raise aspirations","aspire (v.)"]},{"id":272,"topic":"edu","w":"pursue","ipa":"/pəˈsjuː/","pos":"v.","cn":"追求；从事","pun":"迫求","story":"「迫求」：迫切地追求，一路追着梦想不放手。","ex":"More young people are choosing to pursue degrees in computer science.","exCn":"越来越多年轻人选择攻读计算机科学学位。","col":["pursue a degree","pursue a career","pursuit (n.)"]},{"id":273,"topic":"edu","w":"endeavour","ipa":"/ɪnˈdevə(r)/","pos":"n./v.","cn":"努力；尝试","pun":"因得我","story":"「因得我」：因为想得到，我拼命努力去尝试。","ex":"Learning a musical instrument is a worthwhile endeavour for any child.","exCn":"学一门乐器对任何孩子来说都是值得的努力。","col":["academic endeavour","endeavour to do","human endeavour"]},{"id":274,"topic":"edu","w":"persevere","ipa":"/ˌpɜːsəˈvɪə(r)/","pos":"v.","cn":"坚持不懈","pun":"坡色为儿","story":"per（贯穿）+ severe（严酷）：穿过严酷的「坡色为儿」，爬坡再难也为孩子坚持。","ex":"Students who persevere with difficult subjects often achieve the greatest gains.","exCn":"坚持攻克难科目的学生往往收获最大。","col":["persevere with","perseverance (n.)","persevere despite"]},{"id":275,"topic":"edu","w":"resilience","ipa":"/rɪˈzɪliəns/","pos":"n.","cn":"韧性；恢复力","pun":"日子利恩斯","story":"「日子利恩斯」：日子再苦，利恩斯也能弹回来，这就是韧性。","ex":"Failure in examinations can help build resilience in young people.","exCn":"考试失败能帮助年轻人培养韧性。","col":["build resilience","emotional resilience","resilient (adj.)"]},{"id":276,"topic":"edu","w":"diligent","ipa":"/ˈdɪlɪdʒənt/","pos":"adj.","cn":"勤奋的","pun":"地里真特","story":"「地里真特」：地里干活真特别勤奋，天不亮就下田。","ex":"Diligent students frequently outperform gifted but lazy classmates.","exCn":"勤奋的学生常常胜过有天赋但懒惰的同学。","col":["diligent student","diligence (n.)","work diligently"]},{"id":277,"topic":"edu","w":"conscientious","ipa":"/ˌkɒnʃiˈenʃəs/","pos":"adj.","cn":"认真负责的","pun":"看谁演血丝","story":"认真的人「看谁演血丝」：看谁熬夜熬出血丝，认真到底。","ex":"A conscientious approach to homework pays dividends at examination time.","exCn":"认真对待作业的态度在考试时会得到回报。","col":["conscientious student","conscientiousness (n.)","conscientious worker"]},{"id":278,"topic":"edu","w":"punctual","ipa":"/ˈpʌŋktʃuəl/","pos":"adj.","cn":"守时的","pun":"胖客求","story":"「胖客求」：胖客人求老板准时开门，因为他最守时。","ex":"Schools expect pupils to be punctual and prepared for every lesson.","exCn":"学校要求学生每节课都守时并做好准备。","col":["punctual attendance","punctuality (n.)","be punctual"]},{"id":279,"topic":"edu","w":"rigorous","ipa":"/ˈrɪɡərəs/","pos":"adj.","cn":"严格的；严谨的","pun":"立格若死","story":"「立格若死」：立下严格规矩，谁若违反就死定了。","ex":"Rigorous academic standards ensure that degrees retain their value.","exCn":"严格的学术标准确保学位保持其价值。","col":["rigorous training","rigorous standards","rigour (n.)"]},{"id":280,"topic":"edu","w":"scrutinise","ipa":"/ˈskruːtənaɪz/","pos":"v.","cn":"仔细审查","pun":"死克鲁特奈子","story":"「死克鲁特奈子」：死盯着克鲁特的脑袋子仔细审查，一根头发都不放过。","ex":"Examiners scrutinise every essay for evidence of original thought.","exCn":"考官仔细审查每篇文章以寻找独立思考的证据。","col":["scrutinise closely","scrutiny (n.)","under scrutiny"]},{"id":281,"topic":"edu","w":"selective","ipa":"/sɪˈlektɪv/","pos":"adj.","cn":"选拔性的；挑剔的","pun":"塞累踢舞","story":"select（挑选）：选拔性学校「塞累踢舞」，塞满考试，累到跳踢踏舞。","ex":"Selective schools are accused of entrenching social inequality.","exCn":"选拔性学校被指责固化了社会不平等。","col":["selective school","highly selective","selection (n.)"]},{"id":282,"topic":"edu","w":"elite","ipa":"/ɪˈliːt/","pos":"n./adj.","cn":"精英；精英的","pun":"一粒特","story":"精英就是「一粒特」：一粒特别的米，从一堆米里被挑出来。","ex":"Elite universities continue to admit a disproportionate number of privileged students.","exCn":"精英大学继续录取比例过高的特权阶层学生。","col":["elite university","the educational elite","elitist (adj.)"]},{"id":283,"topic":"edu","w":"prestigious","ipa":"/preˈstɪdʒəs/","pos":"adj.","cn":"有声望的","pun":"扑来死踢这死","story":"名校太有声望，考生「扑来死踢这死」：扑上来抢名额，踢也踢不走。","ex":"Graduates of prestigious institutions often enjoy higher starting salaries.","exCn":"名校毕业生往往享有更高的起薪。","col":["prestigious university","prestige (n.)","prestigious award"]},{"id":284,"topic":"edu","w":"admission","ipa":"/ədˈmɪʃn/","pos":"n.","cn":"录取；入场","pun":"额的米神","story":"ad（向）+ mission（送）：被送进大学，「额的米神」，我的米饭之神保佑录取。","ex":"University admission should be based on ability rather than family background.","exCn":"大学录取应基于能力而非家庭背景。","col":["admission requirements","gain admission","admit (v.)"]},{"id":285,"topic":"edu","w":"competitive","ipa":"/kəmˈpetətɪv/","pos":"adj.","cn":"竞争的","pun":"看陪踢踢舞","story":"竞争激烈：「看陪踢踢舞」，看谁陪你踢完踢踏舞还不倒。","ex":"The competitive nature of entrance examinations places enormous stress on teenagers.","exCn":"入学考试的竞争性给青少年带来巨大压力。","col":["highly competitive","competitive exam","competition (n.)"]},{"id":286,"topic":"edu","w":"merit","ipa":"/ˈmerɪt/","pos":"n./v.","cn":"优点；价值；应得","pun":"美丽特","story":"凭「美丽特」质被录取：不是靠关系，是凭真正的优点。","ex":"Places at top universities should be awarded strictly on merit.","exCn":"顶尖大学的名额应严格按优秀程度授予。","col":["on merit","merit-based","meritocracy (n.)"]},{"id":287,"topic":"edu","w":"meritocracy","ipa":"/ˌmerɪˈtɒkrəsi/","pos":"n.","cn":"精英管理制；能者居上","pun":"美丽拓课日","story":"merit（才能）+ cracy（统治）：靠才能统治，「美丽拓课日」，谁课学得好谁上位。","ex":"Critics argue that a true meritocracy is impossible when schooling is unequal.","exCn":"批评者认为学校教育不平等时真正的精英制不可能实现。","col":["educational meritocracy","meritocratic (adj.)","meritocratic ideal"]},{"id":288,"topic":"edu","w":"privilege","ipa":"/ˈprɪvəlɪdʒ/","pos":"n.","cn":"特权；优势","pun":"扑里为你纸","story":"有特权的人「扑里为你纸」：一扑进来就有人为你递纸，什么都不用做。","ex":"Access to private tutoring remains a privilege of wealthier families.","exCn":"获得私人辅导仍是富裕家庭的特权。","col":["educational privilege","privileged (adj.)","privilege and disadvantage"]},{"id":289,"topic":"edu","w":"disadvantaged","ipa":"/ˌdɪsədˈvɑːntɪdʒd/","pos":"adj.","cn":"弱势的；贫困的","pun":"弟色的玩踢纸","story":"dis（否定）+ advantage（优势）：没优势的「弟色的玩踢纸」，只能踢纸团玩。","ex":"Free school meals are provided to children from disadvantaged backgrounds.","exCn":"为来自弱势背景的儿童提供免费校餐。","col":["disadvantaged children","socially disadvantaged","disadvantage (n.)"]},{"id":290,"topic":"edu","w":"underprivileged","ipa":"/ˌʌndəˈprɪvəlɪdʒd/","pos":"adj.","cn":"贫困的；弱势的","pun":"俺的扑里为你纸的","story":"under（低于）+ privileged：「俺的扑里为你纸的」都没有，处于特权之下。","ex":"Charities run after-school clubs for underprivileged children in inner cities.","exCn":"慈善机构为市中心贫困儿童开办课后俱乐部。","col":["underprivileged children","underprivileged areas","the underprivileged"]},{"id":291,"topic":"edu","w":"accessible","ipa":"/əkˈsesəbl/","pos":"adj.","cn":"可获得的；易接近的","pun":"啊可塞死不","story":"教育要人人可得，「啊可塞死不」：门口不能塞死，谁都进得来。","ex":"Online courses have made higher education accessible to people in remote areas.","exCn":"在线课程让偏远地区的人也能接受高等教育。","col":["accessible to all","access (n.)","accessibility (n.)"]},{"id":292,"topic":"edu","w":"subsidise","ipa":"/ˈsʌbsɪdaɪz/","pos":"v.","cn":"补贴；资助","pun":"傻不死呆子","story":"政府补贴「傻不死呆子」：给学费补贴，再傻的呆子也能读得起书。","ex":"The government should subsidise university fees for students from low-income families.","exCn":"政府应为低收入家庭学生补贴大学学费。","col":["subsidise education","subsidy (n.)","heavily subsidised"]},{"id":293,"topic":"edu","w":"funding","ipa":"/ˈfʌndɪŋ/","pos":"n.","cn":"资金；拨款","pun":"放丁","story":"「放丁」：把钱放给丁老师办学，这就是拨款。","ex":"Cuts in government funding have forced many schools to reduce staff numbers.","exCn":"政府拨款削减迫使许多学校裁减人员。","col":["government funding","public funding","fund (v.)"]},{"id":294,"topic":"edu","w":"grant","ipa":"/ɡrɑːnt/","pos":"n./v.","cn":"助学金；授予","pun":"格软特","story":"拿到助学金「格软特」：格外软和特别开心，学费有着落了。","ex":"Maintenance grants once enabled poorer students to attend university without debt.","exCn":"助学金曾让贫困学生无需负债就能上大学。","col":["student grant","research grant","grant a scholarship"]},{"id":295,"topic":"edu","w":"bursary","ipa":"/ˈbɜːsəri/","pos":"n.","cn":"助学金","pun":"薄色瑞","story":"「薄色瑞」：钱包薄的瑞士学生申请助学金，学校发一笔补助。","ex":"Many universities offer bursaries to attract students from poorer backgrounds.","exCn":"许多大学提供助学金以吸引贫困背景的学生。","col":["receive a bursary","bursary scheme","bursary award"]},{"id":296,"topic":"edu","w":"affordable","ipa":"/əˈfɔːdəbl/","pos":"adj.","cn":"负担得起的","pun":"额否的宝","story":"「额否的宝」：额度否掉了的宝贝不能买，能买的才是负担得起。","ex":"Affordable childcare is essential if parents are to continue their education.","exCn":"若家长要继续深造，可负担的托儿服务至关重要。","col":["affordable education","afford (v.)","affordability (n.)"]},{"id":297,"topic":"edu","w":"state-funded","ipa":"/ˌsteɪt ˈfʌndɪd/","pos":"adj.","cn":"公立的；国家资助的","pun":"死忒放丁的","story":"state（国家）+ funded（拨款）：国家「死忒放丁的」学校，钱全由政府放。","ex":"State-funded schools educate the vast majority of children in the country.","exCn":"公立学校教育着该国绝大多数儿童。","col":["state-funded school","state education","publicly funded"]},{"id":298,"topic":"edu","w":"gap year","ipa":"/ˈɡæp jɪə(r)/","pos":"n.","cn":"间隔年","pun":"盖普耶","story":"「盖普耶」：高中毕业盖上被子睡一年、普天下玩一圈、耶！这就是间隔年。","ex":"Taking a gap year before university can broaden a student's horizons.","exCn":"上大学前休间隔年能拓宽学生的视野。","col":["take a gap year","gap-year travel","year out"]},{"id":299,"topic":"edu","w":"overseas","ipa":"/ˌəʊvəˈsiːz/","pos":"adj./adv.","cn":"海外的；在海外","pun":"欧我谁死","story":"over（越过）+ seas（海）：越过大海去留学，「欧我谁死」：欧洲的我谁也不认识。","ex":"Studying overseas exposes students to different cultures and teaching styles.","exCn":"海外留学让学生接触不同的文化和教学风格。","col":["overseas students","study overseas","overseas education"]},{"id":300,"topic":"edu","w":"exchange programme","ipa":"/ɪksˈtʃeɪndʒ ˌprəʊɡræm/","pos":"n.","cn":"交换项目","pun":"一颗穷纸扑","story":"交换生「一颗穷纸扑」：揣着一颗心和穷学生的一张纸，扑向外国大学。","ex":"Student exchange programmes promote mutual understanding between nations.","exCn":"学生交换项目促进国家间的相互理解。","col":["student exchange programme","join an exchange programme","exchange student"]},{"id":301,"topic":"edu","w":"immersion","ipa":"/ɪˈmɜːʃn/","pos":"n.","cn":"沉浸；浸入","pun":"一没神","story":"沉浸式学英语：「一没神」，一泡进去就没了魂，满脑子英文。","ex":"Language immersion is widely regarded as the fastest route to fluency.","exCn":"语言沉浸被普遍认为是达到流利的最快途径。","col":["language immersion","immersion programme","immerse (v.)"]},{"id":302,"topic":"edu","w":"bilingual","ipa":"/ˌbaɪˈlɪŋɡwəl/","pos":"adj.","cn":"双语的","pun":"拜零狗","story":"bi（二）+ lingual（语言）：会两种语言的狗，「拜零狗」，大家都拜它。","ex":"Bilingual children often demonstrate greater cognitive flexibility.","exCn":"双语儿童通常表现出更强的认知灵活性。","col":["bilingual education","bilingual school","bilingualism (n.)"]},{"id":303,"topic":"edu","w":"fluent","ipa":"/ˈfluːənt/","pos":"adj.","cn":"流利的","pun":"服了嗯特","story":"英语说得太流利，大家「服了嗯特」：服了，嗯，特别服。","ex":"Becoming fluent in a foreign language opens up international career opportunities.","exCn":"流利掌握一门外语能打开国际职业机会。","col":["fluent in English","speak fluently","fluency (n.)"]},{"id":304,"topic":"edu","w":"proficiency","ipa":"/prəˈfɪʃnsi/","pos":"n.","cn":"熟练；精通","pun":"扑飞神死","story":"熟练到「扑飞神死」：一扑一飞，神仙看了都佩服死。","ex":"Universities require proof of English proficiency from international applicants.","exCn":"大学要求国际申请者提供英语熟练度证明。","col":["language proficiency","proficiency test","proficient (adj.)"]},{"id":305,"topic":"edu","w":"acquire","ipa":"/əˈkwaɪə(r)/","pos":"v.","cn":"获得；习得","pun":"额快儿","story":"「额快儿」：额头一亮，快速习得了新技能。","ex":"Children acquire their first language without any formal instruction.","exCn":"儿童无需任何正式教学就能习得母语。","col":["acquire knowledge","acquire skills","acquisition (n.)"]},{"id":306,"topic":"edu","w":"mother tongue","ipa":"/ˈmʌðə tʌŋ/","pos":"n.","cn":"母语","pun":"妈的躺","story":"「妈的躺」：躺在妈妈怀里学会的语言，就是母语。","ex":"Pupils should be allowed to learn in their mother tongue during the early years.","exCn":"学生在早期应被允许用母语学习。","col":["mother-tongue education","native language","first language"]},{"id":307,"topic":"edu","w":"dropout","ipa":"/ˈdrɒpaʊt/","pos":"n.","cn":"辍学者；辍学","pun":"揍炮凹特","story":"drop（掉）+ out（出）：从学校掉出去，「揍炮凹特」，被揍得凹进去。","ex":"High dropout rates suggest that many students feel alienated by the school system.","exCn":"高辍学率表明许多学生对学校系统感到疏离。","col":["dropout rate","school dropout","drop out (v.)"]},{"id":308,"topic":"edu","w":"truancy","ipa":"/ˈtruːənsi/","pos":"n.","cn":"逃学","pun":"出恩死","story":"逃学「出恩死」：出了校门，恩师气得要死。","ex":"Persistent truancy is often a sign of problems at home.","exCn":"长期逃学往往是家庭问题的迹象。","col":["truancy rate","play truant","truant (n.)"]},{"id":309,"topic":"edu","w":"absenteeism","ipa":"/ˌæbsənˈtiːɪzəm/","pos":"n.","cn":"旷课；缺勤","pun":"爱不三踢一贼么","story":"absent（缺席）+ ism：旷课「爱不三踢一贼么」：三天两头不来，是贼么？","ex":"Schools are tackling absenteeism by contacting parents on the first day of absence.","exCn":"学校通过在缺勤第一天联系家长来应对旷课问题。","col":["pupil absenteeism","reduce absenteeism","absentee (n.)"]},{"id":310,"topic":"edu","w":"bully","ipa":"/ˈbʊli/","pos":"v./n.","cn":"欺凌；霸凌者","pun":"不理","story":"霸凌者欺负人，别人「不理」他，他更来劲。","ex":"Schools must adopt a zero-tolerance policy towards bullying.","exCn":"学校必须对欺凌采取零容忍政策。","col":["bullying (n.)","cyberbullying","bully victims"]},{"id":311,"topic":"edu","w":"expel","ipa":"/ɪkˈspel/","pos":"v.","cn":"开除","pun":"一可死拍","story":"ex（出）+ pel（推）：推出校门，「一可死拍」，一巴掌拍出去开除。","ex":"Pupils are rarely expelled unless they pose a danger to others.","exCn":"除非对他人构成危险，学生很少被开除。","col":["expel from school","expulsion (n.)","be expelled"]},{"id":312,"topic":"edu","w":"suspend","ipa":"/səˈspend/","pos":"v.","cn":"停学；暂停","pun":"色死喷的","story":"sus（下）+ pend（挂）：挂起来暂停，「色死喷的」，脸色难看得像被喷了，被停学了。","ex":"Students who repeatedly disrupt lessons may be suspended for several days.","exCn":"屡次扰乱课堂的学生可能被停学数天。","col":["suspend from school","suspension (n.)","temporarily suspended"]},{"id":313,"topic":"edu","w":"corporal punishment","ipa":"/ˌkɔːpərəl ˈpʌnɪʃmənt/","pos":"n.","cn":"体罚","pun":"扣坡怕你什么","story":"体罚：「扣坡怕你什么」，老师扣着戒尺问：你怕什么？现在多数国家禁止。","ex":"Corporal punishment has been banned in schools across most of Europe.","exCn":"欧洲大部分国家已在学校禁止体罚。","col":["ban corporal punishment","physical punishment","punish (v.)"]},{"id":314,"topic":"edu","w":"reward","ipa":"/rɪˈwɔːd/","pos":"n./v.","cn":"奖励；报酬","pun":"日我的","story":"「日我的」：每日我得一颗小红星，这是老师给的奖励。","ex":"Rewarding effort rather than results encourages a growth mindset.","exCn":"奖励努力而非结果能培养成长型思维。","col":["reward good behaviour","rewarding (adj.)","reward system"]},{"id":315,"topic":"edu","w":"lenient","ipa":"/ˈliːniənt/","pos":"adj.","cn":"宽容的；仁慈的","pun":"李你恩特","story":"「李你恩特」：李老师对你特别有恩，罚得特别宽松。","ex":"Some argue that lenient teachers fail to prepare pupils for the real world.","exCn":"有人认为宽松的老师无法让学生为现实世界做好准备。","col":["lenient approach","leniency (n.)","too lenient"]},{"id":316,"topic":"edu","w":"authoritarian","ipa":"/ɔːˌθɒrɪˈteəriən/","pos":"adj.","cn":"专制的；独裁的","pun":"哦搜里泰瑞恩","story":"专制的老师「哦搜里泰瑞恩」：哦，搜你的书包，泰瑞恩也不例外，谁都不许说话。","ex":"Authoritarian teaching styles tend to discourage questioning and debate.","exCn":"专制的教学风格往往压制提问和辩论。","col":["authoritarian parenting","authoritarian regime","authority (n.)"]},{"id":317,"topic":"edu","w":"autonomy","ipa":"/ɔːˈtɒnəmi/","pos":"n.","cn":"自主；自治","pun":"我躺你米","story":"auto（自己）+ nomy（管理）：自己管自己，「我躺你米」，我躺着吃你的米也没人管。","ex":"Giving learners more autonomy increases their sense of responsibility.","exCn":"给予学习者更多自主权能增强他们的责任感。","col":["learner autonomy","autonomous (adj.)","academic autonomy"]},{"id":318,"topic":"edu","w":"self-directed","ipa":"/ˌself dɪˈrektɪd/","pos":"adj.","cn":"自主的；自我导向的","pun":"塞夫敌来克特的","story":"self（自己）+ directed（指导）：自己指导自己，「塞夫敌来克特的」，敌人来了自己克。","ex":"Self-directed learning is a vital skill in an age of rapidly changing knowledge.","exCn":"在知识快速变化的时代，自主学习是一项重要技能。","col":["self-directed learning","self-directed study","self-study"]},{"id":319,"topic":"edu","w":"lifelong learning","ipa":"/ˌlaɪflɒŋ ˈlɜːnɪŋ/","pos":"n.","cn":"终身学习","pun":"来夫龙冷宁","story":"life（一生）+ long（长）：一辈子学，「来夫龙冷宁」，来福龙再冷也宁愿学。","ex":"Lifelong learning enables workers to adapt to changes in the labour market.","exCn":"终身学习让劳动者能适应劳动力市场的变化。","col":["promote lifelong learning","lifelong learner","continuing education"]},{"id":320,"topic":"edu","w":"distance learning","ipa":"/ˈdɪstəns ˌlɜːnɪŋ/","pos":"n.","cn":"远程教育","pun":"弟死疼死冷宁","story":"远程学习：「弟死疼死冷宁」，弟弟离得远，疼死也宁愿在家学。","ex":"Distance learning has made degrees available to people who work full-time.","exCn":"远程教育让全职工作者也能攻读学位。","col":["distance learning course","distance education","remote learning"]},{"id":321,"topic":"edu","w":"e-learning","ipa":"/ˈiː lɜːnɪŋ/","pos":"n.","cn":"在线学习","pun":"衣冷宁","story":"e（电子）+ learning：穿着「衣冷宁」，衣服冷也宁愿在网上学。","ex":"E-learning platforms allow students to progress at their own pace.","exCn":"在线学习平台让学生按自己的节奏进步。","col":["e-learning platform","online learning","e-learning tools"]},{"id":322,"topic":"edu","w":"attendance","ipa":"/əˈtendəns/","pos":"n.","cn":"出勤；出席","pun":"额疼登死","story":"出勤率：「额疼登死」，额头疼也要来登记，出勤到死。","ex":"Regular attendance is strongly linked to higher examination results.","exCn":"稳定的出勤率与更高的考试成绩密切相关。","col":["school attendance","attendance rate","attend (v.)"]},{"id":323,"topic":"edu","w":"specialise","ipa":"/ˈspeʃəlaɪz/","pos":"v.","cn":"专攻；专门从事","pun":"死拍手来子","story":"专攻一门：「死拍手来子」，死拍手叫好，一门专业练到底。","ex":"Many students specialise too early, before discovering their true interests.","exCn":"许多学生在发现真正兴趣之前就过早专攻某一领域。","col":["specialise in","specialist (n.)","specialisation (n.)"]},{"id":324,"topic":"edu","w":"elective","ipa":"/ɪˈlektɪv/","pos":"n./adj.","cn":"选修课；选修的","pun":"一来克踢舞","story":"elect（选）：选修课「一来克踢舞」，一来就选踢踏舞课。","ex":"Offering a wide range of electives allows pupils to explore their interests.","exCn":"提供广泛的选修课让学生探索自己的兴趣。","col":["elective course","take an elective","optional subject"]},{"id":325,"topic":"edu","w":"humanities","ipa":"/hjuːˈmænətiz/","pos":"n.","cn":"人文学科","pun":"休妈你踢子","story":"human（人）：人文学科「休妈你踢子」，研究人的学问，休息时妈妈踢你去读书。","ex":"Funding for the humanities has declined as governments prioritise science.","exCn":"随着政府优先发展科学，人文学科的资金减少了。","col":["study humanities","arts and humanities","humanities subjects"]},{"id":326,"topic":"edu","w":"philosophy","ipa":"/fəˈlɒsəfi/","pos":"n.","cn":"哲学；理念","pun":"非老色飞","story":"philo（爱）+ sophy（智慧）：爱智慧，「非老色飞」，非得老了才悟出来飞。","ex":"Teaching philosophy in schools helps children reason more clearly.","exCn":"在学校教哲学有助于孩子更清晰地推理。","col":["educational philosophy","philosophy of education","philosophical (adj.)"]},{"id":327,"topic":"edu","w":"illiterate","ipa":"/ɪˈlɪtərət/","pos":"adj.","cn":"不识字的","pun":"一里特累特","story":"il（不）+ literate（识字）：不识字，走「一里特累特」，路牌都看不懂。","ex":"Millions of adults worldwide remain functionally illiterate.","exCn":"全球数百万成年人仍处于功能性文盲状态。","col":["functionally illiterate","illiteracy (n.)","illiterate adults"]},{"id":328,"topic":"edu","w":"gifted","ipa":"/ˈɡɪftɪd/","pos":"adj.","cn":"有天赋的","pun":"给福踢的","story":"gift（礼物）：老天「给福踢的」，天赋是老天踢过来的礼物。","ex":"Gifted children may become bored if lessons are not sufficiently challenging.","exCn":"有天赋的孩子如果课程不够有挑战性可能会感到无聊。","col":["gifted children","gifted and talented","gift (n.)"]},{"id":329,"topic":"edu","w":"mediocre","ipa":"/ˌmiːdiˈəʊkə(r)/","pos":"adj.","cn":"平庸的","pun":"米滴欧克","story":"「米滴欧克」：一滴米都要欧克，成绩不好不坏，平庸得很。","ex":"Mediocre teaching is often the result of inadequate training and support.","exCn":"平庸的教学往往是培训和支持不足的结果。","col":["mediocre results","mediocrity (n.)","mediocre performance"]},{"id":330,"topic":"edu","w":"underachieve","ipa":"/ˌʌndərəˈtʃiːv/","pos":"v.","cn":"表现不佳","pun":"俺得吃夫","story":"under（低于）+ achieve（达成）：「俺得吃夫」，俺得先吃饭再努力，一直低于水平。","ex":"Boys are more likely than girls to underachieve at secondary school.","exCn":"男孩在中学比女孩更容易表现不佳。","col":["underachieving pupils","underachievement (n.)","underachiever"]},{"id":331,"topic":"edu","w":"excel","ipa":"/ɪkˈsel/","pos":"v.","cn":"擅长；出类拔萃","pun":"一可塞哦","story":"ex（超出）+ cel（高）：高出一截，「一可塞哦」，一下子塞到第一名。","ex":"Some pupils excel in sport while struggling with academic subjects.","exCn":"有些学生擅长运动却在学术科目上吃力。","col":["excel at","excel in","excellence (n.)"]},{"id":332,"topic":"edu","w":"outstanding","ipa":"/aʊtˈstændɪŋ/","pos":"adj.","cn":"杰出的","pun":"奥特死等丁","story":"out（外）+ standing（站）：站在人群外，「奥特死等丁」，奥特曼等着丁老师表扬。","ex":"Schools rated outstanding attract far more applications than places available.","exCn":"被评为杰出的学校收到的申请远超可提供的名额。","col":["outstanding achievement","outstanding school","stand out (v.)"]},{"id":333,"topic":"edu","w":"hands-on","ipa":"/ˌhændz ˈɒn/","pos":"adj.","cn":"动手的；实践的","pun":"汉子昂","story":"hands（手）+ on（上）：动手实践，「汉子昂」，汉子昂着头亲自干。","ex":"Hands-on experience is far more memorable than reading from a textbook.","exCn":"动手实践比读课本更让人印象深刻。","col":["hands-on experience","hands-on learning","practical work"]},{"id":334,"topic":"edu","w":"apprenticeship","ipa":"/əˈprentɪʃɪp/","pos":"n.","cn":"学徒期；学徒制","pun":"额扑人踢薯片","story":"学徒「额扑人踢薯片」：跟着师傅学，先扑地擦、再学踢薯片，边干边学。","ex":"Apprenticeships combine paid work with structured training.","exCn":"学徒制把有薪工作与系统培训结合起来。","col":["serve an apprenticeship","apprentice (n.)","apprenticeship scheme"]},{"id":335,"topic":"edu","w":"internship","ipa":"/ˈɪntɜːnʃɪp/","pos":"n.","cn":"实习","pun":"因疼薯片","story":"实习生「因疼薯片」：因为工资太少，饭钱都心疼，只吃薯片。","ex":"An internship provides valuable insight into a chosen profession.","exCn":"实习为了解所选职业提供了宝贵的洞察。","col":["summer internship","intern (n.)","work placement"]},{"id":336,"topic":"edu","w":"homeschooling","ipa":"/ˈhəʊmskuːlɪŋ/","pos":"n.","cn":"在家教育","pun":"轰死顾灵","story":"home（家）+ schooling：在家上课，「轰死顾灵」，家里轰轰烈烈地给顾灵讲课。","ex":"Homeschooling has grown in popularity but raises concerns about socialisation.","exCn":"在家教育日益流行，但引发了对社交能力的担忧。","col":["opt for homeschooling","homeschool (v.)","home education"]},{"id":337,"topic":"edu","w":"inclusive","ipa":"/ɪnˈkluːsɪv/","pos":"adj.","cn":"包容的；全纳的","pun":"因苦鲁死舞","story":"in（进）+ clus（关）：把所有人都关进来，「因苦鲁死舞」，苦一点也一起跳舞。","ex":"Inclusive education seeks to teach children with and without disabilities together.","exCn":"全纳教育旨在让残障与非残障儿童一起学习。","col":["inclusive education","inclusion (n.)","inclusive classroom"]},{"id":338,"topic":"edu","w":"special needs","ipa":"/ˌspeʃl ˈniːdz/","pos":"n.","cn":"特殊教育需求","pun":"死拍手你子","story":"「死拍手你子」：特殊需求的孩子进步了，老师使劲拍手鼓励你。","ex":"Children with special needs require additional support to reach their potential.","exCn":"有特殊需求的儿童需要额外支持才能发挥潜力。","col":["special needs education","special educational needs","learning difficulties"]},{"id":339,"topic":"edu","w":"dyslexia","ipa":"/dɪsˈleksiə/","pos":"n.","cn":"阅读障碍","pun":"弟死累可谁呀","story":"dys（困难）+ lex（词）：读词困难，「弟死累可谁呀」，弟弟读到死也认不出是谁。","ex":"Early screening for dyslexia allows teachers to intervene before pupils fall behind.","exCn":"早期阅读障碍筛查让教师能在学生落后前干预。","col":["diagnosed with dyslexia","dyslexic (adj.)","learning disability"]},{"id":340,"topic":"edu","w":"mixed-ability","ipa":"/ˌmɪkst əˈbɪləti/","pos":"adj.","cn":"混合能力的","pun":"米克死特饿逼累踢","story":"mixed（混合）+ ability：混合班「米克死特饿逼累踢」，好生差生一起饿一起累。","ex":"Mixed-ability classes benefit weaker students without holding back the strongest.","exCn":"混合能力班级有利于较弱学生，也不拖累最强的学生。","col":["mixed-ability class","mixed-ability teaching","ability grouping"]},{"id":341,"topic":"edu","w":"workload","ipa":"/ˈwɜːkləʊd/","pos":"n.","cn":"工作量","pun":"沃克楼的","story":"work（工作）+ load（负荷）：「沃克楼的」，沃克的作业堆得像楼一样高。","ex":"Excessive workload is a major reason why teachers leave the profession.","exCn":"过重的工作量是教师离职的主要原因。","col":["heavy workload","reduce workload","manage workload"]},{"id":342,"topic":"edu","w":"burnout","ipa":"/ˈbɜːnaʊt/","pos":"n.","cn":"倦怠；精疲力竭","pun":"笨凹特","story":"burn（烧）+ out（尽）：烧尽了，「笨凹特」，累到变笨脸都凹了。","ex":"Academic pressure is leading to burnout among teenagers in many countries.","exCn":"学业压力正导致许多国家的青少年出现倦怠。","col":["teacher burnout","suffer burnout","burn out (v.)"]},{"id":343,"topic":"edu","w":"wellbeing","ipa":"/ˌwelˈbiːɪŋ/","pos":"n.","cn":"幸福；健康","pun":"喂哦必赢","story":"well（好）+ being（存在）：活得好，「喂哦必赢」，喂饱了必定赢。","ex":"Schools are placing greater emphasis on pupils' mental wellbeing.","exCn":"学校越来越重视学生的心理健康。","col":["student wellbeing","emotional wellbeing","health and wellbeing"]},{"id":344,"topic":"edu","w":"counsellor","ipa":"/ˈkaʊnsələ(r)/","pos":"n.","cn":"辅导员；咨询师","pun":"考试了","story":"「考试了」！焦虑的学生跑去找辅导员谈心。","ex":"Every secondary school should employ a trained counsellor.","exCn":"每所中学都应聘用受过培训的辅导员。","col":["school counsellor","career counsellor","counselling (n.)"]},{"id":345,"topic":"edu","w":"employability","ipa":"/ɪmˌplɔɪəˈbɪləti/","pos":"n.","cn":"就业能力","pun":"因扑漏一比累踢","story":"employ（雇用）+ ability：就业能力强，「因扑漏一比累踢」，一比就把别人踢下去。","ex":"Universities are under pressure to improve graduate employability.","exCn":"大学面临提高毕业生就业能力的压力。","col":["graduate employability","employability skills","employable (adj.)"]},{"id":346,"topic":"edu","w":"transferable skills","ipa":"/trænsˌfɜːrəbl ˈskɪlz/","pos":"n.","cn":"可迁移技能","pun":"穿死佛肉不死给哦","story":"transfer（转移）+ able：能带走的技能，「穿死佛肉不死给哦」，换工作也带得走。","ex":"Group work develops transferable skills such as communication and leadership.","exCn":"小组合作培养沟通和领导等可迁移技能。","col":["develop transferable skills","soft skills","transfer (v.)"]},{"id":347,"topic":"edu","w":"collaborate","ipa":"/kəˈlæbəreɪt/","pos":"v.","cn":"合作","pun":"可乐不累特","story":"col（共同）+ labor（劳动）：一起干活，「可乐不累特」，有可乐喝一点也不累。","ex":"Students who collaborate on projects learn to value different viewpoints.","exCn":"在项目中合作的学生学会重视不同观点。","col":["collaborate with","collaboration (n.)","collaborative learning"]},{"id":348,"topic":"edu","w":"articulate","ipa":"/ɑːˈtɪkjuleɪt/","pos":"v./adj.","cn":"清晰表达；口齿伶俐的","pun":"啊踢球累特","story":"「啊踢球累特」：踢球累了，还能清晰地表达自己为什么累，口齿伶俐。","ex":"Debating clubs help students articulate their ideas with confidence.","exCn":"辩论社帮助学生自信地清晰表达想法。","col":["articulate ideas","articulate speaker","articulation (n.)"]},{"id":349,"topic":"edu","w":"tailor","ipa":"/ˈteɪlə(r)/","pos":"v./n.","cn":"量身定制；裁缝","pun":"太乐","story":"裁缝量身定制衣服，穿上「太乐」了，教学也该按学生量身定制。","ex":"Technology allows teachers to tailor lessons to individual needs.","exCn":"技术让教师能根据个体需求定制课程。","col":["tailor to","tailored (adj.)","tailor-made"]},{"id":350,"topic":"edu","w":"league table","ipa":"/ˈliːɡ ˌteɪbl/","pos":"n.","cn":"排名表；排行榜","pun":"立刻太薄","story":"排行榜一出，「立刻太薄」：排名靠后的学校脸皮立刻变薄，压力山大。","ex":"School league tables encourage teaching to the test rather than genuine learning.","exCn":"学校排行榜鼓励应试教学而非真正的学习。","col":["school league table","top of the league table","ranking (n.)"]},{"id":351,"topic":"tech","w":"innovation","ipa":"/ˌɪnəˈveɪʃn/","pos":"n.","cn":"创新","pun":"in 呢为新","story":"「in」（里面）「呢」，为了「新」——从里面翻出新东西，就是创新。","ex":"Technological innovation has transformed the way we communicate.","exCn":"技术创新改变了我们的交流方式。","col":["technological innovation","encourage innovation","innovative (adj.)"]},{"id":352,"topic":"tech","w":"artificial","ipa":"/ˌɑːtɪˈfɪʃl/","pos":"adj.","cn":"人造的；人工的","pun":"阿提 fish 哦","story":"「阿提」提着一条假「fish」，「哦」，原来是人造的。","ex":"Artificial intelligence is likely to replace many routine jobs.","exCn":"人工智能可能会取代许多重复性工作。","col":["artificial intelligence (AI)","artificial light","artificial flavours"]},{"id":353,"topic":"tech","w":"automation","ipa":"/ˌɔːtəˈmeɪʃn/","pos":"n.","cn":"自动化","pun":"奥特美神","story":"「奥特」曼一秒「美」丽变「神」，全自动，不用手动。","ex":"Automation in factories has led to job losses among unskilled workers.","exCn":"工厂自动化导致非技术工人失业。","col":["automation of manufacturing","automate (v.)","automated systems"]},{"id":354,"topic":"tech","w":"obsolete","ipa":"/ˈɒbsəliːt/","pos":"adj.","cn":"过时的；淘汰的","pun":"哦不 so 累特","story":"「哦不」，这方法「so 累特」（太累了），早该淘汰了。","ex":"Many skills will become obsolete as technology develops.","exCn":"随着技术发展，许多技能会变得过时。","col":["become obsolete","obsolete technology","render sth obsolete"]},{"id":355,"topic":"tech","w":"surveillance","ipa":"/sɜːˈveɪləns/","pos":"n.","cn":"监视；监控","pun":"瑟微冷死","story":"被摄像头盯着，「瑟瑟」发抖，「微」微「冷死」了。","ex":"Mass surveillance raises serious concerns about privacy.","exCn":"大规模监控引发了对隐私的严重担忧。","col":["surveillance cameras","under surveillance","mass surveillance"]},{"id":356,"topic":"tech","w":"cyber","ipa":"/ˈsaɪbə(r)/","pos":"adj.","cn":"网络的","pun":"赛博","story":"「赛博」朋克——就是网络世界的那种朋克风。","ex":"Cyber attacks on banks are becoming more sophisticated.","exCn":"针对银行的网络攻击越来越复杂。","col":["cyber attack / crime","cyber security","cyberbullying 网络霸凌"]},{"id":357,"topic":"tech","w":"breakthrough","ipa":"/ˈbreɪkθruː/","pos":"n.","cn":"突破","pun":"不累克死路","story":"break（打破）+ through（穿过）：「不累」，「克」掉「死路」冲过去——突破！","ex":"Scientists have made a major breakthrough in cancer treatment.","exCn":"科学家在癌症治疗上取得重大突破。","col":["make a breakthrough","a major / scientific breakthrough"]},{"id":358,"topic":"tech","w":"addictive","ipa":"/əˈdɪktɪv/","pos":"adj.","cn":"使人上瘾的","pun":"呃弟可提夫","story":"「呃」，「弟」弟「可提夫」——手机一天到晚提在手里，上瘾了。","ex":"Social media is designed to be addictive.","exCn":"社交媒体的设计就是为了让人上瘾。","col":["highly addictive","addiction (n.)","addicted to (adj.)"]},{"id":359,"topic":"tech","w":"efficiency","ipa":"/ɪˈfɪʃnsi/","pos":"n.","cn":"效率","pun":"一飞神速","story":"「一飞」就是「神速」——效率高得飞起。","ex":"Computers have greatly improved the efficiency of office work.","exCn":"计算机大大提高了办公效率。","col":["improve efficiency","energy efficiency","efficient (adj.)"]},{"id":360,"topic":"tech","w":"virtual","ipa":"/ˈvɜːtʃuəl/","pos":"adj.","cn":"虚拟的","pun":"我戳哦","story":"「我戳」一下，「哦」，手穿过去了——原来是虚拟的。","ex":"Virtual classrooms allow students to learn from anywhere.","exCn":"虚拟课堂让学生可以在任何地方学习。","col":["virtual reality (VR)","virtual classroom","virtually (adv.) 几乎"]},{"id":361,"topic":"health","w":"obesity","ipa":"/əʊˈbiːsəti/","pos":"n.","cn":"肥胖（症）","pun":"哦比死弟","story":"「哦」，「比」谁都胖的「死弟」弟，胖得爬不起来。","ex":"Childhood obesity has doubled in the last twenty years.","exCn":"儿童肥胖率在过去二十年翻了一倍。","col":["childhood obesity","obesity rates","obese (adj.)"]},{"id":362,"topic":"health","w":"nutrition","ipa":"/njuˈtrɪʃn/","pos":"n.","cn":"营养","pun":"牛吹神","story":"「牛」奶广告把营养「吹」上「神」坛。","ex":"Good nutrition is essential for children's development.","exCn":"良好的营养对儿童发育至关重要。","col":["poor / good nutrition","nutritious (adj.)","nutritional value"]},{"id":363,"topic":"health","w":"sedentary","ipa":"/ˈsedntri/","pos":"adj.","cn":"久坐的","pun":"傻等吹","story":"「傻傻」地坐着「等」空调「吹」，一坐一整天。","ex":"A sedentary lifestyle increases the risk of heart disease.","exCn":"久坐的生活方式会增加心脏病风险。","col":["sedentary lifestyle","sedentary jobs"]},{"id":364,"topic":"health","w":"epidemic","ipa":"/ˌepɪˈdemɪk/","pos":"n.","cn":"流行病；泛滥","pun":"哎病得密集","story":"「哎」，「病得」太「密集」了，一片一片倒——流行病。","ex":"Obesity has become an epidemic in many developed countries.","exCn":"肥胖在许多发达国家已成为一种流行病。","col":["an epidemic of sth","flu epidemic","pandemic 大流行"]},{"id":365,"topic":"health","w":"immune","ipa":"/ɪˈmjuːn/","pos":"adj.","cn":"免疫的；不受影响的","pun":"一秒 immune","story":"抗体「一秒」（i-mmune）上线，病毒立刻免疫。","ex":"Regular exercise strengthens the immune system.","exCn":"规律运动增强免疫系统。","col":["immune system","immune to sth","immunity (n.)"]},{"id":366,"topic":"health","w":"diagnose","ipa":"/ˈdaɪəɡnəʊz/","pos":"v.","cn":"诊断","pun":"呆哥 no 死","story":"医生一诊断：「呆哥」，「no」，不会「死」，放心。","ex":"Early diagnosis can greatly improve survival rates.","exCn":"早期诊断能大大提高存活率。","col":["be diagnosed with","diagnosis (n.)","early diagnosis"]},{"id":367,"topic":"health","w":"symptom","ipa":"/ˈsɪmptəm/","pos":"n.","cn":"症状","pun":"新疼","story":"身上出现「新」的「疼」，那就是症状。","ex":"Fatigue is a common symptom of stress.","exCn":"疲劳是压力的常见症状。","col":["show symptoms","a symptom of","symptoms include..."]},{"id":368,"topic":"health","w":"hygiene","ipa":"/ˈhaɪdʒiːn/","pos":"n.","cn":"卫生","pun":"嗨，净！","story":"「嗨」，「净」一点——讲卫生！","ex":"Poor hygiene in hospitals can spread infections.","exCn":"医院卫生条件差会传播感染。","col":["personal hygiene","poor hygiene","hygienic (adj.)"]},{"id":369,"topic":"health","w":"therapy","ipa":"/ˈθerəpi/","pos":"n.","cn":"治疗；疗法","pun":"赛拉皮","story":"去做「拉皮」的疗法，比「赛」谁更年轻。","ex":"Music therapy is increasingly used to treat anxiety.","exCn":"音乐疗法越来越多地用于治疗焦虑。","col":["physical therapy","undergo therapy","therapist (n.)"]},{"id":370,"topic":"health","w":"fatigue","ipa":"/fəˈtiːɡ/","pos":"n.","cn":"疲劳","pun":"乏提个","story":"「乏」得连「个」头都「提」不起来——疲劳。","ex":"Long working hours often result in chronic fatigue.","exCn":"长时间工作常导致慢性疲劳。","col":["chronic fatigue","suffer from fatigue","mental fatigue"]},{"id":371,"topic":"health","w":"pandemic","ipa":"/pænˈdemɪk/","pos":"n.","cn":"（全球性）大流行病","pun":"盼得米克","story":"pan-（全部）+ demic（人民）：全世界的人都被传染，只能「盼得米克」（盼着口罩和药）——大流行病。","ex":"The pandemic exposed serious weaknesses in public health systems around the world.","exCn":"这场大流行病暴露了世界各地公共卫生体系的严重缺陷。","col":["global pandemic","during the pandemic","epidemic"]},{"id":372,"topic":"health","w":"outbreak","ipa":"/ˈaʊtbreɪk/","pos":"n.","cn":"（疾病）爆发；突发","pun":"奥特不累客","story":"out（出）+ break（爆）：病毒像奥特曼一样「奥特不累客」，一下子冲出来——疫情爆发。","ex":"An outbreak of cholera was reported in the region after the floods.","exCn":"洪水过后，该地区报告了霍乱爆发。","col":["outbreak of disease","contain an outbreak","break out"]},{"id":373,"topic":"health","w":"infection","ipa":"/ɪnˈfekʃn/","pos":"n.","cn":"感染；传染病","pun":"印飞克心","story":"细菌「印飞克心」——像印章一样飞进你的身体盖在心上，这就是感染。","ex":"Frequent handwashing remains one of the most effective ways to prevent infection.","exCn":"勤洗手仍然是预防感染最有效的方法之一。","col":["risk of infection","viral infection","infect"]},{"id":374,"topic":"health","w":"infectious","ipa":"/ɪnˈfekʃəs/","pos":"adj.","cn":"传染性的","pun":"印飞克射死","story":"infect + -ious：病菌「印飞克射死」，射向谁谁就中招——传染性极强。","ex":"Infectious diseases spread rapidly in overcrowded urban areas with poor sanitation.","exCn":"在卫生条件差的拥挤城区，传染病传播迅速。","col":["infectious disease","highly infectious","contagious"]},{"id":375,"topic":"health","w":"contagious","ipa":"/kənˈteɪdʒəs/","pos":"adj.","cn":"接触传染的","pun":"啃得急死","story":"一个人「啃得急死」，另一个人碰一下也开始啃——一碰就传染，接触传染的。","ex":"Patients with contagious illnesses should be kept apart from other hospital visitors.","exCn":"患有接触传染病的病人应与其他医院访客隔开。","col":["highly contagious","contagious disease","contagion"]},{"id":376,"topic":"health","w":"transmit","ipa":"/trænzˈmɪt/","pos":"v.","cn":"传播；传染","pun":"穿字米特","story":"trans-（穿过）+ mit（送）：病毒「穿字米特」，穿过人群一米一米地送过去——传播。","ex":"Malaria is transmitted to humans through the bite of infected mosquitoes.","exCn":"疟疾通过受感染蚊子的叮咬传播给人类。","col":["transmit a disease","sexually transmitted","transmission"]},{"id":377,"topic":"health","w":"virus","ipa":"/ˈvaɪrəs/","pos":"n.","cn":"病毒","pun":"歪若丝","story":"病毒像一根「歪若丝」，细得看不见，歪歪扭扭钻进细胞里。","ex":"Scientists are racing to understand how the new virus mutates and spreads.","exCn":"科学家们正争分夺秒地研究这种新病毒如何变异和传播。","col":["contract a virus","viral infection","viral"]},{"id":378,"topic":"health","w":"bacteria","ipa":"/bækˈtɪəriə/","pos":"n.","cn":"细菌（复数）","pun":"白克提瑞娅","story":"「白克提瑞娅」——白色的克星提着瑞娅到处跑，这些小东西就是细菌。","ex":"Overuse of antibiotics has allowed some bacteria to develop resistance to treatment.","exCn":"抗生素的过度使用使一些细菌对治疗产生了耐药性。","col":["harmful bacteria","bacterial infection","bacterium"]},{"id":379,"topic":"health","w":"pathogen","ipa":"/ˈpæθədʒən/","pos":"n.","cn":"病原体","pun":"怕射真","story":"patho（病）+ gen（产生）：这个东西「怕射真」，射进身体真会生病——病原体。","ex":"Vaccines train the immune system to recognise specific pathogens.","exCn":"疫苗训练免疫系统识别特定的病原体。","col":["dangerous pathogen","pathogenic","germ"]},{"id":380,"topic":"health","w":"antibiotic","ipa":"/ˌæntibaɪˈɒtɪk/","pos":"n.","cn":"抗生素","pun":"安体拜哦踢克","story":"anti-（反对）+ bio（生命）：「安体拜哦踢克」，为了安体，把细菌踢走——抗生素。","ex":"Doctors are urged to prescribe antibiotics only when they are genuinely necessary.","exCn":"医生被要求只在确有必要时才开抗生素。","col":["prescribe antibiotics","antibiotic resistance","antibacterial"]},{"id":381,"topic":"health","w":"resistance","ipa":"/rɪˈzɪstəns/","pos":"n.","cn":"抵抗力；耐药性","pun":"瑞子死撑","story":"re-（反）+ sist（站）：细菌「瑞子死撑」着不倒，药打不死它——耐药性。","ex":"Antibiotic resistance is now regarded as one of the greatest threats to global health.","exCn":"抗生素耐药性现在被视为全球健康的最大威胁之一。","col":["drug resistance","build up resistance","resistant"]},{"id":382,"topic":"health","w":"chronic","ipa":"/ˈkrɒnɪk/","pos":"adj.","cn":"慢性的；长期的","pun":"克若尼克","story":"chron（时间）：病像「克若尼克」——克你若干年还在你身边，就是慢性的。","ex":"Chronic conditions such as diabetes place a heavy burden on healthcare budgets.","exCn":"糖尿病等慢性病给医疗预算带来沉重负担。","col":["chronic disease","chronic pain","chronically ill"]},{"id":383,"topic":"health","w":"acute","ipa":"/əˈkjuːt/","pos":"adj.","cn":"急性的；严重的","pun":"饿哭他","story":"肚子突然疼得「饿哭他」，来得又急又猛——急性的。","ex":"Acute chest pain should always be treated as a medical emergency.","exCn":"急性胸痛应始终被视为医疗紧急情况。","col":["acute illness","acute shortage","acutely"]},{"id":384,"topic":"health","w":"cardiovascular","ipa":"/ˌkɑːdiəʊˈvæskjələ(r)/","pos":"adj.","cn":"心血管的","pun":"卡地哦挖死扣了","story":"cardio（心）+ vascular（血管）：血管「卡地哦挖死扣了」，卡住了，心脏差点死扣——心血管的。","ex":"Regular exercise significantly reduces the risk of cardiovascular disease.","exCn":"规律锻炼能显著降低患心血管疾病的风险。","col":["cardiovascular disease","cardiovascular health","cardiac"]},{"id":385,"topic":"health","w":"diabetes","ipa":"/ˌdaɪəˈbiːtiːz/","pos":"n.","cn":"糖尿病","pun":"呆啊逼提死","story":"糖吃太多，人「呆啊逼提死」，呆呆地被血糖逼得快不行——糖尿病。","ex":"Rising rates of diabetes are closely linked to sugary diets and inactivity.","exCn":"糖尿病发病率上升与高糖饮食和缺乏运动密切相关。","col":["type 2 diabetes","develop diabetes","diabetic"]},{"id":386,"topic":"health","w":"cancer","ipa":"/ˈkænsə(r)/","pos":"n.","cn":"癌症","pun":"砍色","story":"癌症像螃蟹一样横行，把身体的颜色都「砍色」砍没了。","ex":"Early detection greatly improves the chances of surviving cancer.","exCn":"早期发现大大提高了癌症的生存几率。","col":["lung cancer","cancer treatment","cancerous"]},{"id":387,"topic":"health","w":"tumour","ipa":"/ˈtjuːmə(r)/","pos":"n.","cn":"肿瘤","pun":"丘么","story":"身上鼓起一个小「丘么」？那个丘就是肿瘤，要赶紧检查。","ex":"The scan revealed a small tumour that had not yet spread to other organs.","exCn":"扫描发现了一个尚未扩散到其他器官的小肿瘤。","col":["benign tumour","malignant tumour","remove a tumour"]},{"id":388,"topic":"health","w":"stroke","ipa":"/strəʊk/","pos":"n.","cn":"中风","pun":"死揣克","story":"脑血管突然「死揣克」——像被人死死揣了一脚，人就倒下了，这是中风。","ex":"High blood pressure is the single most important risk factor for stroke.","exCn":"高血压是中风最重要的单一风险因素。","col":["suffer a stroke","stroke patient","heart attack"]},{"id":389,"topic":"health","w":"hypertension","ipa":"/ˌhaɪpəˈtenʃn/","pos":"n.","cn":"高血压","pun":"海坡疼身","story":"hyper-（过高）+ tension（压力）：血压像「海坡」一样高，疼遍全身——高血压。","ex":"Hypertension often has no obvious symptoms, which is why regular screening matters.","exCn":"高血压通常没有明显症状，因此定期筛查很重要。","col":["suffer from hypertension","treat hypertension","high blood pressure"]},{"id":390,"topic":"health","w":"cholesterol","ipa":"/kəˈlestərɒl/","pos":"n.","cn":"胆固醇","pun":"可乐死得肉","story":"天天喝「可乐」吃「死得肉」（肥肉），血里全是胆固醇。","ex":"A diet high in saturated fat can raise cholesterol levels dangerously.","exCn":"高饱和脂肪的饮食会将胆固醇水平提高到危险程度。","col":["high cholesterol","cholesterol levels","lower cholesterol"]},{"id":391,"topic":"health","w":"asthma","ipa":"/ˈæsmə/","pos":"n.","cn":"哮喘","pun":"爱死嘛","story":"一喘不上气就「爱死嘛」，胸口憋得像要死——哮喘。","ex":"Air pollution in cities has been linked to a rise in childhood asthma.","exCn":"城市空气污染与儿童哮喘增加有关。","col":["asthma attack","suffer from asthma","asthmatic"]},{"id":392,"topic":"health","w":"allergy","ipa":"/ˈælədʒi/","pos":"n.","cn":"过敏","pun":"爱了鸡","story":"「爱了鸡」，一吃鸡却全身起疹子——这就是过敏。","ex":"Food allergies among children appear to have become far more common in recent decades.","exCn":"近几十年来，儿童食物过敏似乎变得普遍得多。","col":["food allergy","allergic reaction","allergic to"]},{"id":393,"topic":"health","w":"dementia","ipa":"/dɪˈmenʃə/","pos":"n.","cn":"痴呆症","pun":"弟们瞎","story":"de-（去掉）+ ment（心智）：「弟们瞎」了，脑子里的记忆都被拿走——痴呆症。","ex":"As populations age, dementia is becoming a major challenge for care services.","exCn":"随着人口老龄化，痴呆症正成为护理服务的重大挑战。","col":["suffer from dementia","dementia care","Alzheimer's disease"]},{"id":394,"topic":"health","w":"disorder","ipa":"/dɪsˈɔːdə(r)/","pos":"n.","cn":"失调；疾病","pun":"迪斯奥德","story":"dis-（不）+ order（秩序）：身体的秩序被打乱，像迪斯科一样乱跳——失调、紊乱。","ex":"Eating disorders are increasingly reported among teenagers who use social media heavily.","exCn":"在重度使用社交媒体的青少年中，饮食失调的报告日益增多。","col":["mental disorder","eating disorder","sleep disorder"]},{"id":395,"topic":"health","w":"ailment","ipa":"/ˈeɪlmənt/","pos":"n.","cn":"小病；疾病","pun":"哎哟闷特","story":"「哎哟闷特」——一声哎哟，胸口闷特闷，小病来了。","ex":"Many minor ailments can be treated at home without visiting a doctor.","exCn":"许多小病可以在家治疗，无需看医生。","col":["minor ailment","common ailment","ail"]},{"id":396,"topic":"health","w":"malaria","ipa":"/məˈleəriə/","pos":"n.","cn":"疟疾","pun":"么累呀","story":"mal（坏）+ aria（空气）：古人以为坏空气致病；发烧「么累呀」——疟疾。","ex":"Malaria continues to kill hundreds of thousands of people each year in tropical regions.","exCn":"疟疾每年仍在热带地区夺去数十万人的生命。","col":["contract malaria","malaria prevention","mosquito-borne"]},{"id":397,"topic":"health","w":"tuberculosis","ipa":"/tjuːˌbɜːkjuˈləʊsɪs/","pos":"n.","cn":"肺结核","pun":"丢薄裤楼西斯","story":"「丢薄裤楼西斯」——瘦得裤子都丢了，还在楼里咳嗽的西斯，得了肺结核。","ex":"Tuberculosis remains a serious health threat in many developing countries.","exCn":"肺结核在许多发展中国家仍是严重的健康威胁。","col":["tuberculosis (TB)","TB vaccine","drug-resistant tuberculosis"]},{"id":398,"topic":"health","w":"influenza","ipa":"/ˌɪnfluˈenzə/","pos":"n.","cn":"流行性感冒","pun":"音符轮扎","story":"「音符轮扎」——像音符一样轮流扎到每个人身上，全班都感冒了，这就是流感。","ex":"Seasonal influenza vaccines are recommended for the elderly and those with chronic illnesses.","exCn":"建议老年人和慢性病患者接种季节性流感疫苗。","col":["influenza vaccine","flu season","bird flu"]},{"id":399,"topic":"health","w":"measles","ipa":"/ˈmiːzlz/","pos":"n.","cn":"麻疹","pun":"米粒子","story":"皮肤上冒出一粒粒红「米粒子」——这就是麻疹。","ex":"Declining vaccination rates have led to a resurgence of measles in several countries.","exCn":"疫苗接种率下降导致麻疹在几个国家再次流行。","col":["measles outbreak","measles vaccine","rash"]},{"id":400,"topic":"health","w":"respiratory","ipa":"/rəˈspɪrətri/","pos":"adj.","cn":"呼吸的","pun":"若死比累吹","story":"re-（反复）+ spir（呼吸）：跑完「若死比累吹」，呼哧呼哧吹气——呼吸系统的。","ex":"Smog contributes to a wide range of respiratory problems, especially in children.","exCn":"雾霾会引发多种呼吸系统问题，尤其是在儿童中。","col":["respiratory disease","respiratory system","respiration"]},{"id":401,"topic":"health","w":"cardiac","ipa":"/ˈkɑːdiæk/","pos":"adj.","cn":"心脏的","pun":"卡地哎克","story":"心脏突然「卡地哎克」，卡住不跳了——心脏的（cardiac arrest 心脏骤停）。","ex":"Cardiac arrest survival rates improve dramatically when bystanders know first aid.","exCn":"当旁观者掌握急救知识时，心脏骤停的存活率会显著提高。","col":["cardiac arrest","cardiac surgery","cardiologist"]},{"id":402,"topic":"health","w":"susceptible","ipa":"/səˈseptəbl/","pos":"adj.","cn":"易受影响的；易感的","pun":"色射不得","story":"这种「色射不得」的人，一点风吹草动就中招——特别容易感染。","ex":"Older adults are more susceptible to infections because their immune systems weaken.","exCn":"老年人因免疫系统减弱，更容易受到感染。","col":["susceptible to disease","highly susceptible","susceptibility"]},{"id":403,"topic":"health","w":"exposure","ipa":"/ɪkˈspəʊʒə(r)/","pos":"n.","cn":"接触；暴露","pun":"一颗死泡着","story":"ex-（向外）+ pose（放）：身体「一颗死泡着」，泡在有害环境里——暴露、接触。","ex":"Prolonged exposure to polluted air increases the likelihood of lung disease.","exCn":"长期接触污染空气会增加患肺病的可能性。","col":["exposure to","prolonged exposure","expose"]},{"id":404,"topic":"health","w":"contract","ipa":"/kənˈtrækt/","pos":"v.","cn":"感染（疾病）；收缩","pun":"啃出癞","story":"con-（一起）+ tract（拉）：把病菌一起拉进身体，「啃出癞」子——感染上了。","ex":"Travellers who contract the disease abroad may unknowingly bring it home.","exCn":"在国外感染这种疾病的旅行者可能会在不知情的情况下将其带回国内。","col":["contract a disease","contract an infection","catch"]},{"id":405,"topic":"health","w":"spread","ipa":"/spred/","pos":"v./n.","cn":"传播；蔓延","pun":"死不累的","story":"病毒「死不累的」，永不停歇地到处跑——传播、蔓延。","ex":"Closing schools temporarily helped to slow the spread of the virus.","exCn":"暂时关闭学校有助于减缓病毒的传播。","col":["spread of disease","spread rapidly","widespread"]},{"id":406,"topic":"health","w":"fatal","ipa":"/ˈfeɪtl/","pos":"adj.","cn":"致命的","pun":"废掉","story":"fate（命运）+ -al：命运把人「废掉」——致命的。","ex":"Without prompt treatment, the infection can prove fatal within days.","exCn":"如果不及时治疗，这种感染可能在几天内致命。","col":["fatal disease","prove fatal","fatality"]},{"id":407,"topic":"health","w":"lethal","ipa":"/ˈliːθl/","pos":"adj.","cn":"致死的","pun":"离手","story":"这种毒药一「离手」就要人命——致死的。","ex":"Even small doses of the substance can be lethal to young children.","exCn":"即使是小剂量的这种物质对幼儿也可能致命。","col":["lethal dose","potentially lethal","deadly"]},{"id":408,"topic":"health","w":"terminal","ipa":"/ˈtɜːmɪnl/","pos":"adj.","cn":"晚期的；末期的","pun":"特么闹","story":"term（终点）：病到了终点站，医生「特么闹」也救不回——晚期的。","ex":"Patients with terminal illnesses deserve dignified and compassionate care.","exCn":"晚期疾病患者应得到有尊严且富有同情心的照护。","col":["terminal illness","terminally ill","terminal cancer"]},{"id":409,"topic":"health","w":"prognosis","ipa":"/prɒɡˈnəʊsɪs/","pos":"n.","cn":"预后；预测","pun":"扑弄脑西斯","story":"pro-（提前）+ gnosis（知道）：医生提前「扑弄脑西斯」，预测病人会怎样——预后。","ex":"With early treatment, the prognosis for most patients is generally positive.","exCn":"若能早期治疗，大多数患者的预后通常良好。","col":["good prognosis","poor prognosis","outlook"]},{"id":410,"topic":"health","w":"vaccine","ipa":"/ˈvæksiːn/","pos":"n.","cn":"疫苗","pun":"挖克新","story":"「挖克新」——挖出病毒的克星，做成新药打进身体，就是疫苗。","ex":"The rapid development of vaccines was a remarkable scientific achievement.","exCn":"疫苗的快速研发是一项了不起的科学成就。","col":["develop a vaccine","vaccine rollout","vaccinate"]},{"id":411,"topic":"health","w":"vaccination","ipa":"/ˌvæksɪˈneɪʃn/","pos":"n.","cn":"接种疫苗","pun":"挖克斯内心","story":"vaccine + -ation：把克星「挖克斯内心」，注射进你身体内——接种疫苗。","ex":"Mass vaccination programmes have virtually eliminated polio in most countries.","exCn":"大规模疫苗接种计划几乎在大多数国家消灭了小儿麻痹症。","col":["vaccination programme","childhood vaccination","immunisation"]},{"id":412,"topic":"health","w":"prescription","ipa":"/prɪˈskrɪpʃn/","pos":"n.","cn":"处方；药方","pun":"扑瑞死克瑞普身","story":"pre-（先）+ script（写）：医生先写好「扑瑞死克瑞普身」的药单——处方。","ex":"Some medicines are available only with a doctor's prescription.","exCn":"有些药物只有凭医生处方才能购买。","col":["prescription drugs","on prescription","over-the-counter"]},{"id":413,"topic":"health","w":"prescribe","ipa":"/prɪˈskraɪb/","pos":"v.","cn":"开药；规定","pun":"扑瑞死快","story":"pre- + scribe（写）：医生扑到桌前「扑瑞死快」地写药单——开药。","ex":"Doctors should be cautious about prescribing antibiotics for viral infections.","exCn":"医生对病毒感染开抗生素应持谨慎态度。","col":["prescribe medication","prescribe a course of","prescription"]},{"id":414,"topic":"health","w":"dosage","ipa":"/ˈdəʊsɪdʒ/","pos":"n.","cn":"剂量；用量","pun":"多死记","story":"吃药「多死记」——吃多了会死，一定要记住剂量！","ex":"Patients must follow the recommended dosage to avoid harmful side effects.","exCn":"患者必须遵守推荐剂量，以避免有害的副作用。","col":["recommended dosage","daily dosage","dose"]},{"id":415,"topic":"health","w":"pharmaceutical","ipa":"/ˌfɑːməˈsuːtɪkl/","pos":"adj./n.","cn":"制药的；药品","pun":"发么速踢扣","story":"pharma（药）：药厂「发么速踢扣」，发货速度快得像踢球——制药的。","ex":"Pharmaceutical companies are often criticised for the high prices of new drugs.","exCn":"制药公司常因新药价格过高而受到批评。","col":["pharmaceutical industry","pharmaceutical company","pharmacy"]},{"id":416,"topic":"health","w":"medication","ipa":"/ˌmedɪˈkeɪʃn/","pos":"n.","cn":"药物；药物治疗","pun":"没弟开心","story":"medic（医）：「没弟开心」——弟弟生病不开心，吃了药物才开心。","ex":"Elderly patients often take several medications, which can interact dangerously.","exCn":"老年患者常同时服用多种药物，这些药物可能产生危险的相互作用。","col":["take medication","on medication","medicine"]},{"id":417,"topic":"health","w":"remedy","ipa":"/ˈremədi/","pos":"n.","cn":"疗法；补救办法","pun":"人么弟","story":"「人么弟」——家里人给弟弟找偏方治病，这就是疗法、补救办法。","ex":"Many traditional remedies have never been tested in proper clinical trials.","exCn":"许多传统疗法从未经过正规临床试验的检验。","col":["herbal remedy","home remedy","remedy the problem"]},{"id":418,"topic":"health","w":"cure","ipa":"/kjʊə(r)/","pos":"n./v.","cn":"治愈；疗法","pun":"可要","story":"这药「可要」得！一吃就好——治愈。","ex":"There is still no cure for the common cold, despite decades of research.","exCn":"尽管研究了几十年，普通感冒仍然没有治愈方法。","col":["find a cure","cure a disease","curable"]},{"id":419,"topic":"health","w":"treatment","ipa":"/ˈtriːtmənt/","pos":"n.","cn":"治疗；对待","pun":"吹特闷特","story":"treat（对待）：医生对病人「吹特闷特」——吹一吹、拍一拍，认真对待就是治疗。","ex":"Access to affordable treatment remains a challenge in rural communities.","exCn":"在农村社区，获得负担得起的治疗仍然是一项挑战。","col":["receive treatment","medical treatment","treat"]},{"id":420,"topic":"health","w":"surgery","ipa":"/ˈsɜːdʒəri/","pos":"n.","cn":"外科手术","pun":"色着里","story":"手术室里灯「色着里」——脸色发白地躺在里面开刀，这就是手术。","ex":"Advances in keyhole surgery have shortened recovery times considerably.","exCn":"微创手术的进步大大缩短了恢复时间。","col":["undergo surgery","major surgery","surgical"]},{"id":421,"topic":"health","w":"surgeon","ipa":"/ˈsɜːdʒən/","pos":"n.","cn":"外科医生","pun":"色针","story":"「色针」——拿着闪着冷色光的针线缝伤口的人，就是外科医生。","ex":"Skilled surgeons are in short supply in many parts of the developing world.","exCn":"在发展中国家的许多地区，熟练的外科医生供不应求。","col":["heart surgeon","consultant surgeon","surgical"]},{"id":422,"topic":"health","w":"physician","ipa":"/fɪˈzɪʃn/","pos":"n.","cn":"内科医生；医师","pun":"废自身","story":"physic（医术）：医生为了救人「废自身」，累到自己都倒下——医师。","ex":"Family physicians play a vital role in preventive healthcare.","exCn":"家庭医生在预防保健中发挥着至关重要的作用。","col":["family physician","consult a physician","doctor"]},{"id":423,"topic":"health","w":"practitioner","ipa":"/prækˈtɪʃənə(r)/","pos":"n.","cn":"从业者；开业医生","pun":"扑拉克提身呢","story":"practice（执业）+ -er：「扑拉克提身呢」——扑过去把病人提起来看病的人，执业医生。","ex":"General practitioners are usually the first point of contact for patients.","exCn":"全科医生通常是患者的第一接触点。","col":["general practitioner (GP)","medical practitioner","practise medicine"]},{"id":424,"topic":"health","w":"specialist","ipa":"/ˈspeʃəlɪst/","pos":"n.","cn":"专家；专科医生","pun":"死背色列表","story":"special + -ist：「死背色列表」——把某个专科知识全背下来的人，专科医生。","ex":"Patients in remote areas often wait months to see a specialist.","exCn":"偏远地区的患者常常要等数月才能见到专科医生。","col":["see a specialist","heart specialist","specialise in"]},{"id":425,"topic":"health","w":"clinic","ipa":"/ˈklɪnɪk/","pos":"n.","cn":"诊所","pun":"可怜你可","story":"「可怜你可」怜的，生病了？去街角的小诊所看看吧。","ex":"Mobile clinics bring basic healthcare to villages without hospitals.","exCn":"流动诊所为没有医院的村庄带来基本医疗服务。","col":["health clinic","dental clinic","clinical"]},{"id":426,"topic":"health","w":"ward","ipa":"/wɔːd/","pos":"n.","cn":"病房","pun":"我的","story":"「我的」床在哪？护士说：三号病房。","ex":"Overcrowded hospital wards increase the risk of infections spreading among patients.","exCn":"拥挤的医院病房增加了患者之间感染传播的风险。","col":["hospital ward","children's ward","in the ward"]},{"id":427,"topic":"health","w":"outpatient","ipa":"/ˈaʊtpeɪʃnt/","pos":"n.","cn":"门诊病人","pun":"奥特佩神","story":"out（外）+ patient（病人）：看完病就到外面去的「奥特佩神」——门诊病人。","ex":"Many minor procedures can now be carried out on an outpatient basis.","exCn":"许多小手术现在可以在门诊完成。","col":["outpatient clinic","outpatient treatment","inpatient"]},{"id":428,"topic":"health","w":"consultation","ipa":"/ˌkɒnslˈteɪʃn/","pos":"n.","cn":"咨询；会诊","pun":"看色特心","story":"consult（咨询）：病人来「看色特心」——看脸色、特别关心地问诊，就是会诊。","ex":"Online consultations have made it easier for patients to seek advice.","exCn":"在线问诊让患者更容易寻求建议。","col":["medical consultation","have a consultation","consult a doctor"]},{"id":429,"topic":"health","w":"referral","ipa":"/rɪˈfɜːrəl/","pos":"n.","cn":"转诊；推荐","pun":"瑞佛若","story":"refer（转介）+ -al：医生把病人「瑞佛若」——转给另一位像佛一样的专家，就是转诊。","ex":"A referral from a general practitioner is required before seeing a specialist.","exCn":"看专科医生之前需要全科医生的转诊。","col":["hospital referral","make a referral","refer to"]},{"id":430,"topic":"health","w":"transplant","ipa":"/ˈtrænsplɑːnt/","pos":"n./v.","cn":"移植","pun":"穿死扑烂","story":"trans-（转移）+ plant（种植）：把器官像植物一样「穿死扑烂」——从一个身体挪到另一个，移植。","ex":"Thousands of patients die each year while waiting for an organ transplant.","exCn":"每年有数千名患者在等待器官移植期间死亡。","col":["organ transplant","kidney transplant","transplant surgery"]},{"id":431,"topic":"health","w":"donor","ipa":"/ˈdəʊnə(r)/","pos":"n.","cn":"捐赠者；捐献者","pun":"都呐","story":"don（给予）：「都呐」，我的血、器官都拿去吧——捐献者。","ex":"Encouraging more people to become organ donors could save countless lives.","exCn":"鼓励更多人成为器官捐献者可以拯救无数生命。","col":["organ donor","blood donor","donate"]},{"id":432,"topic":"health","w":"organ","ipa":"/ˈɔːɡən/","pos":"n.","cn":"器官","pun":"哦跟","story":"「哦跟」着心脏一起工作的还有肝、肺、肾——它们都是器官。","ex":"Smoking damages nearly every organ in the human body.","exCn":"吸烟几乎损害人体的每一个器官。","col":["vital organ","organ failure","organic"]},{"id":433,"topic":"health","w":"tissue","ipa":"/ˈtɪʃuː/","pos":"n.","cn":"（生物）组织；纸巾","pun":"体秀","story":"「体秀」——身体秀出来的一层层肌肉、皮肤，就是组织。","ex":"Radiation therapy can damage healthy tissue surrounding the tumour.","exCn":"放射治疗可能损伤肿瘤周围的健康组织。","col":["muscle tissue","tissue damage","soft tissue"]},{"id":434,"topic":"health","w":"anaesthetic","ipa":"/ˌænəsˈθetɪk/","pos":"n.","cn":"麻醉剂","pun":"安呢死赛踢克","story":"an-（无）+ aesthet（感觉）：打了针「安呢死赛踢克」——安静得像死了，踢一脚也没感觉，麻醉剂。","ex":"The patient was given a general anaesthetic before the operation began.","exCn":"手术开始前，病人接受了全身麻醉。","col":["general anaesthetic","local anaesthetic","anaesthetist"]},{"id":435,"topic":"health","w":"injection","ipa":"/ɪnˈdʒekʃn/","pos":"n.","cn":"注射；打针","pun":"印杰克神","story":"in-（进）+ ject（扔）：把药「印杰克神」地扔进身体——注射。","ex":"Insulin injections allow people with diabetes to manage their condition.","exCn":"胰岛素注射使糖尿病患者能够控制病情。","col":["give an injection","flu injection","inject"]},{"id":436,"topic":"health","w":"painkiller","ipa":"/ˈpeɪnkɪlə(r)/","pos":"n.","cn":"止痛药","pun":"喷可勒","story":"pain（疼）+ killer（杀手）：把疼「喷可勒」，一喷就勒死疼——止痛药。","ex":"Over-reliance on painkillers can mask serious underlying conditions.","exCn":"过度依赖止痛药可能掩盖严重的潜在疾病。","col":["take painkillers","strong painkiller","pain relief"]},{"id":437,"topic":"health","w":"placebo","ipa":"/pləˈsiːbəʊ/","pos":"n.","cn":"安慰剂","pun":"扑拉西波","story":"「扑拉西波」——一颗糖丸扑过来，拉起心理的西波（希望）就好了，安慰剂。","ex":"In the trial, half of the participants received a placebo instead of the drug.","exCn":"在试验中，一半参与者服用的是安慰剂而不是药物。","col":["placebo effect","placebo group","placebo-controlled"]},{"id":438,"topic":"health","w":"side effect","ipa":"/ˈsaɪd ɪfekt/","pos":"phr.","cn":"副作用","pun":"塞的一飞克特","story":"药从「塞的」（side 旁边）「一飞克特」飞出来的坏效果——副作用。","ex":"Common side effects of the medication include nausea and dizziness.","exCn":"这种药物的常见副作用包括恶心和头晕。","col":["side effects of","adverse side effect","harmful effect"]},{"id":439,"topic":"health","w":"overdose","ipa":"/ˈəʊvədəʊs/","pos":"n./v.","cn":"用药过量","pun":"欧沃多死","story":"over（过）+ dose（剂量）：「欧沃多死」——吃得太多会死，用药过量。","ex":"Deaths from drug overdoses have risen sharply in several Western countries.","exCn":"在几个西方国家，药物过量致死人数急剧上升。","col":["drug overdose","accidental overdose","overdose on"]},{"id":440,"topic":"health","w":"clinical","ipa":"/ˈklɪnɪkl/","pos":"adj.","cn":"临床的","pun":"可怜你扣","story":"clinic + -al：「可怜你扣」在病床边做的检查和试验——临床的。","ex":"New drugs must pass rigorous clinical trials before they reach the market.","exCn":"新药上市前必须通过严格的临床试验。","col":["clinical trial","clinical practice","clinically proven"]},{"id":441,"topic":"health","w":"trial","ipa":"/ˈtraɪəl/","pos":"n.","cn":"试验；审判","pun":"踹呕","story":"try（尝试）+ -al：新药先在志愿者身上试，被「踹呕」了也要记录——试验。","ex":"The drug showed promising results in early trials involving several hundred patients.","exCn":"该药物在涉及数百名患者的早期试验中显示出良好结果。","col":["clinical trial","drug trial","trial period"]},{"id":442,"topic":"health","w":"relieve","ipa":"/rɪˈliːv/","pos":"v.","cn":"缓解；减轻","pun":"瑞利夫","story":"re-（再）+ lieve（轻）：「瑞利夫」——吃了药，疼痛再次变轻，缓解了。","ex":"Regular stretching can relieve back pain caused by long hours at a desk.","exCn":"经常拉伸可以缓解久坐办公引起的背痛。","col":["relieve pain","relieve stress","pain relief"]},{"id":443,"topic":"health","w":"soothe","ipa":"/suːð/","pos":"v.","cn":"安抚；缓解","pun":"舒缓","story":"「舒缓」——读音和意思一样，一喝热汤喉咙就舒缓了。","ex":"Warm drinks with honey can soothe a sore throat.","exCn":"加蜂蜜的热饮可以缓解喉咙痛。","col":["soothe the pain","soothing effect","soothing"]},{"id":444,"topic":"health","w":"rehabilitation","ipa":"/ˌriːəˌbɪlɪˈteɪʃn/","pos":"n.","cn":"康复；复健","pun":"锐啊比累特心","story":"re-（再）+ habil（能力）：「锐啊比累特心」——再练回能力，比累更特别用心，康复。","ex":"Rehabilitation programmes help stroke patients regain movement and speech.","exCn":"康复项目帮助中风患者恢复运动和语言能力。","col":["rehabilitation centre","physical rehabilitation","rehabilitate"]},{"id":445,"topic":"health","w":"recovery","ipa":"/rɪˈkʌvəri/","pos":"n.","cn":"康复；恢复","pun":"瑞卡佛瑞","story":"re-（再）+ cover（覆盖）：「瑞卡佛瑞」——身体再一次被健康覆盖，恢复了。","ex":"A positive attitude is believed to speed up recovery after surgery.","exCn":"积极的心态被认为能加快术后康复。","col":["full recovery","make a recovery","recover from"]},{"id":446,"topic":"health","w":"relapse","ipa":"/rɪˈlæps/","pos":"n./v.","cn":"复发；旧病复发","pun":"瑞累扑死","story":"re-（再）+ lapse（滑落）：刚好一点又「瑞累扑死」——再次滑落，病又复发。","ex":"Without ongoing support, many recovering addicts suffer a relapse within a year.","exCn":"没有持续的支持，许多正在康复的成瘾者会在一年内复发。","col":["suffer a relapse","risk of relapse","relapse into"]},{"id":447,"topic":"health","w":"paramedic","ipa":"/ˌpærəˈmedɪk/","pos":"n.","cn":"急救人员","pun":"怕啦没弟克","story":"para-（旁）+ medic（医）：「怕啦没弟克」——出事别怕，医生旁边的急救员马上来。","ex":"Paramedics provide critical care at the scene before patients reach hospital.","exCn":"急救人员在患者到达医院前在现场提供关键救治。","col":["paramedic team","trained paramedic","emergency services"]},{"id":448,"topic":"health","w":"ambulance","ipa":"/ˈæmbjələns/","pos":"n.","cn":"救护车","pun":"俺不由人死","story":"「俺不由人死」——救护车呜哇呜哇冲来，绝不由人死。","ex":"Ambulance response times have increased due to staff shortages.","exCn":"由于人手短缺，救护车的响应时间变长了。","col":["call an ambulance","ambulance service","emergency vehicle"]},{"id":449,"topic":"health","w":"emergency","ipa":"/ɪˈmɜːdʒənsi/","pos":"n.","cn":"紧急情况；急诊","pun":"一摸真死","story":"「一摸真死」——一摸病人没气了，快叫急救，紧急情况！","ex":"Emergency departments are frequently overwhelmed during the winter months.","exCn":"急诊科在冬季经常人满为患。","col":["medical emergency","emergency department","in an emergency"]},{"id":450,"topic":"health","w":"first aid","ipa":"/ˌfɜːst ˈeɪd/","pos":"phr.","cn":"急救","pun":"佛死特诶的","story":"first（第一）+ aid（帮助）：「佛死特诶的」——佛也来不及，第一时间自己上手帮忙，急救。","ex":"Teaching first aid in schools could help save lives in everyday emergencies.","exCn":"在学校教授急救知识有助于在日常紧急情况中挽救生命。","col":["first aid kit","first aid training","give first aid"]},{"id":451,"topic":"health","w":"sanitation","ipa":"/ˌsænɪˈteɪʃn/","pos":"n.","cn":"公共卫生；卫生设施","pun":"三腻特心","story":"sanit（健康）：厕所脏得「三腻特心」——三次都腻歪特别恶心，得改善卫生设施。","ex":"Improved sanitation has done more to reduce disease than many medical advances.","exCn":"卫生设施的改善在减少疾病方面比许多医学进步贡献更大。","col":["poor sanitation","water and sanitation","sanitary"]},{"id":452,"topic":"health","w":"sterile","ipa":"/ˈsteraɪl/","pos":"adj.","cn":"无菌的；不育的","pun":"死带绕","story":"手术器械「死带绕」——细菌死光，用带子绕好密封，无菌的。","ex":"All surgical instruments must be kept in sterile conditions to prevent infection.","exCn":"所有手术器械必须保持无菌状态以防感染。","col":["sterile environment","sterile equipment","sterilise"]},{"id":453,"topic":"health","w":"disinfect","ipa":"/ˌdɪsɪnˈfekt/","pos":"v.","cn":"消毒","pun":"弟死印飞克特","story":"dis-（去除）+ infect（感染）：把「印飞克特」（感染）去掉——消毒。","ex":"Hospitals disinfect surfaces regularly to reduce the spread of bacteria.","exCn":"医院定期对物体表面消毒，以减少细菌传播。","col":["disinfect the wound","disinfectant","sterilise"]},{"id":454,"topic":"health","w":"quarantine","ipa":"/ˈkwɒrəntiːn/","pos":"n./v.","cn":"隔离检疫","pun":"跨冉停","story":"「跨冉停」——想跨出门，冉冉地停下，得关在屋里隔离十四天。","ex":"Travellers arriving from affected regions were placed in quarantine for two weeks.","exCn":"来自疫区的旅客被隔离检疫两周。","col":["in quarantine","quarantine period","isolation"]},{"id":455,"topic":"health","w":"isolation","ipa":"/ˌaɪsəˈleɪʃn/","pos":"n.","cn":"隔离；孤立","pun":"爱馊累心","story":"isol（岛）：一个人像在岛上，「爱馊累心」——爱都馊了，累到心里，隔离、孤立。","ex":"Prolonged social isolation can be as harmful to health as smoking.","exCn":"长期社交孤立对健康的危害可能与吸烟相当。","col":["social isolation","in isolation","isolate"]},{"id":456,"topic":"health","w":"screening","ipa":"/ˈskriːnɪŋ/","pos":"n.","cn":"筛查；检查","pun":"死克宁","story":"screen（筛子）：用筛子把病「死克宁」——死死克住，宁可早查出来，筛查。","ex":"Regular screening allows cancers to be detected before symptoms appear.","exCn":"定期筛查可以在症状出现前发现癌症。","col":["cancer screening","screening programme","screen for"]},{"id":457,"topic":"health","w":"check-up","ipa":"/ˈtʃekʌp/","pos":"n.","cn":"体检；检查","pun":"切克阿婆","story":"「切克阿婆」——阿婆每年都去医院切克切克检查一遍身体，体检。","ex":"Annual check-ups can identify health problems at an early and treatable stage.","exCn":"每年体检可以在早期可治疗阶段发现健康问题。","col":["regular check-up","medical check-up","dental check-up"]},{"id":458,"topic":"health","w":"preventive","ipa":"/prɪˈventɪv/","pos":"adj.","cn":"预防性的","pun":"扑瑞玩体夫","story":"pre-（先）+ vent（来）：病还没来，先「扑瑞玩体夫」——扑上去把身体练好，预防性的。","ex":"Investing in preventive medicine is far cheaper than treating illness later.","exCn":"投资预防医学比日后治疗疾病便宜得多。","col":["preventive medicine","preventive measures","prevention"]},{"id":459,"topic":"health","w":"intervention","ipa":"/ˌɪntəˈvenʃn/","pos":"n.","cn":"干预；介入","pun":"因特玩身","story":"inter-（之间）+ vent（来）：医生「因特玩身」——插到病和身体之间来管，干预。","ex":"Early intervention is crucial for children with developmental disorders.","exCn":"对于有发育障碍的儿童，早期干预至关重要。","col":["medical intervention","early intervention","intervene"]},{"id":460,"topic":"health","w":"mortality","ipa":"/mɔːˈtæləti/","pos":"n.","cn":"死亡率；死亡","pun":"摸他累踢","story":"mort（死）：「摸他累踢」——摸一下他，累得被踢一脚就倒，死亡率高。","ex":"Infant mortality has fallen dramatically in countries with universal healthcare.","exCn":"在实行全民医疗的国家，婴儿死亡率大幅下降。","col":["mortality rate","infant mortality","mortal"]},{"id":461,"topic":"health","w":"life expectancy","ipa":"/ˈlaɪf ɪkˌspektənsi/","pos":"phr.","cn":"预期寿命","pun":"来夫一克死拍疼死","story":"life（寿命）+ expect（期望）：大家期望活多久，别「一克死拍疼死」——预期寿命。","ex":"Average life expectancy has risen by more than a decade since the 1960s.","exCn":"自二十世纪六十年代以来，平均预期寿命增加了十多年。","col":["average life expectancy","increase life expectancy","lifespan"]},{"id":462,"topic":"health","w":"longevity","ipa":"/lɒnˈdʒevəti/","pos":"n.","cn":"长寿；寿命","pun":"浪街唯题","story":"long（长）：老人「浪街唯题」——天天在街上浪，唯一话题是怎么长寿。","ex":"Researchers are studying the diets of communities known for their longevity.","exCn":"研究人员正在研究以长寿著称的社区的饮食。","col":["human longevity","the secret of longevity","long-lived"]},{"id":463,"topic":"health","w":"ageing","ipa":"/ˈeɪdʒɪŋ/","pos":"n./adj.","cn":"老龄化；变老","pun":"诶京","story":"age（年龄）+ -ing：「诶京」——诶，京城的老人越来越多，人口老龄化。","ex":"An ageing population puts increasing pressure on pensions and healthcare.","exCn":"人口老龄化给养老金和医疗保健带来越来越大的压力。","col":["ageing population","the ageing process","aged"]},{"id":464,"topic":"health","w":"elderly","ipa":"/ˈeldəli/","pos":"adj.","cn":"年长的；老年的","pun":"饿的累","story":"「饿的累」——老人家又饿又累走不动了，年长的。","ex":"The elderly are particularly at risk during periods of extreme heat.","exCn":"老年人在极端高温期间尤其面临风险。","col":["the elderly","elderly people","elderly care"]},{"id":465,"topic":"health","w":"geriatric","ipa":"/ˌdʒeriˈætrɪk/","pos":"adj.","cn":"老年病的；老年人的","pun":"姐里爱吹克","story":"ger（老）+ iatr（医）：「姐里爱吹克」——老姐姐们爱吹的那位克医生，专治老年病。","ex":"Demand for geriatric care will soar as the population continues to age.","exCn":"随着人口持续老龄化，老年护理的需求将激增。","col":["geriatric care","geriatric ward","geriatrics"]},{"id":466,"topic":"health","w":"nursing home","ipa":"/ˈnɜːsɪŋ həʊm/","pos":"phr.","cn":"养老院；疗养院","pun":"呢兴宏","story":"nurse（护理）+ home（家）：有护士的家，「呢兴宏」——那里兴旺又宏大，养老院。","ex":"Many families struggle to afford places in private nursing homes.","exCn":"许多家庭难以负担私立养老院的费用。","col":["move into a nursing home","care home","residential care"]},{"id":467,"topic":"health","w":"carer","ipa":"/ˈkeərə(r)/","pos":"n.","cn":"看护者；照顾者","pun":"凯若","story":"care（照顾）+ -er：「凯若」——凯若姐姐每天照顾生病的奶奶，是看护者。","ex":"Unpaid carers save the government billions of pounds every year.","exCn":"无偿看护者每年为政府节省数十亿英镑。","col":["family carer","full-time carer","caregiver"]},{"id":468,"topic":"health","w":"disability","ipa":"/ˌdɪsəˈbɪləti/","pos":"n.","cn":"残疾；残障","pun":"弟色比累踢","story":"dis-（不）+ ability（能力）：「弟色比累踢」——弟弟脸色比累还差，腿踢不动了，残疾。","ex":"People with disabilities still face barriers to accessing healthcare services.","exCn":"残疾人在获得医疗服务方面仍面临障碍。","col":["physical disability","learning disability","disabled"]},{"id":469,"topic":"health","w":"impairment","ipa":"/ɪmˈpeəmənt/","pos":"n.","cn":"损伤；缺陷","pun":"因陪门特","story":"im-（使）+ pair（变坏）：「因陪门特」——因为陪着门特别久，听力出了损伤。","ex":"Hearing impairment is one of the most common conditions among older adults.","exCn":"听力损伤是老年人中最常见的病症之一。","col":["visual impairment","cognitive impairment","impair"]},{"id":470,"topic":"health","w":"palliative","ipa":"/ˈpæliətɪv/","pos":"adj.","cn":"缓和的；姑息的","pun":"怕累啊体夫","story":"「怕累啊体夫」——治不好了，怕病人累，就让身体舒服点，缓和治疗。","ex":"Palliative care focuses on comfort rather than cure for the terminally ill.","exCn":"缓和医疗关注晚期病人的舒适而非治愈。","col":["palliative care","palliative treatment","end-of-life care"]},{"id":471,"topic":"health","w":"hospice","ipa":"/ˈhɒspɪs/","pos":"n.","cn":"临终关怀医院","pun":"好死屁事","story":"「好死屁事」——在临终关怀医院里安安静静好好走，别的都是屁事。","ex":"Hospices provide emotional and medical support for patients nearing the end of life.","exCn":"临终关怀医院为生命末期的患者提供情感和医疗支持。","col":["hospice care","local hospice","palliative care"]},{"id":472,"topic":"health","w":"euthanasia","ipa":"/ˌjuːθəˈneɪziə/","pos":"n.","cn":"安乐死","pun":"油射内心呀","story":"eu-（好）+ thanasia（死）：「油射内心呀」——一针药油射进内心，安安静静离开，安乐死。","ex":"Euthanasia remains illegal in most countries despite growing public support.","exCn":"尽管公众支持日增，安乐死在大多数国家仍属非法。","col":["legalise euthanasia","voluntary euthanasia","assisted dying"]},{"id":473,"topic":"health","w":"insurance","ipa":"/ɪnˈʃʊərəns/","pos":"n.","cn":"保险","pun":"应收人死","story":"「应收人死」——人出事或死了，保险公司应该赔钱，这就是保险。","ex":"Without health insurance, a single hospital stay can push a family into debt.","exCn":"没有医疗保险，一次住院就可能让一个家庭陷入债务。","col":["health insurance","insurance policy","insure"]},{"id":474,"topic":"health","w":"privatise","ipa":"/ˈpraɪvətaɪz/","pos":"v.","cn":"私有化","pun":"扑来玩太子","story":"private（私人）+ -ise：「扑来玩太子」——公立医院扑来被太子买走，私有化。","ex":"Critics argue that privatising hospitals puts profit before patient welfare.","exCn":"批评者认为医院私有化把利润置于患者福祉之上。","col":["privatise healthcare","privatisation","private sector"]},{"id":475,"topic":"health","w":"understaffed","ipa":"/ˌʌndəˈstɑːft/","pos":"adj.","cn":"人手不足的","pun":"安德死打夫特","story":"under-（不足）+ staff（员工）：「安德死打夫特」——安德累死了也打不完的活，人手不足。","ex":"Understaffed wards are more likely to make errors in patient care.","exCn":"人手不足的病房更容易在患者护理中出错。","col":["chronically understaffed","understaffed hospitals","overworked"]},{"id":476,"topic":"health","w":"waiting list","ipa":"/ˈweɪtɪŋ lɪst/","pos":"phr.","cn":"候诊名单；等候名单","pun":"喂听里斯特","story":"wait（等）+ list（名单）：「喂听里斯特」——喂，听好，里斯特排在你前面，等候名单。","ex":"Patients on the waiting list for surgery often wait more than six months.","exCn":"等候手术名单上的患者往往要等六个月以上。","col":["on the waiting list","long waiting list","waiting time"]},{"id":477,"topic":"health","w":"telemedicine","ipa":"/ˈtelimedsn/","pos":"n.","cn":"远程医疗","pun":"太累没得省","story":"tele-（远）+ medicine（医）：「太累没得省」——太累不想去医院？远程医疗，路都省了。","ex":"Telemedicine allows doctors to consult patients in remote areas via video link.","exCn":"远程医疗使医生能通过视频与偏远地区的患者会诊。","col":["telemedicine services","remote consultation","telehealth"]},{"id":478,"topic":"health","w":"wearable","ipa":"/ˈweərəbl/","pos":"adj./n.","cn":"可穿戴的；可穿戴设备","pun":"喂若宝","story":"wear（穿）+ -able：「喂若宝」——喂，若宝手上戴的表能测心率，可穿戴设备。","ex":"Wearable devices now allow individuals to monitor their heart rate and sleep.","exCn":"可穿戴设备现在使个人能够监测心率和睡眠。","col":["wearable technology","wearable device","fitness tracker"]},{"id":479,"topic":"health","w":"consent","ipa":"/kənˈsent/","pos":"n./v.","cn":"同意；许可","pun":"肯森特","story":"con-（共同）+ sent（感觉）：大家「肯森特」——肯定森特这个方案，一致同意。","ex":"Doctors must obtain informed consent before carrying out any procedure.","exCn":"医生在进行任何医疗程序前必须获得知情同意。","col":["informed consent","give consent","consent to"]},{"id":480,"topic":"health","w":"confidential","ipa":"/ˌkɒnfɪˈdenʃl/","pos":"adj.","cn":"保密的；机密的","pun":"看肥点手","story":"confide（吐露秘密）：「看肥点手」——病历里连你胖了几斤都写着，得保密。","ex":"Medical records must be kept strictly confidential to protect patient privacy.","exCn":"医疗记录必须严格保密以保护患者隐私。","col":["confidential information","strictly confidential","confidentiality"]},{"id":481,"topic":"health","w":"ethical","ipa":"/ˈeθɪkl/","pos":"adj.","cn":"道德的；伦理的","pun":"爱死可","story":"ethic（伦理）：医生要「爱死可」——爱病人爱到死也可以，这才合乎道德。","ex":"Genetic engineering raises serious ethical questions about human intervention.","exCn":"基因工程引发了关于人类干预的严重伦理问题。","col":["ethical issue","ethical concern","ethics"]},{"id":482,"topic":"health","w":"hazard","ipa":"/ˈhæzəd/","pos":"n.","cn":"危害；危险","pun":"害则的","story":"「害则的」——有害的东西，就是危险源。","ex":"Poorly stored chemicals pose a serious health hazard to factory workers.","exCn":"储存不当的化学品对工厂工人构成严重的健康危害。","col":["health hazard","pose a hazard","hazardous"]},{"id":483,"topic":"health","w":"carcinogen","ipa":"/kɑːˈsɪnədʒən/","pos":"n.","cn":"致癌物","pun":"卡新呢真","story":"carcin（癌）+ gen（产生）：「卡新呢真」——卡在肺里的新东西真会致癌，致癌物。","ex":"Tobacco smoke contains dozens of known carcinogens.","exCn":"烟草烟雾含有数十种已知致癌物。","col":["known carcinogen","potential carcinogen","carcinogenic"]},{"id":484,"topic":"health","w":"anxiety","ipa":"/æŋˈzaɪəti/","pos":"n.","cn":"焦虑；忧虑","pun":"俺仔啊踢","story":"「俺仔啊踢」——俺家仔考试前紧张得直踢腿，这就是焦虑。","ex":"Rising levels of anxiety among young people have been linked to social media use.","exCn":"年轻人焦虑水平上升与社交媒体的使用有关。","col":["anxiety disorder","suffer from anxiety","anxious"]},{"id":485,"topic":"health","w":"depression","ipa":"/dɪˈpreʃn/","pos":"n.","cn":"抑郁症；沮丧","pun":"低扑来身","story":"de-（向下）+ press（压）：情绪「低扑来身」——低到压在身上抬不起头，抑郁症。","ex":"Depression is now one of the leading causes of disability worldwide.","exCn":"抑郁症现已成为全球致残的主要原因之一。","col":["clinical depression","suffer from depression","depressed"]},{"id":486,"topic":"health","w":"insomnia","ipa":"/ɪnˈsɒmniə/","pos":"n.","cn":"失眠","pun":"因啥没你啊","story":"in-（无）+ somn（睡）：半夜问「因啥没你啊」——因为啥睡意没来找你啊？失眠。","ex":"Chronic insomnia can lead to serious physical and mental health problems.","exCn":"长期失眠会导致严重的身心健康问题。","col":["suffer from insomnia","chronic insomnia","sleepless"]},{"id":487,"topic":"health","w":"psychological","ipa":"/ˌsaɪkəˈlɒdʒɪkl/","pos":"adj.","cn":"心理的","pun":"赛扣捞积扣","story":"psycho（心灵）+ logy（学）：「赛扣捞积扣」——从心里一扣一扣捞出积压的事，心理的。","ex":"Bullying can cause lasting psychological harm to children.","exCn":"欺凌会对儿童造成持久的心理伤害。","col":["psychological problems","psychological effect","psychology"]},{"id":488,"topic":"health","w":"psychiatrist","ipa":"/saɪˈkaɪətrɪst/","pos":"n.","cn":"精神科医生","pun":"塞开啊吹死特","story":"psych（心）+ iatr（医）：「塞开啊吹死特」——把塞住的心打开，吹散特别多的愁，精神科医生。","ex":"There is a severe shortage of psychiatrists in many rural regions.","exCn":"许多农村地区精神科医生严重短缺。","col":["see a psychiatrist","child psychiatrist","psychiatry"]},{"id":489,"topic":"health","w":"counselling","ipa":"/ˈkaʊnsəlɪŋ/","pos":"n.","cn":"心理咨询；辅导","pun":"康色灵","story":"counsel（劝告）：「康色灵」——聊完之后脸色变得健康又灵动，心理咨询。","ex":"Schools should offer counselling to students struggling with exam stress.","exCn":"学校应为受考试压力困扰的学生提供心理咨询。","col":["counselling service","receive counselling","counsellor"]},{"id":490,"topic":"health","w":"trauma","ipa":"/ˈtrɔːmə/","pos":"n.","cn":"创伤；精神创伤","pun":"揣么","story":"「揣么」——被人揣了一脚，心里的伤口比腿上更深，创伤。","ex":"Survivors of natural disasters often experience long-term psychological trauma.","exCn":"自然灾害的幸存者常常经历长期的心理创伤。","col":["childhood trauma","emotional trauma","traumatic"]},{"id":491,"topic":"health","w":"stigma","ipa":"/ˈstɪɡmə/","pos":"n.","cn":"污名；耻辱","pun":"死踢个么","story":"「死踢个么」——一提精神病就被人死命踢一脚，这就是污名。","ex":"The stigma surrounding mental illness prevents many people from seeking help.","exCn":"围绕精神疾病的污名使许多人不愿寻求帮助。","col":["social stigma","remove the stigma","stigmatise"]},{"id":492,"topic":"health","w":"cope","ipa":"/kəʊp/","pos":"v.","cn":"应对；处理","pun":"扣扑","story":"压力来了，「扣扑」——扣住它再扑倒它，成功应对。","ex":"Many students find it difficult to cope with the pressure of university life.","exCn":"许多学生发现很难应对大学生活的压力。","col":["cope with stress","cope well","coping strategy"]},{"id":493,"topic":"health","w":"mindfulness","ipa":"/ˈmaɪndflnəs/","pos":"n.","cn":"正念；专注当下","pun":"买的佛呢死","story":"mind（心）+ full：「买的佛呢死」——买了佛像天天静坐观心，正念。","ex":"Mindfulness training has been shown to reduce stress in the workplace.","exCn":"正念训练已被证明能减轻职场压力。","col":["practise mindfulness","mindfulness meditation","mindful"]},{"id":494,"topic":"health","w":"meditation","ipa":"/ˌmedɪˈteɪʃn/","pos":"n.","cn":"冥想；沉思","pun":"没地推身","story":"「没地推身」——没有地方推开身体的杂念？闭眼冥想就行。","ex":"Daily meditation is increasingly recommended as a way to manage anxiety.","exCn":"每日冥想越来越被推荐为管理焦虑的方式。","col":["practise meditation","meditation techniques","meditate"]},{"id":495,"topic":"health","w":"self-esteem","ipa":"/ˌself ɪˈstiːm/","pos":"n.","cn":"自尊；自信","pun":"塞夫一死挺","story":"self（自己）+ esteem（尊重）：「塞夫一死挺」——塞夫就算死也挺直腰，有自尊。","ex":"Constant comparison on social media can damage teenagers' self-esteem.","exCn":"在社交媒体上不断比较会损害青少年的自尊。","col":["low self-esteem","boost self-esteem","self-confidence"]},{"id":496,"topic":"health","w":"loneliness","ipa":"/ˈləʊnlinəs/","pos":"n.","cn":"孤独；寂寞","pun":"楼里呢死","story":"lone（独自）+ -ness：「楼里呢死」——一个人在楼里待到死也没人来，孤独。","ex":"Loneliness among the elderly is now recognised as a serious public health issue.","exCn":"老年人的孤独如今被视为严重的公共卫生问题。","col":["chronic loneliness","feelings of loneliness","lonely"]},{"id":497,"topic":"health","w":"abuse","ipa":"/əˈbjuːs/","pos":"n.","cn":"滥用；虐待","pun":"饿不死","story":"ab-（离开正道）+ use（用）：药「饿不死」也拼命吃——用错了方式，滥用。","ex":"Drug abuse places an enormous strain on emergency services.","exCn":"药物滥用给急救服务带来巨大压力。","col":["substance abuse","alcohol abuse","abusive"]},{"id":498,"topic":"health","w":"binge","ipa":"/bɪndʒ/","pos":"n./v.","cn":"狂饮；暴食","pun":"饼吃","story":"「饼吃」——一口气把一桌饼全吃光，这就是暴食。","ex":"Binge drinking among young adults is a growing concern for health authorities.","exCn":"年轻人的狂饮问题日益引起卫生部门的关注。","col":["binge drinking","binge eating","go on a binge"]},{"id":499,"topic":"health","w":"tobacco","ipa":"/təˈbækəʊ/","pos":"n.","cn":"烟草","pun":"特白扣","story":"「特白扣」——烟草一吸，牙齿特别不白，肺也扣了分。","ex":"Higher taxes on tobacco products have proved effective in reducing smoking.","exCn":"对烟草产品提高税收已被证明能有效减少吸烟。","col":["tobacco industry","tobacco products","smoking"]},{"id":500,"topic":"health","w":"nicotine","ipa":"/ˈnɪkətiːn/","pos":"n.","cn":"尼古丁","pun":"你可停","story":"「你可停」——尼古丁让你上瘾，你可停不下来。","ex":"Nicotine is highly addictive, which makes quitting smoking extremely difficult.","exCn":"尼古丁极易上瘾，这使得戒烟极其困难。","col":["nicotine addiction","nicotine patch","nicotine replacement"]},{"id":501,"topic":"health","w":"dietary","ipa":"/ˈdaɪətəri/","pos":"adj.","cn":"饮食的","pun":"呆特累","story":"diet（饮食）+ -ary：「呆特累」——饮食不好，人就呆呆的特别累，饮食的。","ex":"Dietary habits formed in childhood tend to persist into adulthood.","exCn":"童年形成的饮食习惯往往会延续到成年。","col":["dietary habits","dietary requirements","diet"]},{"id":502,"topic":"health","w":"calorie","ipa":"/ˈkæləri/","pos":"n.","cn":"卡路里；热量","pun":"卡了里","story":"「卡了里」——热量都卡在肚子里出不去，卡路里。","ex":"Restaurants are now required to display the calorie content of their meals.","exCn":"餐馆现在被要求标明餐食的热量含量。","col":["calorie intake","high in calories","low-calorie"]},{"id":503,"topic":"health","w":"intake","ipa":"/ˈɪnteɪk/","pos":"n.","cn":"摄入量","pun":"印特克","story":"in（进）+ take（拿）：「印特克」——吃进去的都印在体重秤上，摄入量。","ex":"Reducing salt intake can lower blood pressure within a few weeks.","exCn":"减少盐摄入量可在几周内降低血压。","col":["daily intake","sugar intake","take in"]},{"id":504,"topic":"health","w":"protein","ipa":"/ˈprəʊtiːn/","pos":"n.","cn":"蛋白质","pun":"扑肉挺","story":"「扑肉挺」——扑向肉，吃完肌肉挺起来，蛋白质。","ex":"A diet lacking in protein can slow growth and weaken the immune system.","exCn":"缺乏蛋白质的饮食会减缓生长并削弱免疫系统。","col":["high-protein diet","source of protein","protein-rich"]},{"id":505,"topic":"health","w":"carbohydrate","ipa":"/ˌkɑːbəʊˈhaɪdreɪt/","pos":"n.","cn":"碳水化合物","pun":"卡包海追特","story":"carbo（碳）+ hydrate（水）：「卡包海追特」——卡着面包在海边追人特别有力气，碳水化合物。","ex":"Refined carbohydrates such as white bread cause rapid spikes in blood sugar.","exCn":"白面包等精制碳水化合物会导致血糖迅速升高。","col":["complex carbohydrates","refined carbohydrates","carbs"]},{"id":506,"topic":"health","w":"fibre","ipa":"/ˈfaɪbə(r)/","pos":"n.","cn":"纤维","pun":"翻吧","story":"「翻吧」——多吃纤维，肠子翻吧翻吧就通畅了。","ex":"Diets rich in fibre are associated with lower rates of bowel cancer.","exCn":"富含纤维的饮食与较低的肠癌发病率相关。","col":["dietary fibre","high in fibre","fibre intake"]},{"id":507,"topic":"health","w":"supplement","ipa":"/ˈsʌplɪmənt/","pos":"n./v.","cn":"补充剂；补充","pun":"傻扑里闷特","story":"sup-（下）+ ple（填满）：「傻扑里闷特」——傻傻地往嘴里扑维生素片，补充剂。","ex":"Many people take vitamin supplements despite little evidence of their benefits.","exCn":"尽管几乎没有证据表明有益，许多人仍服用维生素补充剂。","col":["dietary supplement","vitamin supplement","supplementary"]},{"id":508,"topic":"health","w":"malnutrition","ipa":"/ˌmælnjuːˈtrɪʃn/","pos":"n.","cn":"营养不良","pun":"猫牛吹身","story":"mal-（坏）+ nutrition（营养）：「猫牛吹身」——瘦得像猫，牛一吹就倒，营养不良。","ex":"Malnutrition remains a leading cause of child mortality in poorer countries.","exCn":"营养不良仍是贫穷国家儿童死亡的主要原因。","col":["child malnutrition","suffer from malnutrition","malnourished"]},{"id":509,"topic":"health","w":"processed","ipa":"/ˈprəʊsest/","pos":"adj.","cn":"加工过的","pun":"扑肉塞死特","story":"process（加工）+ -ed：「扑肉塞死特」——肉被扑倒、塞进机器加工，加工食品。","ex":"Heavily processed foods are often high in salt, sugar and fat.","exCn":"深加工食品往往含有大量盐、糖和脂肪。","col":["processed food","highly processed","food processing"]},{"id":510,"topic":"health","w":"metabolism","ipa":"/məˈtæbəlɪzəm/","pos":"n.","cn":"新陈代谢","pun":"么太薄里怎","story":"「么太薄里怎」——怎么吃都太瘦？因为新陈代谢快。","ex":"Regular exercise boosts metabolism and helps maintain a healthy weight.","exCn":"规律运动能促进新陈代谢并有助于保持健康体重。","col":["boost metabolism","slow metabolism","metabolic"]},{"id":511,"topic":"health","w":"digestion","ipa":"/daɪˈdʒestʃən/","pos":"n.","cn":"消化","pun":"呆杰斯陈","story":"digest（消化）：「呆杰斯陈」——吃完饭呆呆地坐着，杰斯和陈都在消化。","ex":"Eating slowly aids digestion and helps prevent overeating.","exCn":"细嚼慢咽有助于消化并防止暴饮暴食。","col":["poor digestion","aid digestion","digest"]},{"id":512,"topic":"health","w":"appetite","ipa":"/ˈæpɪtaɪt/","pos":"n.","cn":"食欲；胃口","pun":"爱陪泰特","story":"「爱陪泰特」——爱陪泰特一起吃饭，胃口特别好，食欲。","ex":"Loss of appetite is a common side effect of chemotherapy.","exCn":"食欲减退是化疗常见的副作用。","col":["loss of appetite","healthy appetite","appetising"]},{"id":513,"topic":"health","w":"dehydration","ipa":"/ˌdiːhaɪˈdreɪʃn/","pos":"n.","cn":"脱水","pun":"地海追身","story":"de-（去）+ hydr（水）：「地海追身」——地上的海都追不上身体丢水的速度，脱水。","ex":"Elderly people are at greater risk of dehydration during heatwaves.","exCn":"老年人在热浪期间脱水风险更大。","col":["severe dehydration","suffer from dehydration","dehydrated"]},{"id":514,"topic":"health","w":"aerobic","ipa":"/eəˈrəʊbɪk/","pos":"adj.","cn":"有氧的","pun":"爱肉比克","story":"aero（空气）：「爱肉比克」——爱肉的人也得比克服惰性去跑步，有氧运动。","ex":"Thirty minutes of aerobic exercise a day can significantly improve heart health.","exCn":"每天三十分钟有氧运动能显著改善心脏健康。","col":["aerobic exercise","aerobic fitness","aerobics"]},{"id":515,"topic":"health","w":"stamina","ipa":"/ˈstæmɪnə/","pos":"n.","cn":"耐力；持久力","pun":"死他米呐","story":"「死他米呐」——跑到累死也不停，全靠平时吃米练的耐力。","ex":"Long-distance runners need exceptional stamina to complete a marathon.","exCn":"长跑运动员需要非凡的耐力才能完成马拉松。","col":["build stamina","physical stamina","endurance"]},{"id":516,"topic":"health","w":"posture","ipa":"/ˈpɒstʃə(r)/","pos":"n.","cn":"姿势；体态","pun":"跑死着","story":"「跑死着」——弯腰驼背跑步，跑到死也跑不快，得改姿势。","ex":"Poor posture from prolonged screen use is causing back problems in young people.","exCn":"长时间使用屏幕导致的不良姿势正引发年轻人的背部问题。","col":["poor posture","good posture","improve posture"]},{"id":517,"topic":"health","w":"injury","ipa":"/ˈɪndʒəri/","pos":"n.","cn":"受伤；损伤","pun":"印这里","story":"「印这里」——伤疤印在这里，受伤留下的痕迹。","ex":"Sports injuries are common among teenagers who train without proper supervision.","exCn":"在没有适当监督下训练的青少年中，运动损伤很常见。","col":["serious injury","sports injury","injure"]},{"id":518,"topic":"health","w":"fracture","ipa":"/ˈfræktʃə(r)/","pos":"n.","cn":"骨折；断裂","pun":"腹裂扯","story":"fract（断）：「腹裂扯」——摔倒时腹部裂开一样疼，扯一下骨头断了，骨折。","ex":"Hip fractures in elderly patients often lead to a permanent loss of independence.","exCn":"老年患者髋部骨折常导致永久丧失自理能力。","col":["hip fracture","suffer a fracture","fractured bone"]},{"id":519,"topic":"health","w":"inflammation","ipa":"/ˌɪnfləˈmeɪʃn/","pos":"n.","cn":"炎症；发炎","pun":"因扶了没身","story":"in-（进）+ flame（火）：「因扶了没身」——因为扶了一下没戴手套，伤口火烧一样红肿，发炎。","ex":"Chronic inflammation has been linked to heart disease and several cancers.","exCn":"慢性炎症与心脏病和多种癌症有关。","col":["reduce inflammation","chronic inflammation","inflamed"]},{"id":520,"topic":"health","w":"genetic","ipa":"/dʒəˈnetɪk/","pos":"adj.","cn":"基因的；遗传的","pun":"这奶踢克","story":"gene（基因）：「这奶踢克」——这孩子踢球像奶奶，基因遗传的。","ex":"Genetic testing can reveal a person's risk of developing certain diseases.","exCn":"基因检测可以揭示一个人患某些疾病的风险。","col":["genetic disorder","genetic testing","genetics"]},{"id":521,"topic":"health","w":"hereditary","ipa":"/həˈredɪtri/","pos":"adj.","cn":"遗传的","pun":"喝累的吹","story":"hered（继承）：「喝累的吹」——爸爸喝酒累了爱吹牛，儿子也一样，遗传的。","ex":"Some hereditary conditions can now be identified before a child is born.","exCn":"一些遗传病现在可以在孩子出生前被识别。","col":["hereditary disease","hereditary factors","inherit"]},{"id":522,"topic":"society","w":"inequality","ipa":"/ˌɪnɪˈkwɒləti/","pos":"n.","cn":"不平等","pun":"一你阔了提","story":"in（不）+ equal（平等）。「一」看「你阔了」，我却没「提」高——不平等。","ex":"Income inequality has widened in recent decades.","exCn":"近几十年收入不平等加剧了。","col":["income / social inequality","gender inequality","reduce inequality"]},{"id":523,"topic":"society","w":"welfare","ipa":"/ˈwelfeə(r)/","pos":"n.","cn":"福利；幸福","pun":"喂 fair","story":"well（好）+ fare（过日子）。国家把大家「喂」得「fair」（公平），就是福利。","ex":"The government spends billions on social welfare each year.","exCn":"政府每年在社会福利上投入数十亿。","col":["social welfare","welfare state","welfare benefits"]},{"id":524,"topic":"society","w":"urbanisation","ipa":"/ˌɜːbənaɪˈzeɪʃn/","pos":"n.","cn":"城市化","pun":"饿本奶贼神","story":"urban 是城市。进城之后「饿」着肚子攒「本」钱买「奶」，「贼神」奇——城市化生活。","ex":"Rapid urbanisation has put pressure on housing and transport.","exCn":"快速城市化给住房和交通带来压力。","col":["rapid urbanisation","urban areas","rural-to-urban migration"]},{"id":525,"topic":"society","w":"commute","ipa":"/kəˈmjuːt/","pos":"v./n.","cn":"通勤","pun":"可谬特","story":"每天两小时上班路，「可谬特」（可太荒谬）了——通勤。","ex":"Many people commute for over an hour each way.","exCn":"许多人单程通勤超过一小时。","col":["commute to work","a long commute","commuter (n.)"]},{"id":526,"topic":"society","w":"unemployment","ipa":"/ˌʌnɪmˈplɔɪmənt/","pos":"n.","cn":"失业","pun":"俺 no 破落门","story":"un（不）+ employ（雇用）。「俺」没工作，「no」钱，家里「破落门」。","ex":"Youth unemployment remains a major challenge for the economy.","exCn":"青年失业仍是经济面临的重大挑战。","col":["unemployment rate","youth unemployment","unemployed (adj.)"]},{"id":527,"topic":"society","w":"immigrant","ipa":"/ˈɪmɪɡrənt/","pos":"n.","cn":"移民（移入者）","pun":"一米哥 run 特","story":"「一米哥」「run」到国外定居——移民。","ex":"Immigrants contribute significantly to the economy of their host country.","exCn":"移民对所在国经济贡献巨大。","col":["illegal immigrants","immigration (n.)","emigrate 移出 vs immigrate 移入"]},{"id":528,"topic":"society","w":"poverty","ipa":"/ˈpɒvəti/","pos":"n.","cn":"贫穷","pun":"破屋提","story":"住在「破屋」里，每天「提」水桶——贫穷。","ex":"Millions of children still live in extreme poverty.","exCn":"数百万儿童仍生活在极端贫困中。","col":["live in poverty","poverty line","alleviate poverty"]},{"id":529,"topic":"society","w":"crime","ipa":"/kraɪm/","pos":"n.","cn":"犯罪","pun":"快埋","story":"犯了罪，证据「快埋」起来。","ex":"CCTV cameras have helped to reduce crime rates in city centres.","exCn":"监控摄像头帮助降低了市中心的犯罪率。","col":["crime rate","commit a crime","criminal (n./adj.)"]},{"id":530,"topic":"society","w":"globalisation","ipa":"/ˌɡləʊbəlaɪˈzeɪʃn/","pos":"n.","cn":"全球化","pun":"够楼抱来贼神","story":"global 是全球。「够」在「楼」下就能「抱来」全球货，「贼神」——全球化。","ex":"Globalisation has made the world more interconnected than ever.","exCn":"全球化让世界比以往任何时候都更紧密相连。","col":["economic globalisation","the effects of globalisation","global (adj.)"]},{"id":531,"topic":"society","w":"ambitious","ipa":"/æmˈbɪʃəs/","pos":"adj.","cn":"有野心的；雄心勃勃的","pun":"俺必胜","story":"「俺必胜」！——一听就野心勃勃。","ex":"The government has set an ambitious target to eliminate poverty by 2040.","exCn":"政府设定了到 2040 年消除贫困的雄心目标。","col":["an ambitious plan / target","ambition (n.)"]},{"id":532,"topic":"work","w":"recruit","ipa":"/rɪˈkruːt/","pos":"v./n.","cn":"招聘；新成员","pun":"日哭特","story":"HR 天天加班到日落还在哭：特别难招人！招聘（recruit）真不容易。","ex":"Many firms now recruit graduates through online platforms rather than traditional job fairs.","exCn":"许多公司现在通过网络平台而非传统招聘会来招聘毕业生。","col":["recruit staff","recruitment agency","recruiter"]},{"id":533,"topic":"work","w":"candidate","ipa":"/ˈkændɪdət/","pos":"n.","cn":"候选人；应聘者","pun":"看的呆特","story":"面试官盯着这位候选人看得呆了：简历太漂亮，这个 candidate 特别优秀。","ex":"The ideal candidate should have at least three years of relevant experience.","exCn":"理想的候选人应具备至少三年相关经验。","col":["suitable candidate","shortlist candidates","candidacy"]},{"id":534,"topic":"work","w":"applicant","ipa":"/ˈæplɪkənt/","pos":"n.","cn":"申请人","pun":"爱铺利肯特","story":"apply（申请）+ -ant（人）：申请人爱铺满桌子的简历，肯定特别想要这份工作。","ex":"Applicants are required to submit a CV and a covering letter before the deadline.","exCn":"申请人须在截止日期前提交简历和求职信。","col":["job applicant","screen applicants","application form"]},{"id":535,"topic":"work","w":"vacancy","ipa":"/ˈveɪkənsi/","pos":"n.","cn":"职位空缺","pun":"未肯洗","story":"洗碗工的位子空着，因为大家都未肯洗碗——这就是职位空缺（vacancy）。","ex":"The company advertised several vacancies for software engineers last month.","exCn":"该公司上个月发布了几个软件工程师的职位空缺。","col":["fill a vacancy","job vacancy","vacant position"]},{"id":536,"topic":"work","w":"shortlist","ipa":"/ˈʃɔːtlɪst/","pos":"v./n.","cn":"列入候选名单","pun":"消特利斯特","story":"short（短）+ list（名单）：把长名单消减成特别短的名单，剩下的人就是入围者。","ex":"Only five applicants were shortlisted for the final round of interviews.","exCn":"只有五名申请人入围了最后一轮面试。","col":["be shortlisted for","draw up a shortlist","make the shortlist"]},{"id":537,"topic":"work","w":"referee","ipa":"/ˌrefəˈriː/","pos":"n.","cn":"推荐人；裁判","pun":"来福瑞","story":"求职时请前老板当推荐人，他说：「来，福气瑞气都给你」，一封推荐信帮你拿下工作。","ex":"Applicants should provide the names of two referees who can comment on their work.","exCn":"申请人应提供两位能评价其工作表现的推荐人姓名。","col":["act as a referee","reference letter","refer"]},{"id":538,"topic":"work","w":"probation","ipa":"/prəˈbeɪʃn/","pos":"n.","cn":"试用期","pun":"跑被审","story":"试用期里天天跑来跑去干活，还要被审核——通过了才能转正。","ex":"New employees are usually on probation for the first three months of their contract.","exCn":"新员工通常在合同前三个月处于试用期。","col":["probation period","on probation","probationary"]},{"id":539,"topic":"work","w":"apprentice","ipa":"/əˈprentɪs/","pos":"n.","cn":"学徒","pun":"额扑人提示","story":"学徒额头上扑满汗，师傅在旁边不停提示：apprentice 就是这样边干边学的人。","ex":"Apprentices learn a trade by working alongside experienced professionals.","exCn":"学徒通过跟随经验丰富的专业人士工作来学习一门手艺。","col":["apprenticeship","serve an apprenticeship","trainee"]},{"id":540,"topic":"work","w":"colleague","ipa":"/ˈkɒliːɡ/","pos":"n.","cn":"同事","pun":"靠利哥","story":"办公室里靠着利哥帮忙，因为利哥是最靠谱的同事（colleague）。","ex":"A supportive relationship with colleagues is essential for job satisfaction.","exCn":"与同事之间的相互支持对工作满意度至关重要。","col":["close colleague","former colleague","co-worker"]},{"id":541,"topic":"work","w":"subordinate","ipa":"/səˈbɔːdɪnət/","pos":"n./adj.","cn":"下属；下级的","pun":"色伯敌呢","story":"sub（下）+ ordin（顺序）：排序在下面的人，就是上司眼里的下属。","ex":"Good managers listen to their subordinates rather than simply giving orders.","exCn":"优秀的管理者会倾听下属的意见，而不是一味下命令。","col":["subordinate staff","be subordinate to","superior"]},{"id":542,"topic":"work","w":"executive","ipa":"/ɪɡˈzekjətɪv/","pos":"n./adj.","cn":"高管；行政的","pun":"一个贼可提","story":"公司里一个高管提着公文包走过，大家说：这一个贼可以，是 executive！","ex":"Senior executives often receive bonuses that far exceed the average worker's salary.","exCn":"高管获得的奖金常常远超普通员工的薪水。","col":["chief executive","executive director","execute"]},{"id":543,"topic":"work","w":"entrepreneur","ipa":"/ˌɒntrəprəˈnɜː(r)/","pos":"n.","cn":"企业家；创业者","pun":"昂穿扑呢","story":"创业者昂着头，穿着西装扑向市场，呢，这就是 entrepreneur 的气质。","ex":"Successful entrepreneurs are willing to take risks that others would avoid.","exCn":"成功的企业家愿意承担别人会回避的风险。","col":["young entrepreneur","entrepreneurial spirit","entrepreneurship"]},{"id":544,"topic":"work","w":"freelance","ipa":"/ˈfriːlɑːns/","pos":"adj./adv./v.","cn":"自由职业的","pun":"free 懒死","story":"free（自由）+ lance（长矛）：中世纪的自由骑士自己接单；现在自由职业者也自由，但绝不能懒死。","ex":"An increasing number of designers choose to work freelance rather than for one company.","exCn":"越来越多的设计师选择做自由职业，而不是只为一家公司工作。","col":["freelance writer","work freelance","freelancer"]},{"id":545,"topic":"work","w":"self-employed","ipa":"/ˌself ɪmˈplɔɪd/","pos":"adj.","cn":"自雇的；个体经营的","pun":"self 硬扑劳一的","story":"self（自己）+ employed（受雇）：自己雇自己，硬着头皮扑向劳动，一切靠自己。","ex":"Self-employed workers enjoy flexibility but often lack sick pay and pension contributions.","exCn":"自雇者享有灵活性，却往往没有病假工资和养老金缴纳。","col":["become self-employed","self-employment","sole trader"]},{"id":546,"topic":"work","w":"workforce","ipa":"/ˈwɜːkfɔːs/","pos":"n.","cn":"劳动力；全体员工","pun":"沃克佛斯","story":"work（工作）+ force（力量）：所有能工作的力量加起来，就是一国的劳动力。","ex":"An ageing workforce poses serious challenges for many developed economies.","exCn":"劳动力老龄化给许多发达经济体带来严峻挑战。","col":["skilled workforce","join the workforce","labour force"]},{"id":547,"topic":"work","w":"labour","ipa":"/ˈleɪbə(r)/","pos":"n./v.","cn":"劳动；劳工","pun":"累啵","story":"体力劳动累得嘴里只剩「啵」的一声——labour 就是苦干。","ex":"Cheap labour has attracted many multinational companies to developing countries.","exCn":"廉价劳动力吸引了许多跨国公司前往发展中国家。","col":["manual labour","labour market","labour shortage"]},{"id":548,"topic":"work","w":"manual","ipa":"/ˈmænjuəl/","pos":"adj./n.","cn":"体力的；手册","pun":"卖牛儿","story":"manu（手）：用手干活的体力活，比如牵着卖牛儿；操作手册也是手拿着看的。","ex":"Manual workers are often the first to lose their jobs when machines are introduced.","exCn":"引入机器时，体力劳动者往往最先失业。","col":["manual labour","manual worker","instruction manual"]},{"id":549,"topic":"work","w":"white-collar","ipa":"/ˌwaɪt ˈkɒlə(r)/","pos":"adj.","cn":"白领的","pun":"歪特靠了","story":"white（白）+ collar（衣领）：穿白衬衫的办公室职员，歪在椅子上靠着——白领。","ex":"White-collar jobs in finance and law remain highly sought after by graduates.","exCn":"金融和法律领域的白领工作仍然备受毕业生追捧。","col":["white-collar worker","white-collar job","blue-collar"]},{"id":550,"topic":"work","w":"occupation","ipa":"/ˌɒkjuˈpeɪʃn/","pos":"n.","cn":"职业；占据","pun":"哦 Q 配审","story":"occupy（占据）：填表时职业一栏，哦，Q 姐配合审核写下「教师」——occupation 就是职业。","ex":"Certain occupations, such as nursing, are still dominated by women.","exCn":"某些职业，比如护理，仍然以女性为主。","col":["choice of occupation","occupational health","occupy"]},{"id":551,"topic":"work","w":"profession","ipa":"/prəˈfeʃn/","pos":"n.","cn":"（专业）职业","pun":"扑飞神","story":"pro（前）+ fess（说）：公开宣誓从业的人，像扑向天空的飞神，是律师医生这类专业职业。","ex":"Teaching is a profession that requires both patience and expert knowledge.","exCn":"教师是一门既需要耐心又需要专业知识的职业。","col":["legal profession","enter a profession","professional"]},{"id":552,"topic":"work","w":"promotion","ipa":"/prəˈməʊʃn/","pos":"n.","cn":"晋升；促销","pun":"扑猫神","story":"pro（向前）+ mot（动）：往前动一步，扑向更高的位置，像猫一样敏捷——晋升啦！","ex":"Employees who work overtime are not necessarily the ones who receive promotion.","exCn":"加班的员工不一定就是获得晋升的人。","col":["gain promotion","promotion prospects","promote"]},{"id":553,"topic":"work","w":"redundancy","ipa":"/rɪˈdʌndənsi/","pos":"n.","cn":"裁员；冗余","pun":"日蛋蛋洗","story":"公司裁员那天，被裁的人回家日日只能对着蛋蛋洗碗——redundancy 就是被裁。","ex":"The factory closure led to hundreds of redundancies in the local community.","exCn":"工厂关闭导致当地社区数百人被裁员。","col":["face redundancy","redundancy payment","be made redundant"]},{"id":554,"topic":"work","w":"dismiss","ipa":"/dɪsˈmɪs/","pos":"v.","cn":"解雇；驳回","pun":"弟死密死","story":"dis（离开）+ miss（送）：把人送走。老板解雇小弟，小弟死也想不到秘密被发现了。","ex":"Employees cannot be dismissed without a valid reason under current labour law.","exCn":"根据现行劳动法，不得无正当理由解雇员工。","col":["be dismissed from","unfair dismissal","dismissal"]},{"id":555,"topic":"work","w":"resign","ipa":"/rɪˈzaɪn/","pos":"v.","cn":"辞职","pun":"日灾","story":"re（回）+ sign（签字）：把合同签回去，从此天天像遭日灾一样自由——辞职了。","ex":"She resigned from her position after the company refused to address her concerns.","exCn":"公司拒绝回应她的关切后，她辞去了职务。","col":["resign from","hand in one's resignation","resignation"]},{"id":556,"topic":"work","w":"retire","ipa":"/rɪˈtaɪə(r)/","pos":"v.","cn":"退休","pun":"日太耶","story":"re（回）+ tire（累）：累了几十年终于回家，每日太耶（太爽）——退休生活。","ex":"Many people choose to retire later because their pensions are insufficient.","exCn":"许多人因养老金不足而选择推迟退休。","col":["retire early","retirement age","retired"]},{"id":557,"topic":"work","w":"pension","ipa":"/ˈpenʃn/","pos":"n.","cn":"养老金","pun":"盆神","story":"退休后每月从养老金盆里舀钱，简直像盆里住着神——pension。","ex":"The government plans to raise the age at which citizens can claim a state pension.","exCn":"政府计划提高公民可领取国家养老金的年龄。","col":["state pension","pension scheme","pensioner"]},{"id":558,"topic":"work","w":"salary","ipa":"/ˈsæləri/","pos":"n.","cn":"薪水（月薪/年薪）","pun":"塞了利","story":"sal（盐）：古罗马用盐当工资；每月老板往你口袋塞了利，就是薪水。","ex":"A competitive salary is not the only factor that attracts talented staff.","exCn":"有竞争力的薪水并不是吸引人才的唯一因素。","col":["annual salary","salary increase","salaried"]},{"id":559,"topic":"work","w":"wage","ipa":"/weɪdʒ/","pos":"n.","cn":"工资（时薪/周薪）","pun":"喂几","story":"工人按小时领工资：老板问喂几个小时了？就发几个小时的钱——wage。","ex":"Raising the minimum wage may reduce poverty but could also increase unemployment.","exCn":"提高最低工资可能减少贫困，但也可能增加失业。","col":["minimum wage","hourly wage","wage gap"]},{"id":560,"topic":"work","w":"income","ipa":"/ˈɪnkʌm/","pos":"n.","cn":"收入","pun":"银亢","story":"in（进）+ come（来）：进来的银子，多得让人亢奋——收入。","ex":"Households with a low income spend a larger proportion of their earnings on food.","exCn":"低收入家庭在食物上的支出占比更大。","col":["disposable income","income tax","source of income"]},{"id":561,"topic":"work","w":"bonus","ipa":"/ˈbəʊnəs/","pos":"n.","cn":"奖金","pun":"包呢死","story":"年底红包呢？老板笑：包里的奖金多得能把你砸死——bonus。","ex":"Performance-related bonuses can motivate staff but may also encourage unhealthy competition.","exCn":"与绩效挂钩的奖金能激励员工，但也可能引发恶性竞争。","col":["annual bonus","performance bonus","receive a bonus"]},{"id":562,"topic":"work","w":"commission","ipa":"/kəˈmɪʃn/","pos":"n.","cn":"佣金；委员会","pun":"可迷神","story":"销售员卖一件抽一点提成，被佣金迷得像神一样疯狂推销——commission。","ex":"Sales staff often receive a commission in addition to their basic salary.","exCn":"销售人员除基本工资外通常还能获得佣金。","col":["earn a commission","on commission","sales commission"]},{"id":563,"topic":"work","w":"perk","ipa":"/pɜːk/","pos":"n.","cn":"额外福利；津贴","pun":"泼克","story":"公司泼给员工的小福利，比如免费咖啡、健身卡，一泼一克都是 perk。","ex":"Free meals and gym membership are common perks offered by technology companies.","exCn":"免费餐食和健身会员是科技公司常见的额外福利。","col":["job perks","company perks","fringe benefit"]},{"id":564,"topic":"work","w":"allowance","ipa":"/əˈlaʊəns/","pos":"n.","cn":"津贴；补贴","pun":"饿了完事","story":"allow（允许）：公司允许你出差饿了就吃，吃完事后报销——这就是津贴。","ex":"Employees who travel frequently are entitled to a daily allowance for meals and accommodation.","exCn":"经常出差的员工有权获得餐饮和住宿的日补贴。","col":["travel allowance","housing allowance","allow"]},{"id":565,"topic":"work","w":"compensation","ipa":"/ˌkɒmpenˈseɪʃn/","pos":"n.","cn":"补偿；薪酬","pun":"看盆赛神","story":"com（一起）+ pens（称重）：把损失称一称补回来；工伤后看着补偿盆，赛过神仙。","ex":"Workers injured on the job are legally entitled to compensation from their employer.","exCn":"在工作中受伤的员工依法有权获得雇主的补偿。","col":["claim compensation","compensation package","compensate"]},{"id":566,"topic":"work","w":"remuneration","ipa":"/rɪˌmjuːnəˈreɪʃn/","pos":"n.","cn":"薪酬；报酬","pun":"日谬呢瑞审","story":"每日缪斯女神呢，瑞气审核你的报酬——remuneration 是正式说法的薪酬。","ex":"The remuneration of top executives has risen far faster than that of ordinary staff.","exCn":"高管薪酬的涨幅远超普通员工。","col":["remuneration package","fair remuneration","remunerate"]},{"id":567,"topic":"work","w":"overtime","ipa":"/ˈəʊvətaɪm/","pos":"n./adv.","cn":"加班","pun":"欧沃太慢","story":"over（超过）+ time（时间）：工作超过时间，欧沃抱怨自己太慢，只好加班。","ex":"Employees who regularly work overtime are more likely to suffer from stress-related illness.","exCn":"经常加班的员工更容易患上与压力有关的疾病。","col":["work overtime","unpaid overtime","overtime pay"]},{"id":568,"topic":"work","w":"shift","ipa":"/ʃɪft/","pos":"n./v.","cn":"轮班；转移","pun":"谁夫特","story":"护士问：今晚谁值夜班？谁的丈夫特别理解，谁就来上这一 shift。","ex":"Night shifts disrupt the body clock and can have long-term effects on health.","exCn":"夜班会打乱生物钟，并可能对健康造成长期影响。","col":["night shift","shift work","work in shifts"]},{"id":569,"topic":"work","w":"flexible","ipa":"/ˈfleksəbl/","pos":"adj.","cn":"灵活的；弹性的","pun":"福来可色","story":"flex（弯曲）：弹性工作让福气来了，可以随意变换颜色和时间——flexible。","ex":"Flexible working hours allow parents to balance their careers with family responsibilities.","exCn":"弹性工作时间让父母能够平衡事业与家庭责任。","col":["flexible working","flexible hours","flexibility"]},{"id":570,"topic":"work","w":"telecommute","ipa":"/ˈtelikəmjuːt/","pos":"v.","cn":"远程办公","pun":"太累可谬特","story":"tele（远）+ commute（通勤）：远距离通勤太累，可谬特了，干脆在家远程办公。","ex":"Employees who telecommute report higher levels of job satisfaction than office-based staff.","exCn":"远程办公的员工比坐班员工的工作满意度更高。","col":["telecommuting","work from home","remote working"]},{"id":571,"topic":"work","w":"remote","ipa":"/rɪˈməʊt/","pos":"adj.","cn":"远程的；偏远的","pun":"日摸特","story":"re（回）+ mot（移动）：移得远远的；远程办公的人每日摸着键盘，特别自在。","ex":"Remote working became the norm for millions of office employees during the pandemic.","exCn":"疫情期间，远程办公成为数百万办公室员工的常态。","col":["remote work","work remotely","remote team"]},{"id":572,"topic":"work","w":"overwhelm","ipa":"/ˌəʊvəˈwelm/","pos":"v.","cn":"使不堪重负；压倒","pun":"欧沃喂门","story":"over（过度）+ whelm（淹没）：任务多得从门口涌进来把欧沃淹没——不堪重负。","ex":"New employees are often overwhelmed by the amount of information they must absorb.","exCn":"新员工常常被必须吸收的大量信息压得喘不过气。","col":["be overwhelmed by","overwhelming workload","overwhelmingly"]},{"id":573,"topic":"work","w":"productivity","ipa":"/ˌprɒdʌkˈtɪvəti/","pos":"n.","cn":"生产力；效率","pun":"扑肉搭剃薇踢","story":"pro（向前）+ duct（引导）：把成果往前导出来；扑上肉搭好，剃刀一挥，效率高得像踢球。","ex":"Studies suggest that shorter working weeks can actually increase productivity.","exCn":"研究表明，缩短每周工时实际上能提高生产力。","col":["boost productivity","labour productivity","productive"]},{"id":574,"topic":"work","w":"multitask","ipa":"/ˌmʌltiˈtɑːsk/","pos":"v.","cn":"同时处理多项任务","pun":"毛提塔斯克","story":"multi（多）+ task（任务）：一边拿毛巾一边提塔一边听课，多任务处理就是 multitask。","ex":"Although many people claim to multitask, research shows it often reduces the quality of work.","exCn":"尽管很多人自称能多任务处理，研究显示这往往降低工作质量。","col":["ability to multitask","multitasking","juggle tasks"]},{"id":575,"topic":"work","w":"delegate","ipa":"/ˈdelɪɡeɪt/","pos":"v./n.","cn":"委派；授权；代表","pun":"得了给它","story":"de（离开）+ leg（派遣）：老板说得了，这活给它（下属）去做——把任务委派出去。","ex":"Effective managers delegate responsibility rather than trying to control every detail.","exCn":"高效的管理者会授权分派责任，而不是试图掌控每个细节。","col":["delegate tasks to","delegation","delegate authority"]},{"id":576,"topic":"work","w":"prioritise","ipa":"/praɪˈɒrətaɪz/","pos":"v.","cn":"优先处理","pun":"拍我瑞太死","story":"prior（在先）：先拍我再拍瑞，不然瑞太急会死——把事情排出先后顺序就是 prioritise。","ex":"Workers must learn to prioritise tasks in order to cope with competing demands.","exCn":"员工必须学会分清任务的优先级，以应对相互竞争的需求。","col":["prioritise tasks","priority","top priority"]},{"id":577,"topic":"work","w":"appraisal","ipa":"/əˈpreɪzl/","pos":"n.","cn":"评估；绩效考核","pun":"额婆瑞走","story":"praise（赞扬）：年终考核时额头冒汗，婆婆瑞姐评完走人——appraisal 就是绩效评估。","ex":"Annual appraisals give employees an opportunity to discuss their progress with managers.","exCn":"年度考核让员工有机会与经理讨论自己的进步。","col":["performance appraisal","annual appraisal","appraise"]},{"id":578,"topic":"work","w":"brainstorm","ipa":"/ˈbreɪnstɔːm/","pos":"v./n.","cn":"集思广益；头脑风暴","pun":"不瑞斯多母","story":"brain（大脑）+ storm（风暴）：脑子里刮风暴，不瑞的点子也多得像母鸡下蛋——头脑风暴。","ex":"Teams often brainstorm ideas before deciding on a final strategy.","exCn":"团队通常先集思广益，再决定最终策略。","col":["brainstorm ideas","brainstorming session","think creatively"]},{"id":579,"topic":"work","w":"competent","ipa":"/ˈkɒmpɪtənt/","pos":"adj.","cn":"能干的；胜任的","pun":"看啤疼特","story":"compete（竞争）：能干的人在竞争中看着对手喝啤酒头疼，自己特别从容——competent。","ex":"Employers value competent staff who can work with minimal supervision.","exCn":"雇主重视无需过多监督也能胜任工作的员工。","col":["highly competent","competent in","competence"]},{"id":580,"topic":"work","w":"proficient","ipa":"/prəˈfɪʃnt/","pos":"adj.","cn":"精通的；熟练的","pun":"扑非神特","story":"pro（前）+ fic（做）：做在前面的人，扑向工作非常神，特别熟练——精通。","ex":"Candidates must be proficient in at least two foreign languages.","exCn":"候选人必须精通至少两门外语。","col":["proficient in","proficiency","language proficiency"]},{"id":581,"topic":"work","w":"versatile","ipa":"/ˈvɜːsətaɪl/","pos":"adj.","cn":"多才多艺的；多用途的","pun":"我色太哦","story":"vers（转）：什么都能转着做，我的颜色太多了哦——versatile 就是多才多艺。","ex":"Versatile employees who can perform several roles are highly valued in small businesses.","exCn":"能胜任多种角色的多面手员工在小企业中备受重视。","col":["versatile worker","versatility","all-rounder"]},{"id":582,"topic":"work","w":"adaptable","ipa":"/əˈdæptəbl/","pos":"adj.","cn":"适应力强的","pun":"额呆铺特包","story":"adapt（适应）+ -able（能）：额，呆在哪都能铺开特大的包住下——适应力强。","ex":"In a rapidly changing job market, workers need to be adaptable and willing to retrain.","exCn":"在快速变化的就业市场中，员工需要适应力强并愿意再培训。","col":["highly adaptable","adaptable to","adaptability"]},{"id":583,"topic":"work","w":"dedicated","ipa":"/ˈdedɪkeɪtɪd/","pos":"adj.","cn":"尽心尽力的；专用的","pun":"呆的可踢的","story":"de（完全）+ dic（说）：完全说到做到；呆在岗位上不走，可踢都踢不走——尽心尽力。","ex":"The hospital relies on a team of dedicated nurses who frequently work unpaid overtime.","exCn":"这家医院依靠一支经常无偿加班的敬业护士团队。","col":["dedicated to","dedication","committed"]},{"id":584,"topic":"work","w":"commitment","ipa":"/kəˈmɪtmənt/","pos":"n.","cn":"投入；承诺","pun":"可密特门","story":"commit（投入）：对工作的投入可以密封在特殊的门里，谁也拉不走——commitment。","ex":"A long-term commitment to staff training benefits both employees and the organisation.","exCn":"对员工培训的长期投入对员工和组织都有益。","col":["commitment to","show commitment","committed"]},{"id":585,"topic":"work","w":"morale","ipa":"/məˈrɑːl/","pos":"n.","cn":"士气","pun":"么绕","story":"士气高的团队，什么困难都不绕道走——morale。","ex":"Frequent layoffs can severely damage the morale of the remaining staff.","exCn":"频繁裁员会严重打击留任员工的士气。","col":["boost morale","low morale","staff morale"]},{"id":586,"topic":"work","w":"coordinate","ipa":"/kəʊˈɔːdɪneɪt/","pos":"v.","cn":"协调","pun":"扣我第内特","story":"co（共同）+ ordin（顺序）：把大家排好顺序；扣住我第一，内特第二——协调。","ex":"The project manager is responsible for coordinating the work of several departments.","exCn":"项目经理负责协调多个部门的工作。","col":["coordinate with","coordination","coordinator"]},{"id":587,"topic":"work","w":"negotiate","ipa":"/nɪˈɡəʊʃieɪt/","pos":"v.","cn":"谈判；协商","pun":"你狗谁诶特","story":"谈判桌上：你的狗归谁？诶，特别难谈——negotiate 就是讨价还价。","ex":"Trade unions negotiate with employers to secure better pay and conditions.","exCn":"工会与雇主谈判，以争取更好的薪酬和条件。","col":["negotiate a contract","negotiation","negotiate with"]},{"id":588,"topic":"work","w":"compromise","ipa":"/ˈkɒmprəmaɪz/","pos":"n./v.","cn":"妥协；折中","pun":"看破卖死","story":"com（一起）+ promise（承诺）：双方一起让步承诺；看破了，别卖到死——妥协吧。","ex":"Both management and workers had to compromise to end the dispute.","exCn":"劳资双方都不得不做出妥协以结束争端。","col":["reach a compromise","compromise on","compromise agreement"]},{"id":589,"topic":"work","w":"harassment","ipa":"/ˈhærəsmənt/","pos":"n.","cn":"骚扰","pun":"害热死门特","story":"害人的热情糊到脸上，让人烦得要死，被堵在门口——这种纠缠就是骚扰。","ex":"Companies must have clear policies for dealing with harassment in the workplace.","exCn":"公司必须制定明确政策来处理职场骚扰问题。","col":["sexual harassment","workplace harassment","harass"]},{"id":590,"topic":"work","w":"discrimination","ipa":"/dɪˌskrɪmɪˈneɪʃn/","pos":"n.","cn":"歧视","pun":"弟死可迷内神","story":"dis（分开）+ crimin（区分）：把人分三六九等；弟弟死盯着可迷的内神不用外人——歧视。","ex":"Age discrimination remains widespread despite laws designed to prevent it.","exCn":"尽管有相关法律，年龄歧视依然普遍存在。","col":["gender discrimination","discriminate against","discriminatory"]},{"id":591,"topic":"work","w":"union","ipa":"/ˈjuːniən/","pos":"n.","cn":"工会；联盟","pun":"油你恩","story":"uni（一）：工人们合成一体；工会说：有油水大家分，你我都有恩——union。","ex":"Trade unions play a vital role in protecting workers from exploitation.","exCn":"工会在保护工人免受剥削方面发挥着重要作用。","col":["trade union","join a union","union member"]},{"id":592,"topic":"work","w":"strike","ipa":"/straɪk/","pos":"n./v.","cn":"罢工；打击","pun":"死踹克","story":"工人罢工时死踹工厂大门，喊：克扣工资我们不干了——strike。","ex":"Thousands of railway workers went on strike over pay and working conditions.","exCn":"数千名铁路工人因薪酬和工作条件问题举行罢工。","col":["go on strike","strike action","striker"]},{"id":593,"topic":"work","w":"ergonomic","ipa":"/ˌɜːɡəˈnɒmɪk/","pos":"adj.","cn":"符合人体工学的","pun":"饿哥闹米克","story":"ergo（工作）+ nom（规律）：饿哥坐在符合人体工学的椅子上闹着要米，腰也不疼了。","ex":"Ergonomic office furniture can reduce back pain and improve concentration.","exCn":"符合人体工学的办公家具能减轻背痛并提高专注力。","col":["ergonomic chair","ergonomic design","ergonomics"]},{"id":594,"topic":"work","w":"permanent","ipa":"/ˈpɜːmənənt/","pos":"adj.","cn":"永久的；固定的","pun":"泼么能特","story":"per（贯穿）+ man（停留）：一直停留；泼出去的水么，能特别永久收不回——permanent。","ex":"Young people today are less likely to find a permanent position straight after graduating.","exCn":"如今年轻人毕业后直接找到固定职位的可能性更小。","col":["permanent job","permanent contract","permanently"]},{"id":595,"topic":"work","w":"temporary","ipa":"/ˈtemprəri/","pos":"adj.","cn":"临时的","pun":"贪婆瑞","story":"temp（时间）：只在一段时间内；贪心的婆婆只请瑞姐干几天，临时工——temporary。","ex":"Temporary contracts offer employers flexibility but leave workers with little security.","exCn":"临时合同给雇主带来灵活性，却让员工缺乏保障。","col":["temporary job","temporary staff","temporarily"]},{"id":596,"topic":"work","w":"part-time","ipa":"/ˌpɑːt ˈtaɪm/","pos":"adj./adv.","cn":"兼职的","pun":"怕太忙","story":"part（部分）+ time（时间）：只用一部分时间工作，因为怕全职太忙——兼职。","ex":"Many students work part-time to cover the cost of their living expenses.","exCn":"许多学生做兼职来支付生活费。","col":["part-time job","work part-time","full-time"]},{"id":597,"topic":"work","w":"gig","ipa":"/ɡɪɡ/","pos":"n.","cn":"零工；临时演出","pun":"给个","story":"零工经济里，平台给个单你就接一单，做完再等下一个 gig。","ex":"The rise of the gig economy has blurred the line between employment and self-employment.","exCn":"零工经济的兴起模糊了雇佣与自雇之间的界限。","col":["gig economy","gig worker","freelance gig"]},{"id":598,"topic":"work","w":"outsource","ipa":"/ˈaʊtsɔːs/","pos":"v.","cn":"外包","pun":"奥特搜死","story":"out（外）+ source（来源）：把活交给外面的人；奥特曼搜遍全球，把活外包给最便宜的。","ex":"Many Western companies outsource customer service to countries with lower labour costs.","exCn":"许多西方公司把客服外包给劳动力成本更低的国家。","col":["outsource production","outsourcing","subcontract"]},{"id":599,"topic":"work","w":"relocate","ipa":"/ˌriːləʊˈkeɪt/","pos":"v.","cn":"搬迁；调动","pun":"瑞漏开特","story":"re（再）+ locate（放置）：重新放个地方；瑞的办公室漏水了，公司决定开车特地搬迁。","ex":"Employees are sometimes asked to relocate to another city when the company expands.","exCn":"公司扩张时，员工有时会被要求调往另一座城市。","col":["relocate to","relocation package","relocation"]},{"id":600,"topic":"work","w":"headhunt","ipa":"/ˈhedhʌnt/","pos":"v.","cn":"猎头挖角","pun":"害的憨特","story":"head（头）+ hunt（猎）：猎头专门「猎」人才，害得憨特被高薪挖走了。","ex":"Talented managers are frequently headhunted by rival firms offering higher salaries.","exCn":"有才华的经理经常被出更高薪水的竞争对手挖走。","col":["be headhunted","headhunter","poach staff"]},{"id":601,"topic":"work","w":"hierarchy","ipa":"/ˈhaɪərɑːki/","pos":"n.","cn":"等级制度","pun":"嗨啊拉克","story":"hier（神圣）+ archy（统治）：从上到下一层层统治；上面的人嗨啊，下面的拉克只能听命——等级制度。","ex":"Flat organisational structures are replacing rigid hierarchies in many modern companies.","exCn":"在许多现代公司，扁平化组织结构正在取代僵化的等级制度。","col":["corporate hierarchy","top of the hierarchy","hierarchical"]},{"id":602,"topic":"work","w":"bureaucracy","ipa":"/bjʊəˈrɒkrəsi/","pos":"n.","cn":"官僚作风；官僚机构","pun":"表绕客拉西","story":"bureau（办公桌）+ cracy（统治）：办公桌统治一切；填表绕来绕去，客人被拉到西边盖章——官僚作风。","ex":"Excessive bureaucracy slows down decision-making and frustrates employees.","exCn":"过度的官僚作风拖慢决策，让员工感到沮丧。","col":["reduce bureaucracy","government bureaucracy","bureaucratic"]},{"id":603,"topic":"work","w":"corporate","ipa":"/ˈkɔːpərət/","pos":"adj.","cn":"公司的；企业的","pun":"靠婆瑞特","story":"corp（身体）：公司像一个大身体；员工靠着婆婆瑞特这样的大公司过日子——corporate。","ex":"Corporate culture has a strong influence on how employees behave and communicate.","exCn":"企业文化对员工的行为和沟通方式有很大影响。","col":["corporate culture","corporate responsibility","corporation"]},{"id":604,"topic":"work","w":"enterprise","ipa":"/ˈentəpraɪz/","pos":"n.","cn":"企业；进取心","pun":"恩特扑来死","story":"enter（进入）+ prise（拿）：敢于进去拿的精神；恩特扑上去拼到死，开了自己的企业。","ex":"Small and medium-sized enterprises account for the majority of jobs in most economies.","exCn":"在大多数经济体中，中小企业提供了大部分就业岗位。","col":["private enterprise","free enterprise","enterprising"]},{"id":605,"topic":"work","w":"startup","ipa":"/ˈstɑːtʌp/","pos":"n.","cn":"初创公司","pun":"死大特阿婆","story":"start（开始）+ up（起来）：刚起步的公司；连死大特阿婆都投钱给这家初创公司。","ex":"Most startups fail within their first five years due to a lack of funding.","exCn":"大多数初创公司因资金不足在头五年内倒闭。","col":["tech startup","launch a startup","startup founder"]},{"id":606,"topic":"work","w":"venture","ipa":"/ˈventʃə(r)/","pos":"n./v.","cn":"风险企业；冒险","pun":"玩车","story":"创业就像玩赛车，刺激又危险——venture 就是带风险的事业。","ex":"The two friends set up a joint venture to sell handmade furniture online.","exCn":"这两位朋友合资创办企业，在网上销售手工家具。","col":["joint venture","venture capital","business venture"]},{"id":607,"topic":"work","w":"founder","ipa":"/ˈfaʊndə(r)/","pos":"n.","cn":"创始人","pun":"放的","story":"found（建立）+ -er（人）：把公司地基放下的人，就是创始人。","ex":"The founder of the company still owns a majority of its shares.","exCn":"该公司的创始人仍持有多数股份。","col":["co-founder","company founder","found a company"]},{"id":608,"topic":"work","w":"investor","ipa":"/ɪnˈvestə(r)/","pos":"n.","cn":"投资者","pun":"因为死特","story":"invest（投资）：因为投资者掏钱，公司才不会死，特别重要。","ex":"Startups must convince investors that their business model will eventually be profitable.","exCn":"初创公司必须让投资者相信其商业模式最终会盈利。","col":["attract investors","private investor","investment"]},{"id":609,"topic":"work","w":"capital","ipa":"/ˈkæpɪtl/","pos":"n.","cn":"资本；首都","pun":"开皮头","story":"cap（头）：钱是生意的「头」；有了资本才能开皮革厂当头儿——capital。","ex":"A lack of start-up capital is the main barrier facing young entrepreneurs.","exCn":"缺乏启动资金是年轻创业者面临的主要障碍。","col":["raise capital","venture capital","human capital"]},{"id":610,"topic":"work","w":"profit","ipa":"/ˈprɒfɪt/","pos":"n./v.","cn":"利润；获益","pun":"扑肥它","story":"pro（向前）+ fit（做）：做出来的成果；老板扑向肥肥的账本，它就是利润。","ex":"Companies that focus solely on short-term profit often neglect staff welfare.","exCn":"只注重短期利润的公司往往忽视员工福祉。","col":["make a profit","profit margin","profitable"]},{"id":611,"topic":"work","w":"revenue","ipa":"/ˈrevənjuː/","pos":"n.","cn":"收入；营业额","pun":"热粉扭","story":"re（回）+ ven（来）：回流进来的钱；热情的粉丝扭着舞买单，公司营收上涨。","ex":"The firm's annual revenue doubled after it expanded into overseas markets.","exCn":"该公司拓展海外市场后，年营收翻了一番。","col":["annual revenue","generate revenue","tax revenue"]},{"id":612,"topic":"work","w":"turnover","ipa":"/ˈtɜːnəʊvə(r)/","pos":"n.","cn":"营业额；人员流动率","pun":"疼哦沃","story":"turn（转）+ over（过）：钱转过一圈是营业额，人转过一圈是流动率；疼啊，沃的员工又走了。","ex":"High staff turnover increases recruitment costs and damages team cohesion.","exCn":"员工流动率高会增加招聘成本并破坏团队凝聚力。","col":["staff turnover","annual turnover","turnover rate"]},{"id":613,"topic":"work","w":"bankruptcy","ipa":"/ˈbæŋkrʌptsi/","pos":"n.","cn":"破产","pun":"帮客拉不起","story":"bank（银行）+ rupt（破）：银行都破了；帮客户拉都拉不起来——破产了。","ex":"The retail chain filed for bankruptcy after years of declining sales.","exCn":"这家零售连锁店在销售连年下滑后申请破产。","col":["file for bankruptcy","go bankrupt","bankrupt"]},{"id":614,"topic":"work","w":"merger","ipa":"/ˈmɜːdʒə(r)/","pos":"n.","cn":"（公司）合并","pun":"么这","story":"merge（合并）：两家公司么来这么一合，就成了一家——merger。","ex":"The merger of the two banks resulted in thousands of job losses.","exCn":"两家银行的合并导致数千人失业。","col":["merger and acquisition","propose a merger","merge with"]},{"id":615,"topic":"work","w":"acquisition","ipa":"/ˌækwɪˈzɪʃn/","pos":"n.","cn":"收购；获得","pun":"爱可为洗神","story":"acquire（获得）：大公司爱买小公司，可为了洗掉对手，神一样地收购。","ex":"The acquisition of a smaller competitor allowed the company to dominate the market.","exCn":"收购一家较小的竞争对手使该公司得以主导市场。","col":["make an acquisition","acquisition of","acquire"]},{"id":616,"topic":"work","w":"shareholder","ipa":"/ˈʃeəhəʊldə(r)/","pos":"n.","cn":"股东","pun":"谁后的","story":"share（股份）+ holder（持有人）：手里握着股份的人；谁站在公司后面撑腰的？股东。","ex":"Shareholders often pressure companies to cut costs in order to maximise dividends.","exCn":"股东常常向公司施压削减成本，以实现股息最大化。","col":["major shareholder","shareholder value","stakeholder"]},{"id":617,"topic":"work","w":"stakeholder","ipa":"/ˈsteɪkhəʊldə(r)/","pos":"n.","cn":"利益相关者","pun":"死带客后的","story":"stake（利害）+ holder：跟公司利益绑在一起的人，员工、客户、供应商都是——死带着客户在后面的人。","ex":"A responsible business considers the interests of all its stakeholders, not just its owners.","exCn":"负责任的企业会考虑所有利益相关者的利益，而不仅是所有者。","col":["key stakeholder","stakeholder engagement","have a stake in"]},{"id":618,"topic":"work","w":"consultant","ipa":"/kənˈsʌltənt/","pos":"n.","cn":"顾问","pun":"肯扫疼特","story":"consult（咨询）：顾问肯帮你扫清头疼的问题，特别贵。","ex":"The company hired a management consultant to improve its internal processes.","exCn":"该公司聘请了一名管理顾问来改进内部流程。","col":["management consultant","consultancy","consult"]},{"id":619,"topic":"work","w":"clerical","ipa":"/ˈklerɪkl/","pos":"adj.","cn":"文书的；办公室事务的","pun":"可累日克","story":"clerk（职员）：文书工作可累了，日日克服重复的表格——clerical work。","ex":"Clerical jobs are among the most likely to be replaced by computer software.","exCn":"文书类工作是最有可能被计算机软件取代的工作之一。","col":["clerical work","clerical staff","clerk"]},{"id":620,"topic":"work","w":"leadership","ipa":"/ˈliːdəʃɪp/","pos":"n.","cn":"领导力；领导层","pun":"利的谢谱","story":"lead（领导）+ -ship（能力）：领导力就是让下属谢你、还愿意跟着你走谱的本事。","ex":"Strong leadership is essential when a company goes through a period of change.","exCn":"公司经历变革期时，强有力的领导至关重要。","col":["leadership skills","leadership style","leader"]},{"id":621,"topic":"work","w":"supervise","ipa":"/ˈsuːpəvaɪz/","pos":"v.","cn":"监督；管理","pun":"苏婆歪子","story":"super（上）+ vis（看）：从上往下看；苏婆歪着脖子盯着儿子写作业——监督。","ex":"Trainees must be supervised by a qualified professional at all times.","exCn":"实习生必须始终由合格的专业人员监督。","col":["supervise staff","closely supervised","supervision"]},{"id":622,"topic":"work","w":"sabbatical","ipa":"/səˈbætɪkl/","pos":"n.","cn":"（带薪）长假；学术休假","pun":"傻被踢扣","story":"sabbath（安息日）：休息一年不干活，同事以为你傻，被踢出去了？其实是带薪长假。","ex":"Some universities allow lecturers to take a sabbatical every seven years to conduct research.","exCn":"一些大学允许讲师每七年休一次学术假去做研究。","col":["take a sabbatical","on sabbatical","sabbatical leave"]},{"id":623,"topic":"work","w":"maternity","ipa":"/məˈtɜːnəti/","pos":"n.","cn":"产假；母亲身份","pun":"么疼呢踢","story":"mater（母亲）：妈妈生孩子么，疼得呢，宝宝还在踢——产假就是 maternity leave。","ex":"Generous maternity leave encourages women to return to work after having children.","exCn":"优厚的产假鼓励女性在生育后重返职场。","col":["maternity leave","maternity pay","paternity leave"]},{"id":624,"topic":"work","w":"misconduct","ipa":"/ˌmɪsˈkɒndʌkt/","pos":"n.","cn":"不当行为；渎职","pun":"密死砍打客特","story":"mis（错）+ conduct（行为）：错误行为；员工秘密砍价还打客户，特别严重的不当行为。","ex":"Employees found guilty of serious misconduct may be dismissed without notice.","exCn":"被认定有严重不当行为的员工可能被立即解雇。","col":["gross misconduct","professional misconduct","conduct"]},{"id":625,"topic":"work","w":"accountability","ipa":"/əˌkaʊntəˈbɪləti/","pos":"n.","cn":"问责制；责任","pun":"额靠他比了踢","story":"account（交代）：出了事额靠他来交代，比谁都先被踢——accountability 就是担责。","ex":"Clear lines of accountability help prevent errors from being ignored in large organisations.","exCn":"明确的问责机制有助于避免大型组织中的错误被忽视。","col":["accountability for","hold accountable","accountable"]},{"id":626,"topic":"work","w":"transparency","ipa":"/trænsˈpærənsi/","pos":"n.","cn":"透明度","pun":"穿死拍人洗","story":"trans（穿过）+ par（显现）：光能穿过去；老板穿死也要拍给人看财务，洗清嫌疑——透明。","ex":"Pay transparency can help reduce the gender wage gap within organisations.","exCn":"薪酬透明有助于缩小组织内部的性别工资差距。","col":["pay transparency","lack of transparency","transparent"]},{"id":627,"topic":"work","w":"ethics","ipa":"/ˈeθɪks/","pos":"n.","cn":"道德；伦理","pun":"爱习克斯","story":"职业道德就是爱好习惯，克制私心——ethics。","ex":"Business ethics should not be sacrificed in the pursuit of higher profits.","exCn":"不应为追求更高利润而牺牲商业道德。","col":["work ethic","business ethics","ethical"]},{"id":628,"topic":"work","w":"integrity","ipa":"/ɪnˈteɡrəti/","pos":"n.","cn":"正直；诚信","pun":"硬特格瑞踢","story":"integer（完整）：品格完整无缺；硬是特别有格调的瑞，踢开贿赂——正直。","ex":"Employers rank integrity among the most important qualities in a new recruit.","exCn":"雇主将诚信列为新员工最重要的品质之一。","col":["personal integrity","act with integrity","integrity and honesty"]},{"id":629,"topic":"work","w":"networking","ipa":"/ˈnetwɜːkɪŋ/","pos":"n.","cn":"人脉拓展；社交","pun":"内特沃肯","story":"net（网）+ work（工作）：织一张人际关系网；内特在酒会上沃肯地跟每个人换名片。","ex":"Networking at industry events is often the key to finding better job opportunities.","exCn":"在行业活动中拓展人脉往往是找到更好工作机会的关键。","col":["networking event","professional networking","network"]},{"id":630,"topic":"work","w":"prospect","ipa":"/ˈprɒspekt/","pos":"n.","cn":"前景；可能性","pun":"扑肉死扒克特","story":"pro（向前）+ spect（看）：往前看；扑上肉，死也要扒开克特的前途——prospects 就是前景。","ex":"Young graduates are attracted to companies that offer good career prospects.","exCn":"年轻毕业生青睐能提供良好职业前景的公司。","col":["career prospects","job prospects","prospective"]},{"id":631,"topic":"work","w":"plateau","ipa":"/ˈplætəʊ/","pos":"n./v.","cn":"停滞期；高原","pun":"扑来头","story":"爬到高原一片平地，怎么扑来头都不再升高——事业停滞期就是 plateau。","ex":"Many mid-career professionals feel they have reached a plateau in their development.","exCn":"许多职业生涯中期的专业人士觉得自己的发展进入了停滞期。","col":["reach a plateau","career plateau","level off"]},{"id":632,"topic":"work","w":"milestone","ipa":"/ˈmaɪlstəʊn/","pos":"n.","cn":"里程碑","pun":"卖偶死通","story":"mile（英里）+ stone（石头）：路边每一英里立一块石头；卖偶像周边卖到死才走通这一步——里程碑。","ex":"Securing the first major client was a milestone in the company's history.","exCn":"拿下第一个大客户是公司历史上的一个里程碑。","col":["reach a milestone","major milestone","milestone in"]},{"id":633,"topic":"work","w":"accomplish","ipa":"/əˈkʌmplɪʃ/","pos":"v.","cn":"完成；实现","pun":"额康普利需","story":"ac（到）+ complete（完成）：额头冒汗，康普利需要的东西全做完——accomplish。","ex":"Setting realistic goals helps employees accomplish more in less time.","exCn":"设定切实可行的目标有助于员工在更短时间内完成更多工作。","col":["accomplish a task","accomplishment","achieve"]},{"id":634,"topic":"work","w":"fulfil","ipa":"/fʊlˈfɪl/","pos":"v.","cn":"实现；履行；使满足","pun":"父服","story":"full（满）+ fill（填）：把梦想填满；父亲服气了，儿子实现了自己的理想——fulfil。","ex":"A job that fulfils people is often more valuable than one that simply pays well.","exCn":"一份能让人获得成就感的工作，往往比只是薪水高的工作更有价值。","col":["fulfil one's potential","fulfilling job","fulfilment"]},{"id":635,"topic":"work","w":"precarious","ipa":"/prɪˈkeəriəs/","pos":"adj.","cn":"不稳定的；危险的","pun":"扑开瑞饿死","story":"零工扑上去接单，开不了张瑞就要饿死——这种工作不稳定就是 precarious。","ex":"Precarious employment has become common among young people in the service sector.","exCn":"不稳定的雇佣关系在服务业年轻人中已很普遍。","col":["precarious work","precarious position","job insecurity"]},{"id":636,"topic":"work","w":"livelihood","ipa":"/ˈlaɪvlihʊd/","pos":"n.","cn":"生计","pun":"来福利胡的","story":"live（生活）+ -hood：活下去的办法；来点福利胡椒地里干活，就是农民的生计。","ex":"The closure of the mine destroyed the livelihood of thousands of families.","exCn":"矿山的关闭毁掉了数千个家庭的生计。","col":["earn a livelihood","source of livelihood","means of livelihood"]},{"id":637,"topic":"work","w":"breadwinner","ipa":"/ˈbredwɪnə(r)/","pos":"n.","cn":"养家糊口的人","pun":"不来的温呢","story":"bread（面包）+ winner（赢得者）：把面包赢回家的人；他不回来温饭，谁养家呢？","ex":"In many households, the traditional role of the male breadwinner is disappearing.","exCn":"在许多家庭中，男性作为养家者的传统角色正在消失。","col":["main breadwinner","sole breadwinner","provide for the family"]},{"id":638,"topic":"work","w":"workaholic","ipa":"/ˌwɜːkəˈhɒlɪk/","pos":"n.","cn":"工作狂","pun":"沃克喝厚利克","story":"work + -aholic（成瘾）：像酒鬼一样对工作上瘾；沃克喝了厚利克的鸡汤，通宵加班。","ex":"Workaholics often sacrifice their health and relationships for their careers.","exCn":"工作狂常常为事业牺牲健康和人际关系。","col":["become a workaholic","workaholism","work addiction"]},{"id":639,"topic":"work","w":"juggle","ipa":"/ˈdʒʌɡl/","pos":"v.","cn":"兼顾；杂耍","pun":"扎狗","story":"杂耍演员一边扎着狗尾巴一边抛球；上班族一边带娃一边加班，都是 juggle。","ex":"Working parents often struggle to juggle their careers and family commitments.","exCn":"职场父母往往难以兼顾事业与家庭责任。","col":["juggle work and family","juggle responsibilities","balance"]},{"id":640,"topic":"work","w":"hectic","ipa":"/ˈhektɪk/","pos":"adj.","cn":"忙乱的","pun":"喝提克","story":"早上忙得只能一边喝咖啡一边提包克服堵车——hectic 的一天。","ex":"The hectic pace of modern office life leaves little time for reflection.","exCn":"现代办公室生活的忙碌节奏几乎没有留下思考的时间。","col":["hectic schedule","hectic lifestyle","frantic"]},{"id":641,"topic":"work","w":"tedious","ipa":"/ˈtiːdiəs/","pos":"adj.","cn":"乏味的；冗长的","pun":"踢地饿死","story":"整天踢着地板发呆，无聊得快饿死——这种乏味就是 tedious。","ex":"Repetitive factory work can be extremely tedious and demoralising.","exCn":"重复性的工厂工作可能极其乏味且令人沮丧。","col":["tedious task","tedious work","tedium"]},{"id":642,"topic":"work","w":"monotonous","ipa":"/məˈnɒtənəs/","pos":"adj.","cn":"单调的","pun":"么那疼呢死","story":"mono（单一）+ tone（音调）：一个调子唱到底；么，那么疼呢，耳朵单调得要死。","ex":"Many assembly-line jobs are monotonous and offer little opportunity for creativity.","exCn":"许多流水线工作单调乏味，几乎没有发挥创造力的机会。","col":["monotonous work","monotonous routine","monotony"]},{"id":643,"topic":"work","w":"repetitive","ipa":"/rɪˈpetətɪv/","pos":"adj.","cn":"重复的","pun":"日拍特提付","story":"repeat（重复）：日日拍同一个动作，特别提不起劲，付出还得不到变化——重复性劳动。","ex":"Repetitive tasks are increasingly being handed over to machines.","exCn":"重复性任务正越来越多地交给机器处理。","col":["repetitive tasks","repetitive strain injury","repeat"]},{"id":644,"topic":"work","w":"mundane","ipa":"/mʌnˈdeɪn/","pos":"adj.","cn":"平凡的；乏味的","pun":"闷呆","story":"每天填表复印，闷得人发呆——mundane 就是平淡无奇。","ex":"Even mundane administrative work is necessary for an organisation to function.","exCn":"即使是平淡的行政工作，对组织运转也是必要的。","col":["mundane tasks","mundane job","ordinary"]},{"id":645,"topic":"work","w":"rewarding","ipa":"/rɪˈwɔːdɪŋ/","pos":"adj.","cn":"有回报的；有意义的","pun":"日窝顶","story":"reward（回报）：每日窝在办公室顶着压力，但看到成果就觉得值——rewarding。","ex":"Nursing is a demanding but highly rewarding profession.","exCn":"护理是一份要求高但非常有意义的职业。","col":["rewarding career","financially rewarding","reward"]},{"id":646,"topic":"work","w":"lucrative","ipa":"/ˈluːkrətɪv/","pos":"adj.","cn":"赚钱的；利润丰厚的","pun":"路可提付","story":"lucr（利益）：这条路可以提着钱袋走，付出就有回报——赚钱的生意。","ex":"Many graduates are drawn to lucrative careers in banking and consultancy.","exCn":"许多毕业生被银行业和咨询业的高薪职业吸引。","col":["lucrative career","lucrative contract","profitable"]},{"id":647,"topic":"work","w":"seniority","ipa":"/ˌsiːniˈɒrəti/","pos":"n.","cn":"资历；年资","pun":"西尼哦瑞踢","story":"senior（年长的）：西尼资历老，哦，瑞刚来就被踢到最后排——按资历排序。","ex":"In some companies, promotion is still based on seniority rather than performance.","exCn":"在一些公司，晋升仍以资历而非业绩为依据。","col":["based on seniority","seniority system","senior"]},{"id":648,"topic":"work","w":"novice","ipa":"/ˈnɒvɪs/","pos":"n.","cn":"新手；初学者","pun":"闹危死","story":"nov（新）：新手一上手就闹出危险，差点吓死师傅——novice。","ex":"Novices tend to make more mistakes, so close supervision is essential at first.","exCn":"新手往往更容易出错，因此起初的严密监督很重要。","col":["complete novice","novice driver","beginner"]},{"id":649,"topic":"work","w":"payroll","ipa":"/ˈpeɪrəʊl/","pos":"n.","cn":"工资单；在职员工总数","pun":"配肉","story":"pay（付）+ roll（名册）：发薪名册；上了工资单的员工，公司才配肉给你吃。","ex":"The company has over five hundred employees on its payroll.","exCn":"该公司在册员工超过五百人。","col":["on the payroll","payroll system","payroll tax"]},{"id":650,"topic":"work","w":"liaise","ipa":"/liˈeɪz/","pos":"v.","cn":"联络；协调","pun":"李爱姿","story":"李爱姿是部门联络人，天天和客户沟通对接——liaise with。","ex":"The marketing team must liaise closely with sales staff to ensure consistent messaging.","exCn":"市场团队必须与销售人员密切联络，以保证信息一致。","col":["liaise with","liaise between","liaison"]},{"id":651,"topic":"work","w":"micromanage","ipa":"/ˌmaɪkrəʊˈmænɪdʒ/","pos":"v.","cn":"微观管理；事无巨细地管","pun":"卖克肉卖你的","story":"micro（微小）+ manage：连卖克肉还是卖你的东西都要管——事无巨细的微观管理。","ex":"Managers who micromanage their staff often discourage initiative and independent thinking.","exCn":"事无巨细管理员工的经理往往会打击主动性和独立思考。","col":["micromanage staff","micromanagement","micromanager"]},{"id":652,"topic":"work","w":"empower","ipa":"/ɪmˈpaʊə(r)/","pos":"v.","cn":"授权；赋能","pun":"硬泡我","story":"em（使）+ power（权力）：给你权力；老板硬把权力泡给我——empower。","ex":"Training programmes empower workers to take on more responsibility.","exCn":"培训项目使员工有能力承担更多责任。","col":["empower employees","empowerment","empowering"]},{"id":653,"topic":"work","w":"streamline","ipa":"/ˈstriːmlaɪn/","pos":"v.","cn":"精简；使高效","pun":"死揣母来","story":"stream（水流）+ line（线）：让流程像水一样顺；死揣着老母亲的旧规矩来，就得精简掉。","ex":"The company streamlined its approval process to reduce delays.","exCn":"该公司精简了审批流程以减少延误。","col":["streamline operations","streamline the process","simplify"]},{"id":654,"topic":"work","w":"downsize","ipa":"/ˈdaʊnsaɪz/","pos":"v.","cn":"裁员；缩减规模","pun":"当赛子","story":"down（下）+ size（规模）：把规模往下压；公司把员工当赛子随手扔——裁员缩编。","ex":"Many firms downsized during the recession in order to cut costs.","exCn":"经济衰退期间，许多公司为削减成本而裁员。","col":["downsize the workforce","downsizing","cut jobs"]},{"id":655,"topic":"work","w":"restructure","ipa":"/ˌriːˈstrʌktʃə(r)/","pos":"v.","cn":"重组；改组","pun":"瑞死揣客车","story":"re（再）+ structure（结构）：重新搭结构；瑞死揣着客车图纸，把部门全部改组。","ex":"The bank restructured its operations, closing dozens of branches.","exCn":"该银行重组业务，关闭了数十家分行。","col":["restructure the company","restructuring","reorganise"]},{"id":656,"topic":"work","w":"lay off","ipa":"/ˌleɪ ˈɒf/","pos":"phr.","cn":"（临时）解雇；裁员","pun":"累哦夫","story":"lay（放）+ off（离开）：把人放走；累哦，丈夫被裁员回家了——lay off。","ex":"The factory laid off two hundred workers when demand for its products fell.","exCn":"产品需求下降时，这家工厂裁掉了两百名工人。","col":["be laid off","lay off staff","layoffs"]},{"id":657,"topic":"work","w":"furlough","ipa":"/ˈfɜːləʊ/","pos":"n./v.","cn":"强制休假；停薪留职","pun":"佛漏","story":"疫情期间被强制休假，坐在家里像尊佛，工资却漏了一半——furlough。","ex":"Millions of employees were placed on furlough during the pandemic.","exCn":"疫情期间，数百万员工被安排停工留职。","col":["on furlough","furlough scheme","furloughed workers"]},{"id":658,"topic":"work","w":"severance","ipa":"/ˈsevərəns/","pos":"n.","cn":"遣散费；离职","pun":"色伐让死","story":"sever（切断）：切断雇佣关系；老板脸色一变，伐掉你，让你死心，再给点遣散费。","ex":"Employees made redundant are entitled to a severance package based on their length of service.","exCn":"被裁员工有权根据工龄获得遣散费。","col":["severance pay","severance package","sever ties"]},{"id":659,"topic":"work","w":"terminate","ipa":"/ˈtɜːmɪneɪt/","pos":"v.","cn":"终止；解雇","pun":"疼米内特","story":"term（期限）：到期结束；疼啊，米内特的合同被终止了——terminate。","ex":"The contract may be terminated by either party with one month's notice.","exCn":"合同任一方均可提前一个月通知终止。","col":["terminate a contract","terminate employment","termination"]},{"id":660,"topic":"work","w":"upskill","ipa":"/ˌʌpˈskɪl/","pos":"v.","cn":"提升技能","pun":"阿婆死扣","story":"up（向上）+ skill（技能）：技能往上提；阿婆死扣着新软件学，就为了升职。","ex":"Governments should invest in programmes that upskill workers displaced by technology.","exCn":"政府应投资于帮助被技术取代的工人提升技能的项目。","col":["upskill the workforce","upskilling","reskill"]},{"id":661,"topic":"work","w":"transferable","ipa":"/trænsˈfɜːrəbl/","pos":"adj.","cn":"可转移的；通用的","pun":"穿死佛热包","story":"transfer（转移）+ -able：可以带走的；沟通、领导这些技能像穿死也不脱的佛热包，去哪都用得上。","ex":"University courses should develop transferable skills such as communication and teamwork.","exCn":"大学课程应培养沟通、团队合作等通用技能。","col":["transferable skills","transfer","transferability"]},{"id":662,"topic":"work","w":"overqualified","ipa":"/ˌəʊvəˈkwɒlɪfaɪd/","pos":"adj.","cn":"资历过高的","pun":"欧沃夸利法的","story":"over（过）+ qualified（合格）：博士去应聘前台，欧沃夸他利害，法官都说资历过高。","ex":"Many graduates are overqualified for the jobs they eventually accept.","exCn":"许多毕业生对于最终接受的工作而言资历过高。","col":["overqualified for","overqualified candidate","underqualified"]},{"id":663,"topic":"work","w":"glass ceiling","ipa":"/ˌɡlɑːs ˈsiːlɪŋ/","pos":"phr.","cn":"玻璃天花板（无形晋升障碍）","pun":"格拉斯洗灵","story":"glass（玻璃）+ ceiling（天花板）：看得见顶层却撞不上去；格拉斯天天洗心灵，升职却总差一步。","ex":"Despite progress, many women still face a glass ceiling in senior management.","exCn":"尽管有所进步，许多女性在高层管理中仍面临玻璃天花板。","col":["break the glass ceiling","hit the glass ceiling","gender gap"]},{"id":664,"topic":"work","w":"nepotism","ipa":"/ˈnepətɪzəm/","pos":"n.","cn":"任人唯亲","pun":"内婆提怎","story":"nepot（侄子）：老板把内侄和婆家亲戚全提拔上来，怎么可以——任人唯亲。","ex":"Nepotism in hiring undermines the principle of equal opportunity.","exCn":"招聘中的任人唯亲损害了机会平等的原则。","col":["accusations of nepotism","nepotism and favouritism","favouritism"]},{"id":665,"topic":"work","w":"hybrid","ipa":"/ˈhaɪbrɪd/","pos":"adj./n.","cn":"混合的；混合物","pun":"嗨不瑞的","story":"一半在家一半在公司，嗨的时候在家，不瑞的时候进办公室——混合办公。","ex":"Hybrid working arrangements combine days in the office with days at home.","exCn":"混合办公模式把在办公室和在家办公的日子结合起来。","col":["hybrid working","hybrid model","hybrid car"]},{"id":666,"topic":"work","w":"consensus","ipa":"/kənˈsensəs/","pos":"n.","cn":"共识","pun":"肯森色死","story":"con（共同）+ sens（感觉）：大家感觉一致；肯森的方案让脸色难看到死的人都点头——达成共识。","ex":"The team reached a consensus on the new strategy after a lengthy discussion.","exCn":"经过长时间讨论，团队就新战略达成了共识。","col":["reach a consensus","general consensus","consensus on"]},{"id":667,"topic":"work","w":"grievance","ipa":"/ˈɡriːvəns/","pos":"n.","cn":"不满；申诉","pun":"格里翻死","story":"grieve（悲伤）：格里翻遍规章也没人理他的委屈，气得要死——grievance 就是正式的不满。","ex":"Employees should be able to raise a grievance without fear of retaliation.","exCn":"员工应能在不担心报复的情况下提出申诉。","col":["raise a grievance","grievance procedure","air grievances"]},{"id":668,"topic":"work","w":"whistleblower","ipa":"/ˈwɪslbləʊə(r)/","pos":"n.","cn":"举报人；吹哨人","pun":"为受不漏我","story":"whistle（哨子）+ blower（吹的人）：为了受害者不再受苦，我吹哨揭发公司，不怕漏了我的名字。","ex":"Laws protecting whistleblowers encourage employees to report corporate wrongdoing.","exCn":"保护举报人的法律鼓励员工揭发企业不法行为。","col":["whistleblower protection","blow the whistle on","whistleblowing"]},{"id":669,"topic":"work","w":"compliance","ipa":"/kəmˈplaɪəns/","pos":"n.","cn":"遵守；合规","pun":"肯扑来恩死","story":"comply（遵守）：肯扑来遵守规则的员工，老板恩情记到死——compliance。","ex":"Compliance with health and safety regulations is mandatory for all employers.","exCn":"所有雇主都必须遵守健康与安全法规。","col":["compliance with","ensure compliance","comply with"]},{"id":670,"topic":"work","w":"expatriate","ipa":"/ˌeksˈpætriət/","pos":"n./adj.","cn":"外派人员；侨民","pun":"爱克死怕吹特","story":"ex（出）+ patria（祖国）：离开祖国工作的人；爱克死怕海外吹的特大风，还是去了。","ex":"Expatriate employees often receive housing allowances and school fees for their children.","exCn":"外派员工通常能获得住房补贴和子女学费。","col":["expatriate worker","expat community","expatriate package"]},{"id":671,"topic":"work","w":"aspire","ipa":"/əˈspaɪə(r)/","pos":"v.","cn":"渴望；有志于","pun":"额死拜尔","story":"a（向）+ spire（呼吸）：向着目标呼吸；额，死也要拜访大老板尔等，渴望晋升。","ex":"Many young professionals aspire to become managers within five years.","exCn":"许多年轻的专业人士渴望在五年内成为经理。","col":["aspire to","aspiration","aspiring"]},{"id":672,"topic":"work","w":"attrition","ipa":"/əˈtrɪʃn/","pos":"n.","cn":"人员自然减少；消耗","pun":"额吹神","story":"公司不裁人，只等员工额头一皱自己走，像吹散的神仙——自然减员就是 attrition。","ex":"The company reduced its headcount through natural attrition rather than redundancies.","exCn":"该公司通过自然减员而非裁员来减少人数。","col":["staff attrition","attrition rate","natural attrition"]},{"id":673,"topic":"work","w":"retention","ipa":"/rɪˈtenʃn/","pos":"n.","cn":"留住（员工）；保留","pun":"日疼神","story":"retain（保留）：每天都疼爱员工像神一样供着，才留得住人——staff retention。","ex":"Good training and clear career paths improve staff retention.","exCn":"良好的培训和清晰的职业路径能提高员工留任率。","col":["staff retention","retention rate","retain"]},{"id":674,"topic":"economy","w":"inflation","ipa":"/ɪnˈfleɪʃn/","pos":"n.","cn":"通货膨胀","pun":"因福来生","story":"in（进）+ flat（吹气）+ ion：钱像气球被吹进太多气，因「福」来得太多，物价全「生」上去了，就是通货膨胀。","ex":"High inflation erodes the purchasing power of ordinary households, particularly those on fixed incomes.","exCn":"高通胀侵蚀普通家庭的购买力，尤其是固定收入者。","col":["inflation rate","curb inflation","inflationary pressure"]},{"id":675,"topic":"economy","w":"recession","ipa":"/rɪˈseʃn/","pos":"n.","cn":"经济衰退","pun":"日晒神","story":"re（往回）+ cess（走）：经济往回走，老板天天在太阳下「日晒」着发呆像尊「神」，没生意可做，这就是衰退。","ex":"During a recession, governments often increase public spending to stimulate economic activity.","exCn":"经济衰退期间，政府往往增加公共支出以刺激经济活动。","col":["economic recession","fall into recession","recessionary"]},{"id":676,"topic":"economy","w":"deficit","ipa":"/ˈdefɪsɪt/","pos":"n.","cn":"赤字；亏空","pun":"得费死它","story":"钱包空了还要花，「得费死它」——花得比挣得多，账上就是赤字。","ex":"A persistent budget deficit forces the government to borrow heavily from international lenders.","exCn":"持续的预算赤字迫使政府大量向国际贷款方借款。","col":["budget deficit","trade deficit","run a deficit"]},{"id":677,"topic":"economy","w":"surplus","ipa":"/ˈsɜːpləs/","pos":"n./adj.","cn":"盈余；过剩","pun":"啥不剩","story":"sur（超过）+ plus（加）：加了又加超过了需要，本来「啥不剩」的仓库堆满了盈余。","ex":"A trade surplus indicates that a country exports more goods than it imports.","exCn":"贸易顺差表明一个国家的出口多于进口。","col":["trade surplus","budget surplus","surplus goods"]},{"id":678,"topic":"economy","w":"tariff","ipa":"/ˈtærɪf/","pos":"n.","cn":"关税","pun":"太累夫","story":"进口货到海关要交关税，商人搬着钱袋子直喊「太累夫」。","ex":"Imposing tariffs on imported goods protects domestic industries but raises prices for consumers.","exCn":"对进口商品征收关税保护国内产业，但会抬高消费者价格。","col":["impose tariffs","tariff barriers","import tariff"]},{"id":679,"topic":"economy","w":"monopoly","ipa":"/məˈnɒpəli/","pos":"n.","cn":"垄断","pun":"摸那破梨","story":"mono（单一）+ poly（卖）：全城只有一家卖梨，你只能「摸那破梨」买，没得选，这就是垄断。","ex":"Governments regulate monopolies to prevent companies from charging excessive prices.","exCn":"政府监管垄断企业，以防其收取过高价格。","col":["have a monopoly on","monopolise","natural monopoly"]},{"id":680,"topic":"economy","w":"invest","ipa":"/ɪnˈvest/","pos":"v.","cn":"投资","pun":"引外势","story":"in（进）+ vest（背心）：把钱塞进背心口袋「引」来「外」面的「势」力，就是投资。","ex":"Governments should invest heavily in infrastructure to boost long-term economic growth.","exCn":"政府应大力投资基础设施以促进长期经济增长。","col":["invest in","investment","investor"]},{"id":681,"topic":"economy","w":"dividend","ipa":"/ˈdɪvɪdend/","pos":"n.","cn":"股息；红利","pun":"地位等","story":"divide（分）+ end：年底一到，股东按「地位等」级分钱，分到的就是股息。","ex":"Shareholders receive dividends when the company reports strong annual profits.","exCn":"当公司年利润强劲时，股东会收到股息。","col":["pay a dividend","dividend yield","annual dividend"]},{"id":682,"topic":"economy","w":"mortgage","ipa":"/ˈmɔːɡɪdʒ/","pos":"n./v.","cn":"抵押贷款","pun":"摸给之","story":"mort（死）+ gage（抵押）：买房贷款一签，直到「摸」着钱「给」到「死」为止，这就是房贷。","ex":"Rising interest rates have made mortgages unaffordable for many first-time buyers.","exCn":"利率上升使许多首次购房者负担不起房贷。","col":["take out a mortgage","mortgage rate","pay off the mortgage"]},{"id":683,"topic":"economy","w":"currency","ipa":"/ˈkʌrənsi/","pos":"n.","cn":"货币","pun":"卡人死","story":"current（流通）+ cy：钱像水流一样流通；出国没换货币就「卡人死」了。","ex":"A weak currency makes exports cheaper but increases the cost of imported goods.","exCn":"货币贬值使出口更便宜，但增加了进口商品成本。","col":["foreign currency","currency exchange","strong currency"]},{"id":684,"topic":"economy","w":"commodity","ipa":"/kəˈmɒdəti/","pos":"n.","cn":"商品；大宗商品","pun":"可卖的踢","story":"石油、小麦这些「可卖的」东西一「踢」就装船出口，就是大宗商品。","ex":"Countries that rely on a single commodity are vulnerable to sudden price fluctuations.","exCn":"依赖单一大宗商品的国家容易受到价格突然波动的影响。","col":["commodity prices","basic commodities","commodity market"]},{"id":685,"topic":"economy","w":"budget","ipa":"/ˈbʌdʒɪt/","pos":"n./v.","cn":"预算","pun":"巴掌它","story":"月初做预算，超支一次就给自己一「巴掌」，「它」就是管钱的预算。","ex":"The government announced a budget that allocates more funds to education and healthcare.","exCn":"政府宣布了一项向教育和医疗分配更多资金的预算。","col":["annual budget","budget cuts","on a tight budget"]},{"id":686,"topic":"economy","w":"expenditure","ipa":"/ɪkˈspendɪtʃə(r)/","pos":"n.","cn":"支出；开支","pun":"一克死盆的车","story":"ex（出）+ spend（花）：花钱花到「一克死盆的车」都买了，开支实在太大。","ex":"Public expenditure on healthcare has doubled over the past two decades.","exCn":"过去二十年公共医疗支出翻了一番。","col":["public expenditure","capital expenditure","reduce expenditure"]},{"id":687,"topic":"economy","w":"fiscal","ipa":"/ˈfɪskl/","pos":"adj.","cn":"财政的","pun":"费死口","story":"财政部长为了税收和开支「费死」了「口」舌，fiscal 就是财政的。","ex":"The government adopted a tight fiscal policy to bring the deficit under control.","exCn":"政府采取紧缩财政政策以控制赤字。","col":["fiscal policy","fiscal year","fiscal deficit"]},{"id":688,"topic":"economy","w":"monetary","ipa":"/ˈmʌnɪtri/","pos":"adj.","cn":"货币的；金融的","pun":"马内锤","story":"money 的形容词：央行「马内」（money）一「锤」定利率，这就是货币政策。","ex":"Central banks use monetary policy to keep inflation within a target range.","exCn":"央行利用货币政策把通胀控制在目标范围内。","col":["monetary policy","monetary union","monetary value"]},{"id":689,"topic":"economy","w":"stagnation","ipa":"/stæɡˈneɪʃn/","pos":"n.","cn":"停滞；不景气","pun":"死待个内神","story":"stagn（池塘死水）：经济像一潭死水，「死待」着不动，「个内神」都急了，这就是停滞。","ex":"Prolonged economic stagnation has led to high youth unemployment in several European countries.","exCn":"长期经济停滞导致几个欧洲国家青年失业率居高不下。","col":["economic stagnation","stagnate","stagnant wages"]},{"id":690,"topic":"economy","w":"prosperity","ipa":"/prɒˈsperəti/","pos":"n.","cn":"繁荣；兴旺","pun":"泼死泼来踢","story":"钱多得往外「泼」，「泼死泼来踢」都花不完，这就是繁荣。","ex":"Free trade has brought unprecedented prosperity to many developing nations.","exCn":"自由贸易给许多发展中国家带来了前所未有的繁荣。","col":["economic prosperity","prosper","prosperous"]},{"id":691,"topic":"economy","w":"affluent","ipa":"/ˈæfluənt/","pos":"adj.","cn":"富裕的","pun":"啊富人的","story":"af + flu（流）：钱像水一样流进来，「啊，富人的」生活就是这么富裕。","ex":"Affluent consumers tend to spend a larger share of their income on luxury goods.","exCn":"富裕消费者往往把更大比例的收入花在奢侈品上。","col":["affluent society","affluent families","affluence"]},{"id":692,"topic":"economy","w":"austerity","ipa":"/ɒˈsterəti/","pos":"n.","cn":"紧缩；节衣缩食","pun":"哦死的踢","story":"政府紧缩开支，福利砍到「哦，死的踢」，老百姓被踢得叫苦，这就是财政紧缩。","ex":"Austerity measures introduced after the crisis led to widespread public protests.","exCn":"危机后推行的紧缩措施引发了广泛的公众抗议。","col":["austerity measures","austerity budget","austere"]},{"id":693,"topic":"economy","w":"asset","ipa":"/ˈæset/","pos":"n.","cn":"资产；财富","pun":"爱赛特","story":"「爱赛特」——爱比谁的房子、车子多，比的就是资产。","ex":"Property remains the most valuable asset for the majority of middle-class families.","exCn":"房产仍是大多数中产家庭最有价值的资产。","col":["fixed assets","asset management","valuable asset"]},{"id":694,"topic":"economy","w":"liability","ipa":"/ˌlaɪəˈbɪləti/","pos":"n.","cn":"负债；责任","pun":"赖啊逼了踢","story":"欠钱想「赖啊」，债主「逼了踢」，逼着你负责——负债和责任都是 liability。","ex":"The company's liabilities exceeded its assets, leaving it unable to pay creditors.","exCn":"公司负债超过资产，无力偿还债权人。","col":["assets and liabilities","legal liability","liable for"]},{"id":695,"topic":"economy","w":"debt","ipa":"/det/","pos":"n.","cn":"债务","pun":"呆特","story":"欠了一屁股债，人「呆特」了——债务压得发呆。","ex":"Household debt has risen sharply as families borrow to cope with the rising cost of living.","exCn":"家庭为应对生活成本上升而借贷，家庭债务急剧上升。","col":["national debt","in debt","debt repayment"]},{"id":696,"topic":"economy","w":"interest","ipa":"/ˈɪntrəst/","pos":"n.","cn":"利息；利益；兴趣","pun":"因吹死特","story":"存钱有利息，「因」为利息「吹」得「死特」高，大家对存钱有了兴趣。","ex":"Higher interest rates discourage borrowing and slow down consumer spending.","exCn":"更高的利率抑制借贷，减缓消费支出。","col":["interest rate","earn interest","in the public interest"]},{"id":697,"topic":"economy","w":"export","ipa":"/ɪkˈspɔːt, ˈekspɔːt/","pos":"v./n.","cn":"出口","pun":"一颗死破的","story":"ex（出）+ port（港口）：从港口运出去就是出口，哪怕「一颗死破的」螺丝也能出口。","ex":"Manufacturing exports account for over half of the country's foreign earnings.","exCn":"制造业出口占该国外汇收入的一半以上。","col":["export goods","export market","exporter"]},{"id":698,"topic":"economy","w":"import","ipa":"/ɪmˈpɔːt, ˈɪmpɔːt/","pos":"v./n.","cn":"进口","pun":"硬破的","story":"im（进）+ port（港口）：从港口运进来就是进口，就算是「硬破的」旧货也算进口。","ex":"The country imports most of its energy, making it vulnerable to global price shocks.","exCn":"该国大部分能源依赖进口，容易受全球价格冲击影响。","col":["import duty","import goods","importer"]},{"id":699,"topic":"economy","w":"merchandise","ipa":"/ˈmɜːtʃəndaɪs/","pos":"n.","cn":"商品；货物","pun":"摸钱带死","story":"merchant（商人）的货：商人「摸钱带死」都要卖的东西就是商品。","ex":"Retailers display merchandise attractively to encourage impulse purchases.","exCn":"零售商把商品陈列得引人注目以鼓励冲动购买。","col":["general merchandise","merchandising","merchant"]},{"id":700,"topic":"economy","w":"wholesale","ipa":"/ˈhəʊlseɪl/","pos":"n./adj.","cn":"批发","pun":"猴塞儿","story":"whole（整体）+ sale（卖）：整箱整箱卖，「猴塞儿」——猴子把整车货塞给你，就是批发。","ex":"Wholesale prices rose by five per cent, and retailers passed the increase on to consumers.","exCn":"批发价上涨了5%，零售商把涨价转嫁给了消费者。","col":["wholesale price","wholesaler","buy wholesale"]},{"id":701,"topic":"economy","w":"retail","ipa":"/ˈriːteɪl/","pos":"n./v.","cn":"零售","pun":"锐特儿","story":"re（再）+ tail（尾巴）：批发商把整批货切成小尾巴卖，「锐特儿」店里一件件零售。","ex":"Online shopping has transformed the retail sector over the past decade.","exCn":"过去十年网购改变了零售行业。","col":["retail sector","retailer","retail price"]},{"id":702,"topic":"economy","w":"corporation","ipa":"/ˌkɔːpəˈreɪʃn/","pos":"n.","cn":"大公司；企业","pun":"扣泼瑞神","story":"corp（身体）：很多人合成一个「身体」就是公司，「扣泼瑞神」——大公司扣钱像泼水。","ex":"Multinational corporations often relocate production to countries with lower labour costs.","exCn":"跨国公司常常把生产转移到劳动力成本更低的国家。","col":["multinational corporation","corporate tax","corporate"]},{"id":703,"topic":"economy","w":"speculate","ipa":"/ˈspekjuleɪt/","pos":"v.","cn":"投机；推测","pun":"死掰扣累特","story":"spec（看）：只看走势不看实业，「死掰」着手指「扣」到「累特」，猜涨跌买卖，就是投机。","ex":"Investors who speculate on property prices can drive up the cost of housing for ordinary families.","exCn":"炒房的投机者会抬高普通家庭的购房成本。","col":["speculate on","speculation","speculative investment"]},{"id":704,"topic":"economy","w":"fluctuate","ipa":"/ˈflʌktʃueɪt/","pos":"v.","cn":"波动；涨落","pun":"弗拉去外特","story":"flu（流）：股价像水流，「弗拉去外特」——一会儿拉出去一会儿拉回来，上下波动。","ex":"Oil prices fluctuate dramatically in response to political tensions in the Middle East.","exCn":"油价随中东政治紧张局势剧烈波动。","col":["fluctuate wildly","price fluctuations","fluctuation in"]},{"id":705,"topic":"economy","w":"depreciate","ipa":"/dɪˈpriːʃieɪt/","pos":"v.","cn":"贬值；折旧","pun":"低价谢特","story":"de（向下）+ preci（价格）：车一开出门就「低价」，「谢特」！这就是贬值、折旧。","ex":"The national currency depreciated by twenty per cent, making imported goods far more expensive.","exCn":"本国货币贬值20%，进口商品贵了很多。","col":["depreciate in value","depreciation","currency depreciation"]},{"id":706,"topic":"economy","w":"appreciate","ipa":"/əˈpriːʃieɪt/","pos":"v.","cn":"升值；欣赏；感激","pun":"饿扑离谢特","story":"ap（向）+ preci（价格）：房子价格往上走，「饿扑离谢特」——饿着肚子也要扑上去买，升值了真感激。","ex":"Property in the city centre has appreciated considerably over the last ten years.","exCn":"市中心房产在过去十年大幅升值。","col":["appreciate in value","appreciation","appreciate the effort"]},{"id":707,"topic":"economy","w":"devalue","ipa":"/ˌdiːˈvæljuː/","pos":"v.","cn":"使贬值","pun":"低外流","story":"de（下）+ value（价值）：政府故意让货币价值往下走，「低外流」——低价往外流出口，就是贬值。","ex":"The government devalued the currency to make exports more competitive on the world market.","exCn":"政府让货币贬值，使出口在世界市场上更具竞争力。","col":["devalue the currency","devaluation","devalued"]},{"id":708,"topic":"economy","w":"exponential","ipa":"/ˌekspəˈnenʃl/","pos":"adj.","cn":"指数级的；急剧的","pun":"一颗死炮能生","story":"「一颗死炮能生」出一百颗，一百颗生一万颗——指数级增长，越来越快。","ex":"The digital economy has seen exponential growth since the widespread adoption of smartphones.","exCn":"自智能手机普及以来，数字经济经历了指数级增长。","col":["exponential growth","exponential increase","exponentially"]},{"id":709,"topic":"economy","w":"franchise","ipa":"/ˈfræntʃaɪz/","pos":"n.","cn":"特许经营权；连锁店","pun":"翻茬子","story":"总部把品牌给你，你「翻茬子」——换个地方再开一模一样的店，这就是特许经营。","ex":"Fast-food franchises have expanded rapidly into emerging markets in Asia and Africa.","exCn":"快餐连锁特许店已迅速扩张到亚非新兴市场。","col":["franchise agreement","fast-food franchise","franchisee"]},{"id":710,"topic":"economy","w":"deregulate","ipa":"/ˌdiːˈreɡjuleɪt/","pos":"v.","cn":"放松管制","pun":"低瑞哥累特","story":"de（去掉）+ regulate（管制）：「低瑞哥累特」——管制的规矩太累，政府一句话去掉，放松管制。","ex":"Deregulating the banking sector encouraged risk-taking that contributed to the financial crisis.","exCn":"放松银行业管制助长了冒险行为，最终导致金融危机。","col":["deregulate the market","deregulation","regulatory"]},{"id":711,"topic":"economy","w":"supply","ipa":"/səˈplaɪ/","pos":"n./v.","cn":"供应；供给","pun":"塞扑来","story":"货物「塞」满仓库「扑来」市场，就是供应；供给和需求是经济学的一对。","ex":"When supply exceeds demand, prices tend to fall until the market reaches equilibrium.","exCn":"当供过于求时，价格趋于下跌，直到市场达到均衡。","col":["supply and demand","supply chain","supplier"]},{"id":712,"topic":"economy","w":"demand","ipa":"/dɪˈmɑːnd/","pos":"n./v.","cn":"需求；要求","pun":"地慢的","story":"「地慢的」——地里粮食长得慢，市场上大家却抢着要，需求旺盛。","ex":"Strong consumer demand for electric cars has encouraged manufacturers to increase production.","exCn":"消费者对电动车的强劲需求鼓励厂商增产。","col":["demand for","meet demand","in demand"]},{"id":713,"topic":"economy","w":"abundance","ipa":"/əˈbʌndəns/","pos":"n.","cn":"充裕；丰富","pun":"啊笨蛋死","story":"东西多到「啊，笨蛋死」——笨蛋才会为多得用不完的东西发愁，这就是充裕。","ex":"An abundance of natural resources does not automatically guarantee a country's prosperity.","exCn":"自然资源丰富并不自动保证一个国家的繁荣。","col":["abundance of","in abundance","abundant"]},{"id":714,"topic":"economy","w":"purchase","ipa":"/ˈpɜːtʃəs/","pos":"n./v.","cn":"购买","pun":"扑车死","story":"看到打折车，「扑车死」——扑上去抢着买，就是购买。","ex":"The purchasing power of consumers has declined as wages fail to keep pace with prices.","exCn":"由于工资跟不上物价，消费者购买力下降。","col":["purchasing power","make a purchase","purchase goods"]},{"id":715,"topic":"economy","w":"consumerism","ipa":"/kənˈsjuːmərɪzəm/","pos":"n.","cn":"消费主义","pun":"啃休么日增","story":"consume（消费）+ ism（主义）：「啃休么日增」——买买买不休息，欲望一天天增长，这就是消费主义。","ex":"Critics claim that consumerism encourages people to buy goods they do not really need.","exCn":"批评者称消费主义鼓励人们购买并不真正需要的商品。","col":["rampant consumerism","consumerist culture","consumer society"]},{"id":716,"topic":"economy","w":"materialistic","ipa":"/məˌtɪəriəˈlɪstɪk/","pos":"adj.","cn":"物质主义的","pun":"么提锐了死踢","story":"material（物质）：满脑子只想物质，「么提锐了死踢」——不提钱就踢你，物质主义的。","ex":"Some argue that modern society has become increasingly materialistic and obsessed with wealth.","exCn":"有人认为现代社会越来越物质主义，痴迷于财富。","col":["materialistic society","materialism","material wealth"]},{"id":717,"topic":"economy","w":"frugal","ipa":"/ˈfruːɡl/","pos":"adj.","cn":"节俭的","pun":"富够","story":"「富够」了还是省着花，一分钱掰两半，这就是节俭的。","ex":"Frugal consumers tend to save a larger proportion of their income during uncertain times.","exCn":"节俭的消费者在不确定时期倾向于把更大比例的收入存起来。","col":["frugal lifestyle","frugal with money","frugality"]},{"id":718,"topic":"economy","w":"extravagant","ipa":"/ɪkˈstrævəɡənt/","pos":"adj.","cn":"奢侈的；挥霍的","pun":"一颗死拽我跟","story":"extra（超出）+ vag（走）：花钱走得太远，「一颗死拽我跟」——钻石一颗也要拽着我跟着买，太奢侈了。","ex":"Extravagant spending by the government on prestige projects has drawn heavy criticism.","exCn":"政府在形象工程上的挥霍招致了严厉批评。","col":["extravagant lifestyle","extravagant spending","extravagance"]},{"id":719,"topic":"economy","w":"bargain","ipa":"/ˈbɑːɡən/","pos":"n./v.","cn":"便宜货；讨价还价","pun":"巴跟","story":"「巴跟」——巴着老板跟着他讨价还价，最后买到便宜货，就是 bargain。","ex":"Consumers often search online for bargains before making major purchases.","exCn":"消费者在大额购物前常常在网上搜寻便宜货。","col":["bargain price","bargain hunting","strike a bargain"]},{"id":720,"topic":"economy","w":"brand","ipa":"/brænd/","pos":"n.","cn":"品牌","pun":"不烂的","story":"大品牌就是「不烂的」——质量不会烂，招牌也不会烂。","ex":"Consumers are frequently willing to pay a premium for well-known brands.","exCn":"消费者常常愿意为知名品牌支付溢价。","col":["brand loyalty","brand image","branding"]},{"id":721,"topic":"economy","w":"rival","ipa":"/ˈraɪvl/","pos":"n./v.","cn":"竞争对手；与……匹敌","pun":"来喔","story":"对手在门口喊「来喔」——来啊，比一比，这就是竞争对手。","ex":"The two supermarket chains have been fierce rivals for decades.","exCn":"这两家超市连锁店几十年来一直是激烈的竞争对手。","col":["business rival","rivalry","rival companies"]},{"id":722,"topic":"economy","w":"dominate","ipa":"/ˈdɒmɪneɪt/","pos":"v.","cn":"支配；占主导","pun":"倒霉内特","story":"domin（主人）：一家公司当主人，别家都「倒霉内特」——倒霉得内伤，这就是主导市场。","ex":"A handful of technology giants dominate the global market for online advertising.","exCn":"少数科技巨头主导着全球在线广告市场。","col":["dominate the market","dominant","market dominance"]},{"id":723,"topic":"economy","w":"saturate","ipa":"/ˈsætʃəreɪt/","pos":"v.","cn":"使饱和；使充满","pun":"洒车锐特","story":"市场像一块吸满水的海绵，「洒车锐特」——洒出去的车已经塞满街，再也卖不动，饱和了。","ex":"The smartphone market in developed countries is now largely saturated.","exCn":"发达国家的智能手机市场如今基本饱和。","col":["saturated market","market saturation","saturate with"]},{"id":724,"topic":"economy","w":"niche","ipa":"/niːʃ/","pos":"n.","cn":"利基市场；小众市场","pun":"你师","story":"「你师」——你是这一小块领域的老师，专做别人不做的小众市场，就是 niche。","ex":"Small businesses can survive by targeting a niche market that large companies ignore.","exCn":"小企业可以靠瞄准大公司忽视的小众市场生存。","col":["niche market","find a niche","niche products"]},{"id":725,"topic":"economy","w":"logistics","ipa":"/ləˈdʒɪstɪks/","pos":"n.","cn":"物流；后勤","pun":"了机死踢克死","story":"物流公司飞机、车队全上，「了机死踢克死」——飞机累死、卡车踢死也要把货送到，就是物流。","ex":"Efficient logistics networks are essential for the success of e-commerce companies.","exCn":"高效的物流网络对电商公司的成功至关重要。","col":["logistics company","supply chain logistics","logistical"]},{"id":726,"topic":"economy","w":"manufacture","ipa":"/ˌmænjuˈfæktʃə(r)/","pos":"v./n.","cn":"制造；生产","pun":"慢扭发克车","story":"manu（手）+ fact（做）：用手做东西，工人「慢扭发克车」——慢慢扭螺丝造出一辆车，就是制造。","ex":"Many developed countries have seen their manufacturing sector shrink as production moves overseas.","exCn":"随着生产向海外转移，许多发达国家的制造业萎缩。","col":["manufacturing industry","manufacturer","manufactured goods"]},{"id":727,"topic":"economy","w":"output","ipa":"/ˈaʊtpʊt/","pos":"n.","cn":"产量；产出","pun":"傲特扑特","story":"out（出）+ put（放）：工厂放出来的东西，「傲特扑特」——骄傲地扑出来一大堆产品，就是产量。","ex":"Industrial output fell by three per cent in the first quarter of the year.","exCn":"今年第一季度工业产出下降了3%。","col":["industrial output","economic output","output growth"]},{"id":728,"topic":"economy","w":"taxation","ipa":"/tækˈseɪʃn/","pos":"n.","cn":"税收；征税","pun":"太可惜神","story":"tax（税）+ ation：工资单上扣掉一大块，「太可惜神」——太可惜了神啊，这就是征税。","ex":"Progressive taxation requires high earners to contribute a larger share of their income.","exCn":"累进税制要求高收入者缴纳更大比例的收入。","col":["progressive taxation","taxation system","taxpayer"]},{"id":729,"topic":"economy","w":"exempt","ipa":"/ɪɡˈzempt/","pos":"adj./v.","cn":"免除的；豁免","pun":"一个怎扑特","story":"ex（出）+ empt（拿）：从名单里拿出去，「一个怎扑特」——一个都怎么扑不到你，免税了。","ex":"Charities are generally exempt from paying corporation tax in most countries.","exCn":"在多数国家，慈善机构通常免缴公司税。","col":["exempt from tax","tax-exempt","exemption"]},{"id":730,"topic":"economy","w":"evasion","ipa":"/ɪˈveɪʒn/","pos":"n.","cn":"逃避；逃税","pun":"一喂真","story":"e（出）+ vas（走）：溜出去不交税，被抓到还「一喂真」——喂，真不是我，这就是逃税。","ex":"Tax evasion by wealthy individuals deprives governments of billions in revenue each year.","exCn":"富人逃税每年使政府损失数十亿收入。","col":["tax evasion","evade tax","evasive"]},{"id":731,"topic":"economy","w":"loophole","ipa":"/ˈluːphəʊl/","pos":"n.","cn":"（法律等的）漏洞","pun":"漏破活","story":"loop（环）+ hole（洞）：法律像张网，「漏破活」——漏出来的破洞让人钻空子活下去，就是漏洞。","ex":"Multinational firms exploit legal loopholes to shift profits to low-tax jurisdictions.","exCn":"跨国公司利用法律漏洞把利润转移到低税地区。","col":["tax loophole","close a loophole","exploit a loophole"]},{"id":732,"topic":"economy","w":"audit","ipa":"/ˈɔːdɪt/","pos":"n./v.","cn":"审计；查账","pun":"奥迪特","story":"aud（听）：审计员一边听老板解释账目，一边看他的「奥迪特」别新，查账查得更仔细了。","ex":"Independent auditors are required to examine the financial statements of listed companies.","exCn":"上市公司的财务报表须由独立审计师审查。","col":["financial audit","auditor","audit report"]},{"id":733,"topic":"economy","w":"transaction","ipa":"/trænˈzækʃn/","pos":"n.","cn":"交易；业务","pun":"穿灾克神","story":"trans（穿过）+ act（做）：钱从一方穿过去到另一方，「穿灾克神」——穿越灾难克服困难，完成交易。","ex":"Digital payments have made financial transactions faster and more transparent.","exCn":"数字支付使金融交易更快、更透明。","col":["financial transaction","cash transaction","transaction fee"]},{"id":734,"topic":"economy","w":"remittance","ipa":"/rɪˈmɪtns/","pos":"n.","cn":"汇款","pun":"瑞米疼死","story":"remit（寄钱）：打工的「瑞米」每月往家寄钱，心「疼死」也要寄，这就是汇款。","ex":"Remittances from migrant workers make up a significant share of GDP in some developing countries.","exCn":"在一些发展中国家，移民工人汇款占GDP很大比例。","col":["send remittances","remittance flows","remit money"]},{"id":735,"topic":"economy","w":"tycoon","ipa":"/taɪˈkuːn/","pos":"n.","cn":"大亨；巨头","pun":"太酷","story":"商业大亨开着私人飞机，「太酷」了，tycoon 就是这么酷的巨头。","ex":"Property tycoons have profited enormously from the rapid rise in urban land values.","exCn":"房地产大亨从城市地价飞涨中获利巨大。","col":["business tycoon","media tycoon","property tycoon"]},{"id":736,"topic":"economy","w":"conglomerate","ipa":"/kənˈɡlɒmərət/","pos":"n.","cn":"企业集团","pun":"啃个楼么锐特","story":"con（一起）+ glomer（团）：一大团公司捏在一起，「啃个楼么锐特」——大到能啃掉一栋楼，就是企业集团。","ex":"Large conglomerates can use their financial power to squeeze smaller competitors out of the market.","exCn":"大型企业集团可以利用财力把较小的竞争者挤出市场。","col":["industrial conglomerate","media conglomerate","multinational conglomerate"]},{"id":737,"topic":"economy","w":"multinational","ipa":"/ˌmʌltiˈnæʃnəl/","pos":"adj./n.","cn":"跨国的；跨国公司","pun":"帽提耐神了","story":"multi（多）+ national（国家的）：在很多国家开公司，「帽提耐神了」——提着帽子跑遍各国，神都耐不住。","ex":"Multinationals often pay less tax than local businesses by shifting profits across borders.","exCn":"跨国公司通过跨境转移利润，纳税常常比本地企业少。","col":["multinational company","multinational corporation","multinational firm"]},{"id":738,"topic":"economy","w":"domestic","ipa":"/dəˈmestɪk/","pos":"adj.","cn":"国内的；家庭的","pun":"德么死踢克","story":"dom（家）：在家里、在国内的，「德么死踢克」——德国人在自己家里踢球，就是国内的。","ex":"Boosting domestic demand can reduce a country's dependence on exports.","exCn":"扩大内需可以减少一国对出口的依赖。","col":["domestic market","domestic demand","gross domestic product"]},{"id":739,"topic":"economy","w":"offshore","ipa":"/ˌɒfˈʃɔː(r)/","pos":"adj./adv.","cn":"离岸的；海外的","pun":"哦福守","story":"off（离开）+ shore（岸）：钱离开岸边藏到海外小岛，「哦福守」——哦，福气在海外守着，就是离岸账户。","ex":"Wealthy individuals hide assets in offshore accounts to avoid paying tax.","exCn":"富人把资产藏在离岸账户以逃避纳税。","col":["offshore account","offshore company","move offshore"]},{"id":740,"topic":"economy","w":"embargo","ipa":"/ɪmˈbɑːɡəʊ/","pos":"n.","cn":"禁运；贸易禁令","pun":"俺爸狗","story":"「俺爸狗」都不许卖给那个国家——一件货都不准进出，这就是禁运。","ex":"The trade embargo severely damaged the country's ability to import essential medicines.","exCn":"贸易禁运严重损害了该国进口基本药品的能力。","col":["trade embargo","impose an embargo","lift the embargo"]},{"id":741,"topic":"economy","w":"sanction","ipa":"/ˈsæŋkʃn/","pos":"n./v.","cn":"制裁；批准","pun":"三克神","story":"大国「三克神」——三下就克住对方，禁止贸易、冻结资产，这就是制裁。","ex":"Economic sanctions were imposed to pressure the regime into changing its policies.","exCn":"实施经济制裁以迫使该政权改变政策。","col":["economic sanctions","impose sanctions on","lift sanctions"]},{"id":742,"topic":"economy","w":"quota","ipa":"/ˈkwəʊtə/","pos":"n.","cn":"配额；限额","pun":"扣它","story":"进口太多就「扣它」——扣住超出的部分，只准进这么多，就是配额。","ex":"Import quotas restrict the quantity of foreign goods allowed into the domestic market.","exCn":"进口配额限制了允许进入国内市场的外国商品数量。","col":["import quota","set a quota","quota system"]},{"id":743,"topic":"economy","w":"protectionism","ipa":"/prəˈtekʃənɪzəm/","pos":"n.","cn":"贸易保护主义","pun":"扑太可神你怎","story":"protect（保护）+ ism：政府扑上去护着本国产业，「扑太可神你怎」——外国货你怎么进得来？就是保护主义。","ex":"Rising protectionism threatens to undermine decades of progress in global trade.","exCn":"抬头的保护主义有可能破坏全球贸易几十年的进展。","col":["trade protectionism","protectionist policies","protectionist"]},{"id":744,"topic":"economy","w":"commerce","ipa":"/ˈkɒmɜːs/","pos":"n.","cn":"商业；贸易","pun":"卡么死","story":"com（一起）+ merc（商品）：大家一起买卖商品，「卡么死」——没有商业交流经济就卡死了。","ex":"The growth of electronic commerce has transformed the way people shop.","exCn":"电子商务的发展改变了人们的购物方式。","col":["electronic commerce","chamber of commerce","commercial"]},{"id":745,"topic":"economy","w":"commercial","ipa":"/kəˈmɜːʃl/","pos":"adj./n.","cn":"商业的；广告","pun":"可么秀","story":"commerce 的形容词：「可么秀」——可以拍个秀来卖东西，这就是商业的，也指电视广告。","ex":"The commercial success of the product depended heavily on its marketing campaign.","exCn":"该产品的商业成功很大程度上依赖于其营销活动。","col":["commercial success","commercial interests","commercialise"]},{"id":746,"topic":"economy","w":"client","ipa":"/ˈklaɪənt/","pos":"n.","cn":"客户；委托人","pun":"可来恩特","story":"「可来恩特」——可以来的都是恩人，律师和咨询公司这么称呼自己的客户。","ex":"Consulting firms compete fiercely to attract high-value corporate clients.","exCn":"咨询公司为吸引高价值企业客户竞争激烈。","col":["corporate client","client base","clientele"]},{"id":747,"topic":"economy","w":"consumer","ipa":"/kənˈsjuːmə(r)/","pos":"n.","cn":"消费者","pun":"啃休么","story":"consume（消费）+ er：「啃休么」——啃东西不休息的人，就是消费者。","ex":"Consumers are increasingly willing to pay more for products that are ethically sourced.","exCn":"消费者越来越愿意为符合道德采购的产品多付钱。","col":["consumer spending","consumer confidence","consumer goods"]},{"id":748,"topic":"economy","w":"supplier","ipa":"/səˈplaɪə(r)/","pos":"n.","cn":"供应商","pun":"塞扑来呀","story":"supply（供应）+ er：「塞扑来呀」——把货塞满扑过来的人，就是供应商。","ex":"Large retailers often pressure suppliers to lower their prices.","exCn":"大型零售商常常向供应商施压要求降价。","col":["main supplier","supplier of","energy supplier"]},{"id":749,"topic":"economy","w":"vendor","ipa":"/ˈvendə(r)/","pos":"n.","cn":"小贩；卖方","pun":"问的","story":"路边小贩「问的」——一路问你要不要买，vendor 就是卖东西的人。","ex":"Street vendors form an important part of the informal economy in many developing cities.","exCn":"街头小贩是许多发展中城市非正规经济的重要组成部分。","col":["street vendor","software vendor","vending machine"]},{"id":750,"topic":"economy","w":"procurement","ipa":"/prəˈkjʊəmənt/","pos":"n.","cn":"采购","pun":"扑扣门特","story":"procure（获取）：采购员「扑扣门特」——扑到供应商门上扣门，买设备买原料，就是采购。","ex":"Transparent public procurement reduces the risk of corruption in government contracts.","exCn":"透明的公共采购降低了政府合同中的腐败风险。","col":["public procurement","procurement process","procure"]},{"id":751,"topic":"economy","w":"inventory","ipa":"/ˈɪnvəntri/","pos":"n.","cn":"库存；存货","pun":"硬闻吐锐","story":"仓库里堆着货，「硬闻吐锐」——硬是闻一闻就想吐，堆太久了，这就是库存。","ex":"Efficient inventory management helps companies avoid tying up capital in unsold goods.","exCn":"高效的库存管理帮助公司避免资金被积压在未售商品上。","col":["inventory management","hold inventory","excess inventory"]},{"id":752,"topic":"economy","w":"insolvent","ipa":"/ɪnˈsɒlvənt/","pos":"adj.","cn":"无力偿债的；破产的","pun":"硬扫翁特","story":"in（不）+ solve（解决）：钱的问题解决不了，「硬扫翁特」——把老翁硬扫出门，无力偿债了。","ex":"The bank was declared insolvent after failing to meet its obligations to depositors.","exCn":"该银行因无法履行对储户的义务被宣布资不抵债。","col":["become insolvent","insolvency","declared insolvent"]},{"id":753,"topic":"economy","w":"liquidate","ipa":"/ˈlɪkwɪdeɪt/","pos":"v.","cn":"清算；变卖","pun":"里去的","story":"liquid（液体）：把公司资产全变成流动的现金，「里去的」——里面东西全卖出去，就是清算。","ex":"The firm was forced to liquidate its assets to repay outstanding debts.","exCn":"该公司被迫变卖资产偿还未清债务。","col":["liquidate assets","liquidation","go into liquidation"]},{"id":754,"topic":"economy","w":"collateral","ipa":"/kəˈlætərəl/","pos":"n.","cn":"抵押品；担保物","pun":"可拉特绕","story":"col（一起）+ lateral（旁边）：借钱时旁边放个东西，「可拉特绕」——还不上就可以拉走，就是抵押品。","ex":"Small farmers often cannot obtain loans because they lack collateral.","exCn":"小农户常常因缺乏抵押品而无法获得贷款。","col":["use as collateral","collateral for a loan","collateral damage"]},{"id":755,"topic":"economy","w":"creditor","ipa":"/ˈkredɪtə(r)/","pos":"n.","cn":"债权人","pun":"快递他","story":"credit（信用）+ or：借钱给你的人，天天「快递他」催款信来，就是债权人。","ex":"Creditors agreed to write off part of the debt to prevent the company from collapsing.","exCn":"债权人同意免除部分债务以防公司倒闭。","col":["pay creditors","creditor nations","credit"]},{"id":756,"topic":"economy","w":"loan","ipa":"/ləʊn/","pos":"n./v.","cn":"贷款；借出","pun":"漏恩","story":"银行「漏恩」——漏一点恩惠给你先用，以后连本带利还，这就是贷款。","ex":"Student loans have left many graduates burdened with debt for decades.","exCn":"学生贷款让许多毕业生背负数十年的债务。","col":["take out a loan","bank loan","loan repayment"]},{"id":757,"topic":"economy","w":"yield","ipa":"/jiːld/","pos":"v./n.","cn":"产生（收益）；收益率","pun":"衣哦的","story":"投资像种田，「衣哦的」——衣服哦，地里长出来的收成，就是产生收益。","ex":"Government bonds yield lower returns but are considered far safer than shares.","exCn":"政府债券收益率较低，但被认为比股票安全得多。","col":["high yield","yield a profit","crop yields"]},{"id":758,"topic":"economy","w":"portfolio","ipa":"/pɔːtˈfəʊliəʊ/","pos":"n.","cn":"投资组合；作品集","pun":"跑佛里哦","story":"port（携带）+ folio（纸页）：带着一叠资产清单「跑佛里哦」——跑到佛寺里求保佑，就是投资组合。","ex":"A diversified investment portfolio reduces the risk of heavy losses.","exCn":"多元化的投资组合可以降低重大损失的风险。","col":["investment portfolio","diversified portfolio","portfolio manager"]},{"id":759,"topic":"economy","w":"equity","ipa":"/ˈekwəti/","pos":"n.","cn":"股本；公平","pun":"爱可威提","story":"equ（平等）：股东按股份平等分利，「爱可威提」——爱可以威风地提要求，这就是股权；也指公平。","ex":"Private equity firms buy struggling companies, restructure them and sell them for a profit.","exCn":"私募股权公司买下困境企业，重组后再出售获利。","col":["private equity","equity stake","social equity"]},{"id":760,"topic":"economy","w":"bond","ipa":"/bɒnd/","pos":"n.","cn":"债券；纽带","pun":"绑的","story":"买债券就像和政府「绑的」在一起——借钱给它，到期连本带息还你，也指人和人的纽带。","ex":"Governments issue bonds to raise money for large infrastructure projects.","exCn":"政府发行债券为大型基础设施项目筹资。","col":["government bond","issue bonds","bond market"]},{"id":761,"topic":"economy","w":"stock","ipa":"/stɒk/","pos":"n.","cn":"股票；库存","pun":"死抠","story":"「死抠」——死抠着股票不肯卖，也死抠着仓库存货，stock 既是股票也是库存。","ex":"The stock market crashed, wiping out billions of pounds in savings overnight.","exCn":"股市崩盘，一夜之间蒸发了数十亿英镑的储蓄。","col":["stock market","stock exchange","out of stock"]},{"id":762,"topic":"economy","w":"bubble","ipa":"/ˈbʌbl/","pos":"n.","cn":"泡沫；经济泡沫","pun":"爸不","story":"房价吹成泡泡，「爸不」——爸爸不肯再买，泡沫一戳就破，这就是经济泡沫。","ex":"The housing bubble burst in 2008, triggering a global financial crisis.","exCn":"2008年房地产泡沫破裂，引发全球金融危机。","col":["housing bubble","bubble bursts","speculative bubble"]},{"id":763,"topic":"economy","w":"crisis","ipa":"/ˈkraɪsɪs/","pos":"n.","cn":"危机","pun":"快死死","story":"金融危机一来，公司「快死死」——快死了，真的要死了，这就是危机。","ex":"The financial crisis exposed serious weaknesses in the global banking system.","exCn":"金融危机暴露了全球银行体系的严重弱点。","col":["financial crisis","economic crisis","in crisis"]},{"id":764,"topic":"economy","w":"downturn","ipa":"/ˈdaʊntɜːn/","pos":"n.","cn":"（经济）衰退；下降","pun":"荡疼","story":"down（下）+ turn（转）：经济掉头往下，「荡疼」——荡下去摔得生疼，就是经济下行。","ex":"The economic downturn forced many companies to lay off staff and freeze investment.","exCn":"经济下行迫使许多公司裁员并冻结投资。","col":["economic downturn","sharp downturn","downturn in"]},{"id":765,"topic":"economy","w":"boom","ipa":"/buːm/","pos":"n./v.","cn":"繁荣；激增","pun":"嘣","story":"经济「嘣」地一声炸开——工厂开工、房子卖光，这就是经济繁荣、迅速增长。","ex":"The construction boom created thousands of jobs but also pushed up property prices.","exCn":"建筑业繁荣创造了数千个岗位，但也推高了房价。","col":["economic boom","boom and bust","booming"]},{"id":766,"topic":"economy","w":"stimulus","ipa":"/ˈstɪmjələs/","pos":"n.","cn":"刺激；刺激措施","pun":"死提么了死","story":"stimul（刺）：经济半死不活，政府拿针「死提么了死」——刺一下、提一下，就活了，就是刺激方案。","ex":"The government introduced a fiscal stimulus package to revive the struggling economy.","exCn":"政府推出财政刺激方案以重振疲弱经济。","col":["stimulus package","economic stimulus","stimulate"]},{"id":767,"topic":"economy","w":"bailout","ipa":"/ˈbeɪlaʊt/","pos":"n.","cn":"（财政）紧急救助","pun":"贝奥特","story":"bail（舀水）+ out：船要沉了赶紧舀水，「贝奥特」——贝壳都被舀出去，政府救银行就是紧急救助。","ex":"Taxpayers were angered by the massive bailout of banks that had taken excessive risks.","exCn":"纳税人对大规模救助那些过度冒险的银行感到愤怒。","col":["bank bailout","bailout package","bail out"]},{"id":768,"topic":"economy","w":"gross","ipa":"/ɡrəʊs/","pos":"adj.","cn":"总的；毛的","pun":"格漏死","story":"税前的总数「格漏死」——一格都没漏掉，全算上，就是 gross；GDP 里的 G 就是它。","ex":"Gross domestic product grew by two per cent last year, slightly below expectations.","exCn":"去年国内生产总值增长2%，略低于预期。","col":["gross domestic product","gross income","gross profit"]},{"id":769,"topic":"economy","w":"per capita","ipa":"/pə ˈkæpɪtə/","pos":"phr.","cn":"人均","pun":"泼开皮它","story":"per（每）+ capita（头）：按人头算，「泼开皮它」——把总数泼开分到每个人的头皮上，就是人均。","ex":"Income per capita in the region has tripled over the past thirty years.","exCn":"该地区人均收入在过去三十年增长了两倍。","col":["GDP per capita","per capita income","per capita consumption"]},{"id":770,"topic":"economy","w":"index","ipa":"/ˈɪndeks/","pos":"n.","cn":"指数；索引","pun":"硬带克死","story":"物价指数「硬带克死」——硬是带着一串数字克死你的钱包，index 就是衡量的指数。","ex":"The consumer price index is the most widely used measure of inflation.","exCn":"消费者价格指数是最常用的通胀衡量指标。","col":["consumer price index","stock index","index of"]},{"id":771,"topic":"economy","w":"benchmark","ipa":"/ˈbentʃmɑːk/","pos":"n.","cn":"基准；标准","pun":"扳尺马克","story":"bench（凳子）+ mark（记号）：工匠在凳子上刻记号当标准，「扳尺马克」——扳着尺子做记号，就是基准。","ex":"The central bank raised its benchmark interest rate to combat inflation.","exCn":"央行上调基准利率以应对通胀。","col":["benchmark rate","set a benchmark","benchmark against"]},{"id":772,"topic":"economy","w":"forecast","ipa":"/ˈfɔːkɑːst/","pos":"n./v.","cn":"预测；预报","pun":"佛卡死特","story":"fore（前）+ cast（投）：往前投一眼，「佛卡死特」——佛掐指一算说明年经济怎样，就是预测。","ex":"Economists forecast that growth will slow to below one per cent next year.","exCn":"经济学家预测明年增长将放缓至1%以下。","col":["economic forecast","forecast growth","weather forecast"]},{"id":773,"topic":"economy","w":"projection","ipa":"/prəˈdʒekʃn/","pos":"n.","cn":"预测；推算","pun":"扑杰克神","story":"pro（向前）+ ject（扔）：把现在的数据往前扔，「扑杰克神」——扑到杰克神那里算未来，就是预测推算。","ex":"Official projections suggest the population will reach seventy million by 2050.","exCn":"官方预测显示人口到2050年将达到七千万。","col":["economic projections","population projection","project"]},{"id":774,"topic":"economy","w":"trend","ipa":"/trend/","pos":"n.","cn":"趋势；潮流","pun":"穿的","story":"看大家「穿的」什么就知道流行趋势，经济数据的走向也叫 trend。","ex":"The upward trend in house prices shows little sign of slowing down.","exCn":"房价上升趋势几乎没有放缓迹象。","col":["upward trend","economic trend","trend towards"]},{"id":775,"topic":"economy","w":"soar","ipa":"/sɔː(r)/","pos":"v.","cn":"猛增；飙升","pun":"嗖","story":"价格「嗖」地一声冲上天，像老鹰一样飙升，就是 soar。","ex":"Energy prices soared following the disruption of global supply chains.","exCn":"全球供应链中断后能源价格飙升。","col":["prices soar","soaring costs","soar to"]},{"id":776,"topic":"economy","w":"plummet","ipa":"/ˈplʌmɪt/","pos":"v.","cn":"暴跌；骤降","pun":"扑拉米特","story":"plumb（铅锤）：股价像铅锤一样直坠，「扑拉米特」——扑通掉下去拉都拉不住，就是暴跌。","ex":"Share prices plummeted after the company announced a major accounting scandal.","exCn":"该公司宣布重大会计丑闻后股价暴跌。","col":["prices plummet","plummet by","plummet to"]},{"id":777,"topic":"economy","w":"surge","ipa":"/sɜːdʒ/","pos":"n./v.","cn":"激增；急剧上升","pun":"涩之","story":"「涩之」——市场一下子涌进一大波需求，像浪头一样冲上来，就是激增。","ex":"A surge in demand for housing has pushed rents to record levels.","exCn":"住房需求激增把租金推至历史高位。","col":["a surge in","surge in demand","price surge"]},{"id":778,"topic":"economy","w":"decline","ipa":"/dɪˈklaɪn/","pos":"v./n.","cn":"下降；衰退；拒绝","pun":"地克赖","story":"de（下）+ clin（倾斜）：往下斜，「地克赖」——地都克着你赖在下坡上，就是下降、衰退。","ex":"The decline of traditional manufacturing has left many industrial towns in poverty.","exCn":"传统制造业的衰退使许多工业城镇陷入贫困。","col":["economic decline","decline in","steady decline"]},{"id":779,"topic":"economy","w":"slump","ipa":"/slʌmp/","pos":"n./v.","cn":"暴跌；萧条","pun":"死拉扑","story":"人瘫在椅子上一动不动，销量「死拉扑」——死拉着往下扑，就是暴跌、萧条。","ex":"The slump in oil prices devastated economies that depend on energy exports.","exCn":"油价暴跌重创了依赖能源出口的经济体。","col":["economic slump","slump in sales","slump to"]},{"id":780,"topic":"economy","w":"rebound","ipa":"/rɪˈbaʊnd/","pos":"v./n.","cn":"反弹；回升","pun":"瑞帮的","story":"re（回）+ bound（跳）：像篮球撞地板弹回来，「瑞帮的」——瑞士银行帮的忙，经济反弹了。","ex":"The economy rebounded strongly once restrictions were lifted and shops reopened.","exCn":"限制解除、商店重开后经济强劲反弹。","col":["rebound from","strong rebound","economic rebound"]},{"id":781,"topic":"economy","w":"volatile","ipa":"/ˈvɒlətaɪl/","pos":"adj.","cn":"不稳定的；易波动的","pun":"我了太哦","story":"vol（飞）：价格像鸟一样飞来飞去，「我了太哦」——我哦，太吓人了，就是不稳定的。","ex":"Cryptocurrencies are highly volatile and unsuitable for risk-averse investors.","exCn":"加密货币波动极大，不适合规避风险的投资者。","col":["volatile market","volatile prices","volatility"]},{"id":782,"topic":"economy","w":"robust","ipa":"/rəʊˈbʌst/","pos":"adj.","cn":"强劲的；稳健的","pun":"肉八四特","story":"经济像个壮汉，「肉八四特」——身上八块肌肉四块特别结实，就是强劲稳健的。","ex":"Robust consumer spending has helped the economy withstand external shocks.","exCn":"强劲的消费支出帮助经济抵御了外部冲击。","col":["robust growth","robust economy","robust demand"]},{"id":783,"topic":"economy","w":"sluggish","ipa":"/ˈslʌɡɪʃ/","pos":"adj.","cn":"缓慢的；萧条的","pun":"死拉个鱼","story":"slug（蜗牛）：经济慢得像蜗牛，「死拉个鱼」——死拉着一条鱼都拉不动，就是萧条缓慢。","ex":"Sluggish growth in Europe has weighed on global demand for Asian exports.","exCn":"欧洲增长乏力拖累了全球对亚洲出口的需求。","col":["sluggish economy","sluggish growth","sluggish demand"]},{"id":784,"topic":"economy","w":"hardship","ipa":"/ˈhɑːdʃɪp/","pos":"n.","cn":"困苦；艰难","pun":"哈的西扑","story":"hard（艰难）+ ship（状态）：日子艰难，「哈的西扑」——哈着气往西扑去找活干，就是困苦。","ex":"Rising food prices have caused severe hardship for low-income families.","exCn":"食品价格上涨给低收入家庭造成严重困难。","col":["economic hardship","financial hardship","suffer hardship"]},{"id":785,"topic":"economy","w":"deprivation","ipa":"/ˌdeprɪˈveɪʃn/","pos":"n.","cn":"匮乏；贫困","pun":"得扑瑞为神","story":"de（去掉）+ priv（私有）：私有的东西全被拿走，「得扑瑞为神」——得扑倒在地求神，就是匮乏。","ex":"Children growing up in deprivation are less likely to succeed at school.","exCn":"在贫困中长大的孩子在学校成功的可能性更低。","col":["social deprivation","deprived of","deprived areas"]},{"id":786,"topic":"economy","w":"destitute","ipa":"/ˈdestɪtjuːt/","pos":"adj.","cn":"赤贫的；一无所有的","pun":"待死踢图特","story":"「待死踢图特」——穷到只能待着等死，被人踢，图个特殊救济，就是赤贫的。","ex":"The economic collapse left thousands of families destitute and dependent on charity.","exCn":"经济崩溃使数千家庭一贫如洗，依赖慈善救济。","col":["left destitute","destitute families","destitution"]},{"id":787,"topic":"economy","w":"philanthropy","ipa":"/fɪˈlænθrəpi/","pos":"n.","cn":"慈善事业；博爱","pun":"非烂死肉皮","story":"phil（爱）+ anthrop（人）：爱人类，「非烂死肉皮」——富豪非要把烂了的皮肉都治好，捐钱做慈善。","ex":"Some billionaires have pledged to give away most of their wealth through philanthropy.","exCn":"一些亿万富翁承诺通过慈善事业捐出大部分财富。","col":["corporate philanthropy","philanthropist","philanthropic"]},{"id":788,"topic":"economy","w":"charity","ipa":"/ˈtʃærəti/","pos":"n.","cn":"慈善；慈善机构","pun":"掐了踢","story":"「掐了踢」——从自己钱包里掐一点出来，踢给需要的人，就是慈善。","ex":"Many people believe that charities, rather than governments, should support the homeless.","exCn":"许多人认为应由慈善机构而非政府来救助无家可归者。","col":["charity organisation","donate to charity","charitable"]},{"id":789,"topic":"economy","w":"donate","ipa":"/dəʊˈneɪt/","pos":"v.","cn":"捐赠","pun":"都内特","story":"don（给）：「都内特」——把口袋里的都给出去，特别大方，就是捐赠。","ex":"Wealthy individuals should be encouraged to donate a proportion of their income to good causes.","exCn":"应鼓励富人把一部分收入捐给公益事业。","col":["donate to","donation","donor"]},{"id":790,"topic":"economy","w":"redistribute","ipa":"/ˌriːdɪˈstrɪbjuːt/","pos":"v.","cn":"重新分配","pun":"瑞地死追不","story":"re（再）+ distribute（分配）：把富人的钱再分一次，「瑞地死追不」——瑞地追着有钱人分，就是再分配。","ex":"Progressive taxes redistribute wealth from the richest citizens to the poorest.","exCn":"累进税把财富从最富的公民重新分配给最穷的人。","col":["redistribute wealth","redistribution","redistribute income"]},{"id":791,"topic":"economy","w":"disparity","ipa":"/dɪˈspærəti/","pos":"n.","cn":"差距；不平等","pun":"地死拍了踢","story":"dis（不）+ par（相等）：不相等，「地死拍了踢」——穷人趴地上，富人拍着桌子踢，就是差距。","ex":"There is a growing disparity between the incomes of urban and rural households.","exCn":"城乡家庭收入差距不断扩大。","col":["income disparity","wealth disparity","disparity between"]},{"id":792,"topic":"economy","w":"subsistence","ipa":"/səbˈsɪstəns/","pos":"n.","cn":"勉强维持生活","pun":"色不喜死疼死","story":"sub（下面）+ sist（站）：站在生存线下面，「色不喜死疼死」——脸色难看，饿得疼死，只能勉强糊口。","ex":"Many rural families rely on subsistence farming and produce little surplus for sale.","exCn":"许多农村家庭依靠自给农业，几乎没有剩余可卖。","col":["subsistence farming","subsistence level","subsist on"]},{"id":793,"topic":"economy","w":"patent","ipa":"/ˈpætnt/","pos":"n./v.","cn":"专利","pun":"拍疼特","story":"发明家「拍疼特」——拍桌子拍得手疼，特别强调这是我的专利，别人不许仿。","ex":"Patents protect inventors and encourage companies to invest in research.","exCn":"专利保护发明者并鼓励公司投资研发。","col":["file a patent","patent protection","patented technology"]},{"id":794,"topic":"economy","w":"marketing","ipa":"/ˈmɑːkɪtɪŋ/","pos":"n.","cn":"营销","pun":"马克踢","story":"market（市场）+ ing：「马克踢」——马克把产品踢进市场，想尽办法让人买，就是营销。","ex":"Aggressive marketing campaigns persuade consumers to buy products they do not need.","exCn":"激进的营销活动说服消费者购买他们不需要的产品。","col":["marketing campaign","marketing strategy","market a product"]},{"id":795,"topic":"economy","w":"discount","ipa":"/ˈdɪskaʊnt/","pos":"n./v.","cn":"折扣","pun":"底是砍它","story":"dis（去掉）+ count（数）：从价钱里减掉一部分，「底是砍它」——底价就是砍它一刀，就是折扣。","ex":"Retailers offer heavy discounts to clear unsold inventory at the end of the season.","exCn":"零售商季末大幅打折以清理未售库存。","col":["offer a discount","at a discount","discounted price"]},{"id":796,"topic":"economy","w":"luxury","ipa":"/ˈlʌkʃəri/","pos":"n./adj.","cn":"奢侈；奢侈品","pun":"拉克涮里","story":"「拉克涮里」——拉着劳斯莱斯去涮火锅，这就是奢侈的生活。","ex":"Demand for luxury goods has grown rapidly among the newly wealthy in emerging economies.","exCn":"新兴经济体新富阶层对奢侈品的需求快速增长。","col":["luxury goods","luxury brand","luxurious"]},{"id":797,"topic":"economy","w":"wealth","ipa":"/welθ/","pos":"n.","cn":"财富","pun":"维尔思","story":"「维尔思」——维持家里的思路就是攒钱，攒出来的就是财富，wealthy 就是富有的。","ex":"The concentration of wealth in the hands of a few threatens social stability.","exCn":"财富集中在少数人手中威胁社会稳定。","col":["wealth gap","accumulate wealth","wealthy"]},{"id":798,"topic":"economy","w":"allocate","ipa":"/ˈæləkeɪt/","pos":"v.","cn":"分配；拨款","pun":"爱了开特","story":"al（去）+ loc（地方）：把钱分到各个地方，「爱了开特」——爱哪儿开支就往哪儿拨，就是分配。","ex":"Governments must decide how to allocate limited resources between competing priorities.","exCn":"政府必须决定如何在相互竞争的优先事项之间分配有限资源。","col":["allocate resources","allocate funds","allocation"]},{"id":799,"topic":"law","w":"legislate","ipa":"/ˈledʒɪsleɪt/","pos":"v.","cn":"立法；制定法律","pun":"累计死累特","story":"legis（法律）+ late：议会累计熬到死累，特意为一件事立法。","ex":"Governments should legislate to limit the use of plastic packaging in supermarkets.","exCn":"政府应立法限制超市中塑料包装的使用。","col":["legislate against","legislate for","legislator"]},{"id":800,"topic":"law","w":"parliament","ipa":"/ˈpɑːləmənt/","pos":"n.","cn":"议会；国会","pun":"怕了门","story":"parl（说话）+ ment：议员们进了议会大门就开始辩论，谁都怕了这扇门后的口水战。","ex":"The bill must be approved by both houses of parliament before it becomes law.","exCn":"该法案必须经议会两院批准后才能成为法律。","col":["member of parliament","parliamentary debate","parliamentary"]},{"id":801,"topic":"law","w":"constitution","ipa":"/ˌkɒnstɪˈtjuːʃn/","pos":"n.","cn":"宪法；体制","pun":"看死踢丢身","story":"con（一起）+ stitute（建立）：宪法把国家的根基一起立起来，谁敢踢它就看死他。","ex":"The constitution guarantees every citizen the right to freedom of speech.","exCn":"宪法保障每位公民享有言论自由的权利。","col":["written constitution","constitutional rights","constitutional"]},{"id":802,"topic":"law","w":"amendment","ipa":"/əˈmendmənt/","pos":"n.","cn":"修正案；修改","pun":"饿闷的门","story":"a + mend（修补）：法律有漏洞像饿闷的门漏风，议会打个补丁，就是修正案。","ex":"The amendment to the housing law was passed after months of heated debate.","exCn":"经过数月激烈辩论后，住房法修正案获得通过。","col":["propose an amendment","constitutional amendment","amend"]},{"id":803,"topic":"law","w":"bureaucratic","ipa":"/ˌbjʊərəˈkrætɪk/","pos":"adj.","cn":"官僚的；繁文缛节的","pun":"标若克拉踢","story":"办公桌前的官员慢吞吞，办事的人急得想踢桌子——这就是官僚的作风。","ex":"Small businesses complain that bureaucratic procedures waste time and money.","exCn":"小企业抱怨官僚程序浪费时间和金钱。","col":["bureaucratic procedures","bureaucratic hurdles","bureaucracy"]},{"id":804,"topic":"law","w":"democracy","ipa":"/dɪˈmɒkrəsi/","pos":"n.","cn":"民主；民主国家","pun":"低摸克拉西","story":"demo（人民）+ cracy（统治）：人民低头摸着选票统治国家，这就是民主。","ex":"A functioning democracy depends on citizens who are willing to participate in elections.","exCn":"运转良好的民主依赖愿意参与选举的公民。","col":["parliamentary democracy","direct democracy","democratic"]},{"id":805,"topic":"law","w":"election","ipa":"/ɪˈlekʃn/","pos":"n.","cn":"选举","pun":"一累可甚","story":"e（出）+ lect（选）：候选人跑遍全国拉票，一累可甚，只为赢得选举。","ex":"Voter turnout in the general election fell to its lowest level in decades.","exCn":"大选投票率降至数十年来的最低水平。","col":["general election","hold an election","elect"]},{"id":806,"topic":"law","w":"electorate","ipa":"/ɪˈlektərət/","pos":"n.","cn":"全体选民","pun":"一累可特瑞特","story":"elect（选举）+ orate：全体选民是投票的主力，候选人累得特别瑞特也要讨好他们。","ex":"Politicians must respond to the concerns of the electorate if they wish to stay in power.","exCn":"政治家若想继续执政，就必须回应全体选民的关切。","col":["the electorate","appeal to the electorate","electoral"]},{"id":807,"topic":"law","w":"ballot","ipa":"/ˈbælət/","pos":"n.","cn":"选票；投票","pun":"白了特","story":"选票上的名字看得眼都白了，特别纠结该投谁。","ex":"Citizens cast their ballots in secret to ensure the election remains free and fair.","exCn":"公民秘密投票，以确保选举保持自由公正。","col":["cast a ballot","secret ballot","ballot box"]},{"id":808,"topic":"law","w":"referendum","ipa":"/ˌrefəˈrendəm/","pos":"n.","cn":"全民公投","pun":"惹法人等","story":"refer（提交）+ endum：把大事直接提交给全民表决，惹得法人们都在等结果——公投。","ex":"The government held a referendum to decide whether the country should leave the union.","exCn":"政府举行全民公投，决定该国是否退出联盟。","col":["hold a referendum","referendum on","national referendum"]},{"id":809,"topic":"law","w":"mandate","ipa":"/ˈmændeɪt/","pos":"n./v.","cn":"授权；命令","pun":"慢待","story":"man（手）+ date（给）：选民把权力交到你手里，你却慢待百姓，授权就会被收回。","ex":"The party claimed it had a clear mandate from voters to raise taxes on the wealthy.","exCn":"该党声称已获得选民明确授权，可对富人加税。","col":["electoral mandate","have a mandate to","mandatory"]},{"id":810,"topic":"law","w":"legitimate","ipa":"/lɪˈdʒɪtɪmət/","pos":"adj.","cn":"合法的；正当的","pun":"累即体没","story":"legi（法律）+ timate：合法的事做起来累即体没关系，因为心里踏实。","ex":"Only a government elected through fair elections can be considered legitimate.","exCn":"只有通过公正选举产生的政府才能被视为合法。","col":["legitimate government","legitimate concern","legitimacy"]},{"id":811,"topic":"law","w":"sovereignty","ipa":"/ˈsɒvrənti/","pos":"n.","cn":"主权","pun":"傻富人替","story":"sovereign（君主）：主权就是国家自己说了算，别指望傻富人替你做主。","ex":"Many citizens feared that joining the treaty would undermine national sovereignty.","exCn":"许多公民担心加入该条约会损害国家主权。","col":["national sovereignty","territorial sovereignty","sovereign state"]},{"id":812,"topic":"law","w":"authority","ipa":"/ɔːˈθɒrəti/","pos":"n.","cn":"权力；当局","pun":"我硕若替","story":"author（作者）：法律的作者说了算，我硕士若想替他做主也不行，这就是权力。","ex":"Local authorities are responsible for maintaining roads and public parks.","exCn":"地方当局负责维护道路和公共公园。","col":["local authorities","exercise authority","authorise"]},{"id":813,"topic":"law","w":"regime","ipa":"/reɪˈʒiːm/","pos":"n.","cn":"政权；制度","pun":"累鸡姆","story":"reg（统治）：这个政权把老百姓累得像鸡一样，姆妈都受不了。","ex":"The old regime collapsed after years of economic decline and public unrest.","exCn":"在多年的经济衰退和公众动荡之后，旧政权垮台了。","col":["military regime","overthrow a regime","regime change"]},{"id":814,"topic":"law","w":"dictatorship","ipa":"/dɪkˈteɪtəʃɪp/","pos":"n.","cn":"独裁；独裁国家","pun":"低可忒特谁婆","story":"dictate（口授命令）+ ship：一个人口授命令全国低头听，忒特别，谁也不敢问——独裁。","ex":"The country moved from dictatorship to democracy within a single generation.","exCn":"该国在一代人的时间内从独裁走向了民主。","col":["military dictatorship","under a dictatorship","dictator"]},{"id":815,"topic":"law","w":"monarchy","ipa":"/ˈmɒnəki/","pos":"n.","cn":"君主制；君主国","pun":"摸那key","story":"mon（单一）+ archy（统治）：只有国王一个人摸得到那把 key，就是君主制。","ex":"Several European countries retain a constitutional monarchy alongside an elected parliament.","exCn":"一些欧洲国家在保留君主立宪制的同时设有民选议会。","col":["constitutional monarchy","abolish the monarchy","monarch"]},{"id":816,"topic":"law","w":"republic","ipa":"/rɪˈpʌblɪk/","pos":"n.","cn":"共和国","pun":"日趴不立刻","story":"re（事）+ public（公众）：国家是公众的事，不是某个人天天趴着不立刻起来的私产。","ex":"After the revolution, the nation declared itself a republic with an elected president.","exCn":"革命后，该国宣布成立由民选总统领导的共和国。","col":["democratic republic","the Republic of","republican"]},{"id":817,"topic":"law","w":"federal","ipa":"/ˈfedərəl/","pos":"adj.","cn":"联邦的","pun":"飞的绕","story":"联邦政府管着好多州，官员飞来飞去绕一圈才转完。","ex":"Federal and state governments often disagree over who should fund education.","exCn":"联邦政府和州政府常在谁应为教育出资上意见不一。","col":["federal government","federal law","federation"]},{"id":818,"topic":"law","w":"municipal","ipa":"/mjuːˈnɪsɪpl/","pos":"adj.","cn":"市政的；地方政府的","pun":"谬你死破","story":"市政府修路，你若不配合，路面谬你死破——这就是市政的事。","ex":"Municipal authorities are planning to expand the city's public transport network.","exCn":"市政当局正计划扩建该市的公共交通网络。","col":["municipal government","municipal services","municipality"]},{"id":819,"topic":"law","w":"jurisdiction","ipa":"/ˌdʒʊərɪsˈdɪkʃn/","pos":"n.","cn":"司法权；管辖权","pun":"猪儿死地刻甚","story":"juris（法律）+ diction（说）：法律说了算的地盘，猪儿死在哪块地就归哪里管——管辖权。","ex":"The court ruled that it had no jurisdiction over crimes committed abroad.","exCn":"法院裁定其对在国外犯下的罪行没有管辖权。","col":["have jurisdiction over","within the jurisdiction","legal jurisdiction"]},{"id":820,"topic":"law","w":"judiciary","ipa":"/dʒuˈdɪʃəri/","pos":"n.","cn":"司法部门；法官","pun":"猪迪谁儿","story":"judic（审判）：司法部门的法官盯着猪迪问是谁儿子干的，公正判案。","ex":"An independent judiciary is essential for protecting citizens from abuses of power.","exCn":"独立的司法机构对于保护公民免受权力滥用至关重要。","col":["independent judiciary","the judiciary","judge"]},{"id":821,"topic":"law","w":"judicial","ipa":"/dʒuˈdɪʃl/","pos":"adj.","cn":"司法的；法院的","pun":"猪迪手","story":"judic（审判）：司法的权力握在法官手里，猪迪也得听法院的。","ex":"The judicial system must treat every defendant equally, regardless of wealth.","exCn":"司法系统必须平等对待每位被告，无论其财富多少。","col":["judicial system","judicial review","judiciary"]},{"id":822,"topic":"law","w":"verdict","ipa":"/ˈvɜːdɪkt/","pos":"n.","cn":"裁决；判决","pun":"我地刻","story":"ver（真实）+ dict（说）：陪审团说出真相的那一刻，我地一声跪下——判决。","ex":"The jury took three days to reach a verdict in the corruption trial.","exCn":"陪审团用了三天时间才对这起腐败案作出裁决。","col":["reach a verdict","guilty verdict","deliver a verdict"]},{"id":823,"topic":"law","w":"jury","ipa":"/ˈdʒʊəri/","pos":"n.","cn":"陪审团","pun":"猪儿瑞","story":"jur（法律）：十二个普通人坐一排，猪儿瑞也在里面，决定被告有没有罪——陪审团。","ex":"Members of the jury are selected at random from the local population.","exCn":"陪审团成员从当地居民中随机挑选。","col":["trial by jury","jury service","juror"]},{"id":824,"topic":"law","w":"tribunal","ipa":"/traɪˈbjuːnl/","pos":"n.","cn":"特别法庭；裁判所","pun":"踹比有奴","story":"tribun（部落长官）：特别法庭里，被踹的一方和比他有钱的奴隶主对簿公堂。","ex":"Workers who are unfairly dismissed can take their case to an employment tribunal.","exCn":"被不公平解雇的员工可将案件提交劳资仲裁法庭。","col":["employment tribunal","international tribunal","tribunal hearing"]},{"id":825,"topic":"law","w":"prosecute","ipa":"/ˈprɒsɪkjuːt/","pos":"v.","cn":"起诉；检控","pun":"扑死Q特","story":"pro（向前）+ secute（追）：检察官一路向前追，扑死那个Q特的嫌疑人——起诉。","ex":"Companies that dump waste illegally should be prosecuted to the full extent of the law.","exCn":"非法倾倒废物的公司应依法受到最严厉的起诉。","col":["prosecute for","be prosecuted","prosecution"]},{"id":826,"topic":"law","w":"defendant","ipa":"/dɪˈfendənt/","pos":"n.","cn":"被告","pun":"底分等特","story":"defend（防守）+ ant（人）：站在被告席上防守的人，底气不足，分数等着别人打。","ex":"The defendant denied all charges and insisted he had never met the victim.","exCn":"被告否认所有指控，坚称从未见过受害者。","col":["the defendant","defendant pleads guilty","defend"]},{"id":827,"topic":"law","w":"plaintiff","ipa":"/ˈpleɪntɪf/","pos":"n.","cn":"原告","pun":"扑累提夫","story":"plaint（抱怨）：原告扑上法庭，累得提着口气讲述自己的委屈。","ex":"The plaintiff argued that the company had failed to honour the terms of the contract.","exCn":"原告辩称该公司未能履行合同条款。","col":["the plaintiff","plaintiff v. defendant","complaint"]},{"id":828,"topic":"law","w":"attorney","ipa":"/əˈtɜːni/","pos":"n.","cn":"律师；代理人","pun":"饿特腻","story":"律师为你出庭忙到饿得特别腻，还得为你据理力争。","ex":"Every citizen accused of a crime has the right to be represented by an attorney.","exCn":"每位被指控犯罪的公民都有权由律师代理。","col":["defence attorney","attorney general","power of attorney"]},{"id":829,"topic":"law","w":"testimony","ipa":"/ˈtestɪməni/","pos":"n.","cn":"证词；证言","pun":"太死体摸你","story":"test（作证）：证人说「他太死体地摸你」，这句证词让全场安静。","ex":"The witness gave detailed testimony about what she saw on the night of the robbery.","exCn":"证人就抢劫当晚所见作了详细证词。","col":["give testimony","witness testimony","testify"]},{"id":830,"topic":"law","w":"witness","ipa":"/ˈwɪtnəs/","pos":"n./v.","cn":"证人；目击","pun":"未特呢死","story":"wit（知道）+ ness：目击者什么都知道，未特别害怕，呢喃着说出真相。","ex":"Several witnesses confirmed that the car had ignored the red light.","exCn":"数名证人证实那辆车闯了红灯。","col":["eyewitness","witness statement","witness a crime"]},{"id":831,"topic":"law","w":"evidence","ipa":"/ˈevɪdəns/","pos":"n.","cn":"证据；证明","pun":"爱为等死","story":"e（出）+ vid（看）：证据就是能看得出来的东西，凶手爱为它等到死也没法否认。","ex":"There is little evidence that harsher sentences reduce the overall crime rate.","exCn":"几乎没有证据表明更严厉的刑罚能降低总体犯罪率。","col":["strong evidence","provide evidence","evident"]},{"id":832,"topic":"law","w":"convict","ipa":"/kənˈvɪkt/","pos":"v.","cn":"定罪；判有罪","pun":"啃威客特","story":"con（完全）+ vict（征服）：证据完全征服了被告，他啃着威客特饼干听宣判——定罪。","ex":"He was convicted of fraud and sentenced to five years in prison.","exCn":"他被判欺诈罪成立，获刑五年。","col":["be convicted of","convicted criminal","conviction"]},{"id":833,"topic":"law","w":"acquit","ipa":"/əˈkwɪt/","pos":"v.","cn":"宣告无罪；释放","pun":"饿快特","story":"ac + quit（脱离）：法官宣告无罪，被告饿得快特快地脱离法庭去吃饭。","ex":"The jury acquitted the accused after finding the evidence unreliable.","exCn":"陪审团认为证据不可靠，宣告被告无罪。","col":["be acquitted of","acquit on all charges","acquittal"]},{"id":834,"topic":"law","w":"sentence","ipa":"/ˈsentəns/","pos":"n./v.","cn":"判决；判刑","pun":"三疼死","story":"法官一句话判了三年，被告心里三疼死了——判刑。","ex":"The judge handed down a lengthy sentence to deter others from committing similar crimes.","exCn":"法官作出了严厉的判决，以震慑他人犯下类似罪行。","col":["prison sentence","life sentence","be sentenced to"]},{"id":835,"topic":"law","w":"imprisonment","ipa":"/ɪmˈprɪznmənt/","pos":"n.","cn":"监禁","pun":"因扑日怎门","story":"im（进）+ prison（监狱）：他因扑倒别人被关进去，天天问怎么开门——监禁。","ex":"Life imprisonment is the most severe punishment available in many countries.","exCn":"终身监禁是许多国家最严厉的刑罚。","col":["life imprisonment","sentence to imprisonment","imprison"]},{"id":836,"topic":"law","w":"custody","ipa":"/ˈkʌstədi/","pos":"n.","cn":"拘留；监护权","pun":"卡死他地","story":"警察把嫌疑人卡死在拘留室那块地里，不许离开——拘留。","ex":"The suspect was held in police custody for forty-eight hours before being charged.","exCn":"嫌疑人在被起诉前被警方拘留了四十八小时。","col":["in custody","take into custody","custody of a child"]},{"id":837,"topic":"law","w":"bail","ipa":"/beɪl/","pos":"n.","cn":"保释；保释金","pun":"呗喽","story":"交了钱就能先出来，「呗喽，先回家等开庭」——保释。","ex":"The court refused bail because the accused was considered likely to flee the country.","exCn":"法院拒绝保释，因为被告被认为很可能潜逃出境。","col":["grant bail","release on bail","bail conditions"]},{"id":838,"topic":"law","w":"appeal","ipa":"/əˈpiːl/","pos":"n./v.","cn":"上诉；呼吁","pun":"饿劈了","story":"一审输了，饿着肚子劈开卷宗再告一次——上诉。","ex":"The defendant has the right to appeal against the verdict within thirty days.","exCn":"被告有权在三十天内对判决提出上诉。","col":["lodge an appeal","appeal against","court of appeal"]},{"id":839,"topic":"law","w":"offence","ipa":"/əˈfens/","pos":"n.","cn":"违法行为；罪行","pun":"饿翻死","story":"of + fence（栅栏）：翻过法律的栅栏就是犯罪，翻得饿翻死也得受罚。","ex":"Driving without a licence is a criminal offence in most countries.","exCn":"在大多数国家，无证驾驶属于刑事犯罪。","col":["criminal offence","commit an offence","minor offence"]},{"id":840,"topic":"law","w":"offender","ipa":"/əˈfendə(r)/","pos":"n.","cn":"罪犯；违法者","pun":"饿翻的","story":"offend（冒犯）+ er（人）：翻栅栏违法的那个人，就是罪犯。","ex":"Young offenders should be offered education rather than long prison terms.","exCn":"应向少年犯提供教育而非长期监禁。","col":["young offender","repeat offender","first-time offender"]},{"id":841,"topic":"law","w":"deterrent","ipa":"/dɪˈterənt/","pos":"n.","cn":"威慑；遏制物","pun":"低太润特","story":"de（离开）+ terr（恐吓）：吓得人低头躲开，太润特了——威慑。","ex":"Many people believe that harsh sentences act as a deterrent to potential criminals.","exCn":"许多人认为严厉的刑罚对潜在罪犯起到威慑作用。","col":["act as a deterrent","effective deterrent","deter"]},{"id":842,"topic":"law","w":"parole","ipa":"/pəˈrəʊl/","pos":"n.","cn":"假释","pun":"怕肉","story":"提前出狱的人怕再吃牢饭，见了肉都不敢碰，乖乖守规矩——假释。","ex":"Prisoners who behave well may be released on parole before completing their sentence.","exCn":"表现良好的囚犯可在服完刑期前获得假释。","col":["release on parole","parole board","eligible for parole"]},{"id":843,"topic":"law","w":"comply","ipa":"/kəmˈplaɪ/","pos":"v.","cn":"遵守；服从","pun":"啃扑来","story":"com（一起）+ ply（折叠）：大家一起折叠成一样，啃着扑来的规矩——遵守。","ex":"Businesses that fail to comply with safety regulations face heavy fines.","exCn":"不遵守安全法规的企业将面临高额罚款。","col":["comply with","fail to comply","compliant"]},{"id":844,"topic":"law","w":"violate","ipa":"/ˈvaɪəleɪt/","pos":"v.","cn":"违反；侵犯","pun":"外饿累特","story":"viol（暴力）：从外面饿着累着闯进来的暴力行为，就是违反法律。","ex":"The company was found to have violated several labour laws.","exCn":"该公司被发现违反了多项劳动法。","col":["violate the law","violate rights","violation"]},{"id":845,"topic":"law","w":"breach","ipa":"/briːtʃ/","pos":"n./v.","cn":"违反；违约","pun":"不理去","story":"break（打破）的亲戚：合同摆在那儿，他不理就去干别的，破坏了约定——违约。","ex":"Sharing customer data without consent is a serious breach of privacy law.","exCn":"未经同意分享客户数据是对隐私法的严重违反。","col":["breach of contract","in breach of","breach the rules"]},{"id":846,"topic":"law","w":"abolish","ipa":"/əˈbɒlɪʃ/","pos":"v.","cn":"废除；取消","pun":"饿包里洗","story":"ab（离开）：把旧法律从饿包里掏出来洗掉，彻底废除。","ex":"Many countries have abolished the death penalty in the past fifty years.","exCn":"过去五十年里，许多国家废除了死刑。","col":["abolish slavery","abolish the death penalty","abolition"]},{"id":847,"topic":"law","w":"regulation","ipa":"/ˌreɡjuˈleɪʃn/","pos":"n.","cn":"法规；管理","pun":"瑞哥有累甚","story":"regulate（监管）+ ion：瑞哥有累甚的一堆条文要背，那就是法规。","ex":"Stricter regulations on food labelling would help consumers make healthier choices.","exCn":"更严格的食品标签法规将帮助消费者做出更健康的选择。","col":["government regulations","safety regulations","regulatory"]},{"id":848,"topic":"law","w":"restriction","ipa":"/rɪˈstrɪkʃn/","pos":"n.","cn":"限制；约束","pun":"瑞死揣可甚","story":"re + strict（严格）：规矩严得瑞死也不能揣可什么东西进来——限制。","ex":"The city introduced restrictions on car use to reduce traffic congestion.","exCn":"该市对汽车使用实施限制，以缓解交通拥堵。","col":["impose restrictions","restrictions on","restrict"]},{"id":849,"topic":"law","w":"prohibit","ipa":"/prəˈhɪbɪt/","pos":"v.","cn":"禁止","pun":"扑嘿比特","story":"pro（前）+ hibit（拿住）：警察扑上前嘿一声比特住你的手，不许干——禁止。","ex":"Smoking is prohibited in all enclosed public spaces under the new law.","exCn":"根据新法，所有封闭公共场所禁止吸烟。","col":["prohibit from","strictly prohibited","prohibition"]},{"id":850,"topic":"law","w":"permit","ipa":"/pəˈmɪt/","pos":"v./n.","cn":"允许；许可证","pun":"陪密特","story":"per（通过）+ mit（送）：官员陪着密特过审，最后一张许可证送到手——允许。","ex":"Foreign workers must obtain a permit before they are allowed to take up employment.","exCn":"外籍工人在获准就业前必须取得许可证。","col":["work permit","permit someone to","permission"]},{"id":851,"topic":"law","w":"licence","ipa":"/ˈlaɪsns/","pos":"n.","cn":"执照；许可证","pun":"来森死","story":"没执照开车被抓，来到森林深处都逃不掉，罚得你想死——执照很重要。","ex":"Businesses selling alcohol are required to hold a valid licence.","exCn":"售酒企业必须持有有效执照。","col":["driving licence","obtain a licence","license"]},{"id":852,"topic":"law","w":"statute","ipa":"/ˈstætʃuːt/","pos":"n.","cn":"成文法；法令","pun":"死达丘特","story":"stat（站立）：立在那里的白纸黑字，死也得达到，丘特也得遵守——成文法。","ex":"The right to a fair trial is protected by statute in most democratic countries.","exCn":"在大多数民主国家，公平审判的权利受到成文法保护。","col":["by statute","statute book","statutory"]},{"id":853,"topic":"law","w":"statutory","ipa":"/ˈstætʃətri/","pos":"adj.","cn":"法定的","pun":"死达丘垂","story":"statute（法令）+ ory：法令规定的东西，死也得达到，丘垂着头也得照做——法定的。","ex":"Employees are entitled to a statutory minimum of twenty days paid leave per year.","exCn":"雇员每年享有法定最低二十天带薪假。","col":["statutory rights","statutory duty","statutory requirement"]},{"id":854,"topic":"law","w":"clause","ipa":"/klɔːz/","pos":"n.","cn":"条款；从句","pun":"扣走","story":"合同里的一条条款，不注意看就把你的钱扣走了。","ex":"The contract contains a clause allowing either party to withdraw with notice.","exCn":"合同包含一项条款，允许任何一方在通知后退出。","col":["contract clause","include a clause","escape clause"]},{"id":855,"topic":"law","w":"provision","ipa":"/prəˈvɪʒn/","pos":"n.","cn":"规定；提供","pun":"扑肉威身","story":"pro（前）+ vis（看）：提前看到需要，扑上肉来威身补给，就是提供；法律里的预先安排就是规定。","ex":"The new law includes provisions to protect workers from unfair dismissal.","exCn":"新法包含保护工人免遭不公平解雇的规定。","col":["make provision for","legal provision","provide"]},{"id":856,"topic":"law","w":"lawsuit","ipa":"/ˈlɔːsuːt/","pos":"n.","cn":"诉讼；官司","pun":"捞书特","story":"law（法律）+ suit（案件）：打官司要从书里捞条文，特别费劲——诉讼。","ex":"The company faces a lawsuit from customers who claim the product was unsafe.","exCn":"该公司面临客户提起的诉讼，客户称产品不安全。","col":["file a lawsuit","face a lawsuit","lawsuit against"]},{"id":857,"topic":"law","w":"litigation","ipa":"/ˌlɪtɪˈɡeɪʃn/","pos":"n.","cn":"诉讼；打官司","pun":"离题给甚","story":"litig（争吵）：两边在法庭上吵得离题，给什么理由都不服——诉讼。","ex":"Lengthy litigation can cost both parties far more than the original dispute was worth.","exCn":"漫长的诉讼可能让双方付出远超原争议价值的代价。","col":["costly litigation","litigation process","litigate"]},{"id":858,"topic":"law","w":"sue","ipa":"/suː/","pos":"v.","cn":"起诉；控告","pun":"诉","story":"发音就是「诉」：把人告上法庭，就是起诉。","ex":"Patients who suffer harm due to medical negligence may sue the hospital.","exCn":"因医疗疏忽受到伤害的患者可以起诉医院。","col":["sue for damages","sue someone for","be sued"]},{"id":859,"topic":"law","w":"liable","ipa":"/ˈlaɪəbl/","pos":"adj.","cn":"负有法律责任的；易于","pun":"赖饿宝","story":"li（绑）+ able：责任绑在你身上赖不掉，饿了也得赔宝——负有法律责任的。","ex":"Employers are legally liable for injuries that occur in the workplace.","exCn":"雇主对工作场所发生的伤害负有法律责任。","col":["be liable for","held liable","liable to"]},{"id":860,"topic":"law","w":"negligence","ipa":"/ˈneɡlɪdʒəns/","pos":"n.","cn":"疏忽；过失","pun":"呢个里怎死","story":"neg（不）+ lig（选）：该做的事不做，「呢个人里怎么死的」，就是疏忽造成的。","ex":"The hospital was sued for negligence after a patient received the wrong medication.","exCn":"一名患者用错药后，该医院因疏忽被起诉。","col":["medical negligence","gross negligence","negligent"]},{"id":861,"topic":"law","w":"entitle","ipa":"/ɪnˈtaɪtl/","pos":"v.","cn":"使有权；给…权利","pun":"因太头","story":"en（使）+ title（头衔）：给你一个头衔，因此你太有头有脸，有权享受福利——使有权。","ex":"All citizens over eighteen are entitled to vote in national elections.","exCn":"所有十八岁以上的公民都有权在全国选举中投票。","col":["be entitled to","entitle someone to","entitlement"]},{"id":862,"topic":"law","w":"obligation","ipa":"/ˌɒblɪˈɡeɪʃn/","pos":"n.","cn":"义务；责任","pun":"哦不离给甚","story":"ob + lig（绑）：责任把你绑住，哦，不离不弃，给什么都得做——义务。","ex":"Citizens have a moral obligation to report crimes they witness.","exCn":"公民有道德义务举报他们目睹的犯罪。","col":["legal obligation","fulfil an obligation","obligatory"]},{"id":863,"topic":"law","w":"accountable","ipa":"/əˈkaʊntəbl/","pos":"adj.","cn":"负有责任的；可问责的","pun":"饿看特宝","story":"account（解释）+ able：官员必须能给出解释，饿着也看特别宝贝的账本——可问责的。","ex":"Elected officials must be held accountable for how they spend public money.","exCn":"民选官员必须对公共资金的使用负责。","col":["hold accountable","accountable to","accountability"]},{"id":864,"topic":"law","w":"corruption","ipa":"/kəˈrʌpʃn/","pos":"n.","cn":"腐败；贪污","pun":"可乱扑甚","story":"cor + rupt（破裂）：制度破裂了，官员可以乱扑什么钱都往兜里装——腐败。","ex":"Widespread corruption discourages foreign investment and slows economic growth.","exCn":"普遍的腐败阻碍外国投资并拖慢经济增长。","col":["political corruption","fight corruption","corrupt"]},{"id":865,"topic":"law","w":"bribery","ipa":"/ˈbraɪbəri/","pos":"n.","cn":"行贿；受贿","pun":"不赖被理","story":"bribe（贿赂）：塞了红包，「不赖，被理会了」，这就是行贿。","ex":"The official was arrested on charges of bribery and abuse of power.","exCn":"这名官员因受贿和滥用职权的指控被捕。","col":["bribery and corruption","accused of bribery","bribe"]},{"id":866,"topic":"law","w":"scandal","ipa":"/ˈskændl/","pos":"n.","cn":"丑闻","pun":"死看到","story":"丑闻曝光后，全国人民死死盯着看到底怎么回事。","ex":"The minister resigned following a scandal involving misuse of public funds.","exCn":"这名部长在一起滥用公款的丑闻后辞职。","col":["political scandal","corruption scandal","scandalous"]},{"id":867,"topic":"law","w":"impartial","ipa":"/ɪmˈpɑːʃl/","pos":"adj.","cn":"公正的；不偏不倚的","pun":"因怕手","story":"im（不）+ partial（偏袒的）：法官因怕偏袒，手里天平端得稳稳的——公正的。","ex":"Judges must remain impartial regardless of their personal opinions.","exCn":"法官无论个人观点如何都必须保持公正。","col":["impartial judge","impartial advice","impartiality"]},{"id":868,"topic":"law","w":"privatisation","ipa":"/ˌpraɪvətaɪˈzeɪʃn/","pos":"n.","cn":"私有化","pun":"扑赖我太贼甚","story":"private（私人的）+ isation：国企卖给私人，有人扑上来赖我太贼什么的——私有化。","ex":"The privatisation of the railways led to higher fares for many passengers.","exCn":"铁路私有化导致许多乘客票价上涨。","col":["privatisation of","oppose privatisation","privatise"]},{"id":869,"topic":"law","w":"nationalise","ipa":"/ˈnæʃnəlaɪz/","pos":"v.","cn":"国有化","pun":"奶什那来死","story":"nation（国家）+ alise：把公司收归国家，老板哭喊「奶奶，什么都那样来死了」——国有化。","ex":"Some argue that the government should nationalise essential services such as water.","exCn":"有人认为政府应将水务等基本服务国有化。","col":["nationalise the railways","nationalised industry","nationalisation"]},{"id":870,"topic":"law","w":"policy","ipa":"/ˈpɒləsi/","pos":"n.","cn":"政策；方针","pun":"跑了西","story":"polis（城邦）：城邦管理的方针一变，人们就跑了西边去——政策。","ex":"The government's housing policy aims to make homes more affordable for young families.","exCn":"政府的住房政策旨在让年轻家庭更能负担得起住房。","col":["government policy","foreign policy","policymaker"]},{"id":871,"topic":"law","w":"reform","ipa":"/rɪˈfɔːm/","pos":"n./v.","cn":"改革","pun":"日佛","story":"re（再）+ form（形成）：制度重新成形，日日拜佛都不如改一改——改革。","ex":"Electoral reform is needed to ensure that every vote carries equal weight.","exCn":"需要进行选举改革，以确保每张选票分量相等。","col":["economic reform","carry out reforms","reformer"]},{"id":872,"topic":"law","w":"implement","ipa":"/ˈɪmplɪment/","pos":"v.","cn":"实施；执行","pun":"因扑了闷","story":"im（进）+ ple（填满）：把政策填进现实里，官员因扑上去干活闷头执行——实施。","ex":"The policy was well designed but poorly implemented at the local level.","exCn":"该政策设计良好，但在地方层面执行不力。","col":["implement a policy","fully implement","implementation"]},{"id":873,"topic":"law","w":"intervene","ipa":"/ˌɪntəˈviːn/","pos":"v.","cn":"干预；介入","pun":"因特喂呢","story":"inter（之间）+ vene（来）：政府因特意插到市场中间来喂饭，这就是干预。","ex":"Governments should intervene when the free market fails to protect vulnerable citizens.","exCn":"当自由市场无法保护弱势公民时，政府应当干预。","col":["intervene in","military intervene","intervention"]},{"id":874,"topic":"law","w":"governance","ipa":"/ˈɡʌvənəns/","pos":"n.","cn":"治理；管理","pun":"嘎我能死","story":"govern（统治）+ ance：治理国家嘎嘎难，我能干到死——治理。","ex":"Good governance requires transparency, accountability and the rule of law.","exCn":"良好治理需要透明、问责和法治。","col":["good governance","corporate governance","govern"]},{"id":875,"topic":"law","w":"administration","ipa":"/ədˌmɪnɪˈstreɪʃn/","pos":"n.","cn":"行政；政府","pun":"饿的米你死追甚","story":"ad + minister（服务）：行政部门为民服务，饿了给米，你死追着问什么都答——行政。","ex":"The new administration promised to cut waste and improve public services.","exCn":"新一届政府承诺减少浪费并改善公共服务。","col":["public administration","the current administration","administrative"]},{"id":876,"topic":"law","w":"ministry","ipa":"/ˈmɪnɪstri/","pos":"n.","cn":"（政府的）部","pun":"米你死追","story":"minister（部长）：部里的人为了一粒米追着你死磕——政府的部。","ex":"The Ministry of Education announced plans to reduce class sizes in primary schools.","exCn":"教育部宣布计划缩小小学班级规模。","col":["Ministry of Health","government ministry","minister"]},{"id":877,"topic":"law","w":"cabinet","ipa":"/ˈkæbɪnət/","pos":"n.","cn":"内阁","pun":"开逼呢特","story":"cabin（小屋）：首相和部长们关在小屋里开会，逼着做决定，呢特别机密——内阁。","ex":"The prime minister reshuffled the cabinet after several ministers resigned.","exCn":"几位部长辞职后，首相改组了内阁。","col":["cabinet minister","cabinet meeting","cabinet reshuffle"]},{"id":878,"topic":"law","w":"civil servant","ipa":"/ˌsɪvl ˈsɜːvənt/","pos":"n.","cn":"公务员","pun":"死我色闻特","story":"civil（公民的）+ servant（仆人）：为公民服务的仆人，死我也不能出错，色闻特别敏感——公务员。","ex":"Civil servants are expected to remain politically neutral while carrying out their duties.","exCn":"公务员在履行职责时应保持政治中立。","col":["senior civil servant","civil service","public servant"]},{"id":879,"topic":"law","w":"official","ipa":"/əˈfɪʃl/","pos":"n./adj.","cn":"官员；官方的","pun":"饿飞手","story":"office（办公室）：办公室里的人饿着也不能飞，手里全是公文——官员。","ex":"Senior officials were criticised for failing to respond to the flooding quickly.","exCn":"高级官员因未能迅速应对洪灾而受到批评。","col":["government official","official statement","officially"]},{"id":880,"topic":"law","w":"diplomat","ipa":"/ˈdɪpləmæt/","pos":"n.","cn":"外交官","pun":"低扑了马特","story":"diploma（文书）：拿着国书出使的人，低头扑了马特意行礼——外交官。","ex":"Diplomats from both countries met to discuss the border dispute.","exCn":"两国外交官会面讨论边界争端。","col":["senior diplomat","career diplomat","diplomatic"]},{"id":881,"topic":"law","w":"diplomacy","ipa":"/dɪˈpləʊməsi/","pos":"n.","cn":"外交；外交手腕","pun":"低扑漏没西","story":"diplomat（外交官）+ cy：低头扑上去谈，绝不漏出没西的底牌——外交手腕。","ex":"Diplomacy rather than military force should be used to resolve international conflicts.","exCn":"应以外交而非军事手段解决国际冲突。","col":["international diplomacy","use diplomacy","diplomatic relations"]},{"id":882,"topic":"law","w":"alliance","ipa":"/əˈlaɪəns/","pos":"n.","cn":"联盟；同盟","pun":"饿赖恩死","story":"ally（结盟）+ ance：结了盟，饿了就赖在盟友家，恩情到死——联盟。","ex":"The two parties formed an alliance to secure a majority in parliament.","exCn":"两党结成联盟，以在议会中获得多数席位。","col":["form an alliance","military alliance","ally"]},{"id":883,"topic":"law","w":"bilateral","ipa":"/ˌbaɪˈlætərəl/","pos":"adj.","cn":"双边的","pun":"白拉特肉","story":"bi（二）+ lateral（边的）：两边各拉一块特好的肉交换——双边的。","ex":"The two countries signed a bilateral agreement on trade and investment.","exCn":"两国签署了关于贸易和投资的双边协定。","col":["bilateral agreement","bilateral relations","multilateral"]},{"id":884,"topic":"law","w":"ambassador","ipa":"/æmˈbæsədə(r)/","pos":"n.","cn":"大使","pun":"俺爸色的","story":"俺爸是驻外大使，穿着最出色的衣服代表国家。","ex":"The ambassador was summoned to explain her government's decision.","exCn":"这位大使被召见，要求解释其政府的决定。","col":["ambassador to","appoint an ambassador","embassy"]},{"id":885,"topic":"law","w":"embassy","ipa":"/ˈembəsi/","pos":"n.","cn":"大使馆","pun":"俺爸洗","story":"俺爸在大使馆里当差，天天洗车迎接外宾。","ex":"Citizens stranded abroad were advised to contact their nearest embassy.","exCn":"滞留海外的公民被建议联系最近的大使馆。","col":["British embassy","embassy staff","ambassador"]},{"id":886,"topic":"law","w":"asylum","ipa":"/əˈsaɪləm/","pos":"n.","cn":"庇护；避难","pun":"饿塞冷","story":"a（无）+ syl（抓捕）：饿着塞进冷冷的船逃到别国，请求不被抓——庇护。","ex":"Thousands of people seek asylum in Europe every year to escape persecution.","exCn":"每年有数千人为逃避迫害而在欧洲寻求庇护。","col":["seek asylum","asylum seeker","grant asylum"]},{"id":887,"topic":"law","w":"refugee","ipa":"/ˌrefjuˈdʒiː/","pos":"n.","cn":"难民","pun":"惹夫鸡","story":"refuge（避难所）：战争惹得丈夫抱着鸡逃到别国——难民。","ex":"Wealthy nations have a moral duty to accept a fair share of refugees.","exCn":"富裕国家有道义责任接纳公平份额的难民。","col":["refugee camp","refugee crisis","refuge"]},{"id":888,"topic":"law","w":"citizenship","ipa":"/ˈsɪtɪzənʃɪp/","pos":"n.","cn":"公民身份；公民权","pun":"西提怎谁婆","story":"citizen（公民）+ ship：城里人身份，「西提怎么是谁的老婆」都得登记——公民身份。","ex":"Applicants for citizenship must pass a test on the country's history and laws.","exCn":"申请公民身份者须通过关于该国历史和法律的考试。","col":["apply for citizenship","dual citizenship","citizen"]},{"id":889,"topic":"law","w":"civic","ipa":"/ˈsɪvɪk/","pos":"adj.","cn":"公民的；市政的","pun":"西为课","story":"civ（城市）：市民都得上西边那堂为市民开的课——公民的。","ex":"Schools should teach civic responsibility so that young people become active citizens.","exCn":"学校应教授公民责任，使年轻人成为积极公民。","col":["civic duty","civic responsibility","civic pride"]},{"id":890,"topic":"law","w":"liberty","ipa":"/ˈlɪbəti/","pos":"n.","cn":"自由","pun":"里伯替","story":"liber（自由）：里面的伯伯终于替大家争到了自由。","ex":"Restricting the press threatens the liberty of all citizens.","exCn":"限制新闻自由威胁到所有公民的自由。","col":["civil liberty","individual liberty","liberate"]},{"id":891,"topic":"law","w":"suffrage","ipa":"/ˈsʌfrɪdʒ/","pos":"n.","cn":"选举权；投票权","pun":"傻夫瑞纸","story":"傻夫也能拿到一张瑞士纸——选票，人人都有投票权。","ex":"Universal suffrage was only achieved in many countries in the twentieth century.","exCn":"许多国家直到二十世纪才实现普选权。","col":["universal suffrage","women's suffrage","suffragette"]},{"id":892,"topic":"law","w":"justice","ipa":"/ˈdʒʌstɪs/","pos":"n.","cn":"正义；司法","pun":"渣死替死","story":"just（公正）：渣男被判死，替受害者讨回公道——正义。","ex":"The justice system must ensure that the poor have the same access to lawyers as the rich.","exCn":"司法系统必须确保穷人与富人获得同等的律师服务。","col":["social justice","bring to justice","justice system"]},{"id":893,"topic":"law","w":"oppression","ipa":"/əˈpreʃn/","pos":"n.","cn":"压迫；压制","pun":"饿扑来甚","story":"op + press（压）：把人往下压，饿得扑上来什么都吃——压迫。","ex":"Many refugees flee political oppression in their home countries.","exCn":"许多难民逃离本国的政治压迫。","col":["political oppression","freedom from oppression","oppress"]},{"id":894,"topic":"law","w":"protest","ipa":"/ˈprəʊtest/","pos":"n./v.","cn":"抗议","pun":"扑肉太死","story":"pro（前）+ test（作证）：冲到前面作证反对，扑肉太死板的政策——抗议。","ex":"Thousands took part in a peaceful protest against the new education cuts.","exCn":"数千人参加了反对新教育削减的和平抗议。","col":["peaceful protest","protest against","protester"]},{"id":895,"topic":"law","w":"demonstration","ipa":"/ˌdemənˈstreɪʃn/","pos":"n.","cn":"示威游行；展示","pun":"呆闷死追甚","story":"demonstrate（展示）：把不满展示在街上，呆闷的人也死追着问要什么——示威。","ex":"The demonstration outside parliament attracted more than ten thousand people.","exCn":"议会外的示威吸引了一万多人参加。","col":["mass demonstration","hold a demonstration","demonstrator"]},{"id":896,"topic":"law","w":"riot","ipa":"/ˈraɪət/","pos":"n.","cn":"暴乱；骚乱","pun":"来饿特","story":"人群来了，饿得特别狠，砸店抢东西——暴乱。","ex":"Riots broke out in several cities after the controversial court ruling.","exCn":"有争议的法院裁决后，多个城市爆发骚乱。","col":["riots break out","riot police","rioter"]},{"id":897,"topic":"law","w":"petition","ipa":"/pəˈtɪʃn/","pos":"n./v.","cn":"请愿；请愿书","pun":"批提甚","story":"pet（寻求）：一张纸上签满名字，交给官员批一批提什么要求——请愿书。","ex":"More than a million people signed a petition calling for the law to be repealed.","exCn":"超过一百万人签署请愿书，要求废除该法律。","col":["sign a petition","petition for","online petition"]},{"id":898,"topic":"law","w":"lobby","ipa":"/ˈlɒbi/","pos":"v./n.","cn":"游说；游说团体","pun":"捞比","story":"在议会大厅（lobby）里拦住议员，捞点好处比谁都快——游说。","ex":"Tobacco companies spend millions lobbying politicians to block stricter regulations.","exCn":"烟草公司花费数百万游说政客阻止更严格的监管。","col":["lobby for","lobby group","lobbyist"]},{"id":899,"topic":"law","w":"advocate","ipa":"/ˈædvəkeɪt/","pos":"v./n.","cn":"提倡；拥护者","pun":"爱的我K特","story":"ad + voc（声音）：为一件事大声说话，「爱的我K歌特别响」——提倡。","ex":"Many economists advocate higher taxes on carbon to reduce fossil fuel use.","exCn":"许多经济学家提倡对碳征收更高税费，以减少化石燃料使用。","col":["advocate for","strong advocate of","advocacy"]},{"id":900,"topic":"law","w":"opposition","ipa":"/ˌɒpəˈzɪʃn/","pos":"n.","cn":"反对；反对党","pun":"哦跑贼甚","story":"op（对）+ pos（放）：站在对面的人，哦，跑去指着贼说什么都不对——反对党。","ex":"The opposition criticised the government for failing to control inflation.","exCn":"反对党批评政府未能控制通货膨胀。","col":["opposition party","strong opposition to","oppose"]},{"id":901,"topic":"law","w":"coalition","ipa":"/ˌkəʊəˈlɪʃn/","pos":"n.","cn":"联合政府；联盟","pun":"抠饿立甚","story":"co（一起）+ alit（生长）：几个小党抠在一起长成大党，饿着也要立什么政府——联合政府。","ex":"No party won a majority, so a coalition government was formed.","exCn":"没有政党赢得多数席位，因此组建了联合政府。","col":["coalition government","form a coalition","coalition partner"]},{"id":902,"topic":"law","w":"veto","ipa":"/ˈviːtəʊ/","pos":"n./v.","cn":"否决；否决权","pun":"喂头","story":"拉丁语「我禁止」：总统一喂头（摇头），法案就被否决了。","ex":"The president used his veto to block the bill passed by parliament.","exCn":"总统动用否决权阻止了议会通过的法案。","col":["veto power","exercise a veto","veto a bill"]},{"id":903,"topic":"law","w":"legislature","ipa":"/ˈledʒɪsleɪtʃə(r)/","pos":"n.","cn":"立法机关","pun":"累计死累车","story":"legislate（立法）+ ure：立法的机关，议员累计熬到死累得像车一样——立法机关。","ex":"The legislature rejected the proposal by a narrow margin.","exCn":"立法机关以微弱多数否决了该提案。","col":["national legislature","state legislature","legislative"]},{"id":904,"topic":"law","w":"senate","ipa":"/ˈsenət/","pos":"n.","cn":"参议院","pun":"三呢特","story":"sen（老）：一群资深的老议员，三三两两呢喃着特别慢——参议院。","ex":"The bill must pass the senate before it can be signed into law.","exCn":"该法案必须通过参议院才能签署成为法律。","col":["the Senate","senate vote","senator"]},{"id":905,"topic":"law","w":"propaganda","ipa":"/ˌprɒpəˈɡændə/","pos":"n.","cn":"宣传（贬义）","pun":"扑扑干哒","story":"propagate（传播）：政府扑扑地干哒干哒往外撒消息，只报喜不报忧——宣传。","ex":"State propaganda was used to convince citizens that the war was necessary.","exCn":"国家宣传被用来说服公民战争是必要的。","col":["political propaganda","propaganda campaign","spread propaganda"]},{"id":906,"topic":"law","w":"ideology","ipa":"/ˌaɪdiˈɒlədʒi/","pos":"n.","cn":"意识形态；思想体系","pun":"爱地哦了机","story":"idea（想法）+ logy（学说）：一整套想法，爱这块地哦得像机器一样——意识形态。","ex":"Political parties are increasingly driven by ideology rather than practical solutions.","exCn":"政党越来越受意识形态而非务实方案驱动。","col":["political ideology","dominant ideology","ideological"]},{"id":907,"topic":"law","w":"conservative","ipa":"/kənˈsɜːvətɪv/","pos":"adj.","cn":"保守的；保守派的","pun":"啃色我踢夫","story":"conserve（保存）：什么都想保存不变，啃老本，谁改就踢谁——保守的。","ex":"Conservative voters tend to favour lower taxes and less government spending.","exCn":"保守派选民倾向于支持低税收和较少的政府开支。","col":["conservative party","conservative views","conservatism"]},{"id":908,"topic":"law","w":"liberal","ipa":"/ˈlɪbərəl/","pos":"adj.","cn":"自由主义的；开明的","pun":"里伯肉","story":"liber（自由）：里面的伯伯思想开明，什么肉都让你吃——自由主义的。","ex":"Liberal policies typically support individual freedom and social equality.","exCn":"自由主义政策通常支持个人自由和社会平等。","col":["liberal democracy","liberal values","liberalism"]},{"id":909,"topic":"law","w":"radical","ipa":"/ˈrædɪkl/","pos":"adj.","cn":"激进的；根本的","pun":"瑞地口","story":"radic（根）：从根上挖起，瑞地口都翻开——根本的改变，也就显得激进。","ex":"The party proposed radical changes to the tax system.","exCn":"该党提出对税收制度进行激进改革。","col":["radical reform","radical change","radically"]},{"id":910,"topic":"law","w":"red tape","ipa":"/ˌred ˈteɪp/","pos":"n.","cn":"繁文缛节；官僚程序","pun":"瑞的胎铺","story":"过去官府用红带子捆文件，瑞的胎铺办个证要拆一百条红带子——繁文缛节。","ex":"Entrepreneurs complain that red tape makes it difficult to start a business.","exCn":"创业者抱怨繁文缛节使创业变得困难。","col":["cut red tape","bureaucratic red tape","tangled in red tape"]},{"id":911,"topic":"law","w":"decentralise","ipa":"/ˌdiːˈsentrəlaɪz/","pos":"v.","cn":"分散；下放权力","pun":"低森揣来死","story":"de（去除）+ central（中央）：中央低头把权力揣出来分给地方，森林各处都能来做主——下放权力。","ex":"Many countries have decentralised power to give local communities more control.","exCn":"许多国家已将权力下放，给予地方社区更多控制权。","col":["decentralise power","decentralised system","decentralisation"]},{"id":912,"topic":"law","w":"unanimous","ipa":"/juˈnænɪməs/","pos":"adj.","cn":"一致同意的","pun":"有男你摸死","story":"un（一）+ anim（心）：所有人一条心，「有男你摸死也同意」——一致的。","ex":"The committee reached a unanimous decision to approve the new policy.","exCn":"委员会一致决定批准新政策。","col":["unanimous decision","unanimous vote","unanimously"]},{"id":913,"topic":"law","w":"oversee","ipa":"/ˌəʊvəˈsiː/","pos":"v.","cn":"监督；监管","pun":"欧我西","story":"over（在上）+ see（看）：站在上面看，欧洲我也看到西边——全程监管。","ex":"A new agency was created to oversee the spending of public funds.","exCn":"设立了一个新机构来监督公共资金的使用。","col":["oversee the process","oversee a project","oversight"]},{"id":914,"topic":"law","w":"mandatory","ipa":"/ˈmændətəri/","pos":"adj.","cn":"强制的；法定的","pun":"慢的特瑞","story":"mandate（命令）+ ory：命令下来，动作慢的特别容易被瑞（骂）——强制的。","ex":"Voting is mandatory in Australia, and those who fail to vote may be fined.","exCn":"在澳大利亚投票是强制性的，不投票者可能被罚款。","col":["mandatory sentence","make something mandatory","mandate"]},{"id":915,"topic":"law","w":"warrant","ipa":"/ˈwɒrənt/","pos":"n./v.","cn":"搜查令；使有正当理由","pun":"我人特","story":"警察举着一张纸「我，人特别正当地进来搜」——搜查令。","ex":"Police must obtain a warrant before searching a private home.","exCn":"警察在搜查私人住宅前必须获得搜查令。","col":["search warrant","arrest warrant","warrant further investigation"]},{"id":916,"topic":"law","w":"fraud","ipa":"/frɔːd/","pos":"n.","cn":"欺诈；骗子","pun":"付肉的","story":"说好付钱买肉的，结果付的是假钞——欺诈。","ex":"Online fraud has increased sharply as more people shop on the internet.","exCn":"随着更多人网购，网络欺诈急剧增加。","col":["commit fraud","tax fraud","fraudulent"]},{"id":917,"topic":"law","w":"ratify","ipa":"/ˈrætɪfaɪ/","pos":"v.","cn":"正式批准；签署生效","pun":"瑞替发","story":"rat（确定）+ ify：议会替条约拍板发文，瑞士也正式批准——批准生效。","ex":"The treaty will only take effect once it has been ratified by all member states.","exCn":"该条约只有在所有成员国批准后才会生效。","col":["ratify a treaty","formally ratify","ratification"]},{"id":918,"topic":"law","w":"repeal","ipa":"/rɪˈpiːl/","pos":"v.","cn":"废除（法律）","pun":"日皮了","story":"re（回）+ peal（呼喊）：把法律喊回来撕了，「日子皮了，这法不要了」——废除。","ex":"Campaigners are calling on the government to repeal the outdated law.","exCn":"活动人士呼吁政府废除这项过时的法律。","col":["repeal a law","repeal legislation","repeal of"]},{"id":919,"topic":"law","w":"tyranny","ipa":"/ˈtɪrəni/","pos":"n.","cn":"暴政；专制","pun":"踢弱你","story":"tyrant（暴君）：暴君专挑弱的踢，「踢弱的你」——暴政。","ex":"A free press is one of the strongest safeguards against tyranny.","exCn":"新闻自由是防止暴政最有力的保障之一。","col":["live under tyranny","tyranny of the majority","tyrant"]},{"id":920,"topic":"crime","w":"felony","ipa":"/ˈfeləni/","pos":"n.","cn":"重罪","pun":"废了你","story":"法官敲锤：这是重罪，判下来直接「废了你」的后半辈子。","ex":"In many countries a felony conviction can prevent a person from voting for life.","exCn":"在许多国家，重罪定罪可能使人终身丧失投票权。","col":["commit a felony","felony charge","felon"]},{"id":921,"topic":"crime","w":"misdemeanour","ipa":"/ˌmɪsdɪˈmiːnə(r)/","pos":"n.","cn":"轻罪","pun":"密室迷你","story":"mis-（坏）+ demeanour（举止）：在「密室」里搞个「迷你」坏举动，只是轻罪，不算大事。","ex":"Shoplifting is generally treated as a misdemeanour rather than a serious crime.","exCn":"入店行窃通常被视为轻罪而非重罪。","col":["minor misdemeanour","charged with a misdemeanour","misdemeanour offence"]},{"id":922,"topic":"crime","w":"theft","ipa":"/θeft/","pos":"n.","cn":"盗窃","pun":"谁付特","story":"超市里东西不见了，老板喊「谁付特」价？没人付——这是盗窃。","ex":"The rise in bicycle theft has prompted the council to install more secure parking.","exCn":"自行车盗窃案上升促使市政委员会安装更安全的停车设施。","col":["petty theft","car theft","thief"]},{"id":923,"topic":"crime","w":"burglary","ipa":"/ˈbɜːɡləri/","pos":"n.","cn":"入室盗窃","pun":"伯格拉锁","story":"「伯格」半夜「拉锁」撬门进屋偷东西，这就是入室盗窃。","ex":"Installing an alarm system has been shown to reduce the risk of burglary significantly.","exCn":"研究表明安装报警系统能显著降低入室盗窃的风险。","col":["commit burglary","burglary rate","burglar"]},{"id":924,"topic":"crime","w":"robbery","ipa":"/ˈrɒbəri/","pos":"n.","cn":"抢劫","pun":"绕不理","story":"劫匪拦路，你「绕」着走他也「不理」你，直接抢——这就是抢劫。","ex":"Armed robbery carries a much heavier sentence than theft because it involves violence.","exCn":"持械抢劫因涉及暴力，刑罚远重于盗窃。","col":["armed robbery","bank robbery","robber"]},{"id":925,"topic":"crime","w":"shoplifting","ipa":"/ˈʃɒplɪftɪŋ/","pos":"n.","cn":"入店行窃","pun":"少扑里付停","story":"shop（商店）+ lift（拿起）：在店里「拿起」东西「付停」——不付钱就走，就是入店行窃。","ex":"Retailers lose billions of pounds every year as a result of shoplifting.","exCn":"零售商每年因入店行窃损失数十亿英镑。","col":["shoplifting offence","caught shoplifting","shoplifter"]},{"id":926,"topic":"crime","w":"vandalism","ipa":"/ˈvændəlɪzəm/","pos":"n.","cn":"故意破坏公物","pun":"玩得离谱","story":"几个少年砸路灯、划车，「玩得离谱」——这就是故意破坏公物。","ex":"Acts of vandalism in public parks cost local governments a great deal of money.","exCn":"公园里的破坏行为让地方政府花费巨大。","col":["acts of vandalism","vandalise","vandal"]},{"id":927,"topic":"crime","w":"arson","ipa":"/ˈɑːsn/","pos":"n.","cn":"纵火","pun":"啊烧","story":"「啊——烧」起来了！有人故意点火烧房子，这叫纵火。","ex":"Police confirmed that the fire at the warehouse was a case of arson.","exCn":"警方证实仓库火灾是一起纵火案。","col":["arson attack","commit arson","arsonist"]},{"id":928,"topic":"crime","w":"forgery","ipa":"/ˈfɔːdʒəri/","pos":"n.","cn":"伪造；赝品","pun":"仿这里","story":"造假者拿着名画说「仿这里」，一笔一笔照抄——这幅赝品就是伪造品。","ex":"The museum discovered that several paintings in its collection were forgeries.","exCn":"博物馆发现其藏品中有几幅画是赝品。","col":["forgery of documents","art forgery","forge"]},{"id":929,"topic":"crime","w":"embezzlement","ipa":"/ɪmˈbezlmənt/","pos":"n.","cn":"挪用公款","pun":"因被这门","story":"会计「因被这门」（钱柜的门）诱惑，把公司的钱悄悄搬回家——挪用公款。","ex":"The accountant was jailed for the embezzlement of company funds over a decade.","exCn":"这名会计因十年间挪用公司资金而入狱。","col":["embezzlement of funds","charged with embezzlement","embezzle"]},{"id":930,"topic":"crime","w":"smuggling","ipa":"/ˈsmʌɡlɪŋ/","pos":"n.","cn":"走私","pun":"死马个领","story":"「死马个领」子里藏着毒品过海关，这就是走私。","ex":"Drug smuggling across the border has increased despite tighter customs checks.","exCn":"尽管海关检查更严，跨境毒品走私仍在增加。","col":["drug smuggling","people smuggling","smuggler"]},{"id":931,"topic":"crime","w":"trafficking","ipa":"/ˈtræfɪkɪŋ/","pos":"n.","cn":"非法贩运","pun":"车飞进","story":"traffic 本是交通，非法「车飞进」边境运人运毒，就成了贩运。","ex":"Human trafficking remains a serious problem that requires international cooperation.","exCn":"人口贩运仍是需要国际合作解决的严重问题。","col":["human trafficking","drug trafficking","trafficker"]},{"id":932,"topic":"crime","w":"kidnapping","ipa":"/ˈkɪdnæpɪŋ/","pos":"n.","cn":"绑架","pun":"kid 拿平","story":"kid（小孩）被人「拿」走了，家长哭得「平」不了心——绑架。","ex":"Kidnapping for ransom has become a lucrative business for organised criminal groups.","exCn":"绑架勒索已成为有组织犯罪集团的赚钱生意。","col":["kidnapping case","kidnap","kidnapper"]},{"id":933,"topic":"crime","w":"abduction","ipa":"/æbˈdʌkʃn/","pos":"n.","cn":"诱拐；劫持","pun":"爱不打醒","story":"ab-（离开）+ duct（引导）：把人「引」走，家人「爱不打醒」地哭——诱拐。","ex":"The abduction of children by strangers is rare but attracts huge media attention.","exCn":"陌生人诱拐儿童虽罕见，却引来媒体高度关注。","col":["child abduction","abduct","abductor"]},{"id":934,"topic":"crime","w":"assault","ipa":"/əˈsɔːlt/","pos":"n./v.","cn":"袭击；殴打","pun":"饿手","story":"「饿手」的人在街头突然动手打人，这就是袭击。","ex":"Cases of assault tend to rise on weekends when alcohol consumption increases.","exCn":"周末饮酒增多时，袭击案件往往上升。","col":["physical assault","assault charge","sexual assault"]},{"id":935,"topic":"crime","w":"homicide","ipa":"/ˈhɒmɪsaɪd/","pos":"n.","cn":"杀人（罪）","pun":"哄迷杀","story":"homi（人）+ cide（杀）：把人「哄迷」了再「杀」，这是杀人罪。","ex":"The city recorded its lowest homicide rate in thirty years last year.","exCn":"该市去年录得三十年来最低的杀人率。","col":["homicide rate","homicide detective","commit homicide"]},{"id":936,"topic":"crime","w":"manslaughter","ipa":"/ˈmænslɔːtə(r)/","pos":"n.","cn":"过失杀人","pun":"慢死漏的","story":"man（人）+ slaughter（宰杀）：司机疏忽，「慢死漏的」刹车害死人，不是故意——过失杀人。","ex":"The driver was convicted of manslaughter rather than murder because the death was unintentional.","exCn":"由于死亡并非故意，司机被判过失杀人而非谋杀。","col":["convicted of manslaughter","involuntary manslaughter","manslaughter charge"]},{"id":937,"topic":"crime","w":"blackmail","ipa":"/ˈblækmeɪl/","pos":"n./v.","cn":"敲诈；勒索","pun":"黑妹儿","story":"black（黑）+ mail（信）：「黑妹儿」寄来一封黑信：不给钱就曝光你——勒索。","ex":"Victims of blackmail are often reluctant to report the crime to the police.","exCn":"勒索的受害者往往不愿向警方报案。","col":["blackmail victim","emotional blackmail","blackmailer"]},{"id":938,"topic":"crime","w":"extortion","ipa":"/ɪkˈstɔːʃn/","pos":"n.","cn":"敲诈勒索","pun":"一磕死扭神","story":"ex-（出）+ tort（扭）：「一磕死扭」，把钱硬从人手里扭出来——敲诈勒索。","ex":"Small businesses in the area have been subjected to extortion by local gangs.","exCn":"该地区的小企业遭到本地帮派的敲诈勒索。","col":["extortion racket","extort money","extortionate"]},{"id":939,"topic":"crime","w":"stalking","ipa":"/ˈstɔːkɪŋ/","pos":"n.","cn":"跟踪骚扰","pun":"死盯","story":"有人在你身后「死盯」着不放，走到哪跟到哪——跟踪骚扰。","ex":"Stalking was only recognised as a specific criminal offence in the UK in 2012.","exCn":"英国直到2012年才将跟踪骚扰列为具体刑事罪行。","col":["stalking victim","stalk","stalker"]},{"id":940,"topic":"crime","w":"hooliganism","ipa":"/ˈhuːlɪɡənɪzəm/","pos":"n.","cn":"流氓行为","pun":"胡里跟你砸","story":"球赛输了，「胡里跟你砸」椅子砸车——足球流氓行为。","ex":"Football hooliganism has declined since stadiums introduced stricter security measures.","exCn":"自体育场引入更严格的安保措施以来，足球流氓行为有所减少。","col":["football hooliganism","hooligan","acts of hooliganism"]},{"id":941,"topic":"crime","w":"pickpocket","ipa":"/ˈpɪkpɒkɪt/","pos":"n.","cn":"扒手","pun":"劈扑刻","story":"pick（掏）+ pocket（口袋）：「劈扑」一下，一「刻」间钱包没了——扒手。","ex":"Tourists are frequently warned about pickpockets operating in crowded areas.","exCn":"游客常被提醒注意拥挤场所活动的扒手。","col":["beware of pickpockets","pickpocketing","pickpocket gang"]},{"id":942,"topic":"crime","w":"mugging","ipa":"/ˈmʌɡɪŋ/","pos":"n.","cn":"街头抢劫","pun":"马跟","story":"黑「马跟」在你身后，突然把你按住抢钱——街头抢劫。","ex":"Muggings often occur in poorly lit streets late at night.","exCn":"街头抢劫常发生在深夜照明不佳的街道上。","col":["mugging victim","mug","mugger"]},{"id":943,"topic":"crime","w":"looting","ipa":"/ˈluːtɪŋ/","pos":"n.","cn":"趁乱抢劫","pun":"撸挺","story":"骚乱时商店玻璃被砸，人群冲进去「撸挺」多东西——趁乱抢劫。","ex":"Widespread looting broke out in the city after the power failure.","exCn":"停电后该市爆发了大范围的趁乱抢劫。","col":["looting and rioting","loot","looter"]},{"id":944,"topic":"crime","w":"piracy","ipa":"/ˈpaɪrəsi/","pos":"n.","cn":"盗版；海盗行为","pun":"拍了谁","story":"电影院里偷偷「拍了谁」的电影传网上——盗版；海上抢船的是海盗。","ex":"Software piracy costs the technology industry billions of dollars annually.","exCn":"软件盗版每年使科技行业损失数十亿美元。","col":["online piracy","software piracy","pirate"]},{"id":945,"topic":"crime","w":"counterfeit","ipa":"/ˈkaʊntəfɪt/","pos":"adj./n./v.","cn":"伪造的；假货","pun":"看它费","story":"counter（相反）+ feit（做）：做得跟真的相反，「看它费」眼也看不出——假货。","ex":"Counterfeit goods are often sold online at prices that seem too good to be true.","exCn":"假货常在网上以看似好得离谱的价格出售。","col":["counterfeit goods","counterfeit money","counterfeiter"]},{"id":946,"topic":"crime","w":"money laundering","ipa":"/ˈmʌni ˌlɔːndərɪŋ/","pos":"phr.","cn":"洗钱","pun":"忙你浪的领","story":"launder 是洗衣服，黑钱脏，「忙你浪的领」子一起洗白——洗钱。","ex":"Banks are legally required to report suspicious transactions to combat money laundering.","exCn":"银行依法必须报告可疑交易以打击洗钱。","col":["money laundering scheme","launder money","anti-money laundering"]},{"id":947,"topic":"crime","w":"tax evasion","ipa":"/tæks ɪˈveɪʒn/","pos":"phr.","cn":"逃税","pun":"太可诶围省","story":"e-（出）+ vade（走）：「太可诶围省」钱了，从税网里溜出去——逃税。","ex":"Tax evasion by multinational companies deprives governments of vital public revenue.","exCn":"跨国公司逃税使政府失去了重要的公共收入。","col":["tax evasion charges","evade tax","tax evader"]},{"id":948,"topic":"crime","w":"identity theft","ipa":"/aɪˈdentəti θeft/","pos":"phr.","cn":"身份盗用","pun":"爱登踢谁付特","story":"骗子「爱登」你的账号，用你的身份「踢谁付特」——身份盗用。","ex":"Identity theft has soared as more personal information is stored online.","exCn":"随着更多个人信息存储在网上，身份盗用急剧增加。","col":["victim of identity theft","identity fraud","steal someone's identity"]},{"id":949,"topic":"crime","w":"hacking","ipa":"/ˈhækɪŋ/","pos":"n.","cn":"黑客攻击","pun":"骇进","story":"黑客「骇进」别人的电脑系统，这就是黑客攻击。","ex":"Hacking into government databases poses a serious threat to national security.","exCn":"侵入政府数据库对国家安全构成严重威胁。","col":["computer hacking","hack into","hacker"]},{"id":950,"topic":"crime","w":"phishing","ipa":"/ˈfɪʃɪŋ/","pos":"n.","cn":"网络钓鱼","pun":"钓鱼型","story":"和 fishing 同音：骗子发假邮件当鱼饵，「钓鱼型」骗密码——网络钓鱼。","ex":"Phishing emails are designed to trick users into revealing their passwords.","exCn":"网络钓鱼邮件旨在诱骗用户泄露密码。","col":["phishing email","phishing scam","phishing attack"]},{"id":951,"topic":"crime","w":"terrorism","ipa":"/ˈterərɪzəm/","pos":"n.","cn":"恐怖主义","pun":"太热热怎","story":"terror 是恐惧：炸弹「太热热怎」么办，人人恐惧——恐怖主义。","ex":"Governments have expanded police powers in response to the threat of terrorism.","exCn":"各国政府为应对恐怖主义威胁扩大了警察权力。","col":["act of terrorism","counter-terrorism","terrorist"]},{"id":952,"topic":"crime","w":"delinquency","ipa":"/dɪˈlɪŋkwənsi/","pos":"n.","cn":"（青少年）违法行为","pun":"地铃抠玩死","story":"少年在「地铃」（地铁铃）上「抠玩死」了设备，被带走——青少年违法行为。","ex":"Juvenile delinquency is often linked to poor parenting and lack of education.","exCn":"青少年违法行为常与教养不良和缺乏教育有关。","col":["juvenile delinquency","delinquent behaviour","delinquent"]},{"id":953,"topic":"crime","w":"culprit","ipa":"/ˈkʌlprɪt/","pos":"n.","cn":"罪犯；肇事者","pun":"扣扑瑞特","story":"警察把「扑」上来的那个人「扣」住，喊「瑞特」就是他——罪犯抓到了。","ex":"Police are still searching for the culprit behind the series of arson attacks.","exCn":"警方仍在搜寻系列纵火案的肇事者。","col":["catch the culprit","the main culprit","identify the culprit"]},{"id":954,"topic":"crime","w":"perpetrator","ipa":"/ˈpɜːpətreɪtə(r)/","pos":"n.","cn":"作案者；犯罪者","pun":"破坡追他","story":"案子一发，警察「破坡追他」，追的就是作案者。","ex":"The perpetrators of the attack were arrested within forty-eight hours.","exCn":"袭击的作案者在四十八小时内被捕。","col":["perpetrator of a crime","alleged perpetrator","perpetrate"]},{"id":955,"topic":"crime","w":"accomplice","ipa":"/əˈkʌmplɪs/","pos":"n.","cn":"同谋；帮凶","pun":"饿康普利死","story":"ac-（去）+ com（一起）+ plic（折叠）：「饿康普利死」跟主犯折叠在一起干坏事——帮凶。","ex":"The accomplice received a lighter sentence for cooperating with the police.","exCn":"这名帮凶因配合警方而获得较轻的判决。","col":["accomplice to murder","act as an accomplice","accomplice in the robbery"]},{"id":956,"topic":"crime","w":"suspect","ipa":"/ˈsʌspekt/","pos":"n./v.","cn":"嫌疑人；怀疑","pun":"杀死派克特","story":"sus-（下）+ spect（看）：警察低头打量「杀死派克特」的那人——嫌疑人。","ex":"The suspect was released without charge due to a lack of evidence.","exCn":"由于缺乏证据，嫌疑人未被起诉即获释。","col":["prime suspect","suspect in a case","suspicious"]},{"id":957,"topic":"crime","w":"victim","ipa":"/ˈvɪktɪm/","pos":"n.","cn":"受害者","pun":"喂可听","story":"「喂，可听」见我哭吗？被抢的受害者在街角求救。","ex":"Victims of violent crime often suffer psychological trauma for years afterwards.","exCn":"暴力犯罪的受害者常在事后多年承受心理创伤。","col":["crime victim","fall victim to","victimise"]},{"id":958,"topic":"crime","w":"gang","ipa":"/ɡæŋ/","pos":"n.","cn":"帮派","pun":"干","story":"一群人喊着「干」就上，这就是帮派。","ex":"Youth gangs are responsible for a large proportion of street crime in the area.","exCn":"青年帮派是该地区大部分街头犯罪的元凶。","col":["gang violence","street gang","gang member"]},{"id":959,"topic":"crime","w":"vigilante","ipa":"/ˌvɪdʒɪˈlænti/","pos":"n.","cn":"私自执法者","pun":"未经蓝袋","story":"「未经」警察（蓝袋制服）允许，自己抓坏人——私自执法者。","ex":"Vigilante groups may deter crime but often undermine the rule of law.","exCn":"私自执法团体或能震慑犯罪，却常常破坏法治。","col":["vigilante justice","vigilante group","vigilantism"]},{"id":960,"topic":"crime","w":"detective","ipa":"/dɪˈtektɪv/","pos":"n.","cn":"侦探","pun":"地铁克提夫","story":"de-（去除）+ tect（遮盖）：「地铁」里「克提夫」揭开真相的盖子——侦探。","ex":"The detective spent months piecing together the evidence before making an arrest.","exCn":"侦探花了数月拼凑证据才实施逮捕。","col":["private detective","detective work","detect"]},{"id":961,"topic":"crime","w":"constable","ipa":"/ˈkʌnstəbl/","pos":"n.","cn":"（英）警员","pun":"看死特薄","story":"英国街头警员「看死特薄」的小偷不放——警员。","ex":"A police constable is usually the first officer to arrive at a crime scene.","exCn":"警员通常是最先到达犯罪现场的警官。","col":["police constable","chief constable","constabulary"]},{"id":962,"topic":"crime","w":"patrol","ipa":"/pəˈtrəʊl/","pos":"n./v.","cn":"巡逻","pun":"扒兜","story":"警察夜里「扒兜」巡逻，看谁鬼鬼祟祟——巡逻。","ex":"Increasing police patrols in high-crime areas can reassure local residents.","exCn":"在高犯罪率地区增加警察巡逻可让居民安心。","col":["police patrol","on patrol","patrol car"]},{"id":963,"topic":"crime","w":"investigate","ipa":"/ɪnˈvestɪɡeɪt/","pos":"v.","cn":"调查","pun":"因外死体给它","story":"「因外死体给它」——院外有尸体，警察赶来调查。","ex":"Police are investigating a series of burglaries in the neighbourhood.","exCn":"警方正在调查该社区的一系列入室盗窃案。","col":["investigate a crime","criminal investigation","investigator"]},{"id":964,"topic":"crime","w":"interrogate","ipa":"/ɪnˈterəɡeɪt/","pos":"v.","cn":"审讯；盘问","pun":"因太热给它","story":"审讯室灯「因太热给它」照得嫌疑人直冒汗，问到招供——审讯。","ex":"Suspects must be informed of their rights before they are interrogated.","exCn":"嫌疑人在被审讯前必须被告知其权利。","col":["interrogate a suspect","police interrogation","interrogation room"]},{"id":965,"topic":"crime","w":"forensic","ipa":"/fəˈrensɪk/","pos":"adj.","cn":"法医的；法庭的","pun":"佛人洗客","story":"「佛人洗客」——法医像佛一样冷静地清洗尸体找线索——法医的。","ex":"Forensic science has revolutionised the way crimes are investigated.","exCn":"法医科学彻底改变了犯罪调查方式。","col":["forensic evidence","forensic scientist","forensic examination"]},{"id":966,"topic":"crime","w":"fingerprint","ipa":"/ˈfɪŋɡəprɪnt/","pos":"n.","cn":"指纹","pun":"分个扑印特","story":"finger（手指）+ print（印记）：手指「分个扑印特」在杯子上——指纹。","ex":"Fingerprints found at the scene matched those of a known criminal.","exCn":"现场发现的指纹与一名已知罪犯吻合。","col":["take fingerprints","fingerprint evidence","fingerprint database"]},{"id":967,"topic":"crime","w":"clue","ipa":"/kluː/","pos":"n.","cn":"线索","pun":"克路","story":"侦探沿着「克路」上掉的纽扣一路追——线索。","ex":"The detective found a vital clue hidden in the victim's diary.","exCn":"侦探在受害者日记里发现了关键线索。","col":["vital clue","search for clues","clueless"]},{"id":968,"topic":"crime","w":"arrest","ipa":"/əˈrest/","pos":"v./n.","cn":"逮捕","pun":"饿累死它","story":"追了三条街，「饿累死它」终于把小偷按倒——逮捕。","ex":"The police made several arrests following the riot.","exCn":"骚乱后警方逮捕了数人。","col":["under arrest","make an arrest","arrest warrant"]},{"id":969,"topic":"crime","w":"detain","ipa":"/dɪˈteɪn/","pos":"v.","cn":"拘留","pun":"地毯","story":"de-（下）+ tain（持）：把嫌疑人按在「地毯」上不许走——拘留。","ex":"Suspects cannot be detained for more than 24 hours without being charged.","exCn":"嫌疑人未被起诉不得拘留超过24小时。","col":["detain a suspect","detained without trial","detention"]},{"id":970,"topic":"crime","w":"raid","ipa":"/reɪd/","pos":"n./v.","cn":"突击搜查","pun":"瑞的","story":"凌晨警察冲进「瑞的」窝点，抓了一屋子人——突击搜查。","ex":"A dawn raid on the warehouse uncovered a large quantity of stolen goods.","exCn":"对仓库的凌晨突击搜查查获大量赃物。","col":["police raid","dawn raid","raid a house"]},{"id":971,"topic":"crime","w":"seize","ipa":"/siːz/","pos":"v.","cn":"查获；抓住","pun":"洗字","story":"警察一把「洗字」（洗掉字迹）的假钞全抓在手里——查获。","ex":"Customs officers seized over a tonne of cocaine at the port.","exCn":"海关人员在港口查获一吨多可卡因。","col":["seize drugs","seize assets","seizure"]},{"id":972,"topic":"crime","w":"confiscate","ipa":"/ˈkɒnfɪskeɪt/","pos":"v.","cn":"没收","pun":"看废死盖它","story":"con-（全部）+ fisc（国库）：老师「看废死盖它」，手机全没收进国库——没收。","ex":"The court ordered that the criminal's assets be confiscated.","exCn":"法院下令没收该罪犯的资产。","col":["confiscate property","confiscated goods","confiscation"]},{"id":973,"topic":"crime","w":"apprehend","ipa":"/ˌæprɪˈhend/","pos":"v.","cn":"逮捕；理解","pun":"啊扑你hand","story":"ap-（去）+ prehend（抓）：「啊扑你 hand」——扑上去抓住你的手——逮捕。","ex":"The suspect was apprehended while trying to cross the border.","exCn":"嫌疑人在企图越境时被捕。","col":["apprehend a suspect","apprehension","apprehensive"]},{"id":974,"topic":"crime","w":"handcuff","ipa":"/ˈhændkʌf/","pos":"v./n.","cn":"给……戴手铐；手铐","pun":"hand 卡夫","story":"hand（手）+ cuff（袖口）：把「hand 卡」进铁「夫」环里——手铐。","ex":"The officer handcuffed the suspect and led him to the police car.","exCn":"警官给嫌疑人戴上手铐并带上警车。","col":["in handcuffs","handcuffed to","put handcuffs on"]},{"id":975,"topic":"crime","w":"charge","ipa":"/tʃɑːdʒ/","pos":"v./n.","cn":"控告；指控","pun":"查即","story":"警察「查即」证据确凿，当场控告——指控。","ex":"He was charged with fraud after a two-year investigation.","exCn":"经过两年调查，他被控欺诈。","col":["charge someone with","face charges","drop the charges"]},{"id":976,"topic":"crime","w":"allege","ipa":"/əˈledʒ/","pos":"v.","cn":"（无证据地）指称","pun":"饿累几","story":"「饿累几」天没吃饭的人说是被老板克扣，但还没证据——指称。","ex":"The report alleges that the police used excessive force during the arrest.","exCn":"报告指称警方在逮捕时使用了过度武力。","col":["alleged offence","allegedly","allegation"]},{"id":977,"topic":"crime","w":"accuse","ipa":"/əˈkjuːz/","pos":"v.","cn":"控告；指责","pun":"饿扣子","story":"ac-（向）+ cuse（原因）：「饿扣子」——他饿了扣走我的饭，我指着他控告——指控。","ex":"She was accused of stealing money from her employer.","exCn":"她被控从雇主那里偷钱。","col":["accuse someone of","the accused","accusation"]},{"id":978,"topic":"crime","w":"indict","ipa":"/ɪnˈdaɪt/","pos":"v.","cn":"正式起诉","pun":"因带它","story":"c 不发音！大陪审团「因带它」去法庭，正式起诉。","ex":"The former minister was indicted on charges of corruption and abuse of power.","exCn":"这位前部长被以腐败和滥用职权罪正式起诉。","col":["indict on charges","indictment","indicted for murder"]},{"id":979,"topic":"crime","w":"plead","ipa":"/pliːd/","pos":"v.","cn":"辩护；认罪或不认罪","pun":"扑里的","story":"被告「扑里的」跪到法官面前：我认罪——辩护表态。","ex":"The defendant pleaded guilty to reduce his sentence.","exCn":"被告认罪以减轻刑罚。","col":["plead guilty","plead not guilty","plea bargain"]},{"id":980,"topic":"crime","w":"confess","ipa":"/kənˈfes/","pos":"v.","cn":"坦白；供认","pun":"啃废丝","story":"con-（完全）+ fess（说）：嫌疑人「啃废丝」般抖着全说了——供认。","ex":"After hours of questioning, the suspect confessed to the burglary.","exCn":"经过数小时讯问，嫌疑人供认了入室盗窃。","col":["confess to a crime","confession","confess guilt"]},{"id":981,"topic":"crime","w":"deny","ipa":"/dɪˈnaɪ/","pos":"v.","cn":"否认","pun":"地奶","story":"「地奶」（地上的奶）是谁打翻的？小孩摇头——否认。","ex":"The defendant denied all the charges brought against him.","exCn":"被告否认对他提出的所有指控。","col":["deny the charges","deny any involvement","denial"]},{"id":982,"topic":"crime","w":"alibi","ipa":"/ˈæləbaɪ/","pos":"n.","cn":"不在场证明","pun":"爱了拜","story":"案发时我在庙里「爱了拜」佛，有和尚作证——不在场证明。","ex":"The suspect had a solid alibi for the night of the robbery.","exCn":"嫌疑人对抢劫当晚有可靠的不在场证明。","col":["solid alibi","provide an alibi","false alibi"]},{"id":983,"topic":"crime","w":"motive","ipa":"/ˈməʊtɪv/","pos":"n.","cn":"动机","pun":"某踢","story":"「某」人「踢」了一脚，为什么踢？背后有动机。","ex":"Detectives struggled to establish a motive for the killing.","exCn":"侦探难以确定杀人动机。","col":["motive for the crime","ulterior motive","motivate"]},{"id":984,"topic":"crime","w":"premeditated","ipa":"/ˌpriːˈmedɪteɪtɪd/","pos":"adj.","cn":"预谋的","pun":"扑里没的太","story":"pre-（先）+ meditate（思考）：「扑里没的太」早就想好了再动手——预谋的。","ex":"Premeditated murder is punished more severely than crimes of passion.","exCn":"预谋杀人比激情犯罪受到更严厉的惩罚。","col":["premeditated murder","premeditated attack","premeditation"]},{"id":985,"topic":"crime","w":"intent","ipa":"/ɪnˈtent/","pos":"n.","cn":"意图；故意","pun":"因疼特","story":"「因疼特」意打人，就是有伤人意图——故意。","ex":"To prove murder, the prosecution must show intent to kill.","exCn":"要证明谋杀，控方必须证明杀人意图。","col":["criminal intent","with intent to","intentional"]},{"id":986,"topic":"crime","w":"fugitive","ipa":"/ˈfjuːdʒətɪv/","pos":"n.","cn":"逃犯","pun":"服绝体夫","story":"fug（逃）：「服绝体夫」——他绝不服判，整个身体跑了——逃犯。","ex":"The fugitive was finally captured after ten years on the run.","exCn":"这名逃犯在逃亡十年后终于落网。","col":["fugitive from justice","wanted fugitive","on the run"]},{"id":987,"topic":"crime","w":"conspiracy","ipa":"/kənˈspɪrəsi/","pos":"n.","cn":"阴谋；共谋","pun":"啃死屁热死","story":"con-（一起）+ spir（呼吸）：几个人凑一起「啃死屁热死」地密谋——共谋。","ex":"Three men were convicted of conspiracy to commit armed robbery.","exCn":"三名男子因共谋持械抢劫被定罪。","col":["conspiracy to commit","criminal conspiracy","conspire"]},{"id":988,"topic":"crime","w":"guilty","ipa":"/ˈɡɪlti/","pos":"adj.","cn":"有罪的；内疚的","pun":"给儿踢","story":"「给儿踢」了一脚，他低下头——有罪的、内疚的。","ex":"The accused was found guilty of fraud and embezzlement.","exCn":"被告被判欺诈和挪用公款罪成立。","col":["find guilty","plead guilty","guilt"]},{"id":989,"topic":"crime","w":"innocent","ipa":"/ˈɪnəsnt/","pos":"adj.","cn":"无罪的；天真的","pun":"一呢森特","story":"in-（不）+ noc（伤害）：「一呢森特」——他一根毛都没伤害过谁——无罪的。","ex":"Everyone is presumed innocent until proven guilty in a court of law.","exCn":"在法庭证明有罪之前，人人都被推定无罪。","col":["presumed innocent","innocent victim","innocence"]},{"id":990,"topic":"crime","w":"prosecutor","ipa":"/ˈprɒsɪkjuːtə(r)/","pos":"n.","cn":"检察官；公诉人","pun":"扑肉死可求特","story":"法庭上「扑肉死可求特」步步紧追的那位——检察官。","ex":"The prosecutor argued that the defendant had planned the attack for months.","exCn":"检察官称被告策划该袭击已有数月。","col":["public prosecutor","chief prosecutor","prosecution"]},{"id":991,"topic":"crime","w":"barrister","ipa":"/ˈbærɪstə(r)/","pos":"n.","cn":"（英）出庭律师","pun":"白瑞死特","story":"英国律师戴白假发，「白瑞死特」地在法庭辩论——出庭律师。","ex":"In England, only a barrister may represent a client in the higher courts.","exCn":"在英格兰，只有出庭律师可在高等法院代理当事人。","col":["defence barrister","instruct a barrister","barrister and solicitor"]},{"id":992,"topic":"crime","w":"testify","ipa":"/ˈtestɪfaɪ/","pos":"v.","cn":"作证","pun":"太死抵赖","story":"证人上台：「太死抵赖」了，我亲眼看见他动手——作证。","ex":"Several employees testified against the company director during the trial.","exCn":"审判期间，几名员工出庭指证公司董事。","col":["testify against","testify in court","testify under oath"]},{"id":993,"topic":"crime","w":"oath","ipa":"/əʊθ/","pos":"n.","cn":"誓言；宣誓","pun":"欧丝","story":"证人手按圣经，「欧丝」一声举手发誓说真话——宣誓。","ex":"Witnesses must take an oath to tell the truth before giving evidence.","exCn":"证人作证前必须宣誓说真话。","col":["take an oath","under oath","swear an oath"]},{"id":994,"topic":"crime","w":"perjury","ipa":"/ˈpɜːdʒəri/","pos":"n.","cn":"伪证罪","pun":"泼这里","story":"per-（坏）+ jur（誓）：宣了誓还「泼这里」满口谎话——伪证罪。","ex":"Lying under oath constitutes perjury, which is itself a serious crime.","exCn":"宣誓后说谎构成伪证罪，本身就是重罪。","col":["commit perjury","charged with perjury","perjure oneself"]},{"id":995,"topic":"crime","w":"overturn","ipa":"/ˌəʊvəˈtɜːn/","pos":"v.","cn":"推翻（判决）","pun":"欧我疼","story":"over（翻过）+ turn（转）：上诉法院把原判「欧我疼」地翻个底朝天——推翻。","ex":"The appeal court overturned the conviction after new evidence emerged.","exCn":"新证据出现后，上诉法院推翻了定罪。","col":["overturn a conviction","overturn a verdict","overturn a decision"]},{"id":996,"topic":"crime","w":"infringe","ipa":"/ɪnˈfrɪndʒ/","pos":"v.","cn":"侵犯（权利）","pun":"因富人挤","story":"in-（进）+ fringe（边缘）：「因富人挤」进了别人的边界——侵犯。","ex":"Downloading films illegally infringes the copyright of their creators.","exCn":"非法下载电影侵犯了创作者的版权。","col":["infringe copyright","infringe on rights","infringement"]},{"id":997,"topic":"crime","w":"harsh","ipa":"/hɑːʃ/","pos":"adj.","cn":"严厉的；苛刻的","pun":"哈许","story":"法官冷冷「哈许」一声，判了二十年——严厉的。","ex":"Some countries impose harsh penalties even for minor drug offences.","exCn":"有些国家即使对轻微毒品罪也处以严厉刑罚。","col":["harsh punishment","harsh sentence","harshly"]},{"id":998,"topic":"crime","w":"fine","ipa":"/faɪn/","pos":"n./v.","cn":"罚款","pun":"罚银","story":"闯红灯被「罚银」两百块——罚款。","ex":"Drivers caught using mobile phones face a fine of up to £1,000.","exCn":"被抓到使用手机的司机面临最高一千英镑罚款。","col":["pay a fine","heavy fine","fined for"]},{"id":999,"topic":"crime","w":"community service","ipa":"/kəˈmjuːnəti ˈsɜːvɪs/","pos":"phr.","cn":"社区服务（刑罚）","pun":"可谬你踢 service","story":"你「可谬你踢」坏了公物？那就罚你去社区扫地——社区服务。","ex":"Community service allows minor offenders to repay their debt to society.","exCn":"社区服务让轻罪犯得以回报社会。","col":["sentenced to community service","community service order","hours of community service"]},{"id":1000,"topic":"crime","w":"deter","ipa":"/dɪˈtɜː(r)/","pos":"v.","cn":"威慑；阻止","pun":"地特","story":"看到「地特」警的警车，小偷吓得转身走——威慑。","ex":"Harsher sentences do not necessarily deter people from committing crimes.","exCn":"更严厉的判决不一定能阻止人们犯罪。","col":["deter crime","deter from","deterrence"]},{"id":1001,"topic":"crime","w":"capital punishment","ipa":"/ˌkæpɪtl ˈpʌnɪʃmənt/","pos":"phr.","cn":"死刑","pun":"开屁头 punishment","story":"capital 本意「头」：砍头的惩罚——「开屁头」——死刑。","ex":"Capital punishment has been abolished in most European countries.","exCn":"大多数欧洲国家已废除死刑。","col":["abolish capital punishment","support capital punishment","capital offence"]},{"id":1002,"topic":"crime","w":"death penalty","ipa":"/ˈdeθ ˌpenəlti/","pos":"phr.","cn":"死刑","pun":"呆死盆儿踢","story":"最重的处罚：「呆死盆儿踢」——直接判死——死刑。","ex":"Opponents of the death penalty argue that innocent people may be executed.","exCn":"反对死刑者认为无辜者可能被处决。","col":["face the death penalty","impose the death penalty","death row"]},{"id":1003,"topic":"crime","w":"pardon","ipa":"/ˈpɑːdn/","pos":"v./n.","cn":"赦免","pun":"怕等","story":"囚犯「怕等」不到那天，总统一纸令下免了他的罪——赦免。","ex":"The president granted a pardon to several political prisoners.","exCn":"总统赦免了几名政治犯。","col":["grant a pardon","presidential pardon","pardon a criminal"]},{"id":1004,"topic":"crime","w":"amnesty","ipa":"/ˈæmnəsti/","pos":"n.","cn":"大赦；特赦","pun":"俺没死踢","story":"a-（无）+ mnes（记忆）：政府说「俺没死踢」——过去的事忘掉，一律不追究——大赦。","ex":"The government declared an amnesty for anyone who handed in illegal weapons.","exCn":"政府宣布对上交非法武器者一律赦免。","col":["declare an amnesty","general amnesty","amnesty for"]},{"id":1005,"topic":"crime","w":"imprison","ipa":"/ɪmˈprɪzn/","pos":"v.","cn":"监禁；关押","pun":"因扑理证","story":"im-（进）+ prison（监狱）：「因扑理证」据确凿，扑进牢房——监禁。","ex":"Imprisoning drug addicts rarely addresses the root cause of their behaviour.","exCn":"监禁吸毒者很少能解决其行为的根本原因。","col":["be imprisoned for","imprisonment","life imprisonment"]},{"id":1006,"topic":"crime","w":"incarcerate","ipa":"/ɪnˈkɑːsəreɪt/","pos":"v.","cn":"监禁","pun":"因卡色瑞特","story":"in-（进）+ carcer（牢笼）：「因卡色瑞特」被卡进铁笼子——监禁。","ex":"The United States incarcerates more people per capita than any other nation.","exCn":"美国人均监禁人数超过任何其他国家。","col":["incarcerated for","mass incarceration","incarceration rate"]},{"id":1007,"topic":"crime","w":"inmate","ipa":"/ˈɪnmeɪt/","pos":"n.","cn":"囚犯；被收容者","pun":"因妹特","story":"in（里面）+ mate（伙伴）：牢里的「因妹特」别难过，大家都是里面的伙伴——囚犯。","ex":"Overcrowding means that many inmates share cells designed for one person.","exCn":"监狱过度拥挤意味着许多囚犯共住单人牢房。","col":["prison inmate","former inmate","fellow inmate"]},{"id":1008,"topic":"crime","w":"warden","ipa":"/ˈwɔːdn/","pos":"n.","cn":"监狱长；看守","pun":"我等","story":"「我等」在门口守着，谁也别想跑——监狱长、看守。","ex":"The prison warden introduced education programmes to reduce violence among inmates.","exCn":"监狱长引入教育项目以减少囚犯间的暴力。","col":["prison warden","traffic warden","warden of the prison"]},{"id":1009,"topic":"crime","w":"confinement","ipa":"/kənˈfaɪnmənt/","pos":"n.","cn":"监禁；禁闭","pun":"啃饭闷特","story":"con-（全）+ fine（边界）：关在小屋里「啃饭闷特」死了——禁闭。","ex":"Solitary confinement has been criticised as a form of psychological torture.","exCn":"单独禁闭被批评为一种心理折磨。","col":["solitary confinement","in confinement","confine"]},{"id":1010,"topic":"crime","w":"reintegrate","ipa":"/ˌriːˈɪntɪɡreɪt/","pos":"v.","cn":"使重新融入社会","pun":"瑞因特格瑞特","story":"re-（再）+ integrate（融合）：出狱后「瑞因特格瑞特」重新融回社会——重新融入。","ex":"Support services help former prisoners reintegrate into society after release.","exCn":"支持服务帮助刑满释放者重新融入社会。","col":["reintegrate into society","reintegration","reintegrate offenders"]},{"id":1011,"topic":"crime","w":"reoffend","ipa":"/ˌriːəˈfend/","pos":"v.","cn":"再次犯罪","pun":"瑞饿疯的","story":"re-（再）+ offend（犯罪）：「瑞饿疯的」出狱又饿疯，再次偷抢——再犯。","ex":"Around half of all released prisoners reoffend within a year.","exCn":"约半数获释囚犯在一年内再次犯罪。","col":["reoffend within a year","likely to reoffend","reoffending rate"]},{"id":1012,"topic":"crime","w":"recidivism","ipa":"/rɪˈsɪdɪvɪzəm/","pos":"n.","cn":"累犯；再犯率","pun":"瑞洗地为怎","story":"re-（回）+ cid（落）：「瑞洗地为怎」么又落回老路了——累犯。","ex":"Education in prisons has been shown to reduce recidivism significantly.","exCn":"监狱教育已被证明能显著降低再犯率。","col":["recidivism rate","reduce recidivism","recidivist"]},{"id":1013,"topic":"crime","w":"remorse","ipa":"/rɪˈmɔːs/","pos":"n.","cn":"悔恨；自责","pun":"瑞摸死","story":"re-（反复）+ mors（咬）：良心「瑞摸死」地反复啃咬他——悔恨。","ex":"The judge noted that the defendant had shown no remorse for his actions.","exCn":"法官指出被告对其行为毫无悔意。","col":["show remorse","genuine remorse","remorseful"]},{"id":1014,"topic":"crime","w":"repent","ipa":"/rɪˈpent/","pos":"v.","cn":"悔改；忏悔","pun":"瑞喷特","story":"「瑞喷特」——他哭着喷出一大堆忏悔话——悔改。","ex":"Offenders who genuinely repent are less likely to commit further crimes.","exCn":"真心悔改的罪犯不太可能再次犯罪。","col":["repent of","repentance","repentant"]},{"id":1015,"topic":"crime","w":"juvenile","ipa":"/ˈdʒuːvənaɪl/","pos":"adj./n.","cn":"青少年的；未成年人","pun":"猪喂奶哦","story":"「猪喂奶哦」——还在喝奶的小猪——未成年的。","ex":"Juvenile offenders should be kept separate from adult prisoners.","exCn":"未成年罪犯应与成年囚犯分开关押。","col":["juvenile crime","juvenile court","juvenile detention"]},{"id":1016,"topic":"crime","w":"peer pressure","ipa":"/ˈpɪə ˌpreʃə(r)/","pos":"phr.","cn":"同伴压力","pun":"皮儿扑来射","story":"peer 是同龄人：一群「皮儿扑来射」你——不抽烟就不带你玩——同伴压力。","ex":"Peer pressure is a major factor driving teenagers into gang activity.","exCn":"同伴压力是促使青少年加入帮派的主要因素。","col":["succumb to peer pressure","under peer pressure","resist peer pressure"]},{"id":1017,"topic":"crime","w":"upbringing","ipa":"/ˈʌpbrɪŋɪŋ/","pos":"n.","cn":"教养；养育","pun":"阿婆不领","story":"up（起来）+ bring（带）：「阿婆不领」，孩子没人带大——教养。","ex":"A stable upbringing reduces the likelihood of children becoming involved in crime.","exCn":"稳定的教养减少了孩子卷入犯罪的可能性。","col":["strict upbringing","poor upbringing","bring up"]},{"id":1018,"topic":"crime","w":"crackdown","ipa":"/ˈkrækdaʊn/","pos":"n.","cn":"严厉打击","pun":"揣可当","story":"crack（砸）+ down（下）：警察「揣可当」一脚踹开门砸下去——严打。","ex":"The government launched a crackdown on drug dealing in the city centre.","exCn":"政府在市中心发起了打击毒品交易的严打行动。","col":["crackdown on crime","launch a crackdown","crack down on"]},{"id":1019,"topic":"crime","w":"marginalised","ipa":"/ˈmɑːdʒɪnəlaɪzd/","pos":"adj.","cn":"被边缘化的","pun":"马金那来着","story":"margin 是页边：「马金那来着」——被挤到书页边缘，没人理——被边缘化的。","ex":"Marginalised communities often have less trust in the police.","exCn":"被边缘化的群体往往对警察缺乏信任。","col":["marginalised groups","socially marginalised","marginalise"]},{"id":1020,"topic":"crime","w":"impunity","ipa":"/ɪmˈpjuːnəti/","pos":"n.","cn":"免受惩罚","pun":"因票你踢","story":"im-（无）+ pun（罚）：「因票你踢」——有免罪票，踢人也不受罚——免受惩罚。","ex":"Powerful officials often commit crimes with impunity in corrupt states.","exCn":"在腐败国家，权贵官员常犯罪而不受惩罚。","col":["with impunity","act with impunity","culture of impunity"]},{"id":1021,"topic":"crime","w":"retribution","ipa":"/ˌretrɪˈbjuːʃn/","pos":"n.","cn":"报应；惩罚","pun":"瑞出不游神","story":"re-（回）+ tribut（给）：「瑞出不游神」——你做的坏事神会还给你——报应。","ex":"Some argue that punishment should be about rehabilitation rather than retribution.","exCn":"有人认为惩罚应着眼于改造而非报应。","col":["seek retribution","retribution for","retributive justice"]},{"id":1022,"topic":"crime","w":"restorative justice","ipa":"/rɪˈstɒrətɪv ˈdʒʌstɪs/","pos":"phr.","cn":"恢复性司法","pun":"瑞死拓儿踢夫 justice","story":"restore 是修复：罪犯当面向受害者道歉赔偿，把「瑞死拓儿踢夫」伤口修复——恢复性司法。","ex":"Restorative justice brings offenders face to face with the victims of their crimes.","exCn":"恢复性司法让罪犯与受害者面对面。","col":["restorative justice programme","practise restorative justice","restorative approach"]},{"id":1023,"topic":"crime","w":"restitution","ipa":"/ˌrestɪˈtjuːʃn/","pos":"n.","cn":"归还；赔偿","pun":"瑞死踢丢神","story":"re-（回）+ stitut（放）：「瑞死踢丢神」踢丢的东西必须放回原处——归还赔偿。","ex":"The court ordered the thief to make full restitution to his victims.","exCn":"法院命令小偷向受害者全额赔偿。","col":["make restitution","restitution to","full restitution"]},{"id":1024,"topic":"crime","w":"safeguard","ipa":"/ˈseɪfɡɑːd/","pos":"v./n.","cn":"保护；保障措施","pun":"塞夫尬的","story":"safe（安全）+ guard（守卫）：「塞夫尬的」——把守卫塞在门口再尴尬也得站——保护。","ex":"New laws were passed to safeguard children from online predators.","exCn":"通过新法以保护儿童免受网络侵害者伤害。","col":["safeguard against","safeguard the rights","legal safeguards"]},{"id":1025,"topic":"crime","w":"neighbourhood watch","ipa":"/ˈneɪbəhʊd wɒtʃ/","pos":"phr.","cn":"邻里守望","pun":"内伯忽的 watch","story":"「内伯忽的 watch」——内伯（邻居）忽然拿着 watch 盯着街上——邻里守望。","ex":"Neighbourhood watch schemes encourage residents to report suspicious activity.","exCn":"邻里守望计划鼓励居民举报可疑活动。","col":["neighbourhood watch scheme","join the neighbourhood watch","community policing"]},{"id":1026,"topic":"crime","w":"curfew","ipa":"/ˈkɜːfjuː/","pos":"n.","cn":"宵禁","pun":"可否","story":"晚上十点后「可否」出门？不可以——宵禁。","ex":"A curfew was imposed on teenagers in the area after a series of violent incidents.","exCn":"一系列暴力事件后，该地区对青少年实施宵禁。","col":["impose a curfew","break the curfew","under curfew"]},{"id":1027,"topic":"crime","w":"illicit","ipa":"/ɪˈlɪsɪt/","pos":"adj.","cn":"非法的；违禁的","pun":"一立死特","story":"il-（不）+ licit（合法）：「一立死特」——货一立在街上就被抓——非法的。","ex":"The illicit drug trade generates billions of dollars for criminal networks.","exCn":"非法毒品交易为犯罪网络创造数十亿美元。","col":["illicit drugs","illicit trade","illicit activities"]},{"id":1028,"topic":"crime","w":"unlawful","ipa":"/ʌnˈlɔːfl/","pos":"adj.","cn":"非法的","pun":"俺捞否","story":"un-（不）+ lawful（合法）：「俺捞否」？不许捞——非法的。","ex":"The court ruled that the detention of the protesters was unlawful.","exCn":"法院裁定对抗议者的拘留是非法的。","col":["unlawful killing","unlawful arrest","unlawfully"]},{"id":1029,"topic":"crime","w":"sabotage","ipa":"/ˈsæbətɑːʒ/","pos":"n./v.","cn":"蓄意破坏","pun":"傻不他job","story":"「傻不他 job」——为了让他丢工作，故意把机器弄坏——蓄意破坏。","ex":"The factory fire was later found to be an act of industrial sabotage.","exCn":"工厂火灾后来被查明是一起工业蓄意破坏。","col":["act of sabotage","sabotage attempt","saboteur"]},{"id":1030,"topic":"crime","w":"ransom","ipa":"/ˈrænsəm/","pos":"n.","cn":"赎金","pun":"让送","story":"绑匪打电话：「让送」一百万来，人才放——赎金。","ex":"The kidnappers demanded a ransom of two million dollars for the businessman's release.","exCn":"绑匪要求两百万美元赎金以释放该商人。","col":["hold to ransom","demand a ransom","ransom note"]},{"id":1031,"topic":"crime","w":"hostage","ipa":"/ˈhɒstɪdʒ/","pos":"n.","cn":"人质","pun":"耗死提及","story":"绑匪拖着人「耗死提及」条件，人质在旁边发抖——人质。","ex":"The hostages were released unharmed after two days of negotiations.","exCn":"经过两天谈判，人质安然获释。","col":["take hostage","hostage situation","hold hostage"]},{"id":1032,"topic":"crime","w":"malicious","ipa":"/məˈlɪʃəs/","pos":"adj.","cn":"恶意的","pun":"么理谁死","story":"mal-（坏）：他「么理谁死」——才不管谁死活，就是要害人——恶意的。","ex":"Spreading malicious rumours online can now lead to criminal prosecution.","exCn":"在网上散布恶意谣言现在可能招致刑事起诉。","col":["malicious intent","malicious damage","malice"]},{"id":1033,"topic":"crime","w":"notorious","ipa":"/nəʊˈtɔːriəs/","pos":"adj.","cn":"臭名昭著的","pun":"no 拓瑞儿死","story":"「no 拓瑞儿死」——没人不知道这个坏蛋——臭名昭著的。","ex":"The notorious gang leader was finally captured after years on the run.","exCn":"这名臭名昭著的帮派头目在逃亡多年后终于落网。","col":["notorious for","notorious criminal","notoriety"]},{"id":1034,"topic":"culture","w":"heritage","ipa":"/ˈherɪtɪdʒ/","pos":"n.","cn":"遗产（文化）","pun":"嘿立提纸","story":"「嘿」，爷爷「立」了遗嘱，「提」着「纸」说：这是留给你的遗产。","ex":"The government should protect the country's cultural heritage.","exCn":"政府应保护国家的文化遗产。","col":["cultural heritage","World Heritage Site","preserve heritage"]},{"id":1035,"topic":"culture","w":"censorship","ipa":"/ˈsensəʃɪp/","pos":"n.","cn":"审查（制度）","pun":"闪色 ship","story":"审查员一挥手：「闪」掉那艘「色」情「ship」——审查。","ex":"Some argue that censorship of the internet limits freedom of speech.","exCn":"有人认为网络审查限制了言论自由。","col":["media censorship","censor (v.)","strict censorship"]},{"id":1036,"topic":"culture","w":"bias","ipa":"/ˈbaɪəs/","pos":"n.","cn":"偏见","pun":"拜饿死","story":"宁可「饿死」也不「拜」——偏见有多深。","ex":"News reports often show a clear political bias.","exCn":"新闻报道常表现出明显的政治偏见。","col":["gender bias","biased (adj.)","without bias"]},{"id":1037,"topic":"culture","w":"celebrity","ipa":"/səˈlebrəti/","pos":"n.","cn":"名人","pun":"谁累不累提","story":"「谁累不累」，拍戏「提」神——名人的生活。","ex":"Young people often see celebrities as role models.","exCn":"年轻人常把名人当作榜样。","col":["celebrity culture","a celebrity chef","become a celebrity"]},{"id":1038,"topic":"culture","w":"mainstream","ipa":"/ˈmeɪnstriːm/","pos":"n./adj.","cn":"主流（的）","pun":"们死追","story":"main（主要）+ stream（溪流）= 主流。大家「们」都「死追」的东西，就是主流。","ex":"Electric cars have moved from niche products into the mainstream.","exCn":"电动车已从小众产品进入主流。","col":["mainstream media","enter the mainstream","mainstream culture"]},{"id":1039,"topic":"culture","w":"tradition","ipa":"/trəˈdɪʃn/","pos":"n.","cn":"传统","pun":"吹地神","story":"老祖宗把「地」上的规矩「吹」得跟「神」一样——传统。","ex":"Many young people are losing interest in traditional customs.","exCn":"许多年轻人对传统习俗失去兴趣。","col":["cultural tradition","traditional (adj.)","keep a tradition alive"]},{"id":1040,"topic":"culture","w":"preserve","ipa":"/prɪˈzɜːv/","pos":"v.","cn":"保存；保护","pun":"扑累者服","story":"pre（提前）+ serve（服务）：提前把「服」装收好，「扑」上去，「累」也要保护。","ex":"Efforts have been made to preserve ancient buildings in the old town.","exCn":"人们努力保护老城的古建筑。","col":["preserve traditions / culture","preservation (n.)"]},{"id":1041,"topic":"culture","w":"diverse","ipa":"/daɪˈvɜːs/","pos":"adj.","cn":"多样的","pun":"带我思","story":"「带我」去看各种各样的世界，让我「思」考——多样的。","ex":"London is one of the most culturally diverse cities in the world.","exCn":"伦敦是世界上文化最多元的城市之一。","col":["culturally diverse","diversity (n.)","a diverse range of"]},{"id":1042,"topic":"culture","w":"advertisement","ipa":"/ədˈvɜːtɪsmənt/","pos":"n.","cn":"广告","pun":"爱的我提死门","story":"「爱的我」——广告每天「提」到你「死」，追到家「门」口。","ex":"Advertisements aimed at children should be banned.","exCn":"针对儿童的广告应该被禁止。","col":["advertise (v.)","advertising (n.) 广告业","TV / online advertisements"]},{"id":1043,"topic":"culture","w":"leisure","ipa":"/ˈleʒə(r)/","pos":"n.","cn":"休闲；空闲","pun":"累着","story":"「累着」了？那就歇一歇，享受休闲时间。","ex":"People today have more leisure time than previous generations.","exCn":"今天的人比前几代人有更多休闲时间。","col":["leisure time / activities","at leisure"]},{"id":1044,"topic":"culture","w":"aesthetic","ipa":"/iːsˈθetɪk/","pos":"adj./n.","cn":"审美的；美学","pun":"衣是赛踢课","story":"衣服是拿去赛「踢」还是赛美？当然比的是审美，穿衣讲究的就是 aesthetic。","ex":"The aesthetic value of a building often matters as much as its practical function.","exCn":"建筑的审美价值往往和实用功能同样重要。","col":["aesthetic value","aesthetic appeal","aesthetics (n.)"]},{"id":1045,"topic":"culture","w":"exhibition","ipa":"/ˌeksɪˈbɪʃn/","pos":"n.","cn":"展览；展览会","pun":"爱可是比省","story":"ex（向外）+ hibit（拿着）：把藏品拿到外面给人看，「爱可是比省」——全省的人都来看展览。","ex":"The exhibition attracted thousands of visitors who had never entered a museum before.","exCn":"这场展览吸引了成千上万从未进过博物馆的参观者。","col":["hold an exhibition","art exhibition","exhibit (v.)"]},{"id":1046,"topic":"culture","w":"sculpture","ipa":"/ˈskʌlptʃə(r)/","pos":"n.","cn":"雕塑；雕刻品","pun":"死扣不去","story":"雕塑家拿着凿子在石头上「死扣不去」的地方一点点抠，抠出一座雕塑。","ex":"Public sculpture can transform an ordinary square into a meaningful cultural space.","exCn":"公共雕塑能把普通广场变成有意义的文化空间。","col":["bronze sculpture","a piece of sculpture","sculptor (n.)"]},{"id":1047,"topic":"culture","w":"masterpiece","ipa":"/ˈmɑːstəpiːs/","pos":"n.","cn":"杰作；代表作","pun":"马斯特披四","story":"master（大师）+ piece（作品）：大师「披四」件斗篷登场，献上的每一件都是杰作。","ex":"Many masterpieces now hanging in galleries were ignored when they were first painted.","exCn":"如今挂在画廊里的许多杰作，刚画出来时曾无人问津。","col":["artistic masterpiece","create a masterpiece","literary masterpiece"]},{"id":1048,"topic":"culture","w":"gallery","ipa":"/ˈɡæləri/","pos":"n.","cn":"画廊；美术馆","pun":"盖了里","story":"在城里「盖了里」外两层的漂亮房子，里面挂满画，这就是画廊。","ex":"Free admission to national galleries encourages people from all backgrounds to enjoy art.","exCn":"国家美术馆免费开放鼓励各阶层的人欣赏艺术。","col":["art gallery","national gallery","gallery owner"]},{"id":1049,"topic":"culture","w":"curator","ipa":"/kjʊəˈreɪtə(r)/","pos":"n.","cn":"策展人；馆长","pun":"扣瑞特","story":"cura（照料）的人：策展人把展品一件件「扣」在瑞特（正确）的位置，安排整个展览。","ex":"The curator decided to display the artefacts in the order they were discovered.","exCn":"策展人决定按出土顺序陈列这些文物。","col":["museum curator","curate an exhibition (v.)","curatorial (adj.)"]},{"id":1050,"topic":"culture","w":"archive","ipa":"/ˈɑːkaɪv/","pos":"n./v.","cn":"档案馆；存档","pun":"啊开了","story":"「啊，开了！」推开尘封的大门，一屋子老档案，这里就是档案馆。","ex":"Digital archives allow researchers to access historical documents without damaging them.","exCn":"数字档案让研究者无需损坏原件就能查阅历史文件。","col":["national archives","archive material","archival (adj.)"]},{"id":1051,"topic":"culture","w":"artefact","ipa":"/ˈɑːtɪfækt/","pos":"n.","cn":"人工制品；文物","pun":"啊提发课的","story":"art（技艺）+ fact（做）：人用手艺做出来的东西。「啊，提发课的」老师从地里挖出一件古代文物。","ex":"Museums face pressure to return artefacts taken from former colonies.","exCn":"博物馆面临归还从前殖民地掠夺文物的压力。","col":["ancient artefacts","cultural artefact","artifact (美式拼写)"]},{"id":1052,"topic":"culture","w":"folklore","ipa":"/ˈfəʊklɔː(r)/","pos":"n.","cn":"民间传说；民俗","pun":"否克咯","story":"folk（民间）+ lore（传说）：老人讲故事，小孩问是真的吗？「否，克咯」——不过是民间传说。","ex":"Folklore passed down orally preserves the values of communities without written records.","exCn":"口耳相传的民间传说保存了没有文字记录的社区的价值观。","col":["local folklore","folklore and mythology","folk (adj.)"]},{"id":1053,"topic":"culture","w":"ritual","ipa":"/ˈrɪtʃuəl/","pos":"n.","cn":"仪式；例行程序","pun":"日出哦","story":"每天「日出哦」的那一刻，部落都要跳同一支舞，这就是固定的仪式。","ex":"Ancient rituals still shape how many communities celebrate birth, marriage and death.","exCn":"古老的仪式仍影响着许多社区庆祝生、婚、死的方式。","col":["religious ritual","perform a ritual","ritualistic (adj.)"]},{"id":1054,"topic":"culture","w":"ceremony","ipa":"/ˈserəməni/","pos":"n.","cn":"典礼；仪式","pun":"色若么你","story":"婚礼典礼上，新郎「色若」痴迷地盯着新娘：「么你」——除了你我谁都不要。","ex":"Graduation ceremonies mark an important transition in a young person's life.","exCn":"毕业典礼标志着年轻人生命中的重要转折。","col":["opening ceremony","wedding ceremony","ceremonial (adj.)"]},{"id":1055,"topic":"culture","w":"carnival","ipa":"/ˈkɑːnɪvl/","pos":"n.","cn":"狂欢节；嘉年华","pun":"卡你我","story":"狂欢节游行人山人海，「卡你我」谁都挤不动，但大家照样跳得开心。","ex":"The annual carnival brings enormous income to the city through tourism.","exCn":"一年一度的狂欢节通过旅游给城市带来巨大收入。","col":["street carnival","carnival parade","carnival atmosphere"]},{"id":1056,"topic":"culture","w":"costume","ipa":"/ˈkɒstjuːm/","pos":"n.","cn":"服装；戏服","pun":"靠死揪","story":"演员上台前「靠死揪」着领子整理戏服，生怕这身传统服装出错。","ex":"Traditional costumes worn at festivals help younger generations connect with their roots.","exCn":"节日穿的传统服装帮助年轻一代与自己的根源建立联系。","col":["national costume","costume drama","in costume"]},{"id":1057,"topic":"culture","w":"cuisine","ipa":"/kwɪˈziːn/","pos":"n.","cn":"菜肴；烹饪风格","pun":"亏进","story":"这家法国餐厅的菜太贵，老板却说「亏进」去也要保持正宗的 cuisine（烹饪风格）。","ex":"Local cuisine is one of the most direct ways tourists experience a foreign culture.","exCn":"当地菜肴是游客体验异国文化最直接的方式之一。","col":["local cuisine","French cuisine","fusion cuisine"]},{"id":1058,"topic":"culture","w":"craftsmanship","ipa":"/ˈkrɑːftsmənʃɪp/","pos":"n.","cn":"手艺；工艺","pun":"克拉夫子们十步","story":"craft（手艺）+ man（人）+ ship（状态）：手艺人「克拉夫子们」十步之内就能雕出一朵花，这就是精湛的工艺。","ex":"Machine production cannot replicate the craftsmanship of traditional furniture makers.","exCn":"机器生产无法复制传统家具匠人的手艺。","col":["fine craftsmanship","traditional craftsmanship","craftsman (n.)"]},{"id":1059,"topic":"culture","w":"handicraft","ipa":"/ˈhændikrɑːft/","pos":"n.","cn":"手工艺；手工艺品","pun":"汉迪克拉夫","story":"hand（手）+ craft（手艺）：「汉迪」师傅「克拉夫」一刻不停地编篮子，卖的是手工艺品。","ex":"Selling handicrafts online has given rural artisans access to global markets.","exCn":"在线销售手工艺品让乡村工匠接触到全球市场。","col":["local handicrafts","handicraft industry","handmade (adj.)"]},{"id":1060,"topic":"culture","w":"pottery","ipa":"/ˈpɒtəri/","pos":"n.","cn":"陶器；制陶","pun":"泼特瑞","story":"pot（罐）+ ery：陶工把泥「泼」到转盘上，做出特别瑞气的罐子——陶器。","ex":"Fragments of pottery reveal how ancient people cooked, stored food and traded.","exCn":"陶器碎片揭示了古人如何做饭、储粮和贸易。","col":["ancient pottery","pottery making","potter (n.)"]},{"id":1061,"topic":"culture","w":"calligraphy","ipa":"/kəˈlɪɡrəfi/","pos":"n.","cn":"书法","pun":"可立个飞","story":"calli（美）+ graphy（写）：书法家一笔写下去，「可立个飞」龙走凤舞的字。","ex":"Calligraphy remains a respected art form in many Asian cultures.","exCn":"在许多亚洲文化中，书法仍是受尊敬的艺术形式。","col":["Chinese calligraphy","practise calligraphy","calligrapher (n.)"]},{"id":1062,"topic":"culture","w":"embroidery","ipa":"/ɪmˈbrɔɪdəri/","pos":"n.","cn":"刺绣","pun":"硬不弱的绣","story":"奶奶的针线「硬不弱」，绣出的花比画还美，这就是刺绣。","ex":"Traditional embroidery patterns often carry symbolic meanings unique to each region.","exCn":"传统刺绣图案往往带有各地独特的象征意义。","col":["hand embroidery","embroidery pattern","embroider (v.)"]},{"id":1063,"topic":"culture","w":"architecture","ipa":"/ˈɑːkɪtektʃə(r)/","pos":"n.","cn":"建筑学；建筑风格","pun":"啊记太克车","story":"「啊，记太克车」——建筑师背着一车图纸，脑子里全是建筑风格。","ex":"Modern architecture should respect the historical character of the surrounding area.","exCn":"现代建筑应尊重周边地区的历史风貌。","col":["modern architecture","Gothic architecture","architect (n.)"]},{"id":1064,"topic":"culture","w":"monument","ipa":"/ˈmɒnjumənt/","pos":"n.","cn":"纪念碑；历史遗迹","pun":"毛你门特","story":"「毛」主席「你门」前那座特别高的碑，就是纪念碑。","ex":"Governments spend large sums maintaining monuments that attract international visitors.","exCn":"政府花巨资维护吸引国际游客的历史遗迹。","col":["national monument","ancient monument","monumental (adj.)"]},{"id":1065,"topic":"culture","w":"landmark","ipa":"/ˈlændmɑːk/","pos":"n.","cn":"地标；里程碑","pun":"懒的骂课","story":"land（土地）+ mark（标记）：土地上最显眼的标记。迷路了「懒的骂课」本，抬头找地标就行。","ex":"The tower has become a landmark that defines the skyline of the city.","exCn":"这座塔已成为定义城市天际线的地标。","col":["famous landmark","historic landmark","landmark decision"]},{"id":1066,"topic":"culture","w":"restoration","ipa":"/ˌrestəˈreɪʃn/","pos":"n.","cn":"修复；恢复","pun":"热死头累省","story":"re（再）+ store（存放）：修复老画时，工人「热死头累省」着力气一点点复原。","ex":"The restoration of the cathedral took over a decade and cost millions.","exCn":"大教堂的修复耗时十多年，花费数百万。","col":["restoration work","undergo restoration","restore (v.)"]},{"id":1067,"topic":"culture","w":"antique","ipa":"/ænˈtiːk/","pos":"n./adj.","cn":"古董；古老的","pun":"安踢课","story":"anti（古老）：「安」静地踢开尘土，露出一件老课桌——原来是古董。","ex":"The antique market thrives because collectors value objects with a history.","exCn":"古董市场繁荣，因为收藏家看重有历史的物件。","col":["antique furniture","antique shop","antiquity (n.)"]},{"id":1068,"topic":"culture","w":"authentic","ipa":"/ɔːˈθentɪk/","pos":"adj.","cn":"真正的；正宗的","pun":"哦深踢课","story":"「哦，深踢课」——老师用力踢开假货，留下真正正宗的那一件。","ex":"Tourists increasingly seek authentic cultural experiences rather than staged performances.","exCn":"游客越来越追求正宗的文化体验，而非表演式的展示。","col":["authentic experience","authentic cuisine","authenticity (n.)"]},{"id":1069,"topic":"culture","w":"indigenous","ipa":"/ɪnˈdɪdʒənəs/","pos":"adj.","cn":"本土的；土著的","pun":"硬地界那是","story":"「硬地界」那是我们祖祖辈辈的地方——本土人指着土地说。","ex":"Indigenous languages are disappearing faster than any other category of language.","exCn":"土著语言比其他任何类型的语言消失得都快。","col":["indigenous people","indigenous culture","indigenous knowledge"]},{"id":1070,"topic":"culture","w":"ethnic","ipa":"/ˈeθnɪk/","pos":"adj.","cn":"民族的；种族的","pun":"爱死你课","story":"民族课上老师说「爱死你课」——每个民族的服饰、歌舞都值得爱。","ex":"Ethnic minorities often struggle to maintain their customs in large cities.","exCn":"少数民族在大城市里常常难以保持自己的习俗。","col":["ethnic group","ethnic minority","ethnicity (n.)"]},{"id":1071,"topic":"culture","w":"minority","ipa":"/maɪˈnɒrəti/","pos":"n.","cn":"少数；少数民族","pun":"买闹热题","story":"minor（少的）：市场上「买闹热题」目的人是少数，多数人只看热闹。","ex":"Protecting the languages of minorities requires investment in education and media.","exCn":"保护少数民族语言需要在教育和媒体上投入。","col":["ethnic minority","minority group","in the minority"]},{"id":1072,"topic":"culture","w":"dialect","ipa":"/ˈdaɪəlekt/","pos":"n.","cn":"方言","pun":"呆哦累课特","story":"外地人听方言「呆哦」，学起来「累课特」别多——一个村一种说法。","ex":"Regional dialects are being replaced by standard forms taught in schools.","exCn":"地方方言正被学校教授的标准语所取代。","col":["local dialect","speak a dialect","dialectal (adj.)"]},{"id":1073,"topic":"culture","w":"assimilate","ipa":"/əˈsɪməleɪt/","pos":"v.","cn":"同化；吸收","pun":"饿死么累特","story":"新移民为了融入当地，「饿死么累特」都要学习当地习惯——被同化了。","ex":"Some argue that immigrants should assimilate rather than keep separate traditions.","exCn":"有人认为移民应当被同化，而不是保留各自的传统。","col":["assimilate into society","assimilate immigrants","assimilation (n.)"]},{"id":1074,"topic":"culture","w":"integrate","ipa":"/ˈɪntɪɡreɪt/","pos":"v.","cn":"融入；整合","pun":"硬踢个雷特","story":"新同学「硬踢个雷特」的球进门，全班欢呼，他一下子就融入了集体。","ex":"Cultural festivals help newcomers integrate into their adopted communities.","exCn":"文化节帮助新来者融入所在社区。","col":["integrate into society","fully integrated","integration (n.)"]},{"id":1075,"topic":"culture","w":"multicultural","ipa":"/ˌmʌltiˈkʌltʃərəl/","pos":"adj.","cn":"多元文化的","pun":"马蹄靠车肉","story":"multi（多）+ cultural（文化的）：街上有「马蹄」小吃、「靠车」的摊和烤「肉」串——各国文化汇聚，多元文化。","ex":"Living in a multicultural city exposes children to a range of languages and beliefs.","exCn":"生活在多元文化城市让孩子接触多种语言和信仰。","col":["multicultural society","multicultural city","multiculturalism (n.)"]},{"id":1076,"topic":"culture","w":"identity","ipa":"/aɪˈdentəti/","pos":"n.","cn":"身份；认同","pun":"爱等踢踢","story":"「爱等踢踢」球的那群人，球衣就是他们的身份认同。","ex":"Language is central to the cultural identity of any nation.","exCn":"语言是任何民族文化认同的核心。","col":["cultural identity","national identity","sense of identity"]},{"id":1077,"topic":"culture","w":"custom","ipa":"/ˈkʌstəm/","pos":"n.","cn":"风俗；习惯","pun":"卡死疼","story":"不懂当地风俗，用错了手势，被「卡死疼」了一下——入乡随俗很重要。","ex":"Many customs surrounding marriage have changed dramatically over a single generation.","exCn":"许多婚姻风俗在一代人之内就发生了巨大变化。","col":["local custom","social customs","customary (adj.)"]},{"id":1078,"topic":"culture","w":"etiquette","ipa":"/ˈetɪket/","pos":"n.","cn":"礼仪；礼节","pun":"爱踢客特","story":"「爱踢客」特别失礼——礼仪课第一条：不能踢客人。","ex":"Business etiquette varies so much between cultures that misunderstandings are common.","exCn":"各文化的商务礼仪差异极大，误会很常见。","col":["social etiquette","table etiquette","a breach of etiquette"]},{"id":1079,"topic":"culture","w":"taboo","ipa":"/təˈbuː/","pos":"n./adj.","cn":"禁忌；忌讳的","pun":"他不","story":"问起那个话题，「他不」肯说——那是当地的禁忌。","ex":"Topics that are taboo in one culture may be discussed openly in another.","exCn":"一种文化的禁忌话题在另一种文化可能被公开讨论。","col":["cultural taboo","break a taboo","taboo subject"]},{"id":1080,"topic":"culture","w":"superstition","ipa":"/ˌsuːpəˈstɪʃn/","pos":"n.","cn":"迷信","pun":"酥皮死踢省","story":"super（超）+ stition（站）：站在理智之上。吃「酥皮」时死活要「踢」一下门，说能省灾——迷信。","ex":"Superstition still influences decisions about weddings and house purchases in many places.","exCn":"迷信在许多地方仍影响婚礼和买房的决定。","col":["popular superstition","superstitious (adj.)","superstitious belief"]},{"id":1081,"topic":"culture","w":"myth","ipa":"/mɪθ/","pos":"n.","cn":"神话；错误观念","pun":"米思","story":"「米思」考了半天：天上真有神仙吗？那只是神话。","ex":"Ancient myths explain how early societies understood the natural world.","exCn":"古代神话解释了早期社会如何理解自然世界。","col":["Greek myth","myth and legend","mythology (n.)"]},{"id":1082,"topic":"culture","w":"legend","ipa":"/ˈledʒənd/","pos":"n.","cn":"传说；传奇人物","pun":"累镇的","story":"「累镇的」人都在讲那个救了全镇的英雄——他成了传说。","ex":"Local legends are often used to promote tourism in small towns.","exCn":"地方传说常被用来推动小镇旅游。","col":["local legend","living legend","legendary (adj.)"]},{"id":1083,"topic":"culture","w":"narrative","ipa":"/ˈnærətɪv/","pos":"n.","cn":"叙述；故事","pun":"那热踢舞","story":"narr（讲述）：说书人讲「那热踢舞」的场面，讲得绘声绘色——这就是叙事。","ex":"Film has become the dominant narrative form of the modern age.","exCn":"电影已成为现代最主要的叙事形式。","col":["historical narrative","narrative structure","narrate (v.)"]},{"id":1084,"topic":"culture","w":"literature","ipa":"/ˈlɪtrətʃə(r)/","pos":"n.","cn":"文学","pun":"里特热车","story":"liter（字母）：一车字母「里特热」，堆成的书就是文学。","ex":"Studying literature develops empathy by exposing readers to unfamiliar lives.","exCn":"学习文学让读者接触陌生的人生，从而培养同理心。","col":["classical literature","English literature","literary (adj.)"]},{"id":1085,"topic":"culture","w":"novelist","ipa":"/ˈnɒvəlɪst/","pos":"n.","cn":"小说家","pun":"闹我累死它","story":"novel（小说）+ ist（人）：小说家天天「闹我累死它」——闹着灵感，累死键盘，写出一本本小说。","ex":"Nineteenth-century novelists documented social change more vividly than historians did.","exCn":"十九世纪小说家比历史学家更生动地记录了社会变迁。","col":["best-selling novelist","novel (n.)","fiction writer"]},{"id":1086,"topic":"culture","w":"poetry","ipa":"/ˈpəʊətri/","pos":"n.","cn":"诗歌","pun":"泡儿吹","story":"诗人对着湖面「泡儿吹」，吹出一串串泡泡，每个泡泡里都是一句诗。","ex":"Poetry is often the first literary form that children encounter in school.","exCn":"诗歌往往是孩子在学校接触的第一种文学形式。","col":["write poetry","poetry reading","poet (n.)"]},{"id":1087,"topic":"culture","w":"prose","ipa":"/prəʊz/","pos":"n.","cn":"散文；散文体","pun":"泼肉丝","story":"诗歌像精致摆盘，散文像随手「泼肉丝」进锅——不押韵、随性，却更家常。","ex":"Her prose is admired for its clarity and lack of unnecessary ornament.","exCn":"她的散文因清晰、不加多余修饰而受推崇。","col":["prose style","prose and poetry","written in prose"]},{"id":1088,"topic":"culture","w":"fiction","ipa":"/ˈfɪkʃn/","pos":"n.","cn":"小说；虚构","pun":"费克省","story":"fict（编造）：作家「费」尽心思「克」制真实，「省」掉事实——写出来的就是虚构的小说。","ex":"Science fiction has predicted many technologies decades before they appeared.","exCn":"科幻小说早在数十年前就预言了许多技术。","col":["science fiction","fiction and non-fiction","fictional (adj.)"]},{"id":1089,"topic":"culture","w":"biography","ipa":"/baɪˈɒɡrəfi/","pos":"n.","cn":"传记","pun":"拜哦哥拉飞","story":"bio（生命）+ graphy（写）：写一个人的一生。「拜哦，哥拉飞」——记录哥哥从崇拜到飞黄腾达的一生，就是传记。","ex":"Biographies of artists reveal how personal hardship shaped their creative work.","exCn":"艺术家的传记揭示了个人苦难如何塑造其创作。","col":["write a biography","autobiography (n.)","biographer (n.)"]},{"id":1090,"topic":"culture","w":"genre","ipa":"/ˈʒɒ̃rə/","pos":"n.","cn":"体裁；类型","pun":"让热","story":"让人一听就「让热」血沸腾的是摇滚，让人流泪的是悲剧——不同的类型（genre）。","ex":"Streaming services recommend films by genre rather than by artistic merit.","exCn":"流媒体按类型而非艺术价值推荐电影。","col":["literary genre","film genre","a new genre"]},{"id":1091,"topic":"culture","w":"anthology","ipa":"/ænˈθɒlədʒi/","pos":"n.","cn":"选集；文选","pun":"俺扫落叶","story":"antho（花）+ logy（收集）：本义采花集。「俺扫落叶」，把最美的叶子收进一本册子——诗歌选集。","ex":"The anthology brings together poems from twenty different countries.","exCn":"这本选集汇集了二十个国家的诗歌。","col":["poetry anthology","an anthology of short stories","compile an anthology"]},{"id":1092,"topic":"culture","w":"manuscript","ipa":"/ˈmænjuskrɪpt/","pos":"n.","cn":"手稿；原稿","pun":"馒头思刻扑","story":"manu（手）+ script（写）：作家啃着「馒头思」考，然后「刻扑」刻扑地在纸上写，写出的就是手稿。","ex":"Medieval manuscripts were copied by hand and decorated with gold leaf.","exCn":"中世纪手稿是手工抄写并用金箔装饰的。","col":["original manuscript","ancient manuscript","submit a manuscript"]},{"id":1093,"topic":"culture","w":"translation","ipa":"/trænzˈleɪʃn/","pos":"n.","cn":"翻译；译文","pun":"穿在累省","story":"trans（跨越）+ lation（搬）：把意思搬过语言的边界。「穿在累省」——翻译官穿梭两国，累但省了误会。","ex":"Much of the beauty of poetry is lost in translation.","exCn":"诗歌的许多美感在翻译中丢失了。","col":["lost in translation","literal translation","translate (v.)"]},{"id":1094,"topic":"culture","w":"metaphor","ipa":"/ˈmetəfə(r)/","pos":"n.","cn":"隐喻；比喻","pun":"妹她佛","story":"「妹她佛」一样安静——把妹妹比作佛，这就是隐喻。","ex":"Writers use metaphor to make abstract emotions concrete and memorable.","exCn":"作家用隐喻把抽象的情感变得具体难忘。","col":["a metaphor for","use a metaphor","metaphorical (adj.)"]},{"id":1095,"topic":"culture","w":"satire","ipa":"/ˈsætaɪə(r)/","pos":"n.","cn":"讽刺；讽刺作品","pun":"洒太热","story":"讽刺作家往权贵头上「洒太热」的辣椒水，笑着骂——这就是讽刺作品。","ex":"Political satire allows citizens to criticise leaders without direct confrontation.","exCn":"政治讽刺让公民无需正面冲突就能批评领导者。","col":["political satire","biting satire","satirical (adj.)"]},{"id":1096,"topic":"culture","w":"protagonist","ipa":"/prəˈtæɡənɪst/","pos":"n.","cn":"主人公；主角","pun":"扑太哥你是","story":"proto（首要）+ agonist（角逐者）：「扑太哥，你是」主角！全场摄像机都跟着你。","ex":"The protagonist of the novel struggles between family duty and personal ambition.","exCn":"小说主人公在家庭责任和个人抱负之间挣扎。","col":["the main protagonist","female protagonist","antagonist (n.)"]},{"id":1097,"topic":"culture","w":"plot","ipa":"/plɒt/","pos":"n./v.","cn":"情节；密谋","pun":"扑落","story":"故事情节一波三折，观众心跟着「扑落」扑落地跳。","ex":"A strong plot keeps readers turning pages long past midnight.","exCn":"精彩的情节让读者过了午夜还在翻页。","col":["plot twist","the plot of the novel","plot development"]},{"id":1098,"topic":"culture","w":"drama","ipa":"/ˈdrɑːmə/","pos":"n.","cn":"戏剧；剧本","pun":"抓马","story":"舞台上演员大喊「抓马」！一匹马冲过观众席——够戏剧性的戏剧。","ex":"School drama classes build confidence and teamwork in shy students.","exCn":"学校戏剧课培养害羞学生的自信和团队合作。","col":["television drama","drama school","dramatic (adj.)"]},{"id":1099,"topic":"culture","w":"playwright","ipa":"/ˈpleɪraɪt/","pos":"n.","cn":"剧作家","pun":"普雷莱特","story":"play（戏剧）+ wright（工匠）：造戏的工匠。「普雷莱特」是位剧作家，一晚上写完一整出戏。","ex":"Shakespeare remains the most performed playwright in the world.","exCn":"莎士比亚仍是世界上作品上演最多的剧作家。","col":["famous playwright","contemporary playwright","dramatist (n.)"]},{"id":1100,"topic":"culture","w":"theatre","ipa":"/ˈθɪətə(r)/","pos":"n.","cn":"剧院；戏剧","pun":"细儿特","story":"剧院里灯光「细儿」暗，特别安静，只等大幕拉开。","ex":"Local theatres struggle to survive without public funding.","exCn":"地方剧院没有公共资助很难生存。","col":["go to the theatre","theatre company","theatrical (adj.)"]},{"id":1101,"topic":"culture","w":"rehearsal","ipa":"/rɪˈhɜːsl/","pos":"n.","cn":"排练；彩排","pun":"日喝so","story":"演员们「日」夜排练，喝水都嫌浪费时间——so 累，这就是彩排。","ex":"Weeks of rehearsal precede every professional stage production.","exCn":"每一场专业舞台演出前都有数周的排练。","col":["dress rehearsal","in rehearsal","rehearse (v.)"]},{"id":1102,"topic":"culture","w":"audience","ipa":"/ˈɔːdiəns/","pos":"n.","cn":"观众；听众","pun":"哦弟恩死","story":"audi（听）：「哦弟恩死」——弟弟在台下感恩得要死，听得入迷——他就是观众。","ex":"Digital platforms have given musicians direct access to a global audience.","exCn":"数字平台让音乐人直接触达全球观众。","col":["target audience","live audience","audience participation"]},{"id":1103,"topic":"culture","w":"applause","ipa":"/əˈplɔːz/","pos":"n.","cn":"掌声；喝彩","pun":"饿扑落死","story":"演出结束，观众饿着肚子也不走，「饿扑落死」也要拍手——雷鸣般的掌声。","ex":"The performance ended to thunderous applause from a full house.","exCn":"演出在满座观众雷鸣般的掌声中结束。","col":["a round of applause","thunderous applause","applaud (v.)"]},{"id":1104,"topic":"culture","w":"performance","ipa":"/pəˈfɔːməns/","pos":"n.","cn":"表演；表现","pun":"泼佛闷死","story":"per（完全）+ form（形式）：把形式做足。台上「泼佛闷死」——演员演得太投入，观众都看闷了神。","ex":"Live performance offers an emotional connection that recordings cannot match.","exCn":"现场表演带来录音无法比拟的情感联结。","col":["live performance","give a performance","perform (v.)"]},{"id":1105,"topic":"culture","w":"improvise","ipa":"/ˈɪmprəvaɪz/","pos":"v.","cn":"即兴创作；临时凑合","pun":"硬扑绕外子","story":"im（不）+ pro（预先）+ vis（看）：没有预先看过剧本。乐手「硬扑绕外子」——硬着头皮绕着外行观众即兴演奏。","ex":"Jazz musicians improvise, creating music that is never played the same way twice.","exCn":"爵士乐手即兴演奏，创造出永不重复的音乐。","col":["improvise a solution","improvised music","improvisation (n.)"]},{"id":1106,"topic":"culture","w":"choreography","ipa":"/ˌkɒriˈɒɡrəfi/","pos":"n.","cn":"编舞","pun":"扣李哦哥拉飞","story":"choreo（舞蹈）+ graphy（写）：「扣李哦，哥拉飞」——编舞老师一扣手，李哥就被拉着飞起来。","ex":"The choreography blends traditional folk dance with contemporary movement.","exCn":"这段编舞融合了传统民间舞与现代动作。","col":["original choreography","choreographer (n.)","choreograph (v.)"]},{"id":1107,"topic":"culture","w":"orchestra","ipa":"/ˈɔːkɪstrə/","pos":"n.","cn":"管弦乐队","pun":"哦可是抓","story":"「哦，可是抓」不住指挥棒——管弦乐队上百人，全靠指挥那根棒。","ex":"Many cities fund an orchestra as a symbol of cultural prestige.","exCn":"许多城市资助管弦乐队，作为文化声望的象征。","col":["symphony orchestra","play in an orchestra","orchestral (adj.)"]},{"id":1108,"topic":"culture","w":"symphony","ipa":"/ˈsɪmfəni/","pos":"n.","cn":"交响乐","pun":"新粉你","story":"sym（一起）+ phony（声音）：所有乐器一起发声。听完交响乐，全场都成了「新粉你」的粉丝。","ex":"Beethoven's symphonies are still performed in concert halls around the world.","exCn":"贝多芬的交响乐仍在世界各地的音乐厅上演。","col":["symphony orchestra","compose a symphony","symphonic (adj.)"]},{"id":1109,"topic":"culture","w":"composer","ipa":"/kəmˈpəʊzə(r)/","pos":"n.","cn":"作曲家","pun":"肯剖泽","story":"com（一起）+ pose（放置）：把音符放在一起。作曲家「肯剖泽」——肯把心剖开，泽被后世的旋律。","ex":"Film composers often receive less recognition than the directors they work with.","exCn":"电影作曲家得到的认可往往少于合作的导演。","col":["classical composer","compose (v.)","composition (n.)"]},{"id":1110,"topic":"culture","w":"melody","ipa":"/ˈmelədi/","pos":"n.","cn":"旋律；曲调","pun":"美了滴","story":"「美了滴」——一滴滴音符落下来，串成美妙的旋律。","ex":"A simple melody can remain in the memory for a lifetime.","exCn":"一段简单的旋律可以在记忆里留一辈子。","col":["catchy melody","hum a melody","melodic (adj.)"]},{"id":1111,"topic":"culture","w":"rhythm","ipa":"/ˈrɪðəm/","pos":"n.","cn":"节奏；韵律","pun":"日怎","story":"鼓手敲着「日怎日怎」的拍子，全场跟着节奏点头。","ex":"Traditional drumming teaches children rhythm long before formal music lessons.","exCn":"传统鼓乐在正式音乐课之前就教会孩子节奏。","col":["sense of rhythm","rhythm and melody","rhythmic (adj.)"]},{"id":1112,"topic":"culture","w":"harmony","ipa":"/ˈhɑːməni/","pos":"n.","cn":"和声；和谐","pun":"哈么你","story":"合唱团里「哈么你」一句，我一句，声部叠在一起，和谐得像一个人在唱。","ex":"Music education encourages harmony between students from different backgrounds.","exCn":"音乐教育促进不同背景学生之间的和谐。","col":["in harmony with","vocal harmony","harmonious (adj.)"]},{"id":1113,"topic":"culture","w":"lyrics","ipa":"/ˈlɪrɪks/","pos":"n.","cn":"歌词","pun":"里瑞克斯","story":"lyre（里拉琴）：古人弹琴唱诗。歌手唱到「里瑞克斯」时忘了词，全场帮他接歌词。","ex":"Song lyrics often reflect the social concerns of the era in which they were written.","exCn":"歌词往往反映其创作年代的社会关切。","col":["write lyrics","song lyrics","lyricist (n.)"]},{"id":1114,"topic":"culture","w":"instrument","ipa":"/ˈɪnstrəmənt/","pos":"n.","cn":"乐器；工具","pun":"硬死揣门特","story":"in（进）+ stru（建造）：「硬死揣」着小提琴进「门」，特别宝贝——那是他的乐器。","ex":"Learning a musical instrument improves memory and concentration in children.","exCn":"学习乐器能提高孩子的记忆力和专注力。","col":["musical instrument","play an instrument","instrumental (adj.)"]},{"id":1115,"topic":"culture","w":"acoustic","ipa":"/əˈkuːstɪk/","pos":"adj.","cn":"声学的；原声的","pun":"饿哭死踢课","story":"acou（听）：不插电的原声吉他，弹得人「饿哭死」也要「踢课」跑去听。","ex":"The concert hall was designed with acoustic quality as the top priority.","exCn":"音乐厅的设计把声学品质放在首位。","col":["acoustic guitar","acoustic performance","acoustics (n.)"]},{"id":1116,"topic":"culture","w":"concert","ipa":"/ˈkɒnsət/","pos":"n.","cn":"音乐会；演唱会","pun":"看色特","story":"con（一起）+ cert（确定）：大家一起「看」舞台，灯光「色特」别炫——这就是音乐会。","ex":"Ticket prices for major concerts have risen far faster than average incomes.","exCn":"大型演唱会门票价格上涨远快于平均收入。","col":["live concert","concert hall","give a concert"]},{"id":1117,"topic":"culture","w":"repertoire","ipa":"/ˈrepətwɑː(r)/","pos":"n.","cn":"全部曲目；保留剧目","pun":"热泼特娃","story":"钢琴家「热泼特娃」——热情地把自己会弹的全部曲目泼给这个小娃听。","ex":"The orchestra's repertoire ranges from Baroque works to contemporary compositions.","exCn":"该乐团的曲目从巴洛克作品到当代作曲无所不包。","col":["a wide repertoire","classical repertoire","add to one's repertoire"]},{"id":1118,"topic":"culture","w":"virtuoso","ipa":"/ˌvɜːtʃuˈəʊsəʊ/","pos":"n.","cn":"艺术大师；演奏能手","pun":"我出哦搜","story":"virtu（卓越）：大师一出场，「我出哦搜」——我一出手，全场惊呼哦，网上都在搜。","ex":"A violin virtuoso can command fees that few other musicians ever earn.","exCn":"小提琴大师的出场费是大多数音乐人难以企及的。","col":["piano virtuoso","virtuoso performance","virtuosity (n.)"]},{"id":1119,"topic":"culture","w":"amateur","ipa":"/ˈæmətə(r)/","pos":"n./adj.","cn":"业余爱好者；业余的","pun":"爱么特","story":"amat（爱）：「爱么，特」别爱，就是不靠它挣钱——业余爱好者。","ex":"Amateur theatre groups keep drama alive in towns without professional companies.","exCn":"业余剧团让没有专业剧团的小镇仍有戏剧。","col":["amateur musician","amateur and professional","amateurish (adj.)"]},{"id":1120,"topic":"culture","w":"patron","ipa":"/ˈpeɪtrən/","pos":"n.","cn":"赞助人；顾客","pun":"陪穿","story":"pater（父亲）：像父亲一样养着艺术家。富商「陪穿」——陪画家穿越困境，掏钱赞助。","ex":"Wealthy patrons have supported artists since the Renaissance.","exCn":"自文艺复兴以来，富有的赞助人一直支持艺术家。","col":["patron of the arts","wealthy patron","patronage (n.)"]},{"id":1121,"topic":"culture","w":"sponsorship","ipa":"/ˈspɒnsəʃɪp/","pos":"n.","cn":"赞助；资助","pun":"死胖色湿扑","story":"sponsor（担保人）：「死胖」老板衣服都「色湿」了，还「扑」上来说要出钱——这就是企业赞助。","ex":"Corporate sponsorship of museums raises questions about artistic independence.","exCn":"企业赞助博物馆引发对艺术独立性的质疑。","col":["corporate sponsorship","seek sponsorship","sponsor (n./v.)"]},{"id":1122,"topic":"culture","w":"commercialise","ipa":"/kəˈmɜːʃəlaɪz/","pos":"v.","cn":"使商业化","pun":"可磨设赖子","story":"commerce（商业）+ ise（使）：为了赚钱，「可磨设赖子」——老庙会磨成商业街，全是耍赖卖货的摊。","ex":"Critics argue that festivals lose their meaning once they are commercialised.","exCn":"批评者认为节日一旦商业化就失去了意义。","col":["heavily commercialised","commercialisation (n.)","commercial (adj.)"]},{"id":1123,"topic":"culture","w":"box office","ipa":"/ˈbɒks ɒfɪs/","pos":"n.","cn":"票房；售票处","pun":"包克死哦费斯","story":"电影院售票处的箱子（box）被抢票的人「包克死」，「哦，费斯」——票房爆了。","ex":"Box office success does not necessarily indicate artistic quality.","exCn":"票房成功并不一定代表艺术质量。","col":["box office hit","box office takings","at the box office"]},{"id":1124,"topic":"culture","w":"blockbuster","ipa":"/ˈblɒkbʌstə(r)/","pos":"n.","cn":"大片；轰动之作","pun":"不落客巴士特","story":"block（街区）+ buster（炸弹）：炸翻整个街区。这部大片「不落客」——没一个座位空着，巴士特意加班拉观众。","ex":"Hollywood blockbusters dominate cinemas, leaving little room for independent films.","exCn":"好莱坞大片占据影院，留给独立电影的空间很小。","col":["summer blockbuster","blockbuster film","blockbuster exhibition"]},{"id":1125,"topic":"culture","w":"sequel","ipa":"/ˈsiːkwəl/","pos":"n.","cn":"续集","pun":"戏扣","story":"sequ（跟随）：第一部结尾留了个「戏扣」，扣住观众非等续集不可。","ex":"Studios prefer sequels because they carry less financial risk than original stories.","exCn":"制片厂偏爱续集，因为它比原创故事的财务风险更低。","col":["film sequel","a sequel to","prequel (n.)"]},{"id":1126,"topic":"culture","w":"screenplay","ipa":"/ˈskriːnpleɪ/","pos":"n.","cn":"电影剧本","pun":"死可怜扑累","story":"screen（银幕）+ play（剧本）：编剧「死可怜」，扑在桌上累一年，才写出一部电影剧本。","ex":"A well-written screenplay is the foundation of any successful film.","exCn":"写得好的剧本是任何成功电影的基础。","col":["write a screenplay","original screenplay","screenwriter (n.)"]},{"id":1127,"topic":"culture","w":"cinematography","ipa":"/ˌsɪnəməˈtɒɡrəfi/","pos":"n.","cn":"电影摄影术","pun":"西那么托哥拉飞","story":"cinema（电影）+ graphy（记录）：「西那么托，哥拉飞」——西边那么美的景，摄影哥拉着无人机飞拍，这就是电影摄影。","ex":"The film was praised for its cinematography rather than its story.","exCn":"这部电影因摄影而非故事受到好评。","col":["stunning cinematography","cinematographer (n.)","cinematic (adj.)"]},{"id":1128,"topic":"culture","w":"documentary","ipa":"/ˌdɒkjuˈmentri/","pos":"n./adj.","cn":"纪录片；纪实的","pun":"道可有闷吹","story":"document（记录）：纪录片「道可有闷」——讲的道理可能有点闷，但不「吹」牛，全是真实记录。","ex":"Documentaries about wildlife have changed public attitudes towards conservation.","exCn":"野生动物纪录片改变了公众对保护的态度。","col":["wildlife documentary","make a documentary","documentary evidence"]},{"id":1129,"topic":"culture","w":"animation","ipa":"/ˌænɪˈmeɪʃn/","pos":"n.","cn":"动画；活力","pun":"爱你妹省","story":"anim（生命）：给画赋予生命。哥哥「爱你妹省」——为了省钱，亲手给妹妹画了一部动画。","ex":"Japanese animation has become one of the country's most successful cultural exports.","exCn":"日本动画已成为该国最成功的文化输出之一。","col":["computer animation","animation studio","animated (adj.)"]},{"id":1130,"topic":"culture","w":"subtitle","ipa":"/ˈsʌbtaɪtl/","pos":"n./v.","cn":"字幕；副标题","pun":"傻不太头","story":"sub（下面）+ title（标题）：屏幕下面的字。不看字幕就「傻不太头」——听不懂，脑袋懵。","ex":"Subtitles allow foreign films to reach audiences that dubbing would alienate.","exCn":"字幕让外国电影触达那些会被配音疏远的观众。","col":["English subtitles","with subtitles","subtitled film"]},{"id":1131,"topic":"culture","w":"dub","ipa":"/dʌb/","pos":"v.","cn":"配音；把…称为","pun":"搭补","story":"外语片声音不对，找演员「搭补」一段中文——这就是配音。","ex":"Children's films are usually dubbed rather than subtitled for young viewers.","exCn":"儿童电影通常为小观众配音而不是加字幕。","col":["dubbed into English","dubbing (n.)","dub sb sth"]},{"id":1132,"topic":"culture","w":"broadcast","ipa":"/ˈbrɔːdkɑːst/","pos":"v./n.","cn":"广播；播放","pun":"不肉的卡斯特","story":"broad（宽）+ cast（撒）：把声音撒向四面八方。「不肉的卡斯特」——卡斯特台不播肉，只播文化节目。","ex":"National broadcasters have a duty to air programmes that reflect local culture.","exCn":"国家广播机构有责任播放反映本土文化的节目。","col":["live broadcast","broadcast a programme","broadcaster (n.)"]},{"id":1133,"topic":"culture","w":"streaming","ipa":"/ˈstriːmɪŋ/","pos":"n.","cn":"流媒体；在线播放","pun":"死追命","story":"stream（溪流）：内容像溪水一样流来。年轻人「死追命」地追剧，全靠流媒体。","ex":"Streaming has changed how audiences consume music, films and television.","exCn":"流媒体改变了观众消费音乐、电影和电视的方式。","col":["streaming service","music streaming","stream (v.)"]},{"id":1134,"topic":"culture","w":"copyright","ipa":"/ˈkɒpiraɪt/","pos":"n.","cn":"版权","pun":"卡皮赖特","story":"copy（复制）+ right（权利）：复制的权利。谁想「卡皮」（copy）我的书？先给「赖特」（right）付版权费。","ex":"Copyright law protects creators but may also restrict access to cultural works.","exCn":"版权法保护创作者，但也可能限制人们接触文化作品。","col":["copyright law","hold the copyright","copyright infringement"]},{"id":1135,"topic":"culture","w":"royalty","ipa":"/ˈrɔɪəlti/","pos":"n.","cn":"版税；王室","pun":"肉哦踢","story":"作家每卖一本书就能收一块「肉」，「哦，踢」都踢不走的稳定收入——版税。","ex":"Musicians receive only a tiny royalty from each song streamed online.","exCn":"音乐人从每首在线播放的歌曲中只能拿到极少的版税。","col":["royalty payments","earn royalties","royalties from book sales"]},{"id":1136,"topic":"culture","w":"intellectual property","ipa":"/ˌɪntəˈlektʃuəl ˈprɒpəti/","pos":"n.","cn":"知识产权","pun":"硬特累课除哦泼泼踢","story":"intellect（智力）+ property（财产）：脑子里的财产。发明者「硬特累课」，别人想「泼泼踢」抢走，法律不许——这是知识产权。","ex":"Weak enforcement of intellectual property rights discourages investment in creative industries.","exCn":"知识产权保护不力会打击对创意产业的投资。","col":["intellectual property rights","protect intellectual property","IP (缩写)"]},{"id":1137,"topic":"culture","w":"imitation","ipa":"/ˌɪmɪˈteɪʃn/","pos":"n.","cn":"模仿；仿制品","pun":"一米忒省","story":"imit（模仿）：「一米忒省」——一米布料太省，只能做出个仿制品，一看就是模仿的。","ex":"Cheap imitations of traditional crafts threaten the livelihood of skilled artisans.","exCn":"传统工艺的廉价仿品威胁到熟练工匠的生计。","col":["cheap imitation","imitation leather","imitate (v.)"]},{"id":1138,"topic":"culture","w":"originality","ipa":"/əˌrɪdʒəˈnæləti/","pos":"n.","cn":"独创性；原创性","pun":"哦瑞纠那了踢","story":"origin（起源）：从自己开始。「哦，瑞纠那了踢」——瑞纠自创了一种踢法，独创性十足。","ex":"Examiners reward originality far more than technical perfection in art competitions.","exCn":"艺术比赛的评委看重独创性远胜于技术完美。","col":["lack originality","artistic originality","original (adj.)"]},{"id":1139,"topic":"culture","w":"inspiration","ipa":"/ˌɪnspəˈreɪʃn/","pos":"n.","cn":"灵感；鼓舞","pun":"硬死不累省","story":"in（入）+ spir（呼吸）：灵感像气一样吸进来。画家「硬死不累省」——灵感一来，硬撑到死也不累，省下睡觉时间。","ex":"Many composers drew inspiration from the folk music of their homeland.","exCn":"许多作曲家从家乡的民间音乐中汲取灵感。","col":["draw inspiration from","a source of inspiration","inspire (v.)"]},{"id":1140,"topic":"culture","w":"imagination","ipa":"/ɪˌmædʒɪˈneɪʃn/","pos":"n.","cn":"想象力","pun":"一妈基内省","story":"image（图像）：脑中造图。「一妈基内省」——妈妈一句话，孩子脑内就自省出一整个世界，想象力惊人。","ex":"Reading fiction stretches the imagination in ways that screens rarely do.","exCn":"读小说以屏幕难以做到的方式拓展想象力。","col":["use your imagination","vivid imagination","imaginative (adj.)"]},{"id":1141,"topic":"culture","w":"abstract","ipa":"/ˈæbstrækt/","pos":"adj./n.","cn":"抽象的；摘要","pun":"爱不死抓课的","story":"abs（离开）+ tract（拉）：把具体形象拉走。「爱不死抓课的」——抽象画你抓不住具体是啥，但爱它爱不死。","ex":"Abstract art challenges viewers to find meaning without recognisable forms.","exCn":"抽象艺术挑战观众在没有具象形式中寻找意义。","col":["abstract art","abstract painting","abstraction (n.)"]},{"id":1142,"topic":"culture","w":"contemporary","ipa":"/kənˈtemprəri/","pos":"adj./n.","cn":"当代的；同时代的人","pun":"肯特扑瑞","story":"con（一起）+ tempor（时间）：同一时代。「肯特扑瑞」——肯特扑向瑞士的当代艺术馆，看的全是当代作品。","ex":"Contemporary art often provokes debate about what deserves to be called art.","exCn":"当代艺术常引发关于什么才配称为艺术的争论。","col":["contemporary art","contemporary society","contemporaries (n.)"]},{"id":1143,"topic":"culture","w":"avant-garde","ipa":"/ˌævɒ̃ ˈɡɑːd/","pos":"adj./n.","cn":"先锋的；前卫派","pun":"啊翁嘎的","story":"法语「前卫部队」：「啊，翁嘎的」——老翁嘎地一声推开门，玩起先锋艺术，比年轻人还前卫。","ex":"Avant-garde movements are often mocked before being accepted by museums.","exCn":"先锋运动常常先被嘲笑，后被博物馆接纳。","col":["avant-garde art","avant-garde composer","the avant-garde"]},{"id":1144,"topic":"culture","w":"classical","ipa":"/ˈklæsɪkl/","pos":"adj.","cn":"古典的；经典的","pun":"克拉西扣","story":"class（等级）：一流等级的。「克拉西扣」——克拉西扣上领结去听古典音乐会。","ex":"Classical music audiences are ageing, raising concerns about its future.","exCn":"古典音乐的观众正在老龄化，引发对其未来的担忧。","col":["classical music","classical literature","classic (n./adj.)"]},{"id":1145,"topic":"culture","w":"medieval","ipa":"/ˌmediˈiːvl/","pos":"adj.","cn":"中世纪的","pun":"没底一窝","story":"medi（中间）+ ev（时代）：中间的时代。「没底一窝」——中世纪的城堡地下没底，一窝一窝的老鼠。","ex":"Medieval cathedrals remain the most visited cultural sites in Europe.","exCn":"中世纪大教堂仍是欧洲游客最多的文化景点。","col":["medieval castle","medieval period","the Middle Ages"]},{"id":1146,"topic":"culture","w":"renaissance","ipa":"/rɪˈneɪsns/","pos":"n.","cn":"文艺复兴；复兴","pun":"日内桑斯","story":"re（再）+ naissance（出生）：再生。「日内桑斯」——日内瓦的桑斯先生让老手艺重新出生，迎来复兴。","ex":"The city is enjoying a cultural renaissance driven by young artists.","exCn":"这座城市正经历由年轻艺术家推动的文化复兴。","col":["the Renaissance","cultural renaissance","Renaissance art"]},{"id":1147,"topic":"culture","w":"iconic","ipa":"/aɪˈkɒnɪk/","pos":"adj.","cn":"标志性的；偶像的","pun":"爱看你课","story":"icon（图像/偶像）：「爱看你课」——学生最爱看你的课，你就是学校的标志性人物。","ex":"The opera house has become an iconic symbol of the nation.","exCn":"这座歌剧院已成为国家的标志性象征。","col":["iconic building","iconic image","icon (n.)"]},{"id":1148,"topic":"culture","w":"symbolic","ipa":"/sɪmˈbɒlɪk/","pos":"adj.","cn":"象征性的","pun":"新报理课","story":"symbol（符号）：「新报理课」——新报纸上讲道理的课，全用符号图案代替文字，象征性十足。","ex":"Colours carry symbolic meanings that differ widely between cultures.","exCn":"颜色所带的象征意义在不同文化间差异很大。","col":["symbolic meaning","symbolic gesture","symbolise (v.)"]},{"id":1149,"topic":"culture","w":"portrait","ipa":"/ˈpɔːtreɪt/","pos":"n.","cn":"肖像；画像","pun":"泼吹特","story":"画家往画布上「泼」颜料，「吹」一口气，人脸就「特」别像了——肖像画。","ex":"Portraits were once the only way wealthy families could record their appearance.","exCn":"肖像画曾是富裕家庭记录容貌的唯一方式。","col":["paint a portrait","self-portrait","portrait gallery"]},{"id":1150,"topic":"culture","w":"landscape","ipa":"/ˈlændskeɪp/","pos":"n.","cn":"风景；风景画","pun":"懒得死盖扑","story":"land（土地）+ scape（景色）：画家「懒得死盖扑」——懒得盖房子，扑在野外画风景画。","ex":"Landscape painting flourished as artists began working outdoors.","exCn":"随着艺术家开始户外作画，风景画兴盛起来。","col":["landscape painting","cultural landscape","urban landscape"]},{"id":1151,"topic":"culture","w":"canvas","ipa":"/ˈkænvəs/","pos":"n.","cn":"画布；帆布","pun":"看我是","story":"画家指着空白画布说：「看我是」怎么把它变成杰作的。","ex":"The artist works on huge canvases that fill an entire gallery wall.","exCn":"这位艺术家在能占满整面画廊墙的巨型画布上创作。","col":["oil on canvas","blank canvas","canvas bag"]},{"id":1152,"topic":"culture","w":"mural","ipa":"/ˈmjʊərəl/","pos":"n.","cn":"壁画","pun":"谬肉","story":"mur（墙）：墙上的画。「谬肉」——墙上画了块肉，狗天天来舔，谬得离谱——壁画太逼真。","ex":"Murals in poor neighbourhoods often express the community's hopes and grievances.","exCn":"贫困社区的壁画常表达社区的希望与不满。","col":["paint a mural","street mural","muralist (n.)"]},{"id":1153,"topic":"culture","w":"graffiti","ipa":"/ɡrəˈfiːti/","pos":"n.","cn":"涂鸦","pun":"哥飞踢","story":"graph（写）：「哥飞踢」——哥飞起一脚踢翻油漆桶，墙上溅出一片涂鸦。","ex":"Some cities now treat graffiti as street art rather than vandalism.","exCn":"一些城市现在把涂鸦视为街头艺术而非破坏行为。","col":["graffiti artist","covered in graffiti","street art"]},{"id":1154,"topic":"culture","w":"installation","ipa":"/ˌɪnstəˈleɪʃn/","pos":"n.","cn":"装置艺术；安装","pun":"硬死道累省","story":"install（安装）：艺术家「硬死道累省」——硬是把一条铁道搬进展厅，累得省了午饭，做成装置艺术。","ex":"Video installations now occupy as much gallery space as traditional paintings.","exCn":"影像装置如今占据的展厅空间与传统绘画一样多。","col":["art installation","installation artist","install (v.)"]},{"id":1155,"topic":"culture","w":"exhibit","ipa":"/ɪɡˈzɪbɪt/","pos":"v./n.","cn":"展出；展品","pun":"一个子比特","story":"ex（外）+ hibit（拿）：拿出去给人看。「一个子比特」——一个子就是一比特，拿出去展示给大家。","ex":"The museum will exhibit works that have never been seen outside Italy.","exCn":"博物馆将展出从未在意大利以外展示过的作品。","col":["exhibit paintings","on exhibit","exhibitor (n.)"]},{"id":1156,"topic":"culture","w":"auction","ipa":"/ˈɔːkʃn/","pos":"n./v.","cn":"拍卖","pun":"哦克省","story":"「哦，克省」——克省长举牌喊价，一锤定音，名画拍卖成交。","ex":"A single painting sold at auction for more than the museum's annual budget.","exCn":"一幅画的拍卖价超过了博物馆的年度预算。","col":["art auction","sell at auction","auction house"]},{"id":1157,"topic":"culture","w":"collector","ipa":"/kəˈlektə(r)/","pos":"n.","cn":"收藏家","pun":"可累课特","story":"collect（收集）的人：收藏家「可累课特」——为了收一张老课本，累得特别惨。","ex":"Private collectors often lend works to public museums for major exhibitions.","exCn":"私人收藏家常把作品借给公立博物馆办大型展览。","col":["art collector","private collector","collection (n.)"]},{"id":1158,"topic":"culture","w":"critic","ipa":"/ˈkrɪtɪk/","pos":"n.","cn":"评论家；批评者","pun":"克踢课","story":"评论家「克踢课」——上来就克制不住地踢开一堂课，专挑毛病，这就是批评家。","ex":"Critics play a vital role in helping the public judge new artistic work.","exCn":"评论家在帮助公众评判新艺术作品方面起重要作用。","col":["art critic","film critic","criticism (n.)"]},{"id":1159,"topic":"culture","w":"acclaim","ipa":"/əˈkleɪm/","pos":"n./v.","cn":"赞誉；称赞","pun":"饿克累母","story":"ac（向）+ claim（喊）：对着你喊好。「饿克累母」——饿着累着的母亲一上台唱歌，全场高声称赞。","ex":"The novel received critical acclaim but sold very few copies.","exCn":"这部小说获得评论界赞誉，但销量很少。","col":["critical acclaim","widely acclaimed","win acclaim"]},{"id":1160,"topic":"culture","w":"renowned","ipa":"/rɪˈnaʊnd/","pos":"adj.","cn":"著名的；有名望的","pun":"日闹的","story":"re（再）+ nown（命名）：名字被反复提起。「日闹的」——他日日被人闹着要签名，太著名了。","ex":"The city is renowned for its opera house and annual music festival.","exCn":"这座城市因歌剧院和年度音乐节而闻名。","col":["world-renowned","renowned for","renown (n.)"]},{"id":1161,"topic":"culture","w":"anonymous","ipa":"/əˈnɒnɪməs/","pos":"adj.","cn":"匿名的；无名的","pun":"饿闹你么死","story":"an（无）+ onym（名字）：没有名字。「饿闹你么死」——有人匿名写信骂我，饿了闹你怎么不去死？可就是不知道谁写的。","ex":"Many folk songs were composed by anonymous singers whose names were never recorded.","exCn":"许多民歌由无名歌手创作，他们的名字从未被记录。","col":["remain anonymous","anonymous donor","anonymity (n.)"]},{"id":1162,"topic":"culture","w":"pseudonym","ipa":"/ˈsjuːdənɪm/","pos":"n.","cn":"笔名；化名","pun":"休得你么","story":"pseudo（假）+ onym（名）：假名。「休得你么」——你休想得知我是谁，我写书只用笔名。","ex":"Female authors in the nineteenth century often published under male pseudonyms.","exCn":"十九世纪的女作家常用男性笔名发表作品。","col":["write under a pseudonym","use a pseudonym","pen name"]},{"id":1163,"topic":"culture","w":"commemorate","ipa":"/kəˈmeməreɪt/","pos":"v.","cn":"纪念；缅怀","pun":"可么么瑞特","story":"com（共同）+ memor（记忆）：大家一起记住。「可么么瑞特」——大家一起亲亲瑞特的雕像，纪念这位英雄。","ex":"The festival commemorates the founding of the city three centuries ago.","exCn":"这个节日纪念三百年前城市的建立。","col":["commemorate the victims","commemorative (adj.)","commemoration (n.)"]},{"id":1164,"topic":"culture","w":"anniversary","ipa":"/ˌænɪˈvɜːsəri/","pos":"n.","cn":"周年纪念","pun":"爱你我色瑞","story":"anni（年）+ vers（转）：一年转一圈。「爱你，我色瑞」——结婚周年那天，我脸色瑞气地说爱你。","ex":"The museum marked its hundredth anniversary with a year of free admission.","exCn":"博物馆以一年免费开放来庆祝百年周年纪念。","col":["wedding anniversary","mark the anniversary","50th anniversary"]},{"id":1165,"topic":"culture","w":"pilgrimage","ipa":"/ˈpɪlɡrɪmɪdʒ/","pos":"n.","cn":"朝圣；朝圣之旅","pun":"皮哥瑞米之","story":"pilgrim（朝圣者）：「皮哥瑞米之」旅——皮哥背着一袋瑞米走几千里去圣地，这就是朝圣。","ex":"Millions undertake a pilgrimage each year to sites of religious significance.","exCn":"每年有数百万人前往宗教圣地朝圣。","col":["go on a pilgrimage","make a pilgrimage to","pilgrim (n.)"]},{"id":1166,"topic":"culture","w":"sacred","ipa":"/ˈseɪkrɪd/","pos":"adj.","cn":"神圣的；宗教的","pun":"色克瑞德","story":"sacr（神圣）：「色克瑞德」——色彩克制的瑞德教堂，一进门就感觉神圣。","ex":"Sacred sites should be protected from the pressures of mass tourism.","exCn":"神圣场所应免受大众旅游的压力。","col":["sacred site","sacred text","sacred and secular"]},{"id":1167,"topic":"culture","w":"spiritual","ipa":"/ˈspɪrɪtʃuəl/","pos":"adj.","cn":"精神的；心灵的","pun":"死劈瑞吹哦","story":"spirit（精神）：「死劈瑞吹哦」——瑞吹哦不管肉体死活，只劈开精神世界追求心灵的宁静。","ex":"Music serves a spiritual purpose in almost every human culture.","exCn":"音乐在几乎所有人类文化中都有精神层面的作用。","col":["spiritual life","spiritual needs","spirituality (n.)"]},{"id":1168,"topic":"culture","w":"secular","ipa":"/ˈsekjələ(r)/","pos":"adj.","cn":"世俗的；非宗教的","pun":"色克了","story":"「色克了」——把教堂的颜色克掉，换成商场的灯光，一切都变得世俗了。","ex":"Many religious festivals have become largely secular celebrations.","exCn":"许多宗教节日已大体变成世俗的庆祝活动。","col":["secular society","secular state","secularism (n.)"]},{"id":1169,"topic":"culture","w":"worship","ipa":"/ˈwɜːʃɪp/","pos":"v./n.","cn":"崇拜；礼拜","pun":"我谁扑","story":"「我谁扑」——我看见神像就不管是谁，扑通跪下——崇拜。","ex":"Places of worship often double as centres for community activity.","exCn":"礼拜场所常兼作社区活动中心。","col":["place of worship","worship a god","worshipper (n.)"]},{"id":1170,"topic":"culture","w":"ancestor","ipa":"/ˈænsestə(r)/","pos":"n.","cn":"祖先；祖宗","pun":"俺谁死特","story":"ante（之前）：先走的人。「俺谁死特」——俺家谁去世了特别早？那是几百年前的祖先。","ex":"Many festivals honour ancestors whose names are still remembered by the family.","exCn":"许多节日纪念家族仍记得名字的祖先。","col":["distant ancestor","ancestor worship","ancestral (adj.)"]},{"id":1171,"topic":"culture","w":"descendant","ipa":"/dɪˈsendənt/","pos":"n.","cn":"后代；后裔","pun":"地深等特","story":"de（下）+ scend（爬）：向下延伸的人。「地深等特」——祖先在地深处等着特别多的后代来上香。","ex":"The descendants of the original settlers still speak the old dialect.","exCn":"最初定居者的后裔仍说着古老的方言。","col":["direct descendant","descendants of","descend from (v.)"]},{"id":1172,"topic":"culture","w":"generation","ipa":"/ˌdʒenəˈreɪʃn/","pos":"n.","cn":"一代人；世代","pun":"债呢累省","story":"gener（产生）：一代代产生。「债呢累省」——上一代的债呢，下一代累着省钱还——世代相传。","ex":"Cultural practices are passed from one generation to the next through storytelling.","exCn":"文化习俗通过讲故事一代代传下去。","col":["younger generation","generation gap","from generation to generation"]},{"id":1173,"topic":"culture","w":"kinship","ipa":"/ˈkɪnʃɪp/","pos":"n.","cn":"亲属关系；亲密关系","pun":"亲湿扑","story":"kin（亲属）+ ship：亲人一见面「亲湿扑」——亲得眼泪湿了扑在一起，这就是亲属关系。","ex":"In many traditional societies kinship determines where people live and work.","exCn":"在许多传统社会，亲属关系决定人们的居住和工作。","col":["kinship ties","a sense of kinship","kin (n.)"]},{"id":1174,"topic":"culture","w":"norm","ipa":"/nɔːm/","pos":"n.","cn":"规范；常态","pun":"闹么","story":"「闹么」？在图书馆大声闹，违反社会规范，所有人瞪你。","ex":"Social norms about dress and behaviour differ widely across cultures.","exCn":"关于着装和举止的社会规范在各文化间差异很大。","col":["social norms","cultural norms","the norm"]},{"id":1175,"topic":"culture","w":"convention","ipa":"/kənˈvenʃn/","pos":"n.","cn":"惯例；大会","pun":"肯玩省","story":"con（一起）+ vent（来）：大家一起来遵守。「肯玩省」——肯陪你玩才能省事，这是当地惯例。","ex":"Artists who break with convention are often rejected by their contemporaries.","exCn":"打破惯例的艺术家常被同时代人排斥。","col":["social convention","break with convention","conventional (adj.)"]},{"id":1176,"topic":"culture","w":"stereotype","ipa":"/ˈsteriətaɪp/","pos":"n./v.","cn":"刻板印象","pun":"死得瑞哦太扑","story":"stereo（固定）+ type（模型）：固定模板。「死得瑞哦太扑」——把瑞哦死死扑进一个模子，这就是刻板印象。","ex":"Films frequently reinforce stereotypes about people from other countries.","exCn":"电影经常强化对外国人的刻板印象。","col":["cultural stereotype","reinforce a stereotype","stereotypical (adj.)"]},{"id":1177,"topic":"culture","w":"prejudice","ipa":"/ˈpredʒədɪs/","pos":"n.","cn":"偏见；成见","pun":"普瑞纠地死","story":"pre（先）+ judic（判断）：提前下判断。「普瑞纠地死」——普瑞一见对方就纠着不放，判他地死，这就是偏见。","ex":"Exposure to other cultures through travel can reduce prejudice.","exCn":"通过旅行接触其他文化可以减少偏见。","col":["racial prejudice","prejudice against","prejudiced (adj.)"]},{"id":1178,"topic":"culture","w":"tolerance","ipa":"/ˈtɒlərəns/","pos":"n.","cn":"宽容；容忍","pun":"托了人死","story":"toler（忍受）：「托了人死」——托着别人的错不计较，宽容得像圣人。","ex":"Multicultural education aims to promote tolerance of different beliefs.","exCn":"多元文化教育旨在促进对不同信仰的宽容。","col":["religious tolerance","promote tolerance","tolerant (adj.)"]},{"id":1179,"topic":"culture","w":"cosmopolitan","ipa":"/ˌkɒzməˈpɒlɪtən/","pos":"adj.","cn":"世界性的；国际化的","pun":"靠死么剖了疼","story":"cosmo（宇宙）+ polit（城市）：世界之城。「靠死么剖了疼」——各国人靠在一起，剖开来看，谁都不疼——国际化大都市。","ex":"London's cosmopolitan character is reflected in its food, music and languages.","exCn":"伦敦的国际化特征体现在饮食、音乐和语言上。","col":["cosmopolitan city","cosmopolitan atmosphere","cosmopolitanism (n.)"]},{"id":1180,"topic":"culture","w":"erode","ipa":"/ɪˈrəʊd/","pos":"v.","cn":"侵蚀；逐渐削弱","pun":"一肉的","story":"e（出）+ rod（啃）：一点点啃掉。「一肉的」——老鼠一口肉一口肉地啃，传统就这样被侵蚀了。","ex":"Global media has eroded many local traditions in a single generation.","exCn":"全球媒体在一代人之内侵蚀了许多地方传统。","col":["erode traditions","gradually erode","erosion (n.)"]},{"id":1181,"topic":"culture","w":"revive","ipa":"/rɪˈvaɪv/","pos":"v.","cn":"复兴；复活","pun":"日外舞","story":"re（再）+ viv（活）：再活过来。「日外舞」——年轻人日日在外跳老舞，让失传的舞蹈复活了。","ex":"Efforts to revive the language have succeeded in a handful of villages.","exCn":"复兴这门语言的努力在少数村庄取得了成功。","col":["revive a tradition","revive interest in","revival (n.)"]},{"id":1182,"topic":"culture","w":"inherit","ipa":"/ɪnˈherɪt/","pos":"v.","cn":"继承","pun":"硬害瑞特","story":"in（进）+ herit（继承人）：「硬害瑞特」——瑞特硬是被害惨了，因为继承的老房子要交巨额税。","ex":"Children inherit not only property but also the values of their parents.","exCn":"孩子继承的不仅是财产，还有父母的价值观。","col":["inherit a tradition","inherit from","inheritance (n.)"]},{"id":1183,"topic":"culture","w":"legacy","ipa":"/ˈleɡəsi/","pos":"n.","cn":"遗产；遗留问题","pun":"累哥西","story":"leg（委托）：委托给后人的东西。「累哥西」——累了一辈子的哥哥去了西天，留下一份文化遗产。","ex":"The Olympic Games leave a cultural legacy that lasts long after the closing ceremony.","exCn":"奥运会留下的文化遗产在闭幕式后长久延续。","col":["cultural legacy","leave a legacy","lasting legacy"]},{"id":1184,"topic":"culture","w":"nostalgia","ipa":"/nɒˈstældʒə/","pos":"n.","cn":"怀旧；乡愁","pun":"闹死头假","story":"nost（回家）+ algia（痛）：想家想到痛。「闹死头假」——请了假回老家，脑子里全是童年——怀旧。","ex":"Nostalgia for the past drives the popularity of vintage fashion and music.","exCn":"对过去的怀旧推动了复古时尚和音乐的流行。","col":["a wave of nostalgia","nostalgia for","nostalgic (adj.)"]},{"id":1185,"topic":"culture","w":"sentimental","ipa":"/ˌsentɪˈmentl/","pos":"adj.","cn":"多愁善感的；感情用事的","pun":"扇踢门头","story":"sentiment（情感）：「扇踢门头」——看完老电影，感动得又扇又踢门头，太多愁善感了。","ex":"Old photographs have little market value but enormous sentimental value.","exCn":"老照片市场价值不高，情感价值却巨大。","col":["sentimental value","sentimental attachment","sentiment (n.)"]},{"id":1186,"topic":"culture","w":"souvenir","ipa":"/ˌsuːvəˈnɪə(r)/","pos":"n.","cn":"纪念品","pun":"酥味腻儿","story":"法语「记忆」：「酥味腻儿」——旅游买的酥饼吃到腻，包装盒却留着当纪念品。","ex":"Souvenir shops selling mass-produced goods now surround most historic sites.","exCn":"售卖批量商品的纪念品店如今包围了大多数历史景点。","col":["souvenir shop","buy a souvenir","as a souvenir"]},{"id":1187,"topic":"culture","w":"archaeology","ipa":"/ˌɑːkiˈɒlədʒi/","pos":"n.","cn":"考古学","pun":"啊克哦乐机","story":"archaeo（古代）+ logy（学）：「啊，克哦乐机」——挖出一台古代乐机，考古学家乐坏了。","ex":"Archaeology reveals aspects of daily life that written history ignores.","exCn":"考古学揭示了文字历史忽略的日常生活。","col":["archaeological site","archaeologist (n.)","archaeological dig"]},{"id":1188,"topic":"culture","w":"relic","ipa":"/ˈrelɪk/","pos":"n.","cn":"遗物；遗迹","pun":"瑞里克","story":"re（回）+ lic（留下）：留下来的东西。「瑞里克」——瑞士里挖出的克数很轻的一枚古币，是罗马时代的遗物。","ex":"Relics from the shipwreck are displayed in the maritime museum.","exCn":"沉船遗物陈列在海事博物馆里。","col":["ancient relic","religious relic","a relic of the past"]},{"id":1189,"topic":"culture","w":"dynasty","ipa":"/ˈdɪnəsti/","pos":"n.","cn":"王朝；朝代","pun":"底那是踢","story":"「底那是踢」——考古队挖到底，那是一块被踢碎的王朝玉玺。","ex":"Pottery styles allow archaeologists to date artefacts to a particular dynasty.","exCn":"陶器风格让考古学家能把文物断代到具体朝代。","col":["Ming dynasty","ruling dynasty","dynastic (adj.)"]},{"id":1190,"topic":"culture","w":"civilisation","ipa":"/ˌsɪvəlaɪˈzeɪʃn/","pos":"n.","cn":"文明","pun":"西围来贼省","story":"civil（公民）：公民社会。「西围来贼省」——西边围墙来了贼，全省人一起修城墙，这就是文明的开始。","ex":"Writing is regarded as one of the defining achievements of early civilisation.","exCn":"文字被视为早期文明的标志性成就之一。","col":["ancient civilisation","Western civilisation","civilised (adj.)"]},{"id":1191,"topic":"culture","w":"linguistic","ipa":"/lɪŋˈɡwɪstɪk/","pos":"adj.","cn":"语言的；语言学的","pun":"领鬼是踢课","story":"lingu（舌头）：「领鬼是踢课」——领着一群鬼上语言课，个个舌头打结——语言的问题。","ex":"Linguistic diversity is declining as dominant languages spread through the media.","exCn":"随着强势语言通过媒体传播，语言多样性正在下降。","col":["linguistic diversity","linguistic skills","linguistics (n.)"]},{"id":1192,"topic":"culture","w":"proverb","ipa":"/ˈprɒvɜːb/","pos":"n.","cn":"谚语；格言","pun":"扑肉喂不","story":"pro（前）+ verb（词）：摆在前面的话。「扑肉喂不」——奶奶总说「扑上去的肉喂不饱贪心的狗」——这就是谚语。","ex":"Proverbs condense the accumulated wisdom of a culture into a single sentence.","exCn":"谚语把一种文化的累积智慧浓缩成一句话。","col":["an old proverb","Chinese proverb","proverbial (adj.)"]},{"id":1193,"topic":"culture","w":"hospitality","ipa":"/ˌhɒspɪˈtæləti/","pos":"n.","cn":"好客；款待","pun":"好死比太累踢","story":"hospit（客人）：「好死比太累踢」——主人好客到死，比太累了还要踢开门迎客，这就是款待。","ex":"Hospitality towards strangers is a core value in many rural communities.","exCn":"对陌生人的好客是许多农村社区的核心价值观。","col":["warm hospitality","hospitality industry","hospitable (adj.)"]},{"id":1194,"topic":"culture","w":"decorative","ipa":"/ˈdekərətɪv/","pos":"adj.","cn":"装饰性的","pun":"待扣热踢舞","story":"decor（装饰）：「待扣热踢舞」——等着扣上装饰的花边，就去跳热烈的踢踏舞——纯装饰性。","ex":"Decorative arts such as ceramics were long dismissed as inferior to painting.","exCn":"陶瓷等装饰艺术长期被贬为不如绘画。","col":["decorative arts","purely decorative","decoration (n.)"]},{"id":1195,"topic":"psych","w":"anxious","ipa":"/ˈæŋkʃəs/","pos":"adj.","cn":"焦虑的；渴望的","pun":"俺可谢死","story":"「俺可谢死」——面试前紧张到想谢天谢地快结束，这就是焦虑的样子。","ex":"Many graduates feel anxious about entering a highly competitive job market.","exCn":"许多毕业生对进入竞争激烈的就业市场感到焦虑。","col":["anxious about","anxious to do sth","anxiety (n.)"]},{"id":1196,"topic":"psych","w":"stress","ipa":"/stres/","pos":"n./v.","cn":"压力；强调","pun":"死揣死","story":"把烦恼「死揣」在心里，揣到「死」，压力就来了；老师则爱强调重点。","ex":"Workplace stress has been linked to a range of physical and mental health problems.","exCn":"职场压力与一系列身心健康问题有关。","col":["under stress","stress management","stressful (adj.)"]},{"id":1197,"topic":"psych","w":"optimistic","ipa":"/ˌɒptɪˈmɪstɪk/","pos":"adj.","cn":"乐观的","pun":"我不迷失踢克","story":"「我不迷失，踢克」——迷路也不慌，还踢着石子往前走，够乐观。","ex":"Young people tend to be more optimistic about technological change than older generations.","exCn":"年轻人往往比老一辈对技术变革更乐观。","col":["optimistic about","cautiously optimistic","optimism (n.)"]},{"id":1198,"topic":"psych","w":"pessimistic","ipa":"/ˌpesɪˈmɪstɪk/","pos":"adj.","cn":"悲观的","pun":"配色迷失踢克","story":"「配色迷失踢克」——衣服配色都能迷失，觉得啥都不行，太悲观了。","ex":"A pessimistic outlook can discourage people from pursuing long-term goals.","exCn":"悲观的心态会让人不愿追求长期目标。","col":["pessimistic about","overly pessimistic","pessimism (n.)"]},{"id":1199,"topic":"psych","w":"confident","ipa":"/ˈkɒnfɪdənt/","pos":"adj.","cn":"自信的；确信的","pun":"看啡等特","story":"「看啡等特」——看着咖啡等待特别的人，姿态从容，一脸自信。","ex":"Public speaking training helps students become more confident in expressing their ideas.","exCn":"演讲训练帮助学生更自信地表达想法。","col":["confident in/about","self-confident","confidence (n.)"]},{"id":1200,"topic":"psych","w":"introverted","ipa":"/ˈɪntrəvɜːtɪd/","pos":"adj.","cn":"内向的","pun":"印着我忒的","story":"intro（向内）+ vert（转）：「印着我忒的」，把心思都印在自己心里，内向。","ex":"Introverted students may prefer written assignments to group presentations.","exCn":"内向的学生可能更喜欢书面作业而非小组展示。","col":["introverted personality","introvert (n.)","extroverted (adj.)"]},{"id":1201,"topic":"psych","w":"extroverted","ipa":"/ˈekstrəvɜːtɪd/","pos":"adj.","cn":"外向的","pun":"爱可是脱我忒的","story":"extro（向外）+ vert（转）：「爱可是脱我忒的」，什么都往外说，外向。","ex":"Extroverted people often thrive in jobs that involve constant social interaction.","exCn":"外向的人往往在需要不断社交的工作中表现出色。","col":["extroverted personality","extrovert (n.)","outgoing (adj.)"]},{"id":1202,"topic":"psych","w":"temperament","ipa":"/ˈtemprəmənt/","pos":"n.","cn":"性情；气质","pun":"贪婆门特","story":"「贪婆门特」——贪吃的婆婆进门就特别吵，这就是她的性情。","ex":"A child's temperament is shaped by both genetic factors and early experiences.","exCn":"孩子的性情由遗传因素和早期经历共同塑造。","col":["calm temperament","artistic temperament","temperamental (adj.)"]},{"id":1203,"topic":"psych","w":"mood","ipa":"/muːd/","pos":"n.","cn":"心情；情绪","pun":"木木的","story":"心情不好时整个人「木木的」，呆呆的，mood 就是心情。","ex":"Regular exercise has been shown to improve mood and reduce feelings of stress.","exCn":"研究表明规律运动能改善心情并减轻压力感。","col":["in a good mood","mood swings","moody (adj.)"]},{"id":1204,"topic":"psych","w":"empathy","ipa":"/ˈempəθi/","pos":"n.","cn":"共情；同理心","pun":"俺怕死","story":"「俺怕死」——你说怕，我也真心感到你的怕，这就是共情。","ex":"Reading fiction is believed to develop empathy by exposing readers to other perspectives.","exCn":"人们认为阅读小说能通过接触不同视角来培养共情能力。","col":["show empathy","empathy for/with","empathetic (adj.)"]},{"id":1205,"topic":"psych","w":"sympathy","ipa":"/ˈsɪmpəθi/","pos":"n.","cn":"同情；支持","pun":"心怕死","story":"「心怕死」——看你受苦我心里替你难过，这是同情。","ex":"The public expressed great sympathy for the victims of the flood.","exCn":"公众对洪灾受害者表达了极大的同情。","col":["have sympathy for","express sympathy","sympathetic (adj.)"]},{"id":1206,"topic":"psych","w":"compassion","ipa":"/kəmˈpæʃn/","pos":"n.","cn":"怜悯；同情心","pun":"肯派神","story":"「肯派神」——肯派神仙下凡救苦救难，是因为有怜悯之心。","ex":"Nurses are expected to treat every patient with compassion and respect.","exCn":"护士应当以怜悯和尊重对待每一位病人。","col":["show compassion","compassion for","compassionate (adj.)"]},{"id":1207,"topic":"psych","w":"generous","ipa":"/ˈdʒenərəs/","pos":"adj.","cn":"慷慨的；大方的","pun":"这呢弱死","story":"「这呢弱死」——看到弱者就想给钱，太大方了，慷慨。","ex":"Generous donors have funded scholarships for students from low-income families.","exCn":"慷慨的捐赠者为低收入家庭学生设立了奖学金。","col":["generous with","generous donation","generosity (n.)"]},{"id":1208,"topic":"psych","w":"stubborn","ipa":"/ˈstʌbən/","pos":"adj.","cn":"固执的；顽固的","pun":"死大笨","story":"「死大笨」——死活不听劝的大笨蛋，固执。","ex":"Stubborn attitudes among older employees can slow down organisational change.","exCn":"年长员工的固执态度会拖慢组织变革。","col":["stubborn refusal","stubbornly (adv.)","obstinate (adj.)"]},{"id":1209,"topic":"psych","w":"arrogant","ipa":"/ˈærəɡənt/","pos":"adj.","cn":"傲慢的；自大的","pun":"爱弱跟特","story":"「爱弱跟特」——爱找弱的人跟着他，好显得自己特别，傲慢。","ex":"Arrogant leaders rarely listen to feedback from their subordinates.","exCn":"傲慢的领导者很少听取下属的反馈。","col":["arrogant attitude","arrogance (n.)","humble (adj.)"]},{"id":1210,"topic":"psych","w":"humble","ipa":"/ˈhʌmbl/","pos":"adj.","cn":"谦逊的；卑微的","pun":"憨薄脸","story":"「憨薄脸」——憨憨的、脸皮薄，从不吹牛，谦逊。","ex":"Despite his success, the scientist remained humble about his achievements.","exCn":"尽管功成名就，这位科学家对自己的成就依然谦逊。","col":["humble background","remain humble","humility (n.)"]},{"id":1211,"topic":"psych","w":"modest","ipa":"/ˈmɒdɪst/","pos":"adj.","cn":"谦虚的；适度的","pun":"莫地死特","story":"「莫地死特」——不要死撑显摆，莫要吹得太特别，谦虚一点。","ex":"Even a modest increase in daily exercise can significantly improve mental health.","exCn":"即使每天运动量适度增加，也能显著改善心理健康。","col":["modest about","modest income","modesty (n.)"]},{"id":1212,"topic":"psych","w":"sensitive","ipa":"/ˈsensətɪv/","pos":"adj.","cn":"敏感的；体贴的","pun":"扇色踢舞","story":"「扇色踢舞」——扇子变色、有人踢舞步，她都能察觉，敏感。","ex":"Teachers need to be sensitive to the emotional needs of vulnerable students.","exCn":"教师需要对脆弱学生的情感需求保持敏感。","col":["sensitive to","highly sensitive","sensitivity (n.)"]},{"id":1213,"topic":"psych","w":"frustration","ipa":"/frʌˈstreɪʃn/","pos":"n.","cn":"挫败感；沮丧","pun":"服啦死追神","story":"「服啦死追神」——死命追神仙还是追不上，服了，满心挫败。","ex":"Repeated failure to find work can lead to deep frustration and loss of confidence.","exCn":"反复找不到工作会导致深深的挫败感和自信心丧失。","col":["a sense of frustration","express frustration","frustrated (adj.)"]},{"id":1214,"topic":"psych","w":"frustrated","ipa":"/frʌˈstreɪtɪd/","pos":"adj.","cn":"沮丧的；受挫的","pun":"服啦死追替的","story":"「服啦死追替的」——死命追赶还被人替换掉，服了，太受挫。","ex":"Many commuters feel frustrated by the unreliable public transport system.","exCn":"许多通勤者对不可靠的公共交通系统感到沮丧。","col":["frustrated with/by","feel frustrated","frustrating (adj.)"]},{"id":1215,"topic":"psych","w":"overwhelmed","ipa":"/ˌəʊvəˈwelmd/","pos":"adj.","cn":"不堪重负的","pun":"欧我威武的","story":"over（超过）+ whelm（淹没）：「欧我威武的」水漫过头顶，再威武也被淹没。","ex":"New parents often feel overwhelmed by the demands of caring for a baby.","exCn":"新手父母常常被照顾婴儿的重担压得喘不过气。","col":["overwhelmed by","feel overwhelmed","overwhelming (adj.)"]},{"id":1216,"topic":"psych","w":"contentment","ipa":"/kənˈtentmənt/","pos":"n.","cn":"满足；知足","pun":"肯藤门特","story":"「肯藤门特」——门口有藤椅能躺就特满足，知足常乐。","ex":"Research suggests that contentment depends more on relationships than on income.","exCn":"研究表明，满足感更多取决于人际关系而非收入。","col":["a sense of contentment","find contentment","content (adj.)"]},{"id":1217,"topic":"psych","w":"gratitude","ipa":"/ˈɡrætɪtjuːd/","pos":"n.","cn":"感激；感恩","pun":"过了踢丢的","story":"「过了踢丢的」——你帮我找回踢丢的球，我心里满是感激。","ex":"Keeping a gratitude journal has been shown to increase overall life satisfaction.","exCn":"研究表明写感恩日记能提高整体生活满意度。","col":["express gratitude","gratitude for","grateful (adj.)"]},{"id":1218,"topic":"psych","w":"satisfaction","ipa":"/ˌsætɪsˈfækʃn/","pos":"n.","cn":"满意；满足","pun":"洒踢死发克神","story":"「洒踢死发克神」——发工资那天洒钱踢球，满意得像神仙。","ex":"Job satisfaction is closely linked to employees' sense of autonomy and recognition.","exCn":"工作满意度与员工的自主感和被认可感密切相关。","col":["job satisfaction","customer satisfaction","satisfied (adj.)"]},{"id":1219,"topic":"psych","w":"fulfilment","ipa":"/fʊlˈfɪlmənt/","pos":"n.","cn":"成就感；实现","pun":"服飞门特","story":"full（满）+ fill（填）：「服飞门特」心被填满、开心得要飞，是成就感。","ex":"Many people seek fulfilment through meaningful work rather than high salaries.","exCn":"许多人通过有意义的工作而非高薪来寻求成就感。","col":["personal fulfilment","a sense of fulfilment","fulfil (v.)"]},{"id":1220,"topic":"psych","w":"insecure","ipa":"/ˌɪnsɪˈkjʊə(r)/","pos":"adj.","cn":"缺乏安全感的；不牢固的","pun":"印死求儿","story":"in-（不）+ secure（安全）：「印死求儿」印子刻到死也求个安全，没安全感。","ex":"Insecure teenagers are more likely to seek approval through social media likes.","exCn":"缺乏安全感的青少年更可能通过社交媒体点赞寻求认可。","col":["feel insecure","insecure about","insecurity (n.)"]},{"id":1221,"topic":"psych","w":"jealous","ipa":"/ˈdʒeləs/","pos":"adj.","cn":"嫉妒的；吃醋的","pun":"这乐死","story":"「这乐死」——看别人乐死了，自己心里酸溜溜，嫉妒。","ex":"Children may become jealous when a new sibling receives most of the parents' attention.","exCn":"当新生的弟妹得到父母大部分关注时，孩子可能会嫉妒。","col":["jealous of","jealousy (n.)","envious (adj.)"]},{"id":1222,"topic":"psych","w":"envy","ipa":"/ˈenvi/","pos":"n./v.","cn":"羡慕；嫉妒","pun":"恩V手","story":"「恩V手」——朋友比了个V字胜利手势，我看着又恩又羡慕。","ex":"Social media often fuels envy by showing only the highlights of other people's lives.","exCn":"社交媒体只展示别人生活的高光，常常助长羡慕嫉妒。","col":["envy of","the envy of","envious (adj.)"]},{"id":1223,"topic":"psych","w":"resentment","ipa":"/rɪˈzentmənt/","pos":"n.","cn":"怨恨；不满","pun":"日怎门特","story":"「日怎门特」——天天问怎么门特别难开，憋出一肚子怨恨。","ex":"Unequal pay can create deep resentment among employees doing the same job.","exCn":"同工不同酬会在员工中造成深深的不满。","col":["feel resentment","resentment towards","resent (v.)"]},{"id":1224,"topic":"psych","w":"grief","ipa":"/ɡriːf/","pos":"n.","cn":"悲痛；悲伤","pun":"归夫泪","story":"「归夫泪」——丈夫归来时只剩骨灰，妻子泪流满面，悲痛欲绝。","ex":"Counselling services help people process grief after losing a loved one.","exCn":"心理咨询帮助人们在失去亲人后处理悲痛。","col":["overcome grief","grief and loss","grieve (v.)"]},{"id":1225,"topic":"psych","w":"tolerate","ipa":"/ˈtɒləreɪt/","pos":"v.","cn":"容忍；忍受","pun":"陀螺瑞特","story":"「陀螺瑞特」——弟弟在客厅抽陀螺吵翻天，姐姐忍着不发火，容忍。","ex":"A healthy society should tolerate different opinions and lifestyles.","exCn":"一个健康的社会应当容忍不同的观点和生活方式。","col":["tolerate criticism","tolerate behaviour","tolerance (n.)"]},{"id":1226,"topic":"psych","w":"tolerant","ipa":"/ˈtɒlərənt/","pos":"adj.","cn":"宽容的；容忍的","pun":"陀螺让特","story":"「陀螺让特」——玩陀螺的孩子撞到你，你特别大度地让开，宽容。","ex":"Younger generations tend to be more tolerant of cultural differences.","exCn":"年轻一代往往对文化差异更加宽容。","col":["tolerant of","tolerant attitude","tolerance (n.)"]},{"id":1227,"topic":"psych","w":"patient","ipa":"/ˈpeɪʃnt/","pos":"adj./n.","cn":"有耐心的；病人","pun":"陪身特","story":"「陪身特」——护士特别耐心地陪在病人身边，既是耐心也是病人。","ex":"Effective teachers are patient with students who learn at a slower pace.","exCn":"优秀的教师对学习较慢的学生很有耐心。","col":["patient with","be patient","patience (n.)"]},{"id":1228,"topic":"psych","w":"impulsive","ipa":"/ɪmˈpʌlsɪv/","pos":"adj.","cn":"冲动的","pun":"硬泼西服","story":"「硬泼西服」——一冲动就把水硬泼在别人西服上，太冲动了。","ex":"Impulsive spending is a common problem among young people with credit cards.","exCn":"冲动消费是持有信用卡的年轻人常见的问题。","col":["impulsive behaviour","impulsive decision","impulse (n.)"]},{"id":1229,"topic":"psych","w":"spontaneous","ipa":"/spɒnˈteɪniəs/","pos":"adj.","cn":"自发的；随性的","pun":"死胖忒你饿死","story":"「死胖忒你饿死」——胖子随性地一口气吃光，还笑你饿着，自发随性。","ex":"Spontaneous acts of kindness can improve the mood of both giver and receiver.","exCn":"自发的善举能改善施与者和接受者双方的心情。","col":["spontaneous reaction","spontaneously (adv.)","spontaneity (n.)"]},{"id":1230,"topic":"psych","w":"cautious","ipa":"/ˈkɔːʃəs/","pos":"adj.","cn":"谨慎的；小心的","pun":"靠社死","story":"「靠社死」——怕社死，说话走路都小心翼翼，谨慎。","ex":"Investors became more cautious after the financial crisis of 2008.","exCn":"2008年金融危机后，投资者变得更加谨慎。","col":["cautious about","cautious approach","caution (n.)"]},{"id":1231,"topic":"psych","w":"reckless","ipa":"/ˈrekləs/","pos":"adj.","cn":"鲁莽的；不计后果的","pun":"瑞克累死","story":"「瑞克累死」——瑞克飙车不要命，累死也不管后果，鲁莽。","ex":"Reckless driving among young men remains a leading cause of road accidents.","exCn":"年轻男性的鲁莽驾驶仍是交通事故的主要原因。","col":["reckless behaviour","reckless driving","recklessly (adv.)"]},{"id":1232,"topic":"psych","w":"determined","ipa":"/dɪˈtɜːmɪnd/","pos":"adj.","cn":"坚定的；下定决心的","pun":"地特敏的","story":"「地特敏的」——脚踩在地上特别敏捷坚定，认准了就不回头。","ex":"Determined students often succeed despite limited resources and support.","exCn":"意志坚定的学生即使资源和支持有限也常能成功。","col":["determined to do","determination (n.)","strong-willed (adj.)"]},{"id":1233,"topic":"psych","w":"persistent","ipa":"/pəˈsɪstənt/","pos":"adj.","cn":"坚持不懈的；持续的","pun":"扑西斯疼特","story":"「扑西斯疼特」——扑向西边一直跑，腿疼也不停，坚持不懈。","ex":"Persistent effort over many years is usually required to master a musical instrument.","exCn":"精通一门乐器通常需要多年持续不懈的努力。","col":["persistent effort","persistent problem","persistence (n.)"]},{"id":1234,"topic":"psych","w":"perseverance","ipa":"/ˌpɜːsɪˈvɪərəns/","pos":"n.","cn":"毅力；坚持","pun":"扑死为人死","story":"「扑死为人死」——为了目标扑上去哪怕拼死，这就是毅力。","ex":"Perseverance, rather than talent, often distinguishes successful people from others.","exCn":"区分成功者与他人的往往是毅力而非天赋。","col":["show perseverance","perseverance and hard work","persevere (v.)"]},{"id":1235,"topic":"psych","w":"meticulous","ipa":"/məˈtɪkjələs/","pos":"adj.","cn":"一丝不苟的；细致的","pun":"么踢球乐死","story":"「么踢球乐死」——踢球前把鞋带系了三遍，细致到令人乐死。","ex":"Scientific research requires meticulous attention to detail and accurate records.","exCn":"科学研究需要一丝不苟的细节关注和准确记录。","col":["meticulous planning","meticulously (adv.)","thorough (adj.)"]},{"id":1236,"topic":"psych","w":"reliable","ipa":"/rɪˈlaɪəbl/","pos":"adj.","cn":"可靠的；可信赖的","pun":"日来啊步","story":"rely（依靠）+ able：「日来啊步」每天准时来，一步不差，可靠。","ex":"Employers value reliable workers who consistently deliver what they promise.","exCn":"雇主看重那些始终兑现承诺的可靠员工。","col":["reliable source","highly reliable","reliability (n.)"]},{"id":1237,"topic":"psych","w":"trustworthy","ipa":"/ˈtrʌstwɜːði/","pos":"adj.","cn":"值得信赖的","pun":"揣死特我记","story":"trust（信任）+ worthy（值得）：「揣死特我记」把秘密揣在心里，特别值得信赖。","ex":"Trustworthy friends are essential for maintaining good mental health.","exCn":"值得信赖的朋友对保持良好心理健康至关重要。","col":["trustworthy source","trustworthy person","trust (n./v.)"]},{"id":1238,"topic":"psych","w":"loyal","ipa":"/ˈlɔɪəl/","pos":"adj.","cn":"忠诚的","pun":"老友诶","story":"「老友诶」——几十年的老友，风雨同舟，忠诚。","ex":"Loyal employees are often rewarded with promotions and long-term security.","exCn":"忠诚的员工往往获得晋升和长期保障。","col":["loyal to","loyal customer","loyalty (n.)"]},{"id":1239,"topic":"psych","w":"sincere","ipa":"/sɪnˈsɪə(r)/","pos":"adj.","cn":"真诚的；诚挚的","pun":"新谢啊","story":"「新谢啊」——新年发自内心地一声感谢，真心实意，真诚。","ex":"A sincere apology can repair relationships damaged by misunderstanding.","exCn":"真诚的道歉能修复因误解而受损的关系。","col":["sincere apology","sincerely (adv.)","sincerity (n.)"]},{"id":1240,"topic":"psych","w":"cynical","ipa":"/ˈsɪnɪkl/","pos":"adj.","cn":"愤世嫉俗的；怀疑的","pun":"死你口","story":"「死你口」——嘴巴毒得能气死你，什么都看不惯，愤世嫉俗。","ex":"Voters have become increasingly cynical about politicians' promises.","exCn":"选民对政客的承诺越来越怀疑。","col":["cynical about","cynical view","cynicism (n.)"]},{"id":1241,"topic":"psych","w":"sceptical","ipa":"/ˈskeptɪkl/","pos":"adj.","cn":"怀疑的；持怀疑态度的","pun":"死给踢口","story":"「死给踢口」——死都不信，非要踢一脚验证，持怀疑态度。","ex":"Many scientists remain sceptical about claims that cannot be tested experimentally.","exCn":"许多科学家对无法用实验验证的说法持怀疑态度。","col":["sceptical about/of","scepticism (n.)","sceptic (n.)"]},{"id":1242,"topic":"psych","w":"curious","ipa":"/ˈkjʊəriəs/","pos":"adj.","cn":"好奇的","pun":"揪你饿死","story":"「揪你饿死」——好奇心把你揪住不放，饭都忘了吃。","ex":"Curious children ask more questions and tend to learn faster.","exCn":"好奇的孩子问更多问题，往往学得更快。","col":["curious about","curiosity (n.)","inquisitive (adj.)"]},{"id":1243,"topic":"psych","w":"imaginative","ipa":"/ɪˈmædʒɪnətɪv/","pos":"adj.","cn":"富有想象力的","pun":"一妈真呢踢舞","story":"「一妈真呢踢舞」——妈妈一边踢舞一边编故事，想象力丰富。","ex":"Imaginative play helps young children develop language and social skills.","exCn":"想象性游戏帮助幼儿发展语言和社交技能。","col":["imaginative solution","imagination (n.)","creative (adj.)"]},{"id":1244,"topic":"psych","w":"open-minded","ipa":"/ˌəʊpən ˈmaɪndɪd/","pos":"adj.","cn":"思想开明的","pun":"欧盆脉的","story":"open（开）+ mind（心）：「欧盆脉的」把心像盆一样打开，接纳一切，开明。","ex":"Travel encourages people to be more open-minded about unfamiliar cultures.","exCn":"旅行鼓励人们对陌生文化持更开放的态度。","col":["open-minded about","open-minded approach","narrow-minded (adj.)"]},{"id":1245,"topic":"psych","w":"narrow-minded","ipa":"/ˌnærəʊ ˈmaɪndɪd/","pos":"adj.","cn":"心胸狭窄的；狭隘的","pun":"呐肉脉的","story":"narrow（窄）+ mind（心）：「呐肉脉的」心眼窄得像肉里一根细血脉，狭隘。","ex":"Narrow-minded attitudes towards immigrants can hinder social integration.","exCn":"对移民的狭隘态度会阻碍社会融合。","col":["narrow-minded view","narrow-minded person","bigoted (adj.)"]},{"id":1246,"topic":"psych","w":"rigid","ipa":"/ˈrɪdʒɪd/","pos":"adj.","cn":"僵硬的；死板的","pun":"瑞机的","story":"「瑞机的」——瑞士机器人动作僵硬，规矩死板一条不改。","ex":"A rigid school timetable leaves little room for creative activities.","exCn":"死板的学校课表几乎没给创造性活动留空间。","col":["rigid rules","rigid thinking","rigidity (n.)"]},{"id":1247,"topic":"psych","w":"assertive","ipa":"/əˈsɜːtɪv/","pos":"adj.","cn":"自信果断的；坚定的","pun":"饿舌踢舞","story":"「饿舌踢舞」——饿了就直说，舌头一动像踢舞，果断自信。","ex":"Assertive communication helps employees express their needs without being aggressive.","exCn":"坚定的沟通方式帮助员工表达需求而不显得咄咄逼人。","col":["assertive behaviour","assertiveness (n.)","assert (v.)"]},{"id":1248,"topic":"psych","w":"aggressive","ipa":"/əˈɡresɪv/","pos":"adj.","cn":"好斗的；有攻击性的","pun":"饿瑰死舞","story":"「饿瑰死舞」——饿疯了的玫瑰刺谁扎谁，攻击性十足。","ex":"Violent video games are often blamed for aggressive behaviour in children.","exCn":"暴力电子游戏常被指责导致儿童的攻击性行为。","col":["aggressive behaviour","aggressively (adv.)","aggression (n.)"]},{"id":1249,"topic":"psych","w":"hostile","ipa":"/ˈhɒstaɪl/","pos":"adj.","cn":"敌对的；不友善的","pun":"好死抬儿","story":"「好死抬儿」——一见面就抬杠，恨不得对方好死，敌意满满。","ex":"A hostile working environment can seriously damage employees' mental health.","exCn":"充满敌意的工作环境会严重损害员工的心理健康。","col":["hostile to/towards","hostile environment","hostility (n.)"]},{"id":1250,"topic":"psych","w":"timid","ipa":"/ˈtɪmɪd/","pos":"adj.","cn":"胆小的；羞怯的","pun":"提米的","story":"「提米的」——小老鼠提米一见猫就躲，胆小羞怯。","ex":"Timid students may hesitate to ask questions in large lecture halls.","exCn":"胆小的学生在大讲堂里可能不敢提问。","col":["timid child","timidly (adv.)","timidity (n.)"]},{"id":1251,"topic":"psych","w":"reserved","ipa":"/rɪˈzɜːvd/","pos":"adj.","cn":"内敛的；矜持的","pun":"日择服的","story":"re（回）+ serve（留）：「日择服的」每天挑好衣服却把话留在心里，内敛。","ex":"The British are often described as reserved compared with people from Mediterranean cultures.","exCn":"与地中海文化的人相比，英国人常被形容为内敛。","col":["reserved nature","quiet and reserved","reserve (n.)"]},{"id":1252,"topic":"psych","w":"sociable","ipa":"/ˈsəʊʃəbl/","pos":"adj.","cn":"好交际的；合群的","pun":"扫舍步","story":"「扫舍步」——扫完宿舍就一步一步串门找人聊天，好交际。","ex":"Sociable people often report higher levels of happiness and lower stress.","exCn":"好交际的人常常报告更高的幸福感和更低的压力。","col":["sociable person","sociability (n.)","outgoing (adj.)"]},{"id":1253,"topic":"psych","w":"outgoing","ipa":"/ˈaʊtɡəʊɪŋ/","pos":"adj.","cn":"外向的；开朗的","pun":"傲特够硬","story":"out（外）+ going（走）：「傲特够硬」总往外走、脸皮够硬敢搭话，开朗外向。","ex":"Outgoing personalities are often well suited to careers in sales and marketing.","exCn":"外向性格的人往往适合销售和市场营销类职业。","col":["outgoing personality","friendly and outgoing","extroverted (adj.)"]},{"id":1254,"topic":"psych","w":"talkative","ipa":"/ˈtɔːkətɪv/","pos":"adj.","cn":"健谈的；话多的","pun":"托克踢舞","story":"talk（说话）+ ative：「托克踢舞」托克一边踢舞一边说个不停，话痨。","ex":"Talkative students can dominate class discussions if teachers do not intervene.","exCn":"如果老师不干预，健谈的学生可能主导课堂讨论。","col":["talkative child","become talkative","chatty (adj.)"]},{"id":1255,"topic":"psych","w":"charismatic","ipa":"/ˌkærɪzˈmætɪk/","pos":"adj.","cn":"有魅力的；有感召力的","pun":"卡瑞子妈踢克","story":"「卡瑞子妈踢克」——卡瑞的妈妈一登场全场欢呼，魅力四射。","ex":"Charismatic leaders can inspire employees but may also discourage independent thinking.","exCn":"有魅力的领导者能激励员工，但也可能抑制独立思考。","col":["charismatic leader","charisma (n.)","charming (adj.)"]},{"id":1256,"topic":"psych","w":"dominant","ipa":"/ˈdɒmɪnənt/","pos":"adj.","cn":"占主导的；强势的","pun":"道么难特","story":"「道么难特」——霸道得让人特别难受，谁都得听他的，强势主导。","ex":"In many families, the dominant parent makes most of the important decisions.","exCn":"在许多家庭中，强势的一方父母做出大部分重要决定。","col":["dominant personality","dominant role","dominate (v.)"]},{"id":1257,"topic":"psych","w":"submissive","ipa":"/səbˈmɪsɪv/","pos":"adj.","cn":"顺从的；服从的","pun":"色不迷西服","story":"sub（下）+ miss（送）：「色不迷西服」把自己送到下面，低头顺从穿西服的老板。","ex":"Traditional cultures sometimes expected women to be submissive to their husbands.","exCn":"传统文化有时期望女性顺从丈夫。","col":["submissive behaviour","submissive to","submit (v.)"]},{"id":1258,"topic":"psych","w":"obedient","ipa":"/əˈbiːdiənt/","pos":"adj.","cn":"服从的；听话的","pun":"欧比顶特","story":"「欧比顶特」——欧比顶顶听话，叫他往东绝不往西。","ex":"Schools once valued obedient pupils more than those who questioned authority.","exCn":"学校曾经更看重听话的学生，而非质疑权威的学生。","col":["obedient child","obedient to","obedience (n.)"]},{"id":1259,"topic":"psych","w":"rebellious","ipa":"/rɪˈbeljəs/","pos":"adj.","cn":"叛逆的；反抗的","pun":"日北里饿死","story":"「日北里饿死」——天天往北跑离家出走，饿死也不回头，叛逆。","ex":"Teenagers often go through a rebellious phase as they seek greater independence.","exCn":"青少年在寻求更多独立时常经历叛逆期。","col":["rebellious teenager","rebellious behaviour","rebel (n./v.)"]},{"id":1260,"topic":"psych","w":"independent","ipa":"/ˌɪndɪˈpendənt/","pos":"adj.","cn":"独立的；自主的","pun":"印地盆等特","story":"in（不）+ depend（依赖）：「印地盆等特」自己端盆自己等，不靠别人，独立。","ex":"Living abroad forces students to become more independent and self-reliant.","exCn":"在国外生活迫使学生变得更独立自主。","col":["independent of","financially independent","independence (n.)"]},{"id":1261,"topic":"psych","w":"self-reliant","ipa":"/ˌself rɪˈlaɪənt/","pos":"adj.","cn":"自力更生的","pun":"塞夫日来恩特","story":"self（自己）+ rely（依靠）：「塞夫日来恩特」每天靠自己，从不求人，自力更生。","ex":"Children who do household chores tend to grow up more self-reliant.","exCn":"做家务的孩子长大后往往更能自力更生。","col":["self-reliant person","become self-reliant","self-reliance (n.)"]},{"id":1262,"topic":"psych","w":"self-control","ipa":"/ˌself kənˈtrəʊl/","pos":"n.","cn":"自制力；自控","pun":"塞夫肯抽","story":"self（自己）+ control（控制）：「塞夫肯抽」肯给自己一鞭子，管住自己，自制力。","ex":"Children with strong self-control tend to achieve better academic results later in life.","exCn":"自制力强的孩子日后往往取得更好的学业成绩。","col":["exercise self-control","lack of self-control","self-discipline (n.)"]},{"id":1263,"topic":"psych","w":"willpower","ipa":"/ˈwɪlpaʊə(r)/","pos":"n.","cn":"意志力","pun":"我要抛","story":"will（意志）+ power（力量）：「我要抛」下定决心把零食抛掉，靠意志力。","ex":"Willpower alone is rarely enough to break a long-standing bad habit.","exCn":"仅靠意志力很少足以戒除长期的坏习惯。","col":["strong willpower","lack of willpower","self-control (n.)"]},{"id":1264,"topic":"psych","w":"enthusiasm","ipa":"/ɪnˈθjuːziæzəm/","pos":"n.","cn":"热情；热忱","pun":"因求兹饿怎","story":"「因求兹饿怎」——因为求知欲，饿了都不管，满腔热情。","ex":"Teachers' enthusiasm for their subject can be contagious in the classroom.","exCn":"教师对学科的热情在课堂上会传染给学生。","col":["enthusiasm for","great enthusiasm","enthusiastic (adj.)"]},{"id":1265,"topic":"psych","w":"passionate","ipa":"/ˈpæʃənət/","pos":"adj.","cn":"热情的；充满激情的","pun":"怕神呢特","story":"「怕神呢特」——热情到连神都怕，特别有激情。","ex":"Passionate employees are more productive and less likely to change jobs.","exCn":"充满激情的员工效率更高，也更少跳槽。","col":["passionate about","passion (n.)","enthusiastic (adj.)"]},{"id":1266,"topic":"psych","w":"indifferent","ipa":"/ɪnˈdɪfrənt/","pos":"adj.","cn":"漠不关心的；冷淡的","pun":"印地弗人特","story":"in（不）+ different（不同）：「印地弗人特」在他眼里人都没区别，谁都不关心，冷漠。","ex":"Many citizens appear indifferent to environmental issues that do not affect them directly.","exCn":"许多公民似乎对不直接影响自己的环境问题漠不关心。","col":["indifferent to","remain indifferent","indifference (n.)"]},{"id":1267,"topic":"psych","w":"apathy","ipa":"/ˈæpəθi/","pos":"n.","cn":"冷漠；无动于衷","pun":"爱怕死","story":"a（无）+ pathy（感情）：「爱怕死」连爱和怕都死了，什么都无所谓，冷漠。","ex":"Voter apathy is a growing concern in many democratic countries.","exCn":"选民冷漠在许多民主国家日益令人担忧。","col":["voter apathy","public apathy","apathetic (adj.)"]},{"id":1268,"topic":"psych","w":"boredom","ipa":"/ˈbɔːdəm/","pos":"n.","cn":"无聊；厌倦","pun":"抱等呆","story":"「抱等呆」——抱着手机干等两小时，等到发呆，无聊到发霉。","ex":"Boredom in the classroom is often a sign that lessons lack challenge or relevance.","exCn":"课堂上的无聊常常说明课程缺乏挑战或相关性。","col":["out of boredom","relieve boredom","bored (adj.)"]},{"id":1269,"topic":"psych","w":"restless","ipa":"/ˈrestləs/","pos":"adj.","cn":"坐立不安的；不安分的","pun":"瑞斯特累死","story":"rest（休息）+ less（无）：「瑞斯特累死」瑞斯特累死了也停不下来，坐立不安。","ex":"Restless children may struggle to concentrate during long lessons.","exCn":"坐不住的孩子在长时间的课堂上可能难以集中注意力。","col":["restless night","feel restless","restlessness (n.)"]},{"id":1270,"topic":"psych","w":"irritable","ipa":"/ˈɪrɪtəbl/","pos":"adj.","cn":"易怒的；烦躁的","pun":"一日踢不","story":"「一日踢不」——一天不踢球就烦躁，谁碰都炸，易怒。","ex":"Lack of sleep makes people irritable and less able to handle stress.","exCn":"睡眠不足使人烦躁，也更难应对压力。","col":["irritable mood","become irritable","irritate (v.)"]},{"id":1271,"topic":"psych","w":"temper","ipa":"/ˈtempə(r)/","pos":"n.","cn":"脾气；怒气","pun":"添破口","story":"「添破口」——脾气一上来，添一句话就破口大骂。","ex":"Managers who lose their temper in meetings quickly lose the respect of their teams.","exCn":"在会议上发脾气的经理很快会失去团队的尊重。","col":["lose one's temper","bad temper","short-tempered (adj.)"]},{"id":1272,"topic":"psych","w":"rage","ipa":"/reɪdʒ/","pos":"n.","cn":"暴怒；狂怒","pun":"瑞奇怒","story":"「瑞奇怒」——瑞奇被人插队，气得脸红脖子粗，暴怒。","ex":"Road rage incidents have increased as traffic congestion worsens in major cities.","exCn":"随着大城市交通拥堵加剧，路怒事件有所增加。","col":["road rage","fly into a rage","enraged (adj.)"]},{"id":1273,"topic":"psych","w":"composed","ipa":"/kəmˈpəʊzd/","pos":"adj.","cn":"镇定的；沉着的","pun":"肯剖死的","story":"「肯剖死的」——肯剖开死鱼的人手一点不抖，非常镇定。","ex":"The pilot remained composed throughout the emergency landing.","exCn":"飞行员在紧急降落全程保持镇定。","col":["remain composed","calm and composed","composure (n.)"]},{"id":1274,"topic":"psych","w":"serene","ipa":"/səˈriːn/","pos":"adj.","cn":"平静的；安详的","pun":"色林静","story":"「色林静」——夕阳染色的树林里静悄悄，心也平静安详。","ex":"A serene environment helps patients recover more quickly after surgery.","exCn":"平静的环境帮助病人术后更快恢复。","col":["serene expression","serene atmosphere","serenity (n.)"]},{"id":1275,"topic":"psych","w":"tranquil","ipa":"/ˈtræŋkwɪl/","pos":"adj.","cn":"宁静的；安宁的","pun":"穿快湖","story":"「穿快湖」——穿过喧闹的快车道，忽然进入一片宁静的湖边。","ex":"Many city dwellers escape to tranquil rural areas to relieve stress.","exCn":"许多城市居民逃到宁静的乡村来缓解压力。","col":["tranquil setting","tranquil lake","tranquillity (n.)"]},{"id":1276,"topic":"psych","w":"unwind","ipa":"/ˌʌnˈwaɪnd/","pos":"v.","cn":"放松；松弛","pun":"安歪的","story":"un（解开）+ wind（缠绕）：「安歪的」安心歪在沙发上，把缠紧的神经解开，放松。","ex":"Listening to music is a popular way for people to unwind after a stressful day.","exCn":"听音乐是人们在紧张一天后放松的常见方式。","col":["unwind after work","relax and unwind","wind down (phr.)"]},{"id":1277,"topic":"psych","w":"psychologist","ipa":"/saɪˈkɒlədʒɪst/","pos":"n.","cn":"心理学家","pun":"赛口了机死特","story":"psycho（心灵）+ logist（学者）：「赛口了机死特」研究心灵的专家，心理学家。","ex":"Psychologists have found that praise is more effective than punishment in shaping behaviour.","exCn":"心理学家发现表扬比惩罚更能有效塑造行为。","col":["clinical psychologist","child psychologist","psychology (n.)"]},{"id":1278,"topic":"psych","w":"mental","ipa":"/ˈmentl/","pos":"adj.","cn":"精神的；心理的","pun":"门头脑","story":"「门头脑」——精神的家门口就是头脑，心理健康就是门头亮不亮。","ex":"Mental health problems are now recognised as a major cause of absence from work.","exCn":"心理健康问题如今被视为缺勤的主要原因。","col":["mental health","mental illness","mentally (adv.)"]},{"id":1279,"topic":"psych","w":"perceive","ipa":"/pəˈsiːv/","pos":"v.","cn":"感知；认为","pun":"怕死舞","story":"per（完全）+ ceive（抓住）：「怕死舞」完全抓住舞台上的变化，感知到了。","ex":"Young people often perceive risk differently from their parents.","exCn":"年轻人对风险的感知常常与父母不同。","col":["perceive as","widely perceived","perception (n.)"]},{"id":1280,"topic":"psych","w":"perception","ipa":"/pəˈsepʃn/","pos":"n.","cn":"感知；看法","pun":"扑塞不神","story":"「扑塞不神」——信息扑面塞进脑子还没成神，只是初步的感知看法。","ex":"Media coverage strongly influences public perception of crime rates.","exCn":"媒体报道强烈影响公众对犯罪率的看法。","col":["public perception","perception of","perceive (v.)"]},{"id":1281,"topic":"psych","w":"intuition","ipa":"/ˌɪntjuˈɪʃn/","pos":"n.","cn":"直觉","pun":"因求一神","story":"「因求一神」——不求证据，只求心里一闪的神念，直觉。","ex":"Experienced doctors often rely on intuition as well as test results.","exCn":"经验丰富的医生常常既靠直觉也靠检查结果。","col":["rely on intuition","female intuition","intuitive (adj.)"]},{"id":1282,"topic":"psych","w":"rational","ipa":"/ˈræʃnəl/","pos":"adj.","cn":"理性的；合理的","pun":"绕神呢","story":"「绕神呢」——遇事先绕着神殿转三圈冷静想想，理性。","ex":"Consumers do not always make rational decisions when shopping online.","exCn":"消费者网购时并不总是做出理性决定。","col":["rational decision","rational explanation","rationality (n.)"]},{"id":1283,"topic":"psych","w":"irrational","ipa":"/ɪˈræʃənl/","pos":"adj.","cn":"不理性的；荒谬的","pun":"一绕神呢","story":"ir（不）+ rational（理性）：「一绕神呢」一绕神就晕头转向，不理性。","ex":"Fear of flying is often described as an irrational response to a very safe form of travel.","exCn":"对飞行的恐惧常被描述为对一种非常安全出行方式的不理性反应。","col":["irrational fear","irrational behaviour","irrationally (adv.)"]},{"id":1284,"topic":"psych","w":"instinct","ipa":"/ˈɪnstɪŋkt/","pos":"n.","cn":"本能；直觉","pun":"印死听克","story":"「印死听克」——一听到咔嚓声就本能地缩脖子，刻在骨子里的本能。","ex":"Humans have a natural instinct to protect their children from danger.","exCn":"人类有保护子女免受危险的天生本能。","col":["natural instinct","by instinct","instinctive (adj.)"]},{"id":1285,"topic":"psych","w":"subconscious","ipa":"/ˌsʌbˈkɒnʃəs/","pos":"adj./n.","cn":"潜意识的；潜意识","pun":"萨伯看社死","story":"sub（下）+ conscious（意识）：「萨伯看社死」意识底下的萨伯偷偷看你社死，潜意识。","ex":"Advertising often targets the subconscious mind through repeated images and slogans.","exCn":"广告常通过重复的画面和口号作用于潜意识。","col":["subconscious mind","subconscious desire","subconsciously (adv.)"]},{"id":1286,"topic":"psych","w":"self-awareness","ipa":"/ˌself əˈweənəs/","pos":"n.","cn":"自我意识；自知","pun":"塞夫饿危呢死","story":"self（自己）+ awareness（意识）：「塞夫饿危呢死」知道自己饿到危险了，自知之明。","ex":"Self-awareness allows people to recognise their strengths and weaknesses honestly.","exCn":"自我意识使人能诚实地认识自己的优缺点。","col":["develop self-awareness","lack self-awareness","self-aware (adj.)"]},{"id":1287,"topic":"psych","w":"introspection","ipa":"/ˌɪntrəˈspekʃn/","pos":"n.","cn":"内省；自我反省","pun":"印着死拜克神","story":"intro（向内）+ spect（看）：「印着死拜克神」向内看自己，把心印在眼前拜一拜，内省。","ex":"Keeping a diary encourages introspection and helps people understand their emotions.","exCn":"写日记鼓励内省，帮助人们理解自己的情绪。","col":["quiet introspection","introspective (adj.)","self-reflection (n.)"]},{"id":1288,"topic":"psych","w":"reflect","ipa":"/rɪˈflekt/","pos":"v.","cn":"反思；反映","pun":"日弗莱克特","story":"re（回）+ flect（弯）：「日弗莱克特」每天把目光弯回自己身上，反思一天。","ex":"Students are encouraged to reflect on their mistakes rather than simply move on.","exCn":"鼓励学生反思错误，而不是简单地翻篇。","col":["reflect on","reflect upon","reflection (n.)"]},{"id":1289,"topic":"psych","w":"attitude","ipa":"/ˈætɪtjuːd/","pos":"n.","cn":"态度；看法","pun":"爱踢丢的","story":"「爱踢丢的」——爱把球踢丢却从不捡，这态度可不行。","ex":"A positive attitude towards failure is essential for long-term success.","exCn":"对失败持积极态度对长期成功至关重要。","col":["attitude towards","positive attitude","change one's attitude"]},{"id":1290,"topic":"psych","w":"mindset","ipa":"/ˈmaɪndset/","pos":"n.","cn":"思维模式；心态","pun":"脉的赛特","story":"mind（心）+ set（设定）：「脉的赛特」心脉里预设好的赛道，就是思维模式。","ex":"Developing a growth mindset helps learners see challenges as opportunities.","exCn":"培养成长型思维帮助学习者把挑战视为机会。","col":["growth mindset","change one's mindset","fixed mindset"]},{"id":1291,"topic":"psych","w":"considerate","ipa":"/kənˈsɪdərət/","pos":"adj.","cn":"体贴的；为人着想的","pun":"肯洗的热特","story":"「肯洗的热特」——肯给你洗碗、热特意留的饭，体贴入微。","ex":"Considerate neighbours make apartment living far more pleasant.","exCn":"体贴的邻居让公寓生活愉快得多。","col":["considerate of/towards","considerate behaviour","consideration (n.)"]},{"id":1292,"topic":"psych","w":"selfish","ipa":"/ˈselfɪʃ/","pos":"adj.","cn":"自私的","pun":"塞夫鱼是","story":"self（自己）+ ish：「塞夫鱼是」鱼都塞给自己，一条不分，自私。","ex":"Critics argue that consumer culture encourages selfish and short-term thinking.","exCn":"批评者认为消费文化助长自私和短视的思维。","col":["selfish behaviour","selfishly (adv.)","selfishness (n.)"]},{"id":1293,"topic":"psych","w":"altruistic","ipa":"/ˌæltruˈɪstɪk/","pos":"adj.","cn":"利他的；无私的","pun":"傲处一死踢克","story":"alter（他人）：「傲处一死踢克」宁愿自己吃亏也把好处一股脑踢给别人，无私。","ex":"Volunteering is often driven by altruistic motives rather than personal gain.","exCn":"志愿服务往往出于利他动机而非个人利益。","col":["altruistic behaviour","altruism (n.)","selfless (adj.)"]},{"id":1294,"topic":"psych","w":"vanity","ipa":"/ˈvænəti/","pos":"n.","cn":"虚荣；自负","pun":"万呢踢","story":"「万呢踢」——花一万块买鞋就为踢给别人看，虚荣。","ex":"Cosmetic surgery is sometimes criticised as a product of vanity rather than need.","exCn":"整容有时被批评为虚荣而非需要的产物。","col":["out of vanity","personal vanity","vain (adj.)"]},{"id":1295,"topic":"psych","w":"ego","ipa":"/ˈiːɡəʊ/","pos":"n.","cn":"自我；自尊心","pun":"一狗我","story":"「一狗我」——他觉得自己天下第一，别人都是狗，自我膨胀。","ex":"A fragile ego can make people unable to accept constructive criticism.","exCn":"脆弱的自我会让人无法接受建设性批评。","col":["big ego","boost one's ego","egotistical (adj.)"]},{"id":1296,"topic":"psych","w":"self-centred","ipa":"/ˌself ˈsentəd/","pos":"adj.","cn":"以自我为中心的","pun":"塞夫森特的","story":"self（自己）+ centre（中心）：「塞夫森特的」把自己塞在世界中心，以自我为中心。","ex":"Self-centred behaviour can quickly damage friendships and teamwork.","exCn":"以自我为中心的行为会迅速破坏友谊和团队合作。","col":["self-centred person","self-centred attitude","egocentric (adj.)"]},{"id":1297,"topic":"psych","w":"manipulative","ipa":"/məˈnɪpjələtɪv/","pos":"adj.","cn":"操控他人的；善于摆布的","pun":"么你扑了踢舞","story":"mani（手）：「么你扑了踢舞」用手把你推来踢去像玩木偶，操控人心。","ex":"Manipulative advertising exploits people's insecurities to sell products.","exCn":"操控性广告利用人们的不安全感来推销产品。","col":["manipulative behaviour","manipulate (v.)","manipulation (n.)"]},{"id":1298,"topic":"psych","w":"deceptive","ipa":"/dɪˈseptɪv/","pos":"adj.","cn":"欺骗性的；误导的","pun":"地塞踢舞","story":"de（离开）+ cept（拿）：「地塞踢舞」把地上东西悄悄拿走再塞进去踢舞，骗人。","ex":"Deceptive claims about health benefits are common in food advertising.","exCn":"关于健康益处的欺骗性宣传在食品广告中很常见。","col":["deceptive advertising","deceptively (adv.)","deceive (v.)"]},{"id":1299,"topic":"psych","w":"suspicious","ipa":"/səˈspɪʃəs/","pos":"adj.","cn":"怀疑的；可疑的","pun":"色死屁社死","story":"「色死屁社死」——脸色都变了，怀疑对方放屁想让自己社死，起疑心。","ex":"Consumers are increasingly suspicious of companies that collect personal data.","exCn":"消费者对收集个人数据的公司越来越怀疑。","col":["suspicious of","suspicious behaviour","suspicion (n.)"]},{"id":1300,"topic":"psych","w":"paranoid","ipa":"/ˈpærənɔɪd/","pos":"adj.","cn":"多疑的；偏执的","pun":"怕人闹一的","story":"「怕人闹一的」——总怕别人搞事害自己，一点风吹草动就紧张，偏执多疑。","ex":"Constant online surveillance can make people paranoid about being watched.","exCn":"持续的网络监控会让人对被监视感到偏执多疑。","col":["paranoid about","become paranoid","paranoia (n.)"]},{"id":1301,"topic":"psych","w":"phobia","ipa":"/ˈfəʊbiə/","pos":"n.","cn":"恐惧症","pun":"否比啊","story":"「否比啊」——一看到比赛就说否、往后缩，怕到不行，恐惧症。","ex":"Social phobia can prevent people from attending job interviews or parties.","exCn":"社交恐惧症会让人无法参加面试或聚会。","col":["social phobia","suffer from a phobia","phobic (adj.)"]},{"id":1302,"topic":"psych","w":"obsession","ipa":"/əbˈseʃn/","pos":"n.","cn":"痴迷；执念","pun":"饿不谢神","story":"ob（对着）+ sess（坐）：「饿不谢神」饿着也不走，对着神像坐一整天，痴迷。","ex":"An obsession with body image can lead to eating disorders among young women.","exCn":"对身材形象的痴迷会导致年轻女性的饮食失调。","col":["obsession with","unhealthy obsession","obsessed (adj.)"]},{"id":1303,"topic":"psych","w":"compulsive","ipa":"/kəmˈpʌlsɪv/","pos":"adj.","cn":"强迫性的；难以自控的","pun":"肯泼西服","story":"com（一起）+ puls（推）：「肯泼西服」被一股力推着非泼西服不可，强迫性行为。","ex":"Compulsive checking of smartphones has become a widespread modern habit.","exCn":"强迫性地查看手机已成为普遍的现代习惯。","col":["compulsive behaviour","compulsive shopper","compulsion (n.)"]},{"id":1304,"topic":"psych","w":"distress","ipa":"/dɪˈstres/","pos":"n./v.","cn":"痛苦；使苦恼","pun":"地死揣死","story":"dis（分开）+ stress（压）：「地死揣死」被压到地上揣着死也说不出，痛苦。","ex":"Financial problems are a major source of emotional distress for many families.","exCn":"经济问题是许多家庭情绪痛苦的主要来源。","col":["emotional distress","in distress","distressing (adj.)"]},{"id":1305,"topic":"psych","w":"panic","ipa":"/ˈpænɪk/","pos":"n./v.","cn":"恐慌；惊慌","pun":"怕你克","story":"「怕你克」——怕你克我，一看见你我就浑身发抖，恐慌。","ex":"Panic attacks can occur suddenly and without any obvious trigger.","exCn":"恐慌发作可能突然出现，且没有明显诱因。","col":["panic attack","in a panic","panicky (adj.)"]},{"id":1306,"topic":"psych","w":"dread","ipa":"/dred/","pos":"n./v.","cn":"恐惧；害怕","pun":"抓的怕","story":"「抓的怕」——怕被老师抓，每天一进校门就心里发怵，恐惧。","ex":"Many employees dread Monday mornings because of unmanageable workloads.","exCn":"许多员工因难以承受的工作量而害怕周一早晨。","col":["dread doing","a sense of dread","dreadful (adj.)"]},{"id":1307,"topic":"psych","w":"tension","ipa":"/ˈtenʃn/","pos":"n.","cn":"紧张；关系紧张","pun":"疼神经","story":"「疼神经」——绷得太紧，连神经都疼，紧张关系。","ex":"Tension between work and family responsibilities affects many working parents.","exCn":"工作与家庭责任之间的紧张关系影响着许多职场父母。","col":["ease tension","tension between","tense (adj.)"]},{"id":1308,"topic":"psych","w":"pressure","ipa":"/ˈpreʃə(r)/","pos":"n./v.","cn":"压力；施压","pun":"扑热舍","story":"「扑热舍」——热浪扑进宿舍，压得人喘不过气，压力。","ex":"Parents should avoid putting excessive pressure on children to achieve top grades.","exCn":"父母应避免给孩子施加过大压力去追求高分。","col":["under pressure","peer pressure","pressure to do"]},{"id":1309,"topic":"psych","w":"habit","ipa":"/ˈhæbɪt/","pos":"n.","cn":"习惯","pun":"还必特","story":"「还必特」——每天还必须特意做一遍，做久了就成习惯。","ex":"Forming a healthy habit typically takes several weeks of consistent practice.","exCn":"养成一个健康习惯通常需要几周的持续练习。","col":["form a habit","break a habit","habitual (adj.)"]},{"id":1310,"topic":"psych","w":"routine","ipa":"/ruːˈtiːn/","pos":"n./adj.","cn":"常规；例行的","pun":"入厅换","story":"「入厅换」——每天进门先入客厅换鞋，一成不变的常规。","ex":"A regular daily routine provides children with a sense of security.","exCn":"规律的日常作息给孩子带来安全感。","col":["daily routine","routine check","routinely (adv.)"]},{"id":1311,"topic":"psych","w":"reluctant","ipa":"/rɪˈlʌktənt/","pos":"adj.","cn":"不情愿的；勉强的","pun":"日辣可疼特","story":"「日辣可疼特」——天天吃辣嘴疼得特别厉害，再也不愿意吃了，不情愿。","ex":"Many employees are reluctant to report mental health problems for fear of stigma.","exCn":"许多员工因害怕被歧视而不愿报告心理健康问题。","col":["reluctant to do","reluctantly (adv.)","reluctance (n.)"]},{"id":1312,"topic":"psych","w":"hesitant","ipa":"/ˈhezɪtənt/","pos":"adj.","cn":"犹豫的；迟疑的","pun":"害怎疼特","story":"「害怎疼特」——害怕怎么办、怕疼，站在门口迟迟不敢进，犹豫。","ex":"Older people are often hesitant to adopt new technology without support.","exCn":"老年人在没有帮助的情况下常常对采用新技术犹豫不决。","col":["hesitant about","hesitant to do","hesitate (v.)"]},{"id":1313,"topic":"psych","w":"eager","ipa":"/ˈiːɡə(r)/","pos":"adj.","cn":"渴望的；热切的","pun":"一哥梦","story":"「一哥梦」——一心想当班里一哥，眼睛都放光，渴望。","ex":"Eager learners take advantage of every opportunity to practise a new language.","exCn":"热切的学习者利用每个机会练习新语言。","col":["eager to do","eager for","eagerness (n.)"]},{"id":1314,"topic":"psych","w":"ambivalent","ipa":"/æmˈbɪvələnt/","pos":"adj.","cn":"矛盾的；举棋不定的","pun":"俺比我冷特","story":"ambi（两边）+ val（价值）：「俺比我冷特」一边热一边冷，两头拉扯，心情矛盾。","ex":"Many parents feel ambivalent about allowing young children to use tablets.","exCn":"许多父母对是否让幼儿使用平板电脑感到矛盾。","col":["ambivalent about","ambivalent attitude","ambivalence (n.)"]},{"id":1315,"topic":"psych","w":"indecisive","ipa":"/ˌɪndɪˈsaɪsɪv/","pos":"adj.","cn":"优柔寡断的","pun":"印地塞西服","story":"in（不）+ decisive（果断）：「印地塞西服」站在地上塞了半天西服还没决定穿哪件，优柔寡断。","ex":"Indecisive managers can leave their teams confused and demotivated.","exCn":"优柔寡断的经理会让团队困惑且失去动力。","col":["indecisive leader","indecision (n.)","decisive (adj.)"]},{"id":1316,"topic":"psych","w":"decisive","ipa":"/dɪˈsaɪsɪv/","pos":"adj.","cn":"果断的；决定性的","pun":"地塞西服","story":"de（切断）+ cis（切）：「地塞西服」一刀切断犹豫，抓起西服就走，果断。","ex":"Decisive action by the government helped calm public fear during the crisis.","exCn":"政府的果断行动帮助平息了危机期间的公众恐慌。","col":["decisive action","decisive factor","decisiveness (n.)"]},{"id":1317,"topic":"psych","w":"mature","ipa":"/məˈtʃʊə(r)/","pos":"adj./v.","cn":"成熟的；成熟","pun":"么丘儿","story":"「么丘儿」——小丘长成大山，孩子长成大人，成熟了。","ex":"Living independently helps young adults become more mature and responsible.","exCn":"独立生活帮助年轻人变得更成熟、更有责任感。","col":["emotionally mature","mature into","maturity (n.)"]},{"id":1318,"topic":"psych","w":"immature","ipa":"/ˌɪməˈtjʊə(r)/","pos":"adj.","cn":"不成熟的；幼稚的","pun":"一么丘儿","story":"im（不）+ mature（成熟）：「一么丘儿」还是一个小土丘，没长大，不成熟。","ex":"Immature behaviour in the workplace can hold back an otherwise talented employee.","exCn":"职场上的幼稚行为会拖累一个本来有才华的员工。","col":["emotionally immature","immature behaviour","immaturity (n.)"]},{"id":1319,"topic":"psych","w":"naive","ipa":"/naɪˈiːv/","pos":"adj.","cn":"天真的；幼稚的","pun":"奶衣服","story":"「奶衣服」——还穿着喝奶时的衣服，以为世界都是好人，天真。","ex":"It is naive to assume that technology alone can solve social problems.","exCn":"以为仅靠技术就能解决社会问题是天真的。","col":["naive to think","naive assumption","naivety (n.)"]},{"id":1320,"topic":"psych","w":"gullible","ipa":"/ˈɡʌləbl/","pos":"adj.","cn":"易受骗的；轻信的","pun":"嘎了不","story":"「嘎了不」——人家说吃了会嘎嘣脆，他不问就信，轻信易骗。","ex":"Gullible consumers are easy targets for online scams and false advertising.","exCn":"轻信的消费者容易成为网络诈骗和虚假广告的目标。","col":["gullible people","gullibility (n.)","credulous (adj.)"]},{"id":1321,"topic":"psych","w":"wisdom","ipa":"/ˈwɪzdəm/","pos":"n.","cn":"智慧；明智","pun":"喂子等","story":"wise（明智）+ dom：「喂子等」喂孩子懂得等一等不急，这是老人的智慧。","ex":"Older generations can pass on valuable wisdom that cannot be found in textbooks.","exCn":"老一辈能传承课本里找不到的宝贵智慧。","col":["conventional wisdom","words of wisdom","wise (adj.)"]},{"id":1322,"topic":"psych","w":"self-conscious","ipa":"/ˌself ˈkɒnʃəs/","pos":"adj.","cn":"难为情的；自我意识过强的","pun":"塞夫看社死","story":"self（自己）+ conscious（意识）：「塞夫看社死」总觉得所有人在看自己，怕社死，难为情。","ex":"Teenagers often feel self-conscious about their appearance in front of peers.","exCn":"青少年在同龄人面前常常对自己的外貌感到难为情。","col":["self-conscious about","feel self-conscious","self-consciousness (n.)"]},{"id":1323,"topic":"food","w":"ingredient","ipa":"/ɪnˈɡriːdiənt/","pos":"n.","cn":"原料；配料","pun":"印个厘点","story":"厨师把每种配料都印个厘点做记号，一克不差——ingredient 就是烹饪原料。","ex":"Food manufacturers are required to list every ingredient on the packaging in order of quantity.","exCn":"食品生产商必须按含量顺序在包装上列出每种原料。","col":["key ingredient","fresh ingredients","raw ingredient"]},{"id":1324,"topic":"food","w":"recipe","ipa":"/ˈresəpi/","pos":"n.","cn":"食谱；秘诀","pun":"热色皮","story":"食谱上写着：把鸡烤到热色皮——recipe 就是做菜的食谱，也引申为成功秘诀。","ex":"Many families no longer pass down traditional recipes from one generation to the next.","exCn":"许多家庭不再把传统食谱一代代传下去。","col":["follow a recipe","a recipe for disaster","recipe book"]},{"id":1325,"topic":"food","w":"crop","ipa":"/krɒp/","pos":"n.","cn":"庄稼；农作物；收成","pun":"可拉破","story":"收庄稼时麻袋装得太满，可拉破了——crop 就是庄稼、作物。","ex":"A single failed crop can push subsistence farmers into severe debt.","exCn":"一次歉收就能把自给自足的农民推入严重的债务之中。","col":["cash crop","crop failure","harvest the crop"]},{"id":1326,"topic":"food","w":"harvest","ipa":"/ˈhɑːvɪst/","pos":"n./v.","cn":"收获；收割","pun":"哈，喂死它","story":"丰收季农夫笑道：哈，谷仓要喂死它了——harvest 就是收获、收割。","ex":"Farmers now harvest wheat with machines that would once have required hundreds of labourers.","exCn":"农民现在用机器收割小麦，而过去这需要数百名劳动力。","col":["a good harvest","harvest season","harvest crops"]},{"id":1327,"topic":"food","w":"livestock","ipa":"/ˈlaɪvstɒk/","pos":"n.","cn":"牲畜；家畜","pun":"来福是猪","story":"live（活的）+ stock（存货）：农场里活的存货——来福是猪，牛羊也都是 livestock。","ex":"Raising livestock requires far more land and water than growing an equivalent amount of grain.","exCn":"饲养牲畜所需的土地和水远多于种植等量谷物。","col":["livestock farming","raise livestock","livestock production"]},{"id":1328,"topic":"food","w":"poultry","ipa":"/ˈpəʊltri/","pos":"n.","cn":"家禽；禽肉","pun":"跑出去","story":"鸡鸭鹅一开笼就跑出去了——poultry 就是家禽。","ex":"Poultry has overtaken beef as the most widely consumed meat in many developed countries.","exCn":"在许多发达国家，禽肉已超过牛肉成为消费最广的肉类。","col":["poultry farm","poultry products","poultry and eggs"]},{"id":1329,"topic":"food","w":"dairy","ipa":"/ˈdeəri/","pos":"n./adj.","cn":"乳制品；奶制品的","pun":"戴瑞","story":"戴瑞每天早上都送牛奶和奶酪——dairy 就是乳制品。","ex":"Dairy products remain an important source of calcium in the Western diet.","exCn":"乳制品仍是西方饮食中钙的重要来源。","col":["dairy products","dairy farm","dairy-free"]},{"id":1330,"topic":"food","w":"starvation","ipa":"/stɑːˈveɪʃn/","pos":"n.","cn":"饥饿；饿死","pun":"死大喂神","story":"饿得快死了，大家只能喂神求救——starvation 就是饥饿、饿死，starve 是动词。","ex":"Aid agencies warned that thousands faced starvation unless food supplies arrived within weeks.","exCn":"援助机构警告说，除非几周内运来粮食，否则数千人将面临饿死。","col":["die of starvation","starvation wages","starve to death"]},{"id":1331,"topic":"food","w":"staple","ipa":"/ˈsteɪpl/","pos":"n./adj.","cn":"主食；主要的","pun":"死抱","story":"米饭死抱着不放，顿顿都要吃——staple 就是主食、主要产品。","ex":"Rice is the staple food for more than half of the world's population.","exCn":"大米是世界一半以上人口的主食。","col":["staple food","staple crop","staple diet"]},{"id":1332,"topic":"food","w":"grain","ipa":"/ɡreɪn/","pos":"n.","cn":"谷物；颗粒","pun":"给人","story":"粮仓里的谷物要给人吃，一粒都不能浪费——grain 就是谷物。","ex":"Global grain reserves have fallen to their lowest level in a decade.","exCn":"全球谷物储备已跌至十年来的最低水平。","col":["grain production","whole grain","grain reserves"]},{"id":1333,"topic":"food","w":"cereal","ipa":"/ˈsɪəriəl/","pos":"n.","cn":"谷类；麦片","pun":"洗了要","story":"麦子洗了要晒干才能磨——cereal 就是谷类作物，也指早餐麦片。","ex":"Cereal crops such as wheat and maize account for the majority of the world's calorie intake.","exCn":"小麦和玉米等谷类作物占了世界热量摄入的大部分。","col":["cereal crops","breakfast cereal","cereal production"]},{"id":1334,"topic":"food","w":"wheat","ipa":"/wiːt/","pos":"n.","cn":"小麦","pun":"味特","story":"新磨的小麦面粉味道特别香——wheat 就是小麦。","ex":"Wheat prices rose sharply after the drought reduced harvests across the northern hemisphere.","exCn":"干旱减少了北半球的收成后，小麦价格急剧上涨。","col":["wheat flour","grow wheat","wheat harvest"]},{"id":1335,"topic":"food","w":"edible","ipa":"/ˈedəbl/","pos":"adj.","cn":"可食用的","pun":"爱的包","story":"妈妈做的包子是爱的包，当然可以吃——edible 就是可食用的。","ex":"Roughly one third of all edible food produced worldwide is thrown away each year.","exCn":"全球生产的可食用食物每年大约有三分之一被扔掉。","col":["edible oil","edible plants","inedible"]},{"id":1336,"topic":"food","w":"perishable","ipa":"/ˈperɪʃəbl/","pos":"adj.","cn":"易腐烂的","pun":"拍了说不","story":"水果拍了照说不能过夜，明天就烂——perishable 就是易腐烂的，perish 是死亡、腐烂。","ex":"Perishable goods such as fresh fish require refrigerated transport to reach distant markets.","exCn":"鲜鱼等易腐商品需要冷藏运输才能到达远方市场。","col":["perishable goods","highly perishable","perishable food"]},{"id":1337,"topic":"food","w":"preservative","ipa":"/prɪˈzɜːvətɪv/","pos":"n.","cn":"防腐剂","pun":"扑热蛇喂踢","story":"扑热了的蛇喂它踢一脚，冻起来放防腐剂就不坏——preservative 就是防腐剂。","ex":"Processed meats often contain preservatives that have been linked to certain cancers.","exCn":"加工肉类常含有与某些癌症相关的防腐剂。","col":["artificial preservatives","preservative-free","contain preservatives"]},{"id":1338,"topic":"food","w":"additive","ipa":"/ˈædətɪv/","pos":"n.","cn":"添加剂","pun":"爱的踢我","story":"add（加）+ -itive：往食物里加东西，爱的踢我一脚也不能多加——additive 就是添加剂。","ex":"Some food additives used to enhance colour and flavour have been banned in the European Union.","exCn":"一些用于增色增味的食品添加剂已在欧盟被禁用。","col":["food additives","chemical additives","additive-free"]},{"id":1339,"topic":"food","w":"takeaway","ipa":"/ˈteɪkəweɪ/","pos":"n.","cn":"外卖；外带食品","pun":"提可为","story":"take（拿）+ away（走）：提着走可为——takeaway 就是外卖。","ex":"The popularity of takeaway meals has contributed to a sharp rise in single-use packaging.","exCn":"外卖的流行导致一次性包装急剧增加。","col":["order a takeaway","takeaway food","takeaway shop"]},{"id":1340,"topic":"food","w":"convenience","ipa":"/kənˈviːniəns/","pos":"n.","cn":"方便；便利","pun":"啃喂你饿死","story":"方便面直接啃，喂你不饿死——convenience food 就是方便食品。","ex":"Convenience foods appeal to busy workers who have little time to cook at home.","exCn":"方便食品吸引了那些没时间在家做饭的忙碌上班族。","col":["convenience food","convenience store","for the sake of convenience"]},{"id":1341,"topic":"food","w":"junk food","ipa":"/ˈdʒʌŋk fuːd/","pos":"phr.","cn":"垃圾食品","pun":"脏可福的","story":"薯片炸鸡脏可福的，吃着爽却没营养——junk food 就是垃圾食品。","ex":"Governments are debating whether junk food advertising aimed at children should be prohibited.","exCn":"各国政府正在讨论是否应禁止针对儿童的垃圾食品广告。","col":["eat junk food","junk food advertising","junk food tax"]},{"id":1342,"topic":"food","w":"fast food","ipa":"/ˌfɑːst ˈfuːd/","pos":"phr.","cn":"快餐","pun":"发死特福的","story":"快餐店老板发死特别有福气，店开遍全球——fast food 就是快餐。","ex":"The spread of fast food chains has altered eating habits in almost every country.","exCn":"快餐连锁店的扩张改变了几乎每个国家的饮食习惯。","col":["fast food chain","fast food restaurant","fast food outlet"]},{"id":1343,"topic":"food","w":"diet","ipa":"/ˈdaɪət/","pos":"n./v.","cn":"日常饮食；节食","pun":"呆饿它","story":"减肥的人呆在家里饿着它——diet 既是日常饮食，也是节食。","ex":"A balanced diet rich in vegetables can significantly reduce the risk of chronic disease.","exCn":"富含蔬菜的均衡饮食能显著降低慢性病风险。","col":["a balanced diet","go on a diet","dietary habits"]},{"id":1344,"topic":"food","w":"vegetarian","ipa":"/ˌvedʒəˈteəriən/","pos":"n./adj.","cn":"素食者；素食的","pun":"喂着太累人","story":"vegetable（蔬菜）+ -arian（人）：养猪喂着太累人，干脆只吃菜——vegetarian 就是素食者。","ex":"A growing number of young people are adopting a vegetarian diet for environmental reasons.","exCn":"越来越多年轻人出于环保原因选择素食。","col":["vegetarian diet","strict vegetarian","vegetarian options"]},{"id":1345,"topic":"food","w":"vegan","ipa":"/ˈviːɡən/","pos":"n./adj.","cn":"纯素食者；纯素的","pun":"喂根","story":"纯素的人只吃植物根茎，连蛋奶都不碰——vegan 就是纯素食者。","ex":"Vegan diets exclude all animal products, including dairy, eggs and honey.","exCn":"纯素饮食排除所有动物产品，包括奶制品、蛋和蜂蜜。","col":["vegan diet","go vegan","veganism"]},{"id":1346,"topic":"food","w":"carnivore","ipa":"/ˈkɑːnɪvɔː(r)/","pos":"n.","cn":"食肉动物；食肉者","pun":"卡你我","story":"carni-（肉）+ -vore（吃）：老虎吃肉，卡住你和我——carnivore 就是食肉动物。","ex":"Humans are not obligate carnivores and can thrive on a largely plant-based diet.","exCn":"人类不是专性食肉动物，靠以植物为主的饮食也能健康生活。","col":["carnivorous","carnivore diet","herbivore"]},{"id":1347,"topic":"food","w":"vitamin","ipa":"/ˈvɪtəmɪn/","pos":"n.","cn":"维生素","pun":"喂它命","story":"喂它维生素就是喂它命，缺了会生病——vitamin 就是维生素。","ex":"Vitamin deficiencies are common among people whose diet consists mainly of refined grains.","exCn":"饮食主要为精制谷物的人群普遍缺乏维生素。","col":["vitamin deficiency","vitamin supplements","rich in vitamins"]},{"id":1348,"topic":"food","w":"mineral","ipa":"/ˈmɪnərəl/","pos":"n.","cn":"矿物质；矿物","pun":"米呢肉","story":"米呢肉呢都有矿物质，铁钙锌都在里面——mineral 就是矿物质。","ex":"Leafy vegetables supply essential minerals such as iron and magnesium.","exCn":"绿叶蔬菜提供铁和镁等必需矿物质。","col":["vitamins and minerals","mineral water","mineral content"]},{"id":1349,"topic":"food","w":"balanced","ipa":"/ˈbælənst/","pos":"adj.","cn":"均衡的","pun":"白冷死的","story":"只吃白米饭冷了会饿死，得荤素搭配——balanced 就是均衡的。","ex":"Schools should teach children how to plan a balanced meal from an early age.","exCn":"学校应从小教孩子如何规划一顿均衡的饭菜。","col":["a balanced diet","well-balanced","balance"]},{"id":1350,"topic":"food","w":"wholesome","ipa":"/ˈhəʊlsəm/","pos":"adj.","cn":"有益健康的","pun":"厚色木","story":"whole（完整）+ some：厚色的木桌上摆着完整的粗粮，吃了有益健康——wholesome。","ex":"Home-cooked meals are generally more wholesome than anything bought from a fast food outlet.","exCn":"家常饭菜通常比任何快餐店买来的食物都更有益健康。","col":["wholesome food","wholesome meal","wholesomeness"]},{"id":1351,"topic":"food","w":"portion","ipa":"/ˈpɔːʃn/","pos":"n.","cn":"一份；份量","pun":"泼神","story":"厨师泼神一样往盘里堆，一份菜大得吓人——portion 就是一份、份量。","ex":"Restaurant portion sizes have grown considerably, encouraging diners to overeat.","exCn":"餐馆的份量大幅增加，鼓励了食客暴饮暴食。","col":["portion size","a small portion","portion control"]},{"id":1352,"topic":"food","w":"serving","ipa":"/ˈsɜːvɪŋ/","pos":"n.","cn":"一份（食物）","pun":"色影","story":"服务员端上一份菜，色泽映在盘里——serving 就是一份食物。","ex":"Health authorities recommend at least five servings of fruit and vegetables a day.","exCn":"卫生部门建议每天至少吃五份水果和蔬菜。","col":["a serving of vegetables","serving size","serve"]},{"id":1353,"topic":"food","w":"overeat","ipa":"/ˌəʊvərˈiːt/","pos":"v.","cn":"吃得过多","pun":"欧巴一直","story":"over（过度）+ eat（吃）：欧巴一直吃，吃得过多撑到躺下——overeat。","ex":"People tend to overeat when they are served food on larger plates.","exCn":"当用更大的盘子盛食物时，人们往往会吃得过多。","col":["tendency to overeat","overeating","overeat at festivals"]},{"id":1354,"topic":"food","w":"indulge","ipa":"/ɪnˈdʌldʒ/","pos":"v.","cn":"放纵；沉溺","pun":"硬倒汁","story":"硬要倒一整杯果汁配蛋糕，放纵一回——indulge 就是放纵、尽情享受。","ex":"It is acceptable to indulge in rich desserts occasionally as part of an otherwise healthy diet.","exCn":"在整体健康的饮食中，偶尔放纵一下吃点丰盛的甜点是可以接受的。","col":["indulge in","indulge oneself","indulgence"]},{"id":1355,"topic":"food","w":"craving","ipa":"/ˈkreɪvɪŋ/","pos":"n.","cn":"渴望；强烈欲望","pun":"快喂应","story":"深夜想吃火锅，快喂应该马上吃——craving 就是强烈的渴望，crave 是动词。","ex":"Sugar cravings are often triggered by stress rather than genuine hunger.","exCn":"对糖的渴望常常由压力而非真正的饥饿引发。","col":["food cravings","satisfy a craving","crave"]},{"id":1356,"topic":"food","w":"flavour","ipa":"/ˈfleɪvə(r)/","pos":"n./v.","cn":"味道；给…调味","pun":"福来喂","story":"福来了就喂你一口，什么味道都尝得到——flavour 就是味道、风味。","ex":"Artificial flavours are widely used to make processed snacks more appealing.","exCn":"人工香精被广泛用于让加工零食更有吸引力。","col":["natural flavour","add flavour","flavouring"]},{"id":1357,"topic":"food","w":"seasoning","ipa":"/ˈsiːzənɪŋ/","pos":"n.","cn":"调味品；佐料","pun":"洗针宁","story":"洗干净针一样细的葱花，宁可多撒点——seasoning 就是调味品，season 也可作调味动词。","ex":"Many packaged seasonings contain far more sodium than consumers realise.","exCn":"许多包装调味料含有的钠远超消费者的想象。","col":["add seasoning","seasoning mix","season with salt"]},{"id":1358,"topic":"food","w":"spice","ipa":"/spaɪs/","pos":"n.","cn":"香料；调味香料","pun":"死拍死","story":"辣椒面撒多了，辣得人死拍死——spice 就是香料，spicy 是辛辣的。","ex":"The spice trade linked Asia and Europe centuries before modern globalised food markets.","exCn":"香料贸易在现代全球化食品市场出现前几百年就已连接亚欧。","col":["herbs and spices","spice trade","spicy food"]},{"id":1359,"topic":"food","w":"condiment","ipa":"/ˈkɒndɪmənt/","pos":"n.","cn":"调味品；佐料","pun":"坎的门","story":"番茄酱芥末摆在门坎边，随手抓来蘸——condiment 就是佐料、调味品。","ex":"Condiments such as ketchup and mayonnaise can add hidden sugar and fat to a meal.","exCn":"番茄酱和蛋黄酱等调味品会给一餐添加隐藏的糖和脂肪。","col":["condiment bottle","a range of condiments","table condiments"]},{"id":1360,"topic":"food","w":"bland","ipa":"/blænd/","pos":"adj.","cn":"清淡的；乏味的","pun":"不烂的","story":"白水煮菜不烂的也没味，太清淡——bland 就是清淡乏味的。","ex":"Hospital food is often criticised for being bland and unappetising.","exCn":"医院的食物常被批评为清淡无味、不开胃。","col":["bland food","bland diet","bland taste"]},{"id":1361,"topic":"food","w":"savoury","ipa":"/ˈseɪvəri/","pos":"adj.","cn":"咸的；可口的","pun":"塞味儿","story":"塞满味儿的咸派，不甜却很可口——savoury 就是咸味的、开胃的。","ex":"British consumers spend more on savoury snacks such as crisps than on confectionery.","exCn":"英国消费者在薯片等咸味零食上的花费超过糖果。","col":["savoury snacks","savoury dishes","sweet and savoury"]},{"id":1362,"topic":"food","w":"culinary","ipa":"/ˈkʌlɪnəri/","pos":"adj.","cn":"烹饪的","pun":"科里那里","story":"厨房科里那里都是锅铲，全是烹饪的事——culinary 就是烹饪的。","ex":"Culinary traditions are an important part of a nation's cultural identity.","exCn":"烹饪传统是一个国家文化认同的重要组成部分。","col":["culinary skills","culinary traditions","culinary arts"]},{"id":1363,"topic":"food","w":"gourmet","ipa":"/ˈɡʊəmeɪ/","pos":"n./adj.","cn":"美食家；美食的","pun":"顾美","story":"顾美家的每道菜都精致，是个美食家——gourmet 就是美食家、精美的。","ex":"Gourmet restaurants cater to a small elite while millions struggle to afford basic food.","exCn":"高级餐厅服务少数精英，而数百万人却难以买得起基本食物。","col":["gourmet food","gourmet restaurant","gourmet meal"]},{"id":1364,"topic":"food","w":"delicacy","ipa":"/ˈdelɪkəsi/","pos":"n.","cn":"美味佳肴；精致","pun":"得力客席","story":"得力的大厨给客席端上珍稀佳肴——delicacy 就是美味佳肴，delicate 是精致的。","ex":"Shark fin soup is considered a delicacy in some cultures despite its environmental cost.","exCn":"尽管代价惨重，鱼翅汤在某些文化中仍被视为珍馐。","col":["local delicacy","a rare delicacy","delicate"]},{"id":1365,"topic":"food","w":"banquet","ipa":"/ˈbæŋkwɪt/","pos":"n.","cn":"宴会","pun":"办亏它","story":"办一场大宴会，办亏了它也得摆——banquet 就是宴会。","ex":"Lavish state banquets are often criticised at a time when many citizens go hungry.","exCn":"在许多公民挨饿的时候，奢华的国宴常受批评。","col":["wedding banquet","hold a banquet","banquet hall"]},{"id":1366,"topic":"food","w":"feast","ipa":"/fiːst/","pos":"n./v.","cn":"盛宴；尽情享用","pun":"费死它","story":"过年办盛宴，费死它一头猪——feast 就是盛宴，也可作动词大吃。","ex":"Harvest festivals traditionally involve a communal feast to celebrate the year's crops.","exCn":"丰收节传统上包括一场集体盛宴来庆祝当年的收成。","col":["a feast of","feast on","festive feast"]},{"id":1367,"topic":"food","w":"dine","ipa":"/daɪn/","pos":"v.","cn":"用餐；进餐","pun":"呆呢","story":"呆在餐厅里呢，慢慢吃正餐——dine 就是用餐，dine out 是外出就餐。","ex":"Families that dine together regularly tend to have healthier eating habits.","exCn":"经常一起用餐的家庭往往有更健康的饮食习惯。","col":["dine out","dine with","fine dining"]},{"id":1368,"topic":"food","w":"catering","ipa":"/ˈkeɪtərɪŋ/","pos":"n.","cn":"餐饮服务；承办酒席","pun":"开特灵","story":"开特别灵的餐饮公司，专门给会议送餐——catering 就是餐饮服务，cater 是提供饮食。","ex":"The catering industry employs millions of workers, many of them on low wages.","exCn":"餐饮业雇用了数百万工人，其中许多人工资很低。","col":["catering industry","catering service","cater for"]},{"id":1369,"topic":"food","w":"canteen","ipa":"/kænˈtiːn/","pos":"n.","cn":"食堂","pun":"看厅","story":"看这大厅里排队打饭的人——canteen 就是食堂。","ex":"School canteens have been ordered to remove sugary drinks from their menus.","exCn":"学校食堂已被要求将含糖饮料从菜单中撤下。","col":["school canteen","staff canteen","canteen food"]},{"id":1370,"topic":"food","w":"cafeteria","ipa":"/ˌkæfəˈtɪəriə/","pos":"n.","cn":"自助餐厅；食堂","pun":"咖啡踢丽娅","story":"咖啡踢了丽娅一脚，她在自助餐厅端盘子摔了——cafeteria 就是自助食堂。","ex":"University cafeterias could play a key role in encouraging students to eat more healthily.","exCn":"大学自助餐厅可以在鼓励学生健康饮食方面发挥关键作用。","col":["school cafeteria","cafeteria food","cafeteria-style"]},{"id":1371,"topic":"food","w":"street food","ipa":"/ˈstriːt fuːd/","pos":"phr.","cn":"街头小吃","pun":"是吃福的","story":"街边小摊是吃福的地方，便宜又香——street food 就是街头小吃。","ex":"Street food is an important part of the culinary heritage of many Asian cities.","exCn":"街头小吃是许多亚洲城市烹饪遗产的重要组成部分。","col":["street food stalls","street food culture","street food market"]},{"id":1372,"topic":"food","w":"genetically modified","ipa":"/dʒəˌnetɪkli ˈmɒdɪfaɪd/","pos":"phr.","cn":"转基因的","pun":"这呢踢客里 摸的发","story":"科学家这呢踢客里，摸一摸基因就发生了改变——genetically modified 就是转基因的，简称 GM。","ex":"Genetically modified crops could help feed a growing population, but public opposition remains strong.","exCn":"转基因作物可以帮助养活不断增长的人口，但公众反对依然强烈。","col":["genetically modified crops","GM food","genetic modification"]},{"id":1373,"topic":"food","w":"modification","ipa":"/ˌmɒdɪfɪˈkeɪʃn/","pos":"n.","cn":"修改；改造","pun":"摸的飞开神","story":"摸一下基因，改了就飞开去找神——modification 就是修改、改造，modify 是动词。","ex":"Genetic modification allows scientists to make crops resistant to pests and disease.","exCn":"基因改造使科学家能让作物抵抗病虫害。","col":["genetic modification","make modifications","modify"]},{"id":1374,"topic":"food","w":"germinate","ipa":"/ˈdʒɜːmɪneɪt/","pos":"v.","cn":"发芽；萌发","pun":"这么内特","story":"种子这么内向，特别慢才发芽——germinate 就是发芽，germination 是名词。","ex":"Seeds will not germinate unless the soil is warm and sufficiently moist.","exCn":"除非土壤温暖且足够湿润，否则种子不会发芽。","col":["seeds germinate","germination rate","germination"]},{"id":1375,"topic":"food","w":"sow","ipa":"/səʊ/","pos":"v.","cn":"播种","pun":"搜","story":"农夫在田里搜一遍，把种子撒下去——sow 就是播种，sow seeds。","ex":"Farmers sow winter wheat in autumn so that it can be harvested the following summer.","exCn":"农民在秋天播种冬小麦，以便来年夏天收割。","col":["sow seeds","sowing season","sow the fields"]},{"id":1376,"topic":"food","w":"plough","ipa":"/plaʊ/","pos":"v./n.","cn":"犁；耕地","pun":"扑捞","story":"牛拉着犁往土里扑，捞起一层泥——plough 就是犁、耕地。","ex":"Ploughing fields too frequently exposes the topsoil to wind and rain.","exCn":"过于频繁地犁地会使表土暴露在风雨之下。","col":["plough the land","ploughed field","plough back"]},{"id":1377,"topic":"food","w":"ranch","ipa":"/rɑːntʃ/","pos":"n.","cn":"大牧场","pun":"让吃","story":"大牧场就是让牛羊随便吃草的地方——ranch 就是大牧场。","ex":"Cattle ranches have replaced vast areas of rainforest in South America.","exCn":"在南美洲，养牛场已取代了大片雨林。","col":["cattle ranch","ranch owner","rancher"]},{"id":1378,"topic":"food","w":"orchard","ipa":"/ˈɔːtʃəd/","pos":"n.","cn":"果园","pun":"哦吃的","story":"哦，果园里全是吃的，苹果梨子挂满枝——orchard 就是果园。","ex":"Many small orchards have been cleared to make way for housing developments.","exCn":"许多小果园已被清除以给住宅开发让路。","col":["apple orchard","orchard fruit","plant an orchard"]},{"id":1379,"topic":"food","w":"vineyard","ipa":"/ˈvɪnjəd/","pos":"n.","cn":"葡萄园","pun":"温雅的","story":"葡萄园里温雅的酒农正在剪枝——vineyard 就是葡萄园，vine 是葡萄藤。","ex":"Rising temperatures are forcing vineyards to move to cooler regions.","exCn":"气温上升正迫使葡萄园迁往更凉爽的地区。","col":["vineyard owner","plant a vineyard","vine"]},{"id":1380,"topic":"food","w":"plantation","ipa":"/plɑːnˈteɪʃn/","pos":"n.","cn":"种植园","pun":"扑烂太深","story":"plant（种）+ -ation：热带种植园里香蕉扑烂在太深的土里——plantation 就是种植园。","ex":"Palm oil plantations are a leading cause of deforestation in Southeast Asia.","exCn":"棕榈油种植园是东南亚森林砍伐的主要原因之一。","col":["tea plantation","palm oil plantation","plantation workers"]},{"id":1381,"topic":"food","w":"pasture","ipa":"/ˈpɑːstʃə(r)/","pos":"n.","cn":"牧场；牧草地","pun":"怕死车","story":"牛羊在牧草地上吃草，怕死车开过来撞——pasture 就是牧场、草地。","ex":"Overgrazing has turned much of the region's pasture into bare, eroded land.","exCn":"过度放牧已使该地区大部分牧场变成光秃秃的被侵蚀土地。","col":["pasture land","put out to pasture","rich pasture"]},{"id":1382,"topic":"food","w":"graze","ipa":"/ɡreɪz/","pos":"v.","cn":"放牧；吃草","pun":"割雷子","story":"牛在草地上像割草机割雷子一样啃草——graze 就是吃草、放牧。","ex":"Cattle that graze on open grassland produce meat with a lower environmental footprint.","exCn":"在开放草地上吃草的牛产出的肉环境足迹更低。","col":["graze on grass","grazing land","overgrazing"]},{"id":1383,"topic":"food","w":"arable","ipa":"/ˈærəbl/","pos":"adj.","cn":"可耕的；耕作的","pun":"哎拉步","story":"哎，拉着犁一步一步走，这地能耕——arable land 就是可耕地。","ex":"Only about a tenth of the country's land is arable, which limits food production.","exCn":"该国只有约十分之一的土地可耕，这限制了粮食生产。","col":["arable land","arable farming","arable crops"]},{"id":1384,"topic":"food","w":"soil erosion","ipa":"/ˌsɔɪl ɪˈrəʊʒn/","pos":"phr.","cn":"水土流失","pun":"搜一搜 一漏针","story":"搜一搜，土壤像漏针一样一点点漏走了——soil erosion 就是水土流失，erode 是侵蚀。","ex":"Soil erosion caused by intensive farming threatens the long-term productivity of agricultural land.","exCn":"集约化耕作造成的水土流失威胁着农业用地的长期生产力。","col":["prevent soil erosion","erode","topsoil"]},{"id":1385,"topic":"food","w":"monoculture","ipa":"/ˈmɒnəkʌltʃə(r)/","pos":"n.","cn":"单一作物种植","pun":"摸呢卡车","story":"mono-（单一）+ culture（种植）：摸呢卡车拉的全是同一种玉米——monoculture 就是单一作物种植。","ex":"Monoculture increases vulnerability to pests because a single disease can wipe out the entire crop.","exCn":"单一种植增加了对病虫害的脆弱性，因为一种病害就能毁掉整片作物。","col":["monoculture farming","reliance on monoculture","crop diversity"]},{"id":1386,"topic":"food","w":"rotation","ipa":"/rəʊˈteɪʃn/","pos":"n.","cn":"轮作；轮换","pun":"肉贴神","story":"今年种豆明年种麦，像肉贴神像那样一年换一次——crop rotation 就是轮作。","ex":"Crop rotation helps restore nutrients to the soil without relying on chemical fertilisers.","exCn":"轮作有助于恢复土壤养分，而不依赖化肥。","col":["crop rotation","in rotation","rotate crops"]},{"id":1387,"topic":"food","w":"self-sufficient","ipa":"/ˌself səˈfɪʃnt/","pos":"adj.","cn":"自给自足的","pun":"赛尔夫 色费神","story":"self（自己）+ sufficient（充足）：自己种够吃的，不用赛尔夫去费神买——self-sufficient 就是自给自足。","ex":"Few modern nations are entirely self-sufficient in food production.","exCn":"很少有现代国家在粮食生产上完全自给自足。","col":["self-sufficient in food","become self-sufficient","self-sufficiency"]},{"id":1388,"topic":"food","w":"food security","ipa":"/ˌfuːd sɪˈkjʊərəti/","pos":"phr.","cn":"粮食安全","pun":"福的 死扣锐踢","story":"粮仓的门死扣得紧紧的，有福的人才吃得饱——food security 就是粮食安全。","ex":"Climate change poses a serious threat to global food security.","exCn":"气候变化对全球粮食安全构成严重威胁。","col":["ensure food security","threat to food security","food insecurity"]},{"id":1389,"topic":"food","w":"supply chain","ipa":"/səˈplaɪ tʃeɪn/","pos":"phr.","cn":"供应链","pun":"色不来 缠","story":"菜色不来，是供应链上哪一环缠住了——supply chain 就是供应链。","ex":"Disruptions to the global supply chain left supermarket shelves empty during the pandemic.","exCn":"疫情期间全球供应链中断，超市货架空空如也。","col":["food supply chain","supply chain disruption","global supply chain"]},{"id":1390,"topic":"food","w":"distribution","ipa":"/ˌdɪstrɪˈbjuːʃn/","pos":"n.","cn":"分配；分销","pun":"地市去不用申","story":"粮食往地市去分，不用申请——distribution 就是分配、分销，distribute 是动词。","ex":"Hunger is often caused by poor distribution rather than insufficient production.","exCn":"饥饿往往由分配不均而非生产不足造成。","col":["food distribution","distribution network","distribute"]},{"id":1391,"topic":"food","w":"wastage","ipa":"/ˈweɪstɪdʒ/","pos":"n.","cn":"浪费；损耗","pun":"喂死提纸","story":"waste（浪费）+ -age：剩饭多到喂死狗，还得提纸擦嘴——wastage 就是浪费、损耗。","ex":"Food wastage occurs at every stage, from the farm to the consumer's kitchen.","exCn":"从农场到消费者的厨房，食物浪费发生在每个环节。","col":["food wastage","reduce wastage","wastage rate"]},{"id":1392,"topic":"food","w":"leftover","ipa":"/ˈleftəʊvə(r)/","pos":"n./adj.","cn":"剩菜；剩余的","pun":"来夫特欧巴","story":"left（剩下）+ over：剩下的菜来喂夫特和欧巴——leftovers 就是剩菜。","ex":"Restaurants could reduce waste by encouraging customers to take leftovers home.","exCn":"餐馆可以通过鼓励顾客把剩菜带回家来减少浪费。","col":["leftover food","eat leftovers","leftover rice"]},{"id":1393,"topic":"food","w":"expiry date","ipa":"/ɪkˈspaɪəri deɪt/","pos":"phr.","cn":"保质期；有效期","pun":"一颗死拍瑞 逮它","story":"过了保质期，一颗死了的拍瑞牌牛奶被逮住扔掉——expiry date 就是保质期，expire 是到期。","ex":"Confusion over expiry dates leads many households to throw away food that is still safe to eat.","exCn":"对保质期的困惑导致许多家庭扔掉仍可安全食用的食物。","col":["past its expiry date","check the expiry date","expire"]},{"id":1394,"topic":"food","w":"shelf life","ipa":"/ˈʃelf laɪf/","pos":"phr.","cn":"货架期；保存期限","pun":"晒了夫 来夫","story":"货架上晒了太久的面包，来夫说它的寿命到了——shelf life 就是货架期、保存期限。","ex":"Preservatives extend the shelf life of products but may have long-term health effects.","exCn":"防腐剂延长了产品的货架期，但可能有长期健康影响。","col":["long shelf life","extend shelf life","short shelf life"]},{"id":1395,"topic":"food","w":"label","ipa":"/ˈleɪbl/","pos":"n./v.","cn":"标签；贴标签","pun":"雷宝","story":"雷宝在每罐果酱上贴标签，写清成分——label 就是标签，food labelling 是食品标识。","ex":"Clearer food labels would help consumers make healthier choices.","exCn":"更清晰的食品标签能帮助消费者做出更健康的选择。","col":["food label","nutrition label","labelling"]},{"id":1396,"topic":"food","w":"sanitary","ipa":"/ˈsænətri/","pos":"adj.","cn":"卫生的；清洁的","pun":"三呢推","story":"三个厨师呢推着消毒车打扫厨房——sanitary 就是卫生的，sanitation 是卫生设施。","ex":"Poor sanitary conditions in food markets increase the risk of disease outbreaks.","exCn":"食品市场恶劣的卫生条件增加了疾病爆发的风险。","col":["sanitary conditions","sanitation","unsanitary"]},{"id":1397,"topic":"food","w":"toxin","ipa":"/ˈtɒksɪn/","pos":"n.","cn":"毒素","pun":"他可新","story":"他可新买的发霉花生有毒素，赶紧扔——toxin 就是毒素，toxic 是有毒的。","ex":"Toxins produced by mould can accumulate in grain that is stored in damp conditions.","exCn":"霉菌产生的毒素会在潮湿环境储存的谷物中积累。","col":["harmful toxins","toxic","remove toxins"]},{"id":1398,"topic":"food","w":"spoil","ipa":"/spɔɪl/","pos":"v.","cn":"变质；宠坏；破坏","pun":"死抛","story":"牛奶变质了只能死抛进垃圾桶——spoil 就是变质，也指宠坏孩子。","ex":"Without refrigeration, fresh produce spoils within days in tropical climates.","exCn":"在热带气候中，没有冷藏，新鲜农产品几天内就会变质。","col":["food spoils","spoiled food","spoilage"]},{"id":1399,"topic":"food","w":"decompose","ipa":"/ˌdiːkəmˈpəʊz/","pos":"v.","cn":"分解；腐烂","pun":"地扛剖死","story":"de-（去除）+ compose（组成）：埋在地里扛不住，剖开就烂了——decompose 就是分解、腐烂。","ex":"Organic waste decomposes naturally and can be turned into compost for farms.","exCn":"有机垃圾会自然分解，可以变成农场用的堆肥。","col":["decompose naturally","decomposition","decomposing matter"]},{"id":1400,"topic":"food","w":"decay","ipa":"/dɪˈkeɪ/","pos":"v./n.","cn":"腐烂；蛀牙；衰败","pun":"弟开","story":"弟弟开了一罐过期罐头，里面全烂了——decay 就是腐烂，tooth decay 是蛀牙。","ex":"Sugary drinks are the leading cause of tooth decay among schoolchildren.","exCn":"含糖饮料是学童蛀牙的主要原因。","col":["tooth decay","begin to decay","decayed fruit"]},{"id":1401,"topic":"food","w":"ferment","ipa":"/fəˈment/","pos":"v.","cn":"发酵","pun":"发门特","story":"发酵的面团把门特别顶开了——ferment 就是发酵，fermented food 是发酵食品。","ex":"Fermented foods such as yoghurt and kimchi are believed to benefit digestive health.","exCn":"酸奶和泡菜等发酵食品被认为有益于消化健康。","col":["fermented food","fermentation","ferment grapes"]},{"id":1402,"topic":"food","w":"refrigerate","ipa":"/rɪˈfrɪdʒəreɪt/","pos":"v.","cn":"冷藏","pun":"瑞飞几个热的","story":"瑞飞把几个热的菜放进冰箱冷藏——refrigerate 就是冷藏，refrigerator 是冰箱。","ex":"Vaccines and fresh food must be refrigerated throughout the entire supply chain.","exCn":"疫苗和新鲜食品在整个供应链中都必须冷藏。","col":["refrigerated transport","refrigeration","keep refrigerated"]},{"id":1403,"topic":"food","w":"agricultural","ipa":"/ˌæɡrɪˈkʌltʃərəl/","pos":"adj.","cn":"农业的","pun":"啊哥里靠车肉","story":"agri-（田地）+ culture（耕种）：啊哥在田里靠车拉肉，农业的活儿——agricultural 就是农业的。","ex":"Agricultural land accounts for nearly forty per cent of the planet's ice-free surface.","exCn":"农业用地占地球无冰陆地面积的近四成。","col":["agricultural land","agricultural production","agriculture"]},{"id":1404,"topic":"food","w":"canned","ipa":"/kænd/","pos":"adj.","cn":"罐装的","pun":"看的","story":"看的都是罐头，货架上一排排——canned food 就是罐装食品。","ex":"Canned vegetables retain most of their nutrients and can be stored for years.","exCn":"罐装蔬菜保留了大部分营养，可以储存数年。","col":["canned food","canned fruit","tinned"]},{"id":1405,"topic":"food","w":"ready meal","ipa":"/ˌredi ˈmiːl/","pos":"phr.","cn":"即食餐；预制菜","pun":"热的 密友","story":"热一下就能吃的密友饭盒——ready meal 就是即食餐、预制菜。","ex":"Ready meals are convenient but typically contain high levels of salt and saturated fat.","exCn":"即食餐很方便，但通常含盐和饱和脂肪很高。","col":["microwave ready meal","frozen ready meal","ready-made"]},{"id":1406,"topic":"food","w":"microwave","ipa":"/ˈmaɪkrəweɪv/","pos":"n./v.","cn":"微波炉；用微波炉加热","pun":"卖可喂","story":"micro（微）+ wave（波）：卖可以喂饱人的微波炉——microwave 就是微波炉。","ex":"The microwave oven has changed how families prepare food, favouring speed over freshness.","exCn":"微波炉改变了家庭准备食物的方式，重速度而轻新鲜。","col":["microwave oven","microwave a meal","microwaveable"]},{"id":1407,"topic":"food","w":"slaughter","ipa":"/ˈslɔːtə(r)/","pos":"v./n.","cn":"屠宰；屠杀","pun":"死喽它","story":"屠宰场里猪一进去就死喽它——slaughter 就是屠宰，slaughterhouse 是屠宰场。","ex":"Animals are often transported long distances to slaughter under stressful conditions.","exCn":"动物常常在紧张的条件下被长途运送去屠宰。","col":["slaughterhouse","slaughter animals","mass slaughter"]},{"id":1408,"topic":"food","w":"butcher","ipa":"/ˈbʊtʃə(r)/","pos":"n./v.","cn":"屠夫；肉贩","pun":"不吃","story":"肉贩天天切肉，自己反而不吃——butcher 就是屠夫、肉贩。","ex":"Local butchers have largely disappeared as supermarkets dominate meat sales.","exCn":"随着超市主导肉类销售，本地肉贩基本消失了。","col":["local butcher","butcher shop","the butcher's"]},{"id":1409,"topic":"food","w":"intensive","ipa":"/ɪnˈtensɪv/","pos":"adj.","cn":"集约的；密集的","pun":"因疼死我","story":"集约化养鸡场把鸡挤到因为疼死我——intensive farming 就是集约化农业。","ex":"Intensive farming methods maximise output but raise concerns about animal welfare and pollution.","exCn":"集约化耕作方法使产量最大化，但引发对动物福利和污染的担忧。","col":["intensive farming","labour-intensive","intensive agriculture"]},{"id":1410,"topic":"food","w":"factory farming","ipa":"/ˈfæktri ˈfɑːmɪŋ/","pos":"phr.","cn":"工厂化养殖","pun":"发可吹 发明","story":"把养殖场变成工厂，发可吹的量产发明——factory farming 就是工厂化养殖。","ex":"Critics argue that factory farming treats living animals as mere units of production.","exCn":"批评者认为工厂化养殖把活生生的动物仅仅当作生产单位。","col":["factory farming practices","factory-farmed meat","industrial farming"]},{"id":1411,"topic":"food","w":"free-range","ipa":"/ˌfriː ˈreɪndʒ/","pos":"adj.","cn":"散养的；放养的","pun":"福利 润之","story":"free（自由）+ range（活动范围）：鸡自由跑动是福利，肉也润——free-range 就是散养的。","ex":"Free-range eggs cost more but many consumers believe the higher price is justified.","exCn":"散养鸡蛋更贵，但许多消费者认为高价是合理的。","col":["free-range eggs","free-range chicken","free-range farming"]},{"id":1412,"topic":"food","w":"cruelty","ipa":"/ˈkruːəlti/","pos":"n.","cn":"残忍；虐待","pun":"哭喔踢","story":"小牛被踢得哭喔哭喔，太残忍——cruelty 就是残忍、虐待，cruel 是形容词。","ex":"Undercover footage exposed widespread cruelty on industrial pig farms.","exCn":"卧底拍摄的画面揭露了工业化养猪场普遍存在的虐待行为。","col":["animal cruelty","cruelty to animals","cruel"]},{"id":1413,"topic":"food","w":"hormone","ipa":"/ˈhɔːməʊn/","pos":"n.","cn":"激素；荷尔蒙","pun":"喝猛","story":"牛喝猛了激素，长得飞快——hormone 就是激素，growth hormone 是生长激素。","ex":"Some countries ban beef from cattle treated with growth hormones.","exCn":"一些国家禁止来自使用生长激素牛的牛肉。","col":["growth hormone","hormone-treated","hormone-free"]},{"id":1414,"topic":"food","w":"chemical","ipa":"/ˈkemɪkl/","pos":"n./adj.","cn":"化学品；化学的","pun":"可没颗","story":"打了化学农药，虫子可没一颗活的——chemical 就是化学品、化学的。","ex":"Consumers increasingly prefer food grown without synthetic chemicals.","exCn":"消费者越来越偏爱不使用合成化学品种植的食物。","col":["agricultural chemicals","chemical-free","chemical fertiliser"]},{"id":1415,"topic":"food","w":"synthetic","ipa":"/sɪnˈθetɪk/","pos":"adj.","cn":"合成的；人造的","pun":"新塞踢克","story":"新做的塞进肉里的踢克是合成香料，不是天然的——synthetic 就是合成的、人造的。","ex":"Synthetic sweeteners allow manufacturers to reduce sugar without sacrificing taste.","exCn":"合成甜味剂使生产商在不牺牲口味的情况下减少糖分。","col":["synthetic fertiliser","synthetic flavouring","synthesise"]},{"id":1416,"topic":"food","w":"raw","ipa":"/rɔː/","pos":"adj.","cn":"生的；未加工的","pun":"肉","story":"生的肉直接端上来——raw 就是生的、未加工的，raw material 是原材料。","ex":"Eating raw or undercooked meat carries a significant risk of food poisoning.","exCn":"食用生的或未煮熟的肉有很大的食物中毒风险。","col":["raw meat","raw materials","raw vegetables"]},{"id":1417,"topic":"food","w":"produce","ipa":"/ˈprɒdjuːs/","pos":"n.","cn":"农产品","pun":"泼肉丢死","story":"重音在前的 produce 是名词：泼了一地的肉和菜丢死人，都是农产品——produce 就是农产品。","ex":"Farmers' markets allow consumers to buy fresh produce directly from growers.","exCn":"农贸市场让消费者直接从种植者手里购买新鲜农产品。","col":["fresh produce","local produce","agricultural produce"]},{"id":1418,"topic":"food","w":"seasonal","ipa":"/ˈsiːzənl/","pos":"adj.","cn":"季节性的；应季的","pun":"洗针呢","story":"season（季节）+ -al：洗针呢，等到应季才吃草莓——seasonal 就是应季的、季节性的。","ex":"Eating seasonal fruit and vegetables reduces the energy needed for storage and transport.","exCn":"食用应季蔬果减少了储存和运输所需的能源。","col":["seasonal produce","seasonal workers","seasonal variation"]},{"id":1419,"topic":"food","w":"exotic","ipa":"/ɪɡˈzɒtɪk/","pos":"adj.","cn":"异国的；外来的","pun":"一个杂踢客","story":"一个杂七杂八的水果，踢开一看是外国来的——exotic 就是异国的、外来的。","ex":"Supermarkets now stock exotic fruits that would have been unheard of a generation ago.","exCn":"超市现在储备着一代人之前闻所未闻的异国水果。","col":["exotic fruit","exotic species","exotic dishes"]},{"id":1420,"topic":"food","w":"aquaculture","ipa":"/ˈækwəkʌltʃə(r)/","pos":"n.","cn":"水产养殖","pun":"啊夸卡车","story":"aqua（水）+ culture（养殖）：啊，夸一车养的鱼虾——aquaculture 就是水产养殖。","ex":"Aquaculture now supplies more than half of the fish consumed worldwide.","exCn":"水产养殖现在供应了全球一半以上的食用鱼。","col":["aquaculture industry","fish farming","aquaculture production"]},{"id":1421,"topic":"food","w":"fishery","ipa":"/ˈfɪʃəri/","pos":"n.","cn":"渔业；渔场","pun":"费鞋日","story":"渔场打鱼费鞋，日日踩在船板上——fishery 就是渔业、渔场。","ex":"Many coastal fisheries have collapsed because of decades of unregulated fishing.","exCn":"由于几十年无管制的捕捞，许多沿海渔场已经崩溃。","col":["commercial fisheries","fishery management","fisheries policy"]},{"id":1422,"topic":"food","w":"mechanisation","ipa":"/ˌmekənaɪˈzeɪʃn/","pos":"n.","cn":"机械化","pun":"没可耐泽神","story":"machine（机器）+ -isation：没有可以耐劳的人，只能请机器泽神——mechanisation 就是机械化。","ex":"Mechanisation has dramatically reduced the number of workers needed on farms.","exCn":"机械化大幅减少了农场所需的工人数量。","col":["farm mechanisation","mechanise","mechanised agriculture"]},{"id":1423,"topic":"food","w":"hunger","ipa":"/ˈhʌŋɡə(r)/","pos":"n.","cn":"饥饿；渴望","pun":"哼歌","story":"饿得只能哼歌转移注意力——hunger 就是饥饿，world hunger 是全球饥饿问题。","ex":"Ending world hunger requires better distribution as much as increased production.","exCn":"消除全球饥饿既需要增加生产，也同样需要更好的分配。","col":["world hunger","hunger and malnutrition","go hungry"]},{"id":1424,"topic":"food","w":"undernourished","ipa":"/ˌʌndəˈnʌrɪʃt/","pos":"adj.","cn":"营养不足的","pun":"安德 那日是特","story":"under（不足）+ nourish（滋养）：安德那日是特别瘦，吃得不够——undernourished 就是营养不足的。","ex":"Around one in ten people worldwide remain undernourished despite record harvests.","exCn":"尽管收成创纪录，全球仍约有十分之一的人营养不足。","col":["undernourished children","chronically undernourished","undernourishment"]},{"id":1425,"topic":"food","w":"nourish","ipa":"/ˈnʌrɪʃ/","pos":"v.","cn":"滋养；养育","pun":"那日是","story":"那日是妈妈熬的粥滋养了我——nourish 就是滋养，nourishing 是有营养的。","ex":"A varied diet nourishes both the body and the developing brain of a child.","exCn":"多样化的饮食滋养儿童的身体和发育中的大脑。","col":["nourish the body","nourishing food","nourishment"]},{"id":1426,"topic":"food","w":"digest","ipa":"/daɪˈdʒest/","pos":"v.","cn":"消化；领会","pun":"呆着死的","story":"吃太撑呆着死的不动，胃在慢慢消化——digest 就是消化，digestive 是消化的。","ex":"Fibre-rich foods take longer to digest and therefore keep people feeling full.","exCn":"富含纤维的食物消化时间更长，因此让人更有饱腹感。","col":["digest food","digestive system","digestion"]},{"id":1427,"topic":"food","w":"intolerance","ipa":"/ɪnˈtɒlərəns/","pos":"n.","cn":"不耐受；不容忍","pun":"硬套了人事","story":"in-（不）+ tolerance（耐受）：硬套了人家的食谱，喝奶不耐受拉肚子——intolerance 就是不耐受。","ex":"Lactose intolerance is far more common in East Asia than in northern Europe.","exCn":"乳糖不耐受在东亚比在北欧常见得多。","col":["lactose intolerance","food intolerance","intolerant"]},{"id":1428,"topic":"food","w":"gluten","ipa":"/ˈɡluːtn/","pos":"n.","cn":"麸质；谷蛋白","pun":"骨录腾","story":"面团里的骨录腾胶一样黏，那是麸质——gluten 就是麸质，gluten-free 是无麸质的。","ex":"Gluten-free products have moved from a medical necessity to a fashionable lifestyle choice.","exCn":"无麸质产品已从医学必需品变成时髦的生活方式选择。","col":["gluten-free","gluten intolerance","contain gluten"]},{"id":1429,"topic":"food","w":"sugary","ipa":"/ˈʃʊɡəri/","pos":"adj.","cn":"含糖的；甜腻的","pun":"熟哥里","story":"sugar（糖）+ -y：熟哥里外全是糖，饮料甜得发腻——sugary 就是含糖的。","ex":"A tax on sugary drinks has been introduced in several countries to tackle childhood obesity.","exCn":"几个国家已对含糖饮料征税以应对儿童肥胖。","col":["sugary drinks","sugary snacks","sugar tax"]},{"id":1430,"topic":"food","w":"fatty","ipa":"/ˈfæti/","pos":"adj.","cn":"高脂肪的；油腻的","pun":"肥踢","story":"fat（脂肪）+ -y：肥肉踢都踢不动，太油腻——fatty 就是高脂肪的。","ex":"Fatty foods should be eaten sparingly as part of a healthy diet.","exCn":"作为健康饮食的一部分，高脂肪食物应少量食用。","col":["fatty foods","fatty acids","fatty meat"]},{"id":1431,"topic":"food","w":"saturated","ipa":"/ˈsætʃəreɪtɪd/","pos":"adj.","cn":"饱和的","pun":"洒车蕊踢的","story":"洒了满车的油，蕊踢一脚都溢出来，饱和了——saturated fat 就是饱和脂肪。","ex":"Diets high in saturated fat raise cholesterol levels and increase the risk of heart disease.","exCn":"高饱和脂肪饮食会提高胆固醇水平，增加心脏病风险。","col":["saturated fat","unsaturated","saturated with"]},{"id":1432,"topic":"food","w":"excessive","ipa":"/ɪkˈsesɪv/","pos":"adj.","cn":"过多的；过度的","pun":"一颗塞死我","story":"exceed（超过）：一颗一颗吃到塞死我，太过量——excessive 就是过多的，excess 是过量。","ex":"Excessive consumption of red meat has been linked to bowel cancer.","exCn":"红肉的过度消费与肠癌有关。","col":["excessive consumption","excessive amounts","in excess"]},{"id":1433,"topic":"food","w":"moderation","ipa":"/ˌmɒdəˈreɪʃn/","pos":"n.","cn":"适度；节制","pun":"摸得瑞神","story":"摸得瑞神的指点：什么都吃一点，不过量——moderation 就是适度，in moderation 是适量地。","ex":"Most nutritionists agree that any food can be enjoyed in moderation.","exCn":"大多数营养学家认为任何食物都可以适量享用。","col":["in moderation","eat in moderation","moderate"]},{"id":1434,"topic":"food","w":"appetising","ipa":"/ˈæpɪtaɪzɪŋ/","pos":"adj.","cn":"开胃的；诱人的","pun":"爱陪太醒","story":"appetite（食欲）+ -ising：菜香得爱陪太太半夜醒来吃——appetising 就是开胃的。","ex":"Making healthy meals look appetising is one way to encourage children to eat vegetables.","exCn":"让健康餐看起来诱人是鼓励孩子吃蔬菜的一种方法。","col":["appetising smell","look appetising","unappetising"]},{"id":1435,"topic":"food","w":"palatable","ipa":"/ˈpælətəbl/","pos":"adj.","cn":"可口的；可接受的","pun":"怕了他伯","story":"palate（味觉）+ -able：怕了他伯伯的手艺，居然做得很可口——palatable 就是可口的。","ex":"Insects could become a palatable protein source if they are processed into familiar forms.","exCn":"如果加工成熟悉的形态，昆虫可能成为可口的蛋白质来源。","col":["palatable food","more palatable","palate"]},{"id":1436,"topic":"food","w":"hearty","ipa":"/ˈhɑːti/","pos":"adj.","cn":"丰盛的；健壮的","pun":"哈提","story":"heart（心）+ -y：哈，提着一大锅炖菜，暖心又丰盛——hearty 就是丰盛的。","ex":"Farm workers traditionally ate a hearty breakfast before a long day in the fields.","exCn":"农场工人传统上在田间劳作一整天前会吃一顿丰盛的早餐。","col":["hearty meal","hearty breakfast","hearty appetite"]},{"id":1437,"topic":"food","w":"home-cooked","ipa":"/ˌhəʊm ˈkʊkt/","pos":"adj.","cn":"家常的；自家做的","pun":"后母哭的","story":"后母哭着做了一桌家常菜——home-cooked 就是自家做的，home-cooked meal 是家常饭。","ex":"Home-cooked meals allow families to control exactly what goes into their food.","exCn":"家常饭菜让家庭能精确控制食物里放了什么。","col":["home-cooked meal","home-cooked food","home cooking"]},{"id":1438,"topic":"food","w":"smallholder","ipa":"/ˈsmɔːlhəʊldə(r)/","pos":"n.","cn":"小农户","pun":"死猫后的","story":"small（小）+ holder（持有者）：小农户守着一小块地，死猫后的院子也种上菜——smallholder 就是小农户。","ex":"Smallholders produce a large share of the food consumed in developing countries.","exCn":"小农户生产了发展中国家消费食物的很大一部分。","col":["smallholder farmers","smallholder agriculture","smallholding"]},{"id":1439,"topic":"language","w":"accent","ipa":"/ˈæksent/","pos":"n.","cn":"口音；重音","pun":"爱可森特","story":"爱可森特一开口，大家就听出他是苏格兰来的——口音藏不住。","ex":"A regional accent should never be regarded as a sign of poor education.","exCn":"地方口音绝不应被视为教育水平低的标志。","col":["a strong accent","regional accent","accented speech"]},{"id":1440,"topic":"language","w":"vocabulary","ipa":"/vəˈkæbjələri/","pos":"n.","cn":"词汇量","pun":"我开步了里","story":"voc 是「叫、说」的词根：我开步了，每天往脑子里装新词，词汇量越走越大。","ex":"Reading widely is the most reliable way to expand one's academic vocabulary.","exCn":"广泛阅读是扩大学术词汇量最可靠的方法。","col":["expand vocabulary","a wide vocabulary","vocabulary acquisition"]},{"id":1441,"topic":"language","w":"grammar","ipa":"/ˈɡræmə(r)/","pos":"n.","cn":"语法","pun":"哥拉么","story":"哥拉么，你这句话主谓宾全乱了——语法要重新学。","ex":"Some educators argue that explicit grammar instruction is less effective than natural exposure.","exCn":"一些教育者认为，明确的语法教学不如自然接触有效。","col":["grammar rules","grammatical error","grammatically correct"]},{"id":1442,"topic":"language","w":"pronunciation","ipa":"/prəˌnʌnsiˈeɪʃn/","pos":"n.","cn":"发音","pun":"扑朗西诶申","story":"pro-nounce 是「向外发声」：扑朗西诶申，一个个音往外扑，练的就是发音。","ex":"Clear pronunciation matters more than a native-like accent in international communication.","exCn":"在国际交流中，清晰的发音比地道口音更重要。","col":["correct pronunciation","pronounce a word","pronunciation practice"]},{"id":1443,"topic":"language","w":"multilingual","ipa":"/ˌmʌltiˈlɪŋɡwəl/","pos":"adj.","cn":"多语言的","pun":"毛提零狗","story":"multi- 是「多」：毛提零狗会四国语言，多语言的才叫真本事。","ex":"Multilingual societies tend to be more open to cultural exchange and international trade.","exCn":"多语言社会往往更愿意接受文化交流和国际贸易。","col":["multilingual society","multilingual staff","multilingualism"]},{"id":1444,"topic":"language","w":"native","ipa":"/ˈneɪtɪv/","pos":"adj./n.","cn":"母语的；本地人","pun":"内替我","story":"nat 是「出生」：出生就会的语言，内替我说也说不出那种味儿——母语的。","ex":"Native speakers are not necessarily the best teachers of their own language.","exCn":"母语者未必是教自己语言的最佳老师。","col":["native speaker","native language","non-native"]},{"id":1445,"topic":"language","w":"eloquent","ipa":"/ˈeləkwənt/","pos":"adj.","cn":"雄辩的；有口才的","pun":"爱了快恩特","story":"loqu 是「说」：他一开口，全场「爱了」，快恩特这口才叫雄辩。","ex":"An eloquent speech can sway public opinion more effectively than pages of statistics.","exCn":"一篇雄辩的演讲比成页的数据更能左右舆论。","col":["an eloquent speech","eloquently","eloquence"]},{"id":1446,"topic":"language","w":"coherent","ipa":"/kəʊˈhɪərənt/","pos":"adj.","cn":"连贯的；条理清晰的","pun":"扣黑人特","story":"co- 是「一起」，here 是「粘」：把句子扣在一起粘牢，文章就连贯了。","ex":"Examiners reward essays that present a coherent argument supported by relevant examples.","exCn":"考官会给出论证连贯、例证相关的文章高分。","col":["a coherent argument","coherence","coherently"]},{"id":1447,"topic":"language","w":"concise","ipa":"/kənˈsaɪs/","pos":"adj.","cn":"简洁的","pun":"肯赛死","story":"cis 是「切」：肯把废话统统切掉，赛死那些啰嗦的人——这叫简洁。","ex":"A concise summary is often more persuasive than a lengthy explanation.","exCn":"简洁的总结往往比冗长的解释更有说服力。","col":["concise and clear","a concise summary","concisely"]},{"id":1448,"topic":"language","w":"ambiguous","ipa":"/æmˈbɪɡjuəs/","pos":"adj.","cn":"模棱两可的","pun":"俺比给我死","story":"ambi- 是「两边」：「俺比给我死」到底是谁比谁？两种理解都通，模棱两可。","ex":"Ambiguous wording in a contract can lead to costly legal disputes.","exCn":"合同措辞含糊可能导致代价高昂的法律纠纷。","col":["ambiguous wording","deliberately ambiguous","ambiguity"]},{"id":1449,"topic":"language","w":"literal","ipa":"/ˈlɪtərəl/","pos":"adj.","cn":"字面的；逐字的","pun":"里特若","story":"liter 是「字母」：里特若翻译只看字面，一个字对一个字，闹出不少笑话。","ex":"A literal translation rarely captures the tone of the original text.","exCn":"逐字翻译很少能传达原文的语气。","col":["literal meaning","literal translation","literally"]},{"id":1450,"topic":"language","w":"figurative","ipa":"/ˈfɪɡərətɪv/","pos":"adj.","cn":"比喻的","pun":"飞哥若替我","story":"飞哥说「我心里飞起来了」，并不是真的飞，是比喻的说法。","ex":"Learners often struggle with figurative language such as metaphors and idioms.","exCn":"学习者常常难以理解比喻性语言，如隐喻和习语。","col":["figurative language","figurative meaning","figure of speech"]},{"id":1451,"topic":"language","w":"idiom","ipa":"/ˈɪdiəm/","pos":"n.","cn":"习语；成语","pun":"一地儿么","story":"「一地儿么」——一个地方人才懂的固定说法，外人听不懂，这就是习语。","ex":"Idioms are notoriously difficult to translate because their meaning is not literal.","exCn":"习语出了名地难翻译，因为它们的意思不是字面的。","col":["a common idiom","idiomatic expression","idiomatically"]},{"id":1452,"topic":"language","w":"slang","ipa":"/slæŋ/","pos":"n.","cn":"俚语","pun":"死浪","story":"「死浪」这种年轻人的街头说法，词典查不到，就是俚语。","ex":"Teenagers use slang to establish a sense of identity within their peer group.","exCn":"青少年用俚语在同龄群体中建立身份认同。","col":["teenage slang","slang term","use slang"]},{"id":1453,"topic":"language","w":"jargon","ipa":"/ˈdʒɑːɡən/","pos":"n.","cn":"行话；术语","pun":"渣根","story":"医生一开口全是「渣根」听不懂的词——满嘴行话。","ex":"Scientists should avoid technical jargon when communicating with the general public.","exCn":"科学家与公众交流时应避免专业行话。","col":["technical jargon","legal jargon","full of jargon"]},{"id":1454,"topic":"language","w":"colloquial","ipa":"/kəˈləʊkwiəl/","pos":"adj.","cn":"口语的；非正式的","pun":"可搂魁儿","story":"col- 是「一起」，loqu 是「说」：大家搂在一起随便聊的话，就是口语化的。","ex":"Colloquial expressions are appropriate in speech but should be avoided in academic essays.","exCn":"口语表达在口头交流中合适，但学术论文中应避免。","col":["colloquial language","colloquial expression","colloquially"]},{"id":1455,"topic":"language","w":"interpret","ipa":"/ɪnˈtɜːprɪt/","pos":"v.","cn":"口译；解读","pun":"银特扑瑞特","story":"inter- 是「之间」：站在两个人之间把话「扑」过去，就是口译、解读。","ex":"Diplomats rely on professionals to interpret speeches accurately during international summits.","exCn":"外交官在国际峰会上依靠专业人员准确口译讲话。","col":["interpret a speech","interpret data","interpretation"]},{"id":1456,"topic":"language","w":"translate","ipa":"/trænzˈleɪt/","pos":"v.","cn":"翻译","pun":"穿死累特","story":"trans- 是「跨过」，late 是「搬」：把意思跨语言搬过去，穿着都累了——翻译真辛苦。","ex":"Machine tools can translate simple texts but often fail with literature and humour.","exCn":"机器工具能翻译简单文本，但在文学和幽默上常常失败。","col":["translate into English","translation","translator"]},{"id":1457,"topic":"language","w":"transcribe","ipa":"/trænˈskraɪb/","pos":"v.","cn":"转录；抄写","pun":"穿死快步","story":"scribe 是「写」：录音一放，穿死快步把每个字写下来，就是转录。","ex":"Researchers must transcribe every interview before analysing the data.","exCn":"研究者在分析数据前必须转录每一次访谈。","col":["transcribe an interview","transcription","transcript"]},{"id":1458,"topic":"language","w":"paraphrase","ipa":"/ˈpærəfreɪz/","pos":"v./n.","cn":"改述；意译","pun":"派若弗雷兹","story":"para- 是「旁边」，phrase 是「说法」：在原话旁边换个说法，就是改述。","ex":"Candidates should paraphrase the question rather than copying it word for word.","exCn":"考生应改述题目，而不是逐字照抄。","col":["paraphrase a sentence","paraphrasing skills","a paraphrase of"]},{"id":1459,"topic":"language","w":"summarise","ipa":"/ˈsʌməraɪz/","pos":"v.","cn":"总结；概括","pun":"傻么来","story":"sum 是「总和」：傻么，来把一大篇加起来说成三句，这就是总结。","ex":"The final paragraph should summarise the main points without introducing new ideas.","exCn":"结尾段应总结要点，而不引入新观点。","col":["summarise the findings","summary","in summary"]},{"id":1460,"topic":"language","w":"convey","ipa":"/kənˈveɪ/","pos":"v.","cn":"传达；表达","pun":"啃维","story":"con- 是「一起」，vey 是「路」：啃着面包沿路送信，把意思传达过去。","ex":"Body language can convey emotions that words alone cannot express.","exCn":"肢体语言能传达言语无法表达的情感。","col":["convey a message","convey meaning","convey emotion"]},{"id":1461,"topic":"language","w":"gesture","ipa":"/ˈdʒestʃə(r)/","pos":"n./v.","cn":"手势；示意","pun":"接手车","story":"接手车时，司机不说话，一个手势示意你过去。","ex":"The same gesture may be polite in one culture and offensive in another.","exCn":"同一个手势在一种文化里礼貌，在另一种文化里却冒犯。","col":["hand gesture","make a gesture","gesture towards"]},{"id":1462,"topic":"language","w":"intonation","ipa":"/ˌɪntəˈneɪʃn/","pos":"n.","cn":"语调","pun":"因特内申","story":"in- 加 tone「音调」：因特内申说话像唱歌，高低起伏，这就是语调。","ex":"Rising intonation at the end of a sentence often indicates a question in English.","exCn":"英语中句尾升调常表示疑问。","col":["rising intonation","intonation pattern","falling intonation"]},{"id":1463,"topic":"language","w":"tone","ipa":"/təʊn/","pos":"n.","cn":"语气；音调","pun":"通","story":"通知一样的东西，用不同语气说出来，听着完全两回事。","ex":"The tone of an email can easily be misread without the cues of face-to-face conversation.","exCn":"没有面对面交谈的线索，电子邮件的语气很容易被误读。","col":["tone of voice","a formal tone","set the tone"]},{"id":1464,"topic":"language","w":"nonverbal","ipa":"/ˌnɒnˈvɜːbl/","pos":"adj.","cn":"非语言的","pun":"农我播","story":"non- 是「非」，verb 是「话」：农民伯伯不说话，我用眼神播报，这是非语言交流。","ex":"Studies suggest that nonverbal signals account for a large proportion of communication.","exCn":"研究表明，非语言信号在交流中占很大比重。","col":["nonverbal communication","nonverbal cues","nonverbal behaviour"]},{"id":1465,"topic":"language","w":"eye contact","ipa":"/ˈaɪ kɒntækt/","pos":"phr.","cn":"目光接触","pun":"爱看太可","story":"爱看太可爱的人，眼神一对上，这就是目光接触。","ex":"In many Western cultures, maintaining eye contact is seen as a sign of honesty.","exCn":"在许多西方文化中，保持目光接触被视为诚实的标志。","col":["maintain eye contact","make eye contact","avoid eye contact"]},{"id":1466,"topic":"language","w":"body language","ipa":"/ˈbɒdi læŋɡwɪdʒ/","pos":"phr.","cn":"肢体语言","pun":"巴弟练归着","story":"巴弟不说话，练着归着一个动作，你就知道他不高兴——肢体语言。","ex":"Interviewers often read a candidate's body language as closely as their answers.","exCn":"面试官读候选人的肢体语言，和读答案一样仔细。","col":["read body language","positive body language","body language expert"]},{"id":1467,"topic":"language","w":"lingua franca","ipa":"/ˌlɪŋɡwə ˈfræŋkə/","pos":"phr.","cn":"通用语","pun":"零挂法兰卡","story":"零挂科的法兰卡靠一门大家都懂的语言走遍天下——通用语。","ex":"English now serves as a lingua franca among people who share no common mother tongue.","exCn":"英语如今是没有共同母语的人之间的通用语。","col":["global lingua franca","serve as a lingua franca","English as a lingua franca"]},{"id":1468,"topic":"language","w":"universal","ipa":"/ˌjuːnɪˈvɜːsl/","pos":"adj.","cn":"普遍的；通用的","pun":"油腻我搜","story":"uni- 是「一」：油腻大叔全世界都一个样，普遍的、通用的。","ex":"Some linguists believe that certain grammatical features are universal to all human languages.","exCn":"一些语言学家认为，某些语法特征是所有人类语言共有的。","col":["universal language","universally accepted","universality"]},{"id":1469,"topic":"language","w":"standardise","ipa":"/ˈstændədaɪz/","pos":"v.","cn":"使标准化","pun":"死蛋得代兹","story":"standard 是「标准」：死蛋也得按代码标准来，全国拼写统一，这是标准化。","ex":"Efforts to standardise spelling helped create a shared national written language.","exCn":"统一拼写的努力帮助形成了全国共享的书面语。","col":["standardise spelling","standardised test","standardisation"]},{"id":1470,"topic":"language","w":"alphabet","ipa":"/ˈælfəbet/","pos":"n.","cn":"字母表","pun":"爱发被他","story":"alpha 和 beta 是希腊头两个字母：爱发被他背了个遍，整套字母表。","ex":"The Latin alphabet has been adopted by hundreds of languages around the world.","exCn":"拉丁字母表已被全世界数百种语言采用。","col":["the Latin alphabet","alphabetical order","learn the alphabet"]},{"id":1471,"topic":"language","w":"script","ipa":"/skrɪpt/","pos":"n.","cn":"文字；剧本","pun":"死可瑞普特","story":"scrib 是「写」：死可怕，瑞普特写的文字弯弯绕绕像画符——一套书写文字。","ex":"Some languages are written in more than one script, which complicates literacy education.","exCn":"有些语言使用不止一种文字书写，这使识字教育更加复杂。","col":["writing script","Arabic script","film script"]},{"id":1472,"topic":"language","w":"syllable","ipa":"/ˈsɪləbl/","pos":"n.","cn":"音节","pun":"洗了包","story":"洗、了、包——三个音一拍一拍数，每一拍就是一个音节。","ex":"Stress placement on the wrong syllable can make a word unintelligible to listeners.","exCn":"重音放错音节会让听者听不懂这个词。","col":["stressed syllable","a two-syllable word","syllable stress"]},{"id":1473,"topic":"language","w":"phrase","ipa":"/freɪz/","pos":"n./v.","cn":"短语；措辞","pun":"弗雷兹","story":"弗雷兹不背单词只背短语，几个词打包一起用，说话地道多了。","ex":"Learning fixed phrases helps learners sound more natural than memorising isolated words.","exCn":"学习固定短语比背孤立单词更能让学习者听起来自然。","col":["a fixed phrase","phrase a question","phrasing"]},{"id":1474,"topic":"language","w":"utterance","ipa":"/ˈʌtərəns/","pos":"n.","cn":"话语；发声","pun":"阿特润死","story":"utter 是「说出」：阿特一开口，润死你的耳朵，说出来的每句话都是话语。","ex":"Linguists analyse everyday utterances to understand how meaning is negotiated in conversation.","exCn":"语言学家分析日常话语，以了解对话中意义如何协商。","col":["a single utterance","utter a word","spoken utterance"]},{"id":1475,"topic":"language","w":"verbal","ipa":"/ˈvɜːbl/","pos":"adj.","cn":"口头的；言语的","pun":"我播","story":"verb 是「词、话」：我播报的是口头的话，没写下来，这叫口头的。","ex":"Verbal agreements are harder to enforce than written contracts.","exCn":"口头协议比书面合同更难执行。","col":["verbal communication","verbal skills","verbally"]},{"id":1476,"topic":"language","w":"oral","ipa":"/ˈɔːrəl/","pos":"adj.","cn":"口头的；口腔的","pun":"哦若","story":"哦若你不写，就用嘴说吧——口头的，也是口腔的。","ex":"Oral traditions preserved history for centuries before writing systems were developed.","exCn":"在书写系统发展之前，口头传统保存了几个世纪的历史。","col":["oral tradition","oral presentation","orally"]},{"id":1477,"topic":"language","w":"legible","ipa":"/ˈledʒəbl/","pos":"adj.","cn":"字迹清楚的","pun":"来举包","story":"leg 是「读」：来，举起包裹上的字，能读清楚就是字迹清楚的。","ex":"Handwritten answers must be legible, or examiners cannot award marks.","exCn":"手写答案必须字迹清楚，否则考官无法给分。","col":["legible handwriting","clearly legible","illegible"]},{"id":1478,"topic":"language","w":"handwriting","ipa":"/ˈhændraɪtɪŋ/","pos":"n.","cn":"书写；笔迹","pun":"汉得赖听","story":"hand 加 writing：汉得靠听写练字，每个人的笔迹都不一样。","ex":"Some schools worry that typing has replaced handwriting almost entirely.","exCn":"一些学校担心打字几乎完全取代了手写。","col":["neat handwriting","handwriting skills","handwritten"]},{"id":1479,"topic":"language","w":"punctuation","ipa":"/ˌpʌŋktʃuˈeɪʃn/","pos":"n.","cn":"标点符号","pun":"胖客出诶申","story":"punct 是「点」：胖客出门一句话不带点，读得人喘不过气——缺标点。","ex":"Poor punctuation can change the meaning of a sentence entirely.","exCn":"标点使用不当可能完全改变句意。","col":["punctuation marks","correct punctuation","punctuate"]},{"id":1480,"topic":"language","w":"abbreviation","ipa":"/əˌbriːviˈeɪʃn/","pos":"n.","cn":"缩写","pun":"额不理为诶申","story":"brev 是「短」：额，不理会那么长，为了省事写短点——缩写。","ex":"Text messaging has popularised abbreviations that now appear even in formal writing.","exCn":"短信普及了缩写，如今连正式写作中也出现了。","col":["a common abbreviation","abbreviate","the abbreviation for"]},{"id":1481,"topic":"language","w":"acronym","ipa":"/ˈækrənɪm/","pos":"n.","cn":"首字母缩略词","pun":"爱克若您","story":"acro 是「顶端」，nym 是「名」：把每个词顶端的字母拼成新名，如 IELTS——首字母缩略词。","ex":"Government documents are often full of acronyms that confuse ordinary readers.","exCn":"政府文件常常充满让普通读者困惑的首字母缩略词。","col":["stand for an acronym","use an acronym","acronyms and abbreviations"]},{"id":1482,"topic":"language","w":"terminology","ipa":"/ˌtɜːmɪˈnɒlədʒi/","pos":"n.","cn":"术语","pun":"特么闹了几","story":"term 是「术语」：特么闹了几遍还听不懂，那些专业词就是术语。","ex":"Medical terminology often acts as a barrier between doctors and their patients.","exCn":"医学术语常常成为医生和患者之间的障碍。","col":["technical terminology","legal terminology","terminological"]},{"id":1483,"topic":"language","w":"nuance","ipa":"/ˈnjuːɑːns/","pos":"n.","cn":"细微差别","pun":"牛昂死","story":"牛昂头和牛低头，表情差一点点，意思完全不同——细微差别。","ex":"Only advanced learners can appreciate the nuances of meaning between similar words.","exCn":"只有高级学习者才能体会近义词之间意义的细微差别。","col":["subtle nuance","nuance of meaning","nuanced"]},{"id":1484,"topic":"language","w":"connotation","ipa":"/ˌkɒnəˈteɪʃn/","pos":"n.","cn":"内涵；隐含意义","pun":"看呢忒申","story":"con- 是「一起」，not 是「记号」：看呢，词身上一起带着的感情记号——内涵。","ex":"The word cheap carries a negative connotation that inexpensive does not.","exCn":"cheap 一词带有 inexpensive 所没有的负面含义。","col":["negative connotation","carry a connotation","connote"]},{"id":1485,"topic":"language","w":"implication","ipa":"/ˌɪmplɪˈkeɪʃn/","pos":"n.","cn":"含义；暗示","pun":"因扑力开心","story":"im- 是「里面」，plic 是「折」：意思折在话里面，因扑力开心才能读出暗示。","ex":"The implication of the report is that current language policy has failed.","exCn":"这份报告的言外之意是，当前的语言政策已经失败。","col":["clear implication","have implications for","by implication"]},{"id":1486,"topic":"language","w":"infer","ipa":"/ɪnˈfɜː(r)/","pos":"v.","cn":"推断","pun":"因佛","story":"in- 是「里」，fer 是「带」：因为佛不明说，你得从话里带出意思——推断。","ex":"Readers must infer the author's attitude from subtle word choices.","exCn":"读者必须从细微的用词中推断作者的态度。","col":["infer from","inference","draw an inference"]},{"id":1487,"topic":"language","w":"imply","ipa":"/ɪmˈplaɪ/","pos":"v.","cn":"暗示；意味着","pun":"因扑来","story":"im- 是「里」，ply 是「折」：意思折在里面，因为扑来的暗示你得自己拆。","ex":"Her silence seemed to imply disagreement with the proposal.","exCn":"她的沉默似乎暗示着不同意这项提议。","col":["imply that","implied meaning","implicit"]},{"id":1488,"topic":"language","w":"persuade","ipa":"/pəˈsweɪd/","pos":"v.","cn":"说服","pun":"泼水的","story":"per- 是「彻底」，suade 是「劝」：泼水的一直劝你别泼，最后把你说服了。","ex":"Advertisers use emotional language to persuade consumers to buy products they do not need.","exCn":"广告商用情感化语言说服消费者购买不需要的产品。","col":["persuade sb to do","persuasive","persuasion"]},{"id":1489,"topic":"language","w":"convince","ipa":"/kənˈvɪns/","pos":"v.","cn":"使信服","pun":"啃文思","story":"con- 是「完全」，vince 是「征服」：啃完他的文思，完全被征服——信服了。","ex":"Statistics alone rarely convince an audience unless they are linked to a human story.","exCn":"除非与人的故事相联系，否则单靠数据很少能让听众信服。","col":["convince sb of","convincing","convinced that"]},{"id":1490,"topic":"language","w":"argue","ipa":"/ˈɑːɡjuː/","pos":"v.","cn":"论证；争论","pun":"阿狗","story":"阿狗为了一根骨头跟人吵，还讲一二三条理由——争论、论证。","ex":"Some argue that learning a foreign language should be optional rather than compulsory.","exCn":"有人认为学外语应该是可选的，而不是必修的。","col":["argue that","argue for","argument"]},{"id":1491,"topic":"language","w":"debate","ipa":"/dɪˈbeɪt/","pos":"n./v.","cn":"辩论","pun":"地贝特","story":"de- 是「向下」，bat 是「打」：地贝特和对手你来我往往下打，用嘴打就是辩论。","ex":"The debate over whether children should start learning English at three remains unresolved.","exCn":"关于儿童是否应从三岁开始学英语的辩论仍无定论。","col":["heated debate","debate over","debatable"]},{"id":1492,"topic":"language","w":"rhetoric","ipa":"/ˈretərɪk/","pos":"n.","cn":"修辞；华丽辞藻","pun":"热特瑞克","story":"热特瑞克演讲一套一套，排比、反问全上，全是修辞，就是没内容。","ex":"Political rhetoric often appeals to emotion rather than evidence.","exCn":"政治修辞常常诉诸情感而非证据。","col":["political rhetoric","empty rhetoric","rhetorical question"]},{"id":1493,"topic":"language","w":"assert","ipa":"/əˈsɜːt/","pos":"v.","cn":"断言；坚称","pun":"饿射特","story":"饿了也要射出特别肯定的话：「就是这样！」——断言。","ex":"The author asserts that language shapes the way we perceive the world.","exCn":"作者断言，语言塑造了我们感知世界的方式。","col":["assert that","assertion","assertive"]},{"id":1494,"topic":"language","w":"contradict","ipa":"/ˌkɒntrəˈdɪkt/","pos":"v.","cn":"反驳；与……矛盾","pun":"看出弟克特","story":"contra- 是「相反」，dict 是「说」：看出弟弟克特说的和事实相反，当场反驳。","ex":"The witness's statement appeared to contradict the evidence presented earlier.","exCn":"证人的陈述似乎与先前出示的证据相矛盾。","col":["contradict a claim","contradiction","contradictory"]},{"id":1495,"topic":"language","w":"refute","ipa":"/rɪˈfjuːt/","pos":"v.","cn":"驳斥；反驳","pun":"瑞否特","story":"瑞士人说「否」，特别有证据地否定你——驳斥。","ex":"The researchers were able to refute the claim that bilingualism delays speech development.","exCn":"研究者得以驳斥「双语延迟语言发展」的说法。","col":["refute an argument","refute a claim","refutation"]},{"id":1496,"topic":"language","w":"counterargument","ipa":"/ˈkaʊntərɑːɡjumənt/","pos":"n.","cn":"反驳论点","pun":"扛特阿狗门特","story":"counter- 是「相反」：阿狗门口扛着相反的理由等你——反驳论点。","ex":"A strong essay anticipates the counterargument and addresses it directly.","exCn":"一篇好文章会预见反方论点并直接回应。","col":["present a counterargument","address the counterargument","counter an argument"]},{"id":1497,"topic":"language","w":"justify","ipa":"/ˈdʒʌstɪfaɪ/","pos":"v.","cn":"证明……合理","pun":"杰斯提飞","story":"just 是「公正」：杰斯提着理由飞过来，证明他做的事合理。","ex":"Candidates must justify their opinions with relevant reasons and examples.","exCn":"考生必须用相关理由和例子来证明自己的观点合理。","col":["justify a decision","justification","justifiable"]},{"id":1498,"topic":"language","w":"emphasise","ipa":"/ˈemfəsaɪz/","pos":"v.","cn":"强调","pun":"俺发塞死","story":"俺发言时把重点塞到最前面，说三遍——强调。","ex":"Teachers should emphasise communication rather than perfect grammar.","exCn":"教师应强调交流，而不是完美的语法。","col":["emphasise the importance of","emphasis on","emphatic"]},{"id":1499,"topic":"language","w":"clarify","ipa":"/ˈklærəfaɪ/","pos":"v.","cn":"澄清；阐明","pun":"克拉若飞","story":"clar 是「清楚」：克拉若飞起来把雾吹散，一切说清楚——澄清。","ex":"Speakers should pause to clarify any point the audience appears not to understand.","exCn":"演讲者应停下来澄清听众似乎不理解的任何要点。","col":["clarify a point","clarification","seek clarification"]},{"id":1500,"topic":"language","w":"elaborate","ipa":"/ɪˈlæbəreɪt/","pos":"v./adj.","cn":"详细阐述；精心的","pun":"一啦伯瑞特","story":"e- 是「出」，labor 是「劳动」：一啦一啦费力往外说细节——详细阐述。","ex":"In the speaking test, candidates are expected to elaborate on their answers rather than give one-word replies.","exCn":"口语考试中，考生应详细展开回答，而非只答一个词。","col":["elaborate on","an elaborate plan","elaboration"]},{"id":1501,"topic":"language","w":"illustrate","ipa":"/ˈɪləstreɪt/","pos":"v.","cn":"举例说明；阐明","pun":"一拉死追特","story":"lustr 是「光」：一拉开窗帘光照进来，死角都看清了——用例子说明。","ex":"The writer uses several case studies to illustrate how language policy affects minority communities.","exCn":"作者用几个案例说明语言政策如何影响少数群体。","col":["illustrate a point","illustration","illustrative"]},{"id":1502,"topic":"language","w":"quote","ipa":"/kwəʊt/","pos":"v./n.","cn":"引述；引文","pun":"阔特","story":"阔特演讲时开口就是「名人说过……」，一字不改地引述原话。","ex":"It is acceptable to quote an expert briefly, provided the source is acknowledged.","exCn":"只要注明来源，简短引述专家的话是可以接受的。","col":["quote from","direct quote","quotation"]},{"id":1503,"topic":"language","w":"misunderstanding","ipa":"/ˌmɪsʌndəˈstændɪŋ/","pos":"n.","cn":"误解","pun":"米死安得死单顶","story":"mis- 是「错」加 understand：米死安得听错了一句，两人吵了一晚，全是误解。","ex":"Cultural differences in politeness often lead to misunderstanding between colleagues.","exCn":"礼貌方面的文化差异常导致同事之间的误解。","col":["cause a misunderstanding","clear up a misunderstanding","misunderstand"]},{"id":1504,"topic":"language","w":"misinterpret","ipa":"/ˌmɪsɪnˈtɜːprɪt/","pos":"v.","cn":"曲解；误译","pun":"米新特扑瑞特","story":"mis- 加 interpret：米新特把「扑」过来的话理解反了——曲解。","ex":"Without context, readers may misinterpret a message that was intended as a joke.","exCn":"没有语境，读者可能会曲解原本是玩笑的信息。","col":["misinterpret a remark","easily misinterpreted","misinterpretation"]},{"id":1505,"topic":"language","w":"barrier","ipa":"/ˈbæriə(r)/","pos":"n.","cn":"障碍；隔阂","pun":"拜里呀","story":"bar 是「横杆」：拜托，里面有杆挡着呀，过不去——障碍。","ex":"Language barriers prevent many migrants from accessing essential public services.","exCn":"语言障碍使许多移民无法获得基本公共服务。","col":["language barrier","overcome a barrier","break down barriers"]},{"id":1506,"topic":"language","w":"interact","ipa":"/ˌɪntərˈækt/","pos":"v.","cn":"互动；交流","pun":"因特爱可特","story":"inter- 是「之间」，act 是「行动」：因特网上爱可特和人来回互动。","ex":"Students learn a language faster when they interact with native speakers regularly.","exCn":"经常与母语者互动的学生学语言更快。","col":["interact with","interaction","interactive"]},{"id":1507,"topic":"language","w":"dialogue","ipa":"/ˈdaɪəlɒɡ/","pos":"n.","cn":"对话","pun":"呆呀捞个","story":"dia- 是「之间」，logue 是「说」：两人之间呆呀一句捞个一句，就是对话。","ex":"Open dialogue between governments and citizens strengthens democratic institutions.","exCn":"政府与公民之间的公开对话能巩固民主制度。","col":["open dialogue","engage in dialogue","dialogue between"]},{"id":1508,"topic":"language","w":"monologue","ipa":"/ˈmɒnəlɒɡ/","pos":"n.","cn":"独白","pun":"莫呢捞个","story":"mono- 是「单一」：莫呢一个人捞个话筒自说自话——独白。","ex":"A lecture that becomes a monologue quickly loses the attention of the audience.","exCn":"一堂变成独白的课很快就会失去听众的注意力。","col":["deliver a monologue","inner monologue","a long monologue"]},{"id":1509,"topic":"language","w":"converse","ipa":"/kənˈvɜːs/","pos":"v.","cn":"交谈","pun":"啃我死","story":"con- 是「一起」，verse 是「转」：两人一起把话题转来转去，啃我死了也聊——交谈。","ex":"The ability to converse comfortably in a second language takes years to develop.","exCn":"用第二语言自如交谈的能力需要多年培养。","col":["converse with","converse in English","conversation"]},{"id":1510,"topic":"language","w":"correspondence","ipa":"/ˌkɒrəˈspɒndəns/","pos":"n.","cn":"通信；书信往来","pun":"可若死磅的死","story":"co- 是「一起」，respond 是「回应」：可若一直回信，死磅的信一起往来——通信。","ex":"Business correspondence has shifted almost entirely from letters to email.","exCn":"商务通信几乎已完全从信件转向电子邮件。","col":["business correspondence","correspondence with","correspond"]},{"id":1511,"topic":"language","w":"interpersonal","ipa":"/ˌɪntəˈpɜːsənl/","pos":"adj.","cn":"人际的","pun":"因特泊森诺","story":"inter- 是「之间」，person 是「人」：因特网上泊着的人之间的关系——人际的。","ex":"Employers increasingly value interpersonal skills over technical qualifications.","exCn":"雇主越来越看重人际交往能力，而非技术资历。","col":["interpersonal skills","interpersonal communication","interpersonal relationship"]},{"id":1512,"topic":"language","w":"rapport","ipa":"/ræˈpɔː(r)/","pos":"n.","cn":"融洽关系","pun":"拉泡","story":"拉着朋友泡茶聊天，一见如故——融洽关系。","ex":"Teachers who build rapport with students find it easier to encourage participation.","exCn":"与学生建立融洽关系的老师更容易鼓励他们参与。","col":["build rapport","establish rapport","rapport with"]},{"id":1513,"topic":"language","w":"courtesy","ipa":"/ˈkɜːtəsi/","pos":"n.","cn":"礼貌；谦恭","pun":"客特西","story":"court 是「宫廷」：客人特地学西式宫廷礼仪，对谁都彬彬有礼——礼貌。","ex":"Simple courtesy, such as greeting colleagues, improves the atmosphere of any workplace.","exCn":"简单的礼貌，比如问候同事，能改善任何职场的氛围。","col":["common courtesy","as a courtesy","courteous"]},{"id":1514,"topic":"language","w":"tactful","ipa":"/ˈtæktfl/","pos":"adj.","cn":"得体的；圆滑的","pun":"太可服","story":"tact 是「触觉」：太可服了，他说话像轻轻摸，从不戳痛人——得体。","ex":"A tactful manager delivers criticism without damaging an employee's confidence.","exCn":"得体的经理提出批评时不会损伤员工的自信。","col":["a tactful reply","tactfully","tact"]},{"id":1515,"topic":"language","w":"blunt","ipa":"/blʌnt/","pos":"adj.","cn":"直率的；钝的","pun":"不烂特","story":"不烂特说话不拐弯，一刀砍下来——直率得让人疼。","ex":"Some cultures value blunt honesty, while others regard it as rude.","exCn":"有些文化重视直率的诚实，另一些则视之为无礼。","col":["blunt criticism","to be blunt","bluntly"]},{"id":1516,"topic":"language","w":"outspoken","ipa":"/aʊtˈspəʊkən/","pos":"adj.","cn":"直言不讳的","pun":"奥特死剖肯","story":"out 加 spoken：奥特曼把心里话全剖出来说，肯说敢说——直言不讳。","ex":"Outspoken critics of the policy were quickly silenced by the authorities.","exCn":"该政策的直言批评者很快被当局压制。","col":["an outspoken critic","outspoken about","outspokenness"]},{"id":1517,"topic":"language","w":"reticent","ipa":"/ˈretɪsnt/","pos":"adj.","cn":"沉默寡言的","pun":"瑞提森特","story":"瑞提森特被问什么都只点头，一句不多说——沉默寡言。","ex":"Reticent students may know the answer but hesitate to speak in front of the class.","exCn":"沉默寡言的学生可能知道答案，却不愿在全班面前开口。","col":["reticent about","naturally reticent","reticence"]},{"id":1518,"topic":"language","w":"stammer","ipa":"/ˈstæmə(r)/","pos":"v./n.","cn":"口吃；结巴","pun":"死太么","story":"死、死、太么紧张，一个词卡了三遍——口吃。","ex":"Speech therapy can help children who stammer gain confidence in public speaking.","exCn":"语言治疗能帮助口吃儿童在公开演讲中建立自信。","col":["stammer badly","have a stammer","stammering"]},{"id":1519,"topic":"language","w":"mumble","ipa":"/ˈmʌmbl/","pos":"v.","cn":"含糊地说","pun":"妈不","story":"妈不高兴时嘴里嘟嘟囔囔，谁也听不清——含糊地说。","ex":"Candidates who mumble lose marks for pronunciation even if their grammar is perfect.","exCn":"说话含糊的考生即使语法完美，发音也会被扣分。","col":["mumble an apology","mumble to oneself","mumbling"]},{"id":1520,"topic":"language","w":"murmur","ipa":"/ˈmɜːmə(r)/","pos":"v./n.","cn":"低语；小声抱怨","pun":"么么","story":"么么小声地在耳边嘀咕，像蜜蜂嗡嗡——低语。","ex":"A murmur of disapproval spread through the audience as the speaker continued.","exCn":"演讲者继续时，一阵不满的低语在听众中传开。","col":["murmur softly","a murmur of","murmuring"]},{"id":1521,"topic":"language","w":"exclaim","ipa":"/ɪkˈskleɪm/","pos":"v.","cn":"惊叫；大声说","pun":"一克死克雷母","story":"ex- 是「出」，claim 是「喊」：一克死了，克雷母亲惊叫出声。","ex":"Visitors often exclaim in surprise when they hear how many languages are spoken in the city.","exCn":"游客听说这座城市有多少种语言时常常惊叹出声。","col":["exclaim in surprise","exclamation","exclamation mark"]},{"id":1522,"topic":"language","w":"utter","ipa":"/ˈʌtə(r)/","pos":"v./adj.","cn":"说出；完全的","pun":"阿特","story":"阿特一整天一个字都没说出口，完全的沉默。","ex":"The child did not utter a single word until she was almost three.","exCn":"这孩子快三岁了才说出第一个字。","col":["utter a word","utter nonsense","utterly"]},{"id":1523,"topic":"language","w":"proclaim","ipa":"/prəˈkleɪm/","pos":"v.","cn":"宣告；声明","pun":"扑若克雷母","story":"pro- 是「向前」，claim 是「喊」：扑到人群前面大喊——宣告。","ex":"The government proclaimed the local language an official medium of instruction.","exCn":"政府宣布当地语言为官方教学语言。","col":["proclaim independence","proclaim that","proclamation"]},{"id":1524,"topic":"language","w":"declare","ipa":"/dɪˈkleə(r)/","pos":"v.","cn":"宣布；声明","pun":"地克累儿","story":"clar 是「清楚」：地克累儿站在台上清清楚楚宣布结果。","ex":"Several countries have declared English a second official language to attract investment.","exCn":"几个国家已宣布英语为第二官方语言以吸引投资。","col":["declare that","declaration","openly declare"]},{"id":1525,"topic":"language","w":"narrate","ipa":"/nəˈreɪt/","pos":"v.","cn":"叙述；讲故事","pun":"那瑞特","story":"那瑞特坐在火堆旁，把从前的事一件件讲下去——叙述。","ex":"Storytellers narrate the history of the tribe from memory, without any written record.","exCn":"讲故事的人凭记忆叙述部落的历史，没有任何书面记录。","col":["narrate a story","narrative","narrator"]},{"id":1526,"topic":"language","w":"depict","ipa":"/dɪˈpɪkt/","pos":"v.","cn":"描绘；描述","pun":"地皮克特","story":"pict 是「画」：地皮上克特用笔画出整个村子的样子——描绘。","ex":"The novel depicts the struggle of immigrants learning a new language.","exCn":"这部小说描绘了移民学习新语言的艰辛。","col":["depict as","depiction","vividly depict"]},{"id":1527,"topic":"language","w":"portray","ipa":"/pɔːˈtreɪ/","pos":"v.","cn":"描绘；刻画","pun":"跑追","story":"跑着追人的画面被画家一笔一笔刻画出来——描绘。","ex":"The media often portray dialect speakers as less educated than they are.","exCn":"媒体常把说方言的人描绘得比实际教育程度低。","col":["portray as","portrayal","portray a character"]},{"id":1528,"topic":"language","w":"analogy","ipa":"/əˈnælədʒi/","pos":"n.","cn":"类比","pun":"饿那了几","story":"ana- 是「按照」，log 是「比例」：饿了那就比几个东西的相似处——类比。","ex":"Teachers often explain grammar by analogy with rules students already know.","exCn":"老师常用学生已知的规则做类比来解释语法。","col":["draw an analogy","by analogy with","analogous"]},{"id":1529,"topic":"language","w":"anecdote","ipa":"/ˈænɪkdəʊt/","pos":"n.","cn":"轶事；趣闻","pun":"安妮克都特","story":"安妮克都特爱讲自己出洋相的小故事，逗大家笑——轶事。","ex":"Speakers often open with an anecdote to establish a connection with the audience.","exCn":"演讲者常以一则轶事开场，与听众建立联系。","col":["a personal anecdote","tell an anecdote","anecdotal evidence"]},{"id":1530,"topic":"language","w":"cliché","ipa":"/ˈkliːʃeɪ/","pos":"n.","cn":"陈词滥调","pun":"克里谢","story":"克里谢一开口又是「时间就是金钱」，听了一万遍——陈词滥调。","ex":"Examiners are unimpressed by clichés such as every coin has two sides.","exCn":"考官对「凡事都有两面」这类陈词滥调不以为然。","col":["avoid clichés","a tired cliché","clichéd"]},{"id":1531,"topic":"language","w":"euphemism","ipa":"/ˈjuːfəmɪzəm/","pos":"n.","cn":"委婉语","pun":"油腐米粽","story":"eu- 是「好」，phem 是「说」：把「死了」说成「走了」，油腐米粽都说得好听——委婉语。","ex":"Companies use euphemisms such as downsizing to soften the reality of job losses.","exCn":"公司用「精简」等委婉语淡化裁员的现实。","col":["a euphemism for","use a euphemism","euphemistic"]},{"id":1532,"topic":"language","w":"sarcasm","ipa":"/ˈsɑːkæzəm/","pos":"n.","cn":"讽刺；挖苦","pun":"傻卡怎么","story":"「傻卡，怎么这么聪明啊？」——话是夸，意思是骂——讽刺。","ex":"Sarcasm is particularly difficult for non-native speakers to detect in online messages.","exCn":"非母语者尤其难以在网络信息中识别讽刺。","col":["heavy sarcasm","a hint of sarcasm","sarcastic"]},{"id":1533,"topic":"language","w":"irony","ipa":"/ˈaɪrəni/","pos":"n.","cn":"反语；讽刺意味","pun":"爱若你","story":"「爱若你」表面说爱，实际相反——反语；语言老师自己说错话，也是讽刺。","ex":"There is a certain irony in a language teacher who cannot spell.","exCn":"一个不会拼写的语言老师，颇有几分讽刺意味。","col":["dramatic irony","a sense of irony","ironic"]},{"id":1534,"topic":"language","w":"humour","ipa":"/ˈhjuːmə(r)/","pos":"n.","cn":"幽默","pun":"休么","story":"休息时么么讲个笑话，全屋笑翻——幽默。","ex":"Humour rarely survives translation because it depends on cultural references and wordplay.","exCn":"幽默很少能经受翻译，因为它依赖文化背景和文字游戏。","col":["sense of humour","dry humour","humorous"]},{"id":1535,"topic":"language","w":"wit","ipa":"/wɪt/","pos":"n.","cn":"机智；风趣","pun":"喂特","story":"喂，特别机灵的那位一句话就把尴尬化解了——机智。","ex":"The speaker's wit kept the audience engaged throughout a long technical talk.","exCn":"演讲者的风趣让听众在漫长的技术讲座中始终保持专注。","col":["sharp wit","quick wit","witty"]},{"id":1536,"topic":"language","w":"banter","ipa":"/ˈbæntə(r)/","pos":"n./v.","cn":"打趣；调侃","pun":"班特","story":"班上特别熟的同学互相开玩笑，谁也不当真——打趣。","ex":"Friendly banter between colleagues can strengthen team relationships.","exCn":"同事之间友好的打趣能加强团队关系。","col":["friendly banter","exchange banter","banter with"]},{"id":1537,"topic":"language","w":"gossip","ipa":"/ˈɡɒsɪp/","pos":"n./v.","cn":"闲话；八卦","pun":"高谁扑","story":"高声聊谁和谁扑朔迷离的事——八卦闲话。","ex":"Office gossip spreads faster than official announcements.","exCn":"办公室八卦传播得比官方通知还快。","col":["office gossip","gossip about","a piece of gossip"]},{"id":1538,"topic":"language","w":"rumour","ipa":"/ˈruːmə(r)/","pos":"n.","cn":"谣言；传闻","pun":"入么","story":"入了耳朵么，就传给下一个人，越传越离谱——谣言。","ex":"Social media allows rumours to spread across the globe within hours.","exCn":"社交媒体让谣言在几小时内传遍全球。","col":["spread a rumour","rumour has it","rumoured"]},{"id":1539,"topic":"language","w":"criticism","ipa":"/ˈkrɪtɪsɪzəm/","pos":"n.","cn":"批评","pun":"克里踢死人","story":"克里一开口就踢得人心里疼——批评。","ex":"Public figures must learn to respond to criticism without becoming defensive.","exCn":"公众人物必须学会回应批评而不变得防御。","col":["face criticism","constructive criticism","criticise"]},{"id":1540,"topic":"language","w":"compliment","ipa":"/ˈkɒmplɪmənt/","pos":"n./v.","cn":"赞美；恭维","pun":"康普里门特","story":"康普站在里面的门口特地夸你今天真好看——赞美。","ex":"Accepting a compliment gracefully is a skill that varies between cultures.","exCn":"优雅地接受赞美是一种因文化而异的技巧。","col":["pay a compliment","compliment sb on","complimentary"]},{"id":1541,"topic":"language","w":"flattery","ipa":"/ˈflætəri/","pos":"n.","cn":"奉承；谄媚","pun":"弗拉特里","story":"flat 是「平」：弗拉特里把话说得平平的、软软的，专捡好听的讲——奉承。","ex":"Flattery may win short-term favour but rarely earns genuine respect.","exCn":"奉承或许能赢得短期好感，却很少赢得真正的尊重。","col":["empty flattery","flatter sb","flattering"]},{"id":1542,"topic":"language","w":"hint","ipa":"/hɪnt/","pos":"n./v.","cn":"暗示；提示","pun":"很特","story":"很特别地咳嗽一声，看你一眼——暗示你别说了。","ex":"Speakers from indirect cultures often drop hints rather than making requests openly.","exCn":"来自含蓄文化的人常给暗示，而不是公开提出要求。","col":["drop a hint","hint at","take the hint"]},{"id":1543,"topic":"language","w":"cue","ipa":"/kjuː/","pos":"n.","cn":"提示；信号","pun":"Q","story":"主持人一比 Q 的手势，嘉宾就知道该说话了——提示信号。","ex":"Listeners rely on visual cues such as nodding to know when to take their turn.","exCn":"听者依靠点头等视觉信号来判断何时轮到自己说话。","col":["visual cue","take one's cue from","on cue"]},{"id":1544,"topic":"language","w":"symbol","ipa":"/ˈsɪmbl/","pos":"n.","cn":"符号；象征","pun":"新宝","story":"新宝贝身上画个爱心，人人看懂是爱——符号、象征。","ex":"Written words are simply symbols agreed upon by a community of speakers.","exCn":"书面文字不过是一个语言社群约定的符号。","col":["a symbol of","symbolic","symbolise"]},{"id":1545,"topic":"language","w":"sign language","ipa":"/ˈsaɪn læŋɡwɪdʒ/","pos":"phr.","cn":"手语","pun":"赛恩练归着","story":"赛恩练着一套手势归着比划，听障朋友全懂——手语。","ex":"Sign language is now recognised as an official language in several countries.","exCn":"手语现已在多个国家被认定为官方语言。","col":["learn sign language","British Sign Language","sign language interpreter"]},{"id":1546,"topic":"language","w":"braille","ipa":"/breɪl/","pos":"n.","cn":"盲文","pun":"不瑞哦","story":"不用眼睛，瑞哦用手指摸凸点就能读书——盲文。","ex":"Public signs in braille allow visually impaired people to navigate independently.","exCn":"盲文公共标识让视障人士能独立出行。","col":["read braille","braille signs","in braille"]},{"id":1547,"topic":"language","w":"decode","ipa":"/ˌdiːˈkəʊd/","pos":"v.","cn":"解码；解读","pun":"地扣的","story":"de- 是「解开」，code 是「密码」：把地上扣着的密码解开——解码。","ex":"Young readers must learn to decode written symbols into the sounds they represent.","exCn":"小读者必须学会把书面符号解码为其代表的声音。","col":["decode a message","decode meaning","decoding skills"]},{"id":1548,"topic":"language","w":"medium","ipa":"/ˈmiːdiəm/","pos":"n.","cn":"媒介；手段","pun":"米地儿","story":"medi 是「中间」：米地儿站在中间传话，语言就是传递思想的媒介。","ex":"English is the medium of instruction in most international universities.","exCn":"英语是大多数国际大学的教学语言。","col":["medium of instruction","through the medium of","media"]},{"id":1549,"topic":"language","w":"interpreter","ipa":"/ɪnˈtɜːprɪtə(r)/","pos":"n.","cn":"口译员","pun":"银特扑瑞特","story":"inter- 是「之间」：站在两个人之间把话扑来扑去的人——口译员。","ex":"Courts must provide a qualified interpreter for defendants who do not speak the local language.","exCn":"法院必须为不会当地语言的被告提供合格的口译员。","col":["a professional interpreter","act as an interpreter","simultaneous interpreter"]},{"id":1550,"topic":"language","w":"comprehend","ipa":"/ˌkɒmprɪˈhend/","pos":"v.","cn":"理解；领会","pun":"康普瑞汉的","story":"com- 是「全」，prehend 是「抓住」：康普瑞把汉语的意思全抓住了——理解。","ex":"Students may pronounce a text perfectly yet fail to comprehend its meaning.","exCn":"学生可能把课文读得很标准，却没有理解意思。","col":["fully comprehend","comprehension","comprehensible"]},{"id":1551,"topic":"language","w":"audible","ipa":"/ˈɔːdəbl/","pos":"adj.","cn":"听得见的","pun":"哦得包","story":"aud 是「听」：哦，得包着耳朵才听不见——听得见的。","ex":"Speakers should ensure their voice is audible to those at the back of the room.","exCn":"演讲者应确保房间后排的人能听见自己的声音。","col":["clearly audible","barely audible","inaudible"]},{"id":1552,"topic":"language","w":"verbatim","ipa":"/vɜːˈbeɪtɪm/","pos":"adv./adj.","cn":"逐字地","pun":"我背题","story":"verb 是「词」：我背题一字不差地背下来——逐字地。","ex":"Copying a source verbatim without quotation marks is considered academic misconduct.","exCn":"不加引号逐字照抄来源被视为学术不端。","col":["quote verbatim","a verbatim record","repeat verbatim"]},{"id":1553,"topic":"language","w":"impromptu","ipa":"/ɪmˈprɒmptjuː/","pos":"adj./adv.","cn":"即兴的；无准备的","pun":"因扑让普图","story":"in- 是「没」，prompt 是「准备」：因为扑上台没准备，普图只好即兴讲。","ex":"Managers are often required to give impromptu speeches at company events.","exCn":"经理常被要求在公司活动上即兴发言。","col":["an impromptu speech","speak impromptu","impromptu performance"]},{"id":1554,"topic":"language","w":"rehearse","ipa":"/rɪˈhɜːs/","pos":"v.","cn":"排练；预演","pun":"瑞喝死","story":"re- 是「再」：瑞一遍又一遍练到喝水都想吐——排练。","ex":"Candidates who rehearse their presentation several times speak with more confidence.","exCn":"多次排练演讲的考生说起来更自信。","col":["rehearse a speech","rehearsal","well-rehearsed"]},{"id":1555,"topic":"language","w":"recite","ipa":"/rɪˈsaɪt/","pos":"v.","cn":"背诵；朗诵","pun":"瑞塞特","story":"re- 是「再」，cite 是「引」：瑞把塞进脑子里的诗再原样念出来——背诵。","ex":"In traditional classrooms, pupils were expected to recite texts from memory.","exCn":"在传统课堂上，学生被要求凭记忆背诵课文。","col":["recite a poem","recite from memory","recitation"]},{"id":1556,"topic":"language","w":"mnemonic","ipa":"/nɪˈmɒnɪk/","pos":"n./adj.","cn":"记忆法；助记的","pun":"你妈你可","story":"你妈教你可以用谐音记单词——这本身就是一种记忆法。","ex":"Mnemonics such as rhymes and images help learners retain difficult spellings.","exCn":"押韵、图像等记忆法帮助学习者记住难拼的词。","col":["a mnemonic device","use mnemonics","mnemonic technique"]},{"id":1557,"topic":"language","w":"linguist","ipa":"/ˈlɪŋɡwɪst/","pos":"n.","cn":"语言学家","pun":"灵归斯特","story":"lingu 是「舌头」：舌头灵活，归斯特研究各种语言——语言学家。","ex":"Linguists have documented fewer than half of the world's remaining languages.","exCn":"语言学家记录的现存语言不到世界总数的一半。","col":["a leading linguist","linguistics","linguistic research"]},{"id":1558,"topic":"language","w":"etymology","ipa":"/ˌetɪˈmɒlədʒi/","pos":"n.","cn":"词源；词源学","pun":"爱提莫了几","story":"etym 是「真实」，logy 是「学」：爱提问莫了几个词是从哪儿来的——词源学。","ex":"Studying etymology helps learners see connections between words across languages.","exCn":"研究词源能帮助学习者看到不同语言之间词汇的联系。","col":["the etymology of","etymological","etymologically"]},{"id":1559,"topic":"language","w":"semantics","ipa":"/sɪˈmæntɪks/","pos":"n.","cn":"语义学；语义","pun":"死慢踢克斯","story":"死慢慢踢，克斯先弄懂每个词到底什么意思——语义学。","ex":"Arguments about semantics often obscure the real issue under discussion.","exCn":"关于语义的争论常常掩盖了讨论中的真正问题。","col":["a matter of semantics","semantic meaning","semantic field"]},{"id":1560,"topic":"language","w":"syntax","ipa":"/ˈsɪntæks/","pos":"n.","cn":"句法；语序","pun":"新胎克斯","story":"syn- 是「一起」，tax 是「排列」：新胎克斯把词按顺序排在一起——句法。","ex":"English syntax places the verb before the object, unlike Japanese or Korean.","exCn":"英语句法把动词放在宾语之前，与日语、韩语不同。","col":["English syntax","syntax error","syntactic"]},{"id":1561,"topic":"language","w":"phonetic","ipa":"/fəˈnetɪk/","pos":"adj.","cn":"语音的；表音的","pun":"佛内踢克","story":"phon 是「声音」：佛内踢克把每个声音都用符号写下来——语音的。","ex":"Phonetic symbols allow learners to pronounce unfamiliar words correctly.","exCn":"音标让学习者能正确读出不熟悉的词。","col":["phonetic symbol","phonetic alphabet","phonetics"]},{"id":1562,"topic":"language","w":"loanword","ipa":"/ˈləʊnwɜːd/","pos":"n.","cn":"外来词","pun":"漏我的","story":"loan 是「借」：从别的语言借来的词，漏进了我的语言——外来词。","ex":"English has absorbed thousands of loanwords from French, Latin and other languages.","exCn":"英语吸收了成千上万来自法语、拉丁语等语言的外来词。","col":["a loanword from","borrow a loanword","borrowing"]},{"id":1563,"topic":"language","w":"discourse","ipa":"/ˈdɪskɔːs/","pos":"n.","cn":"话语；论述","pun":"弟死扣死","story":"dis- 是「四处」，course 是「跑」：弟弟四处跑着扣人讨论——一整段话语、论述。","ex":"Public discourse on immigration is often shaped by the language used in the media.","exCn":"关于移民的公共话语常被媒体的措辞所塑造。","col":["public discourse","political discourse","discourse analysis"]},{"id":1564,"topic":"language","w":"register","ipa":"/ˈredʒɪstə(r)/","pos":"n./v.","cn":"语域；登记","pun":"瑞几死特","story":"瑞几次见死特总统用正式语，见朋友用俚语——切换语域。","ex":"Choosing the wrong register, such as slang in an essay, costs candidates marks.","exCn":"选错语域，比如在文章里用俚语，会让考生丢分。","col":["formal register","register for","registration"]},{"id":1565,"topic":"language","w":"verbose","ipa":"/vɜːˈbəʊs/","pos":"adj.","cn":"啰嗦的；冗长的","pun":"我播死","story":"verb 是「词」：我播了一万个词，把人听死——啰嗦的。","ex":"Verbose writing wastes the reader's time and obscures the main argument.","exCn":"冗长的写作浪费读者时间，掩盖主要论点。","col":["verbose style","overly verbose","verbosity"]},{"id":1566,"topic":"language","w":"succinct","ipa":"/səkˈsɪŋkt/","pos":"adj.","cn":"简明扼要的","pun":"色克新克特","story":"色克把话新克成一小节，特别短特别准——简明扼要。","ex":"A succinct introduction tells the reader exactly what the essay will argue.","exCn":"简明扼要的引言让读者确切知道文章将论证什么。","col":["a succinct summary","succinctly","succinct and clear"]},{"id":1567,"topic":"language","w":"lucid","ipa":"/ˈluːsɪd/","pos":"adj.","cn":"清晰易懂的","pun":"露洗的","story":"luc 是「光」：露水洗过的玻璃透亮，讲话像它一样清楚——清晰易懂。","ex":"The professor is admired for her lucid explanations of difficult grammatical concepts.","exCn":"这位教授因对复杂语法概念的清晰解释而受人钦佩。","col":["a lucid explanation","lucidly","lucidity"]},{"id":1568,"topic":"language","w":"vague","ipa":"/veɪɡ/","pos":"adj.","cn":"含糊的；不明确的","pun":"喂个","story":"喂个问题过去，他答得云里雾里——含糊的。","ex":"Vague expressions such as many people think weaken an academic argument.","exCn":"「很多人认为」之类含糊的表达会削弱学术论证。","col":["a vague answer","vaguely","vagueness"]},{"id":1569,"topic":"language","w":"explicit","ipa":"/ɪkˈsplɪsɪt/","pos":"adj.","cn":"明确的；直白的","pun":"一克死不理谁的","story":"ex- 是「外」，plic 是「折」：把折着的话全摊到外面，一克不理谁都看得明明白白——明确。","ex":"Some cultures prefer explicit communication, while others rely on shared context.","exCn":"有些文化偏好直白的交流，另一些则依赖共享语境。","col":["explicit instructions","make explicit","explicitly"]},{"id":1570,"topic":"language","w":"implicit","ipa":"/ɪmˈplɪsɪt/","pos":"adj.","cn":"含蓄的；隐含的","pun":"因扑理谁的","story":"im- 是「里」，plic 是「折」：意思折在里面，因扑去理谁都得自己猜——隐含。","ex":"Much of the meaning in Japanese conversation is implicit rather than stated directly.","exCn":"日语对话中的很多意思是隐含的，而非直接说出。","col":["implicit meaning","implicit in","implicitly"]},{"id":1571,"topic":"language","w":"tacit","ipa":"/ˈtæsɪt/","pos":"adj.","cn":"心照不宣的；默许的","pun":"太洗特","story":"太洗特和朋友互看一眼，谁也不说，都懂了——心照不宣。","ex":"There was a tacit agreement among staff never to discuss salaries openly.","exCn":"员工之间有一种心照不宣的默契：从不公开谈论薪水。","col":["tacit agreement","tacit approval","tacitly"]},{"id":1572,"topic":"history","w":"excavate","ipa":"/ˈekskəveɪt/","pos":"v.","cn":"挖掘；发掘","pun":"挖死刻围","story":"ex-（向外）+cav（洞）：把土「挖死」再「刻围」出一圈，就是考古发掘。","ex":"Archaeologists excavated the site for three summers before uncovering the palace foundations.","exCn":"考古学家在遗址挖掘了三个夏天才发现宫殿地基。","col":["excavate a site","excavation work","excavation"]},{"id":1573,"topic":"history","w":"ancient","ipa":"/ˈeɪnʃənt/","pos":"adj.","cn":"古代的；古老的","pun":"俺婶特","story":"俺婶特别老，讲的全是古代的故事，简直是古老的活化石。","ex":"Ancient Greek philosophers laid the foundations of Western political thought.","exCn":"古希腊哲学家奠定了西方政治思想的基础。","col":["ancient history","ancient ruins","antiquity"]},{"id":1574,"topic":"history","w":"empire","ipa":"/ˈempaɪə(r)/","pos":"n.","cn":"帝国","pun":"俺派儿","story":"皇帝说：俺派儿子去管那片新地——领土越派越大，成了帝国。","ex":"At its height, the Roman Empire stretched from Britain to the Middle East.","exCn":"罗马帝国鼎盛时期从不列颠延伸到中东。","col":["the British Empire","build an empire","imperial"]},{"id":1575,"topic":"history","w":"colony","ipa":"/ˈkɒləni/","pos":"n.","cn":"殖民地","pun":"靠了你","story":"母国对殖民地说：粮食、矿产全靠了你——殖民地就是被靠着的地方。","ex":"By 1900, much of Africa had been divided into European colonies.","exCn":"到1900年，非洲大部分地区已被划分为欧洲殖民地。","col":["former colony","establish a colony","colonial"]},{"id":1576,"topic":"history","w":"colonise","ipa":"/ˈkɒlənaɪz/","pos":"v.","cn":"殖民；开拓殖民地","pun":"靠了那儿","story":"colony+-ise（使成为）：船队靠了那儿就不走了，插旗建城，把它变成殖民地。","ex":"European powers colonised vast areas of the Americas from the sixteenth century onwards.","exCn":"从十六世纪起，欧洲列强殖民了美洲的广大地区。","col":["colonise a region","colonisation","coloniser"]},{"id":1577,"topic":"history","w":"conquer","ipa":"/ˈkɒŋkə(r)/","pos":"v.","cn":"征服；攻克","pun":"扛课","story":"将军扛着课本冲上城墙，硬是攻克了敌城——扛课就是征服。","ex":"The Normans conquered England in 1066 and reshaped its language and institutions.","exCn":"诺曼人于1066年征服英格兰，重塑了其语言和制度。","col":["conquer a territory","conqueror","conquest"]},{"id":1578,"topic":"history","w":"invade","ipa":"/ɪnˈveɪd/","pos":"v.","cn":"入侵；侵略","pun":"硬围的","story":"in-（进入）+vade（走）：敌军硬围着走进来，就是入侵。","ex":"When the Mongols invaded, many cities along the Silk Road were destroyed.","exCn":"蒙古人入侵时，丝绸之路沿线的许多城市被毁。","col":["invade a country","invasion","invader"]},{"id":1579,"topic":"history","w":"settlement","ipa":"/ˈsetlmənt/","pos":"n.","cn":"定居点；聚落","pun":"塞头满","story":"早期移民把河边塞得头满头满的，搭起棚屋，形成了定居点。","ex":"The earliest human settlements in the region were located along fertile riverbanks.","exCn":"该地区最早的人类定居点位于肥沃的河岸。","col":["early settlement","permanent settlement","settle"]},{"id":1580,"topic":"history","w":"migrate","ipa":"/maɪˈɡreɪt/","pos":"v.","cn":"迁徙；移居","pun":"买个锐特","story":"全村人买个「锐特」牌拖车往北方迁徙，一路浩浩荡荡地移居。","ex":"Thousands of families migrated westward in search of farmland during the nineteenth century.","exCn":"十九世纪，成千上万家庭为寻找农田向西迁徙。","col":["migrate to","mass migration","migration"]},{"id":1581,"topic":"history","w":"nomadic","ipa":"/nəʊˈmædɪk/","pos":"adj.","cn":"游牧的；流浪的","pun":"挪没地","story":"游牧民族的口号：挪，没地也挪——逐水草而居，永远在搬家。","ex":"Nomadic tribes on the steppe moved their herds seasonally between pastures.","exCn":"草原上的游牧部落随季节在牧场之间迁移畜群。","col":["nomadic lifestyle","nomadic tribes","nomad"]},{"id":1582,"topic":"history","w":"territory","ipa":"/ˈterətri/","pos":"n.","cn":"领土；地区","pun":"太热特厉","story":"这块领土太热，特别厉害，可两国还是抢着要——领土就是命根子。","ex":"Disputes over territory have triggered numerous conflicts throughout recorded history.","exCn":"有史以来，领土争端引发了无数冲突。","col":["disputed territory","occupied territory","territorial"]},{"id":1583,"topic":"history","w":"frontier","ipa":"/ˈfrʌntɪə(r)/","pos":"n.","cn":"边境；边疆","pun":"翻踢儿","story":"front（前面）+ier：在最前面翻墙踢儿——那就是边疆，最前线的边界。","ex":"Settlers pushed the frontier steadily westward, displacing native populations.","exCn":"定居者不断把边疆向西推进，迫使原住民迁离。","col":["frontier region","push back the frontier","borderland"]},{"id":1584,"topic":"history","w":"boundary","ipa":"/ˈbaʊndri/","pos":"n.","cn":"边界；界限","pun":"帮得利","story":"两村在田里拉根绳，帮得利地分清各自地界——那绳子就是边界。","ex":"The river served as a natural boundary between the two kingdoms for centuries.","exCn":"几个世纪以来，这条河一直是两个王国之间的天然边界。","col":["national boundary","draw a boundary","boundaries"]},{"id":1585,"topic":"history","w":"peninsula","ipa":"/pəˈnɪnsjələ/","pos":"n.","cn":"半岛","pun":"盆里塞了","story":"盆里塞了块土，三面泡在水里，一面连着陆地——这就是半岛。","ex":"The Iberian Peninsula was ruled by Muslim dynasties for nearly eight centuries.","exCn":"伊比利亚半岛曾被穆斯林王朝统治近八个世纪。","col":["the Korean Peninsula","peninsular","coastline"]},{"id":1586,"topic":"history","w":"volcanic","ipa":"/vɒlˈkænɪk/","pos":"adj.","cn":"火山的","pun":"我看你渴","story":"火山口冒烟，我看你渴得冒火——火山的脾气就是这么热。","ex":"Volcanic ash buried Pompeii, preserving the city for archaeologists to study centuries later.","exCn":"火山灰掩埋了庞贝城，使其得以保存供后世考古学家研究。","col":["volcanic eruption","volcanic soil","volcano"]},{"id":1587,"topic":"history","w":"ruins","ipa":"/ˈruːɪnz/","pos":"n.","cn":"废墟；遗迹","pun":"入影子","story":"走入古城废墟，只剩断墙的影子——ruin 就是毁掉后的遗迹。","ex":"The ruins of the temple attract thousands of visitors each year.","exCn":"这座神庙的遗迹每年吸引成千上万的游客。","col":["ancient ruins","in ruins","ruin (v.)"]},{"id":1588,"topic":"history","w":"inscription","ipa":"/ɪnˈskrɪpʃn/","pos":"n.","cn":"铭文；题词","pun":"硬刻立铺申","story":"in-（在上）+script（写）：把字硬刻在立起的石铺上申明——那就是铭文。","ex":"The inscription on the stone records a victory won more than two thousand years ago.","exCn":"石碑上的铭文记录了两千多年前的一场胜利。","col":["stone inscription","bear an inscription","inscribe"]},{"id":1589,"topic":"history","w":"chronicle","ipa":"/ˈkrɒnɪkl/","pos":"n./v.","cn":"编年史；记载","pun":"克罗尼扣","story":"chron（时间）：克罗尼一年扣一颗扣子记事，扣了一辈子，成了编年史。","ex":"The chronicle describes the famine that struck the kingdom in the twelfth century.","exCn":"这部编年史描述了十二世纪袭击该王国的饥荒。","col":["historical chronicle","chronicle events","chronological"]},{"id":1590,"topic":"history","w":"era","ipa":"/ˈɪərə/","pos":"n.","cn":"时代；纪元","pun":"一啦","story":"钟声一啦响，旧朝结束，新时代开始——一个纪元翻篇了。","ex":"The invention of printing marked the beginning of a new era in European history.","exCn":"印刷术的发明标志着欧洲历史新时代的开始。","col":["a new era","the Victorian era","epoch"]},{"id":1591,"topic":"history","w":"prehistoric","ipa":"/ˌpriːhɪˈstɒrɪk/","pos":"adj.","cn":"史前的","pun":"扑里洗桶里","story":"pre-（之前）+historic（历史）：文字记载之前，人还在桶里洗东西——史前的。","ex":"Prehistoric cave paintings suggest that early humans had complex symbolic thinking.","exCn":"史前洞穴壁画表明早期人类已有复杂的符号思维。","col":["prehistoric times","prehistoric site","prehistory"]},{"id":1592,"topic":"history","w":"collapse","ipa":"/kəˈlæps/","pos":"n./v.","cn":"崩溃；倒塌","pun":"可拉扑死","story":"帝国的墙被人可劲一拉，扑地倒塌——政权彻底崩溃了。","ex":"The collapse of the Maya cities may have been linked to prolonged periods of dry weather.","exCn":"玛雅城市的崩溃可能与长期干旱天气有关。","col":["economic collapse","collapse of an empire","collapsed"]},{"id":1593,"topic":"history","w":"revolution","ipa":"/ˌrevəˈluːʃn/","pos":"n.","cn":"革命；巨变","pun":"热我路神","story":"群众热血冲上路，把「路神」推倒换新的——这就是革命。","ex":"The Industrial Revolution transformed Britain from an agricultural to a manufacturing economy.","exCn":"工业革命使英国从农业经济转变为制造业经济。","col":["the French Revolution","industrial revolution","revolutionary"]},{"id":1594,"topic":"history","w":"rebellion","ipa":"/rɪˈbeljən/","pos":"n.","cn":"叛乱；反抗","pun":"利被劣人","story":"利益被劣人独占，百姓拿起锄头造反——这就是叛乱。","ex":"The peasant rebellion of 1381 challenged the feudal order in England.","exCn":"1381年的农民起义挑战了英格兰的封建秩序。","col":["armed rebellion","rebellion against","rebel"]},{"id":1595,"topic":"history","w":"warfare","ipa":"/ˈwɔːfeə(r)/","pos":"n.","cn":"战争；作战","pun":"我费儿","story":"war（战争）+fare（进行）：打仗最费儿子——战争夺走无数年轻人。","ex":"Trench warfare caused enormous casualties on both sides during the First World War.","exCn":"一战期间，堑壕战给双方造成了巨大伤亡。","col":["modern warfare","guerrilla warfare","chemical warfare"]},{"id":1596,"topic":"history","w":"siege","ipa":"/siːdʒ/","pos":"n.","cn":"围攻；围困","pun":"死挤","story":"敌军把城门死死挤住，不让粮食进去——这就是围城。","ex":"After a siege lasting eight months, the city finally surrendered to the invaders.","exCn":"围城八个月后，该城最终向入侵者投降。","col":["lay siege to","under siege","besiege"]},{"id":1597,"topic":"history","w":"fortress","ipa":"/ˈfɔːtrəs/","pos":"n.","cn":"堡垒；要塞","pun":"佛揣死","story":"fort（强）：这座堡垒连佛都揣不动，城墙死厚——要塞就是打不进的强城。","ex":"The fortress on the hill controlled the only road through the mountains.","exCn":"山上的要塞控制着穿越山脉的唯一道路。","col":["medieval fortress","impregnable fortress","fortify"]},{"id":1598,"topic":"history","w":"reign","ipa":"/reɪn/","pos":"n./v.","cn":"统治；在位","pun":"润","story":"国王在位几十年，把国家治理得润润的——这段统治期就是 reign。","ex":"During her long reign, the queen oversaw significant expansion of overseas trade.","exCn":"在她漫长的统治期间，女王主导了海外贸易的大幅扩张。","col":["during the reign of","reign over","reign supreme"]},{"id":1599,"topic":"history","w":"monarch","ipa":"/ˈmɒnək/","pos":"n.","cn":"君主","pun":"摸那壳","story":"mon（单一）+arch（统治）：只有一个人能摸那个金壳王冠——他就是君主。","ex":"The monarch held absolute power and answered to no elected assembly.","exCn":"君主拥有绝对权力，不对任何民选议会负责。","col":["absolute monarch","reigning monarch","monarchy"]},{"id":1600,"topic":"history","w":"aristocracy","ipa":"/ˌærɪˈstɒkrəsi/","pos":"n.","cn":"贵族；贵族统治","pun":"爱丽丝多可惜","story":"爱丽丝多可惜，没生在贵族家——aristocracy 就是那群生来就有爵位的人。","ex":"The aristocracy owned most of the land and dominated political life for centuries.","exCn":"几个世纪以来，贵族拥有大部分土地并主导政治生活。","col":["landed aristocracy","aristocratic","aristocrat"]},{"id":1601,"topic":"history","w":"peasant","ipa":"/ˈpeznt/","pos":"n.","cn":"农民；佃农","pun":"陪身特","story":"农民一辈子陪着身边那块地，特别辛苦——peasant 就是旧时的种地人。","ex":"Medieval peasants were required to give a portion of their harvest to the lord.","exCn":"中世纪农民必须把部分收成上交领主。","col":["peasant farmers","peasant uprising","peasantry"]},{"id":1602,"topic":"history","w":"feudal","ipa":"/ˈfjuːdl/","pos":"adj.","cn":"封建的","pun":"服头","story":"农民服从地头的领主，领主服从国王，一层压一层——这就是封建制度。","ex":"Under the feudal system, land was exchanged for military service and loyalty.","exCn":"在封建制度下，土地用来交换兵役和效忠。","col":["feudal system","feudal lord","feudalism"]},{"id":1603,"topic":"history","w":"agrarian","ipa":"/əˈɡreəriən/","pos":"adj.","cn":"农业的；土地的","pun":"饿给人","story":"agr（田地）：田里没收成就饿给人看——农业社会靠天吃饭。","ex":"Most of the population lived in agrarian communities before industrialisation began.","exCn":"工业化开始前，大多数人口生活在农业社区。","col":["agrarian society","agrarian reform","agriculture"]},{"id":1604,"topic":"history","w":"plague","ipa":"/pleɪɡ/","pos":"n./v.","cn":"瘟疫；折磨","pun":"扑来个","story":"瘟疫像黑影一样扑来个不停，整座城都被折磨——plague 就是大瘟疫。","ex":"The plague of 1348 killed roughly a third of Europe's population.","exCn":"1348年的瘟疫夺去了欧洲约三分之一的人口。","col":["bubonic plague","plagued by","the Black Death"]},{"id":1605,"topic":"history","w":"trade route","ipa":"/ˈtreɪd ruːt/","pos":"n.","cn":"贸易路线；商路","pun":"戳的路","story":"商人用骆驼蹄子一步步戳出来的路，就是贸易路线。","ex":"Control of trade routes across the desert made the kingdom extraordinarily wealthy.","exCn":"对穿越沙漠的贸易路线的控制使该王国极为富有。","col":["ancient trade route","maritime trade route","the Silk Road"]},{"id":1606,"topic":"history","w":"merchant","ipa":"/ˈmɜːtʃənt/","pos":"n.","cn":"商人","pun":"摸钱特","story":"商人天天摸钱，摸得特别熟练——merchant 就是做买卖的人。","ex":"Venetian merchants grew rich by controlling the spice trade with the East.","exCn":"威尼斯商人通过控制与东方的香料贸易致富。","col":["wealthy merchant","merchant ship","merchandise"]},{"id":1607,"topic":"history","w":"caravan","ipa":"/ˈkærəvæn/","pos":"n.","cn":"商队；旅行队","pun":"开了万","story":"沙漠里骆驼商队开了万里路，才把丝绸送到西边——那就是 caravan。","ex":"Camel caravans carried silk and spices across Central Asia for over a thousand years.","exCn":"骆驼商队在中亚运送丝绸和香料超过一千年。","col":["camel caravan","caravan route","caravanserai"]},{"id":1608,"topic":"history","w":"navigation","ipa":"/ˌnævɪˈɡeɪʃn/","pos":"n.","cn":"航海；导航","pun":"那位给深","story":"nav（船）：那位老船长给的深浅图，全靠它航海——这就是导航。","ex":"Improvements in navigation enabled European sailors to cross open oceans safely.","exCn":"航海技术的进步使欧洲水手能安全横渡大洋。","col":["navigation skills","maritime navigation","navigate"]},{"id":1609,"topic":"history","w":"expedition","ipa":"/ˌekspəˈdɪʃn/","pos":"n.","cn":"远征；探险","pun":"爱克斯陪弟深","story":"ex-（向外）：爱克斯陪弟弟深入丛林探险——这一趟就是远征。","ex":"The expedition set out to map the interior of the continent, which remained largely unknown.","exCn":"这次远征旨在绘制当时仍大多未知的大陆内陆地图。","col":["scientific expedition","lead an expedition","expedition to"]},{"id":1610,"topic":"history","w":"voyage","ipa":"/ˈvɔɪɪdʒ/","pos":"n.","cn":"航行；航海","pun":"喂一只","story":"长途航行一路喂一只海鸥陪伴，才不寂寞——voyage 就是海上远行。","ex":"Columbus's first voyage across the Atlantic took just over two months.","exCn":"哥伦布首次横渡大西洋的航行耗时两个多月。","col":["sea voyage","embark on a voyage","voyager"]},{"id":1611,"topic":"history","w":"explorer","ipa":"/ɪkˈsplɔːrə(r)/","pos":"n.","cn":"探险家","pun":"一颗死泼了","story":"ex-（向外）+plore：探险家往外走，一颗心都泼出去了——不怕死才叫探险家。","ex":"Early explorers relied on local guides to survive in unfamiliar landscapes.","exCn":"早期探险家依靠当地向导在陌生地貌中生存。","col":["polar explorer","explore","exploration"]},{"id":1612,"topic":"history","w":"cartography","ipa":"/kɑːˈtɒɡrəfi/","pos":"n.","cn":"地图绘制","pun":"卡桌各绘","story":"carto（地图）+graphy（画）：卡在桌前各自绘图——制图学就是画地图。","ex":"Advances in cartography allowed rulers to visualise the extent of their territories.","exCn":"制图学的进步让统治者能直观看到自己领土的范围。","col":["medieval cartography","cartographer","map-making"]},{"id":1613,"topic":"history","w":"terrain","ipa":"/təˈreɪn/","pos":"n.","cn":"地形；地势","pun":"特累","story":"terr（土地）：这片地形特累人，全是山坡和碎石——terrain 就是地面情况。","ex":"The rugged terrain made it difficult for invading armies to move supplies.","exCn":"崎岖的地形使入侵军队难以运送补给。","col":["rugged terrain","mountainous terrain","difficult terrain"]},{"id":1614,"topic":"history","w":"altitude","ipa":"/ˈæltɪtjuːd/","pos":"n.","cn":"海拔；高度","pun":"饿了提丢","story":"alt（高）：爬到高海拔饿了，提的干粮又丢了——高度越高越难受。","ex":"Settlements at high altitude developed distinctive farming techniques on terraced slopes.","exCn":"高海拔定居点在梯田坡地上发展出独特的耕作技术。","col":["high altitude","at an altitude of","altitude sickness"]},{"id":1615,"topic":"history","w":"latitude","ipa":"/ˈlætɪtjuːd/","pos":"n.","cn":"纬度","pun":"拉提丢","story":"横着拉一条线，提起来丢在地球上——横线就是纬度。","ex":"Regions at similar latitudes often share comparable climates and crops.","exCn":"纬度相近的地区往往气候和作物相似。","col":["high latitude","northern latitudes","longitude"]},{"id":1616,"topic":"history","w":"hemisphere","ipa":"/ˈhemɪsfɪə(r)/","pos":"n.","cn":"半球","pun":"海米死废儿","story":"hemi（半）+sphere（球）：海米把球切一半，废了一半——半球。","ex":"Most of the world's landmass is located in the northern hemisphere.","exCn":"世界上大部分陆地位于北半球。","col":["northern hemisphere","southern hemisphere","hemispheric"]},{"id":1617,"topic":"history","w":"equator","ipa":"/ɪˈkweɪtə(r)/","pos":"n.","cn":"赤道","pun":"一亏他","story":"equ（相等）：赤道把地球平分，南北一样，一点都不亏他——这就是赤道。","ex":"Countries near the equator receive intense sunlight throughout the year.","exCn":"赤道附近的国家全年日照强烈。","col":["cross the equator","near the equator","equatorial"]},{"id":1618,"topic":"history","w":"delta","ipa":"/ˈdeltə/","pos":"n.","cn":"三角洲","pun":"得了它","story":"河流入海时把泥沙全留下，得了它就成一块三角形的地——三角洲。","ex":"The Nile Delta has been intensively farmed for more than five thousand years.","exCn":"尼罗河三角洲已被密集耕种五千多年。","col":["river delta","the Mekong Delta","delta region"]},{"id":1619,"topic":"history","w":"estuary","ipa":"/ˈestʃuəri/","pos":"n.","cn":"河口；入海口","pun":"爱死出了","story":"河水爱死了出海的那一刻——河口就是河流出海的地方。","ex":"Many early ports were established at estuaries where rivers met the sea.","exCn":"许多早期港口建在河流入海的河口处。","col":["river estuary","estuary mouth","tidal"]},{"id":1620,"topic":"history","w":"tributary","ipa":"/ˈtrɪbjətri/","pos":"n.","cn":"支流","pun":"吹不出力","story":"小河吹不出力，只能汇入大河——tributary 就是支流。","ex":"The main river and its tributaries provided the only routes into the interior.","exCn":"干流及其支流是通往内陆的唯一通道。","col":["major tributary","tributary of","river system"]},{"id":1621,"topic":"history","w":"basin","ipa":"/ˈbeɪsn/","pos":"n.","cn":"盆地；流域","pun":"背身","story":"四周的山背对着身子围成一圈，中间凹下去——那就是盆地。","ex":"The Amazon basin contains the largest river system on Earth.","exCn":"亚马逊流域拥有地球上最大的河流系统。","col":["river basin","the Sichuan Basin","drainage basin"]},{"id":1622,"topic":"history","w":"archipelago","ipa":"/ˌɑːkɪˈpeləɡəʊ/","pos":"n.","cn":"群岛","pun":"阿基拍了狗","story":"阿基在一串小岛上挨个拍了狗——一串岛就是群岛。","ex":"The archipelago consists of more than seven thousand islands, many still uninhabited.","exCn":"该群岛由七千多个岛屿组成，许多仍无人居住。","col":["volcanic archipelago","island chain","islands"]},{"id":1623,"topic":"history","w":"strait","ipa":"/streɪt/","pos":"n.","cn":"海峡","pun":"死缺","story":"两块陆地之间就死缺那一条窄窄的水道——海峡。","ex":"Whoever controlled the strait could tax every ship passing between the two seas.","exCn":"谁控制了海峡，就能向往来两海的每艘船征税。","col":["the Strait of Gibraltar","narrow strait","channel"]},{"id":1624,"topic":"history","w":"continent","ipa":"/ˈkɒntɪnənt/","pos":"n.","cn":"大陆；洲","pun":"看提能","story":"con（一起）+tin（保持）：一整块连在一起、提都提不动的陆地，就是大陆。","ex":"Humans spread across every continent except Antarctica within a few tens of thousands of years.","exCn":"人类在几万年内扩散到除南极洲以外的每一个大陆。","col":["the African continent","continental","across continents"]},{"id":1625,"topic":"history","w":"tectonic","ipa":"/tekˈtɒnɪk/","pos":"adj.","cn":"地壳构造的","pun":"太可痛你渴","story":"地壳板块一撞，太可痛，撞得你渴到地裂——tectonic 是地壳构造的。","ex":"Tectonic activity along the fault line has shaped the region's mountains and valleys.","exCn":"断层线上的构造活动塑造了该地区的山脉和峡谷。","col":["tectonic plates","tectonic activity","plate tectonics"]},{"id":1626,"topic":"history","w":"topography","ipa":"/təˈpɒɡrəfi/","pos":"n.","cn":"地形；地势","pun":"他跑各费","story":"topo（地方）+graphy（描绘）：他跑遍各地，费力画出高低起伏——地形学。","ex":"The topography of the valley explains why the city was built on its eastern side.","exCn":"山谷的地形解释了为什么城市建在东侧。","col":["local topography","topographic map","topographical"]},{"id":1627,"topic":"history","w":"canyon","ipa":"/ˈkænjən/","pos":"n.","cn":"峡谷","pun":"砍咽","story":"大河像刀一样把高原砍出一道深深的咽喉——那就是峡谷。","ex":"The canyon was carved by the river over millions of years.","exCn":"这条峡谷是河流历经数百万年切割而成的。","col":["the Grand Canyon","deep canyon","gorge"]},{"id":1628,"topic":"history","w":"cliff","ipa":"/klɪf/","pos":"n.","cn":"悬崖","pun":"克里夫","story":"克里夫站在海边一块直上直下的大石头上，脚下就是海——悬崖。","ex":"Coastal cliffs are retreating by several centimetres every year due to wave action.","exCn":"由于海浪作用，海岸悬崖每年后退数厘米。","col":["steep cliff","cliff face","cliff edge"]},{"id":1629,"topic":"history","w":"dune","ipa":"/djuːn/","pos":"n.","cn":"沙丘","pun":"丢","story":"风把沙子一把把丢起来，堆成一座座小山——沙丘。","ex":"Shifting sand dunes have buried entire villages along the desert's edge.","exCn":"移动的沙丘已把沙漠边缘的整个村庄掩埋。","col":["sand dune","coastal dune","dune system"]},{"id":1630,"topic":"history","w":"savanna","ipa":"/səˈvænə/","pos":"n.","cn":"热带草原","pun":"洒完呐","story":"雨季雨水洒完呐，草原上草长起来，动物成群——savanna 是热带草原。","ex":"Early humans are thought to have evolved on the African savanna.","exCn":"人们认为早期人类是在非洲热带草原上进化的。","col":["African savanna","savanna grassland","grassland"]},{"id":1631,"topic":"history","w":"tundra","ipa":"/ˈtʌndrə/","pos":"n.","cn":"苔原；冻土带","pun":"躺着","story":"极北的地方冷得只能躺着，地里冻得长不出树——tundra 是苔原。","ex":"Hunters crossed the frozen tundra following herds of reindeer.","exCn":"猎人跟随驯鹿群穿越冰冻的苔原。","col":["Arctic tundra","frozen tundra","permafrost"]},{"id":1632,"topic":"history","w":"inland","ipa":"/ˈɪnlænd/","pos":"adj./adv.","cn":"内陆的；向内陆","pun":"硬烂的","story":"in（里）+land（地）：内陆的路硬得像烂石头，离海远——inland。","ex":"Railways allowed inland regions to export grain that had previously been unreachable.","exCn":"铁路使内陆地区得以出口以前无法运出的谷物。","col":["inland areas","move inland","landlocked"]},{"id":1633,"topic":"history","w":"densely","ipa":"/ˈdensli/","pos":"adv.","cn":"稠密地","pun":"顶死里","story":"人挤得顶死里，一个挨一个——densely populated 就是人口稠密。","ex":"The river valley was densely populated long before the first written records.","exCn":"早在有文字记载之前，这片河谷就人口稠密。","col":["densely populated","densely packed","density"]},{"id":1634,"topic":"history","w":"sparse","ipa":"/spɑːs/","pos":"adj.","cn":"稀少的；稀疏的","pun":"死怕死","story":"荒原上人烟稀少，一个人走着死怕死——sparse 就是稀疏。","ex":"Population remained sparse across the desert interior until oil was discovered.","exCn":"在发现石油之前，沙漠腹地人口一直稀少。","col":["sparse population","sparsely populated","scarce"]},{"id":1635,"topic":"history","w":"populate","ipa":"/ˈpɒpjuleɪt/","pos":"v.","cn":"居住于；构成人口","pun":"跑不了","story":"popul（人民）：人们搬进来就跑不了了，越住越多——populate 是住满。","ex":"The islands were first populated by seafarers from Southeast Asia around three thousand years ago.","exCn":"这些岛屿最早由来自东南亚的航海者在约三千年前定居。","col":["densely populated","population","populous"]},{"id":1636,"topic":"history","w":"inhabitant","ipa":"/ɪnˈhæbɪtənt/","pos":"n.","cn":"居民","pun":"硬还必等","story":"in（里）+habit（住）：住在里面的人硬是还要等着——inhabitant 是居民。","ex":"The original inhabitants of the valley were displaced when the dam was built.","exCn":"修建大坝时，山谷的原住民被迫迁离。","col":["local inhabitants","inhabit","inhabited"]},{"id":1637,"topic":"history","w":"lineage","ipa":"/ˈlɪniɪdʒ/","pos":"n.","cn":"血统；世系","pun":"里你一支","story":"line（线）：家族像一条线，里头你这一支从祖先传下来——世系。","ex":"Royal lineage was used to justify claims to the throne throughout medieval Europe.","exCn":"在整个中世纪欧洲，王室血统被用来证明王位主张的合法性。","col":["royal lineage","trace one's lineage","bloodline"]},{"id":1638,"topic":"history","w":"tribe","ipa":"/traɪb/","pos":"n.","cn":"部落","pun":"踹步","story":"部落战士围着火堆踹步跳舞——tribe 就是部落。","ex":"Germanic tribes gradually settled within the borders of the Roman Empire.","exCn":"日耳曼部落逐渐在罗马帝国境内定居。","col":["nomadic tribe","tribal","tribal leader"]},{"id":1639,"topic":"history","w":"sacrifice","ipa":"/ˈsækrɪfaɪs/","pos":"n./v.","cn":"祭祀；牺牲","pun":"洒个来饭死","story":"sacr（神圣）：往祭坛洒个饭，把猪献给神——祭祀就是牺牲。","ex":"The Aztecs practised human sacrifice as part of their religious ceremonies.","exCn":"阿兹特克人把人祭作为宗教仪式的一部分。","col":["make a sacrifice","human sacrifice","sacrificial"]},{"id":1640,"topic":"history","w":"temple","ipa":"/ˈtempl/","pos":"n.","cn":"庙宇；神殿","pun":"添铺","story":"信徒给神殿添铺一层新瓦——temple 就是庙宇。","ex":"The temple complex was aligned precisely with the rising sun at midsummer.","exCn":"这座神庙建筑群与仲夏日出方向精确对齐。","col":["ancient temple","Buddhist temple","shrine"]},{"id":1641,"topic":"history","w":"abandon","ipa":"/əˈbændən/","pos":"v.","cn":"遗弃；放弃","pun":"饿绊蹲","story":"饿得走不动，绊了一跤就蹲着不走了——只好放弃、遗弃行李。","ex":"The city was abandoned around 900 AD, possibly because of prolonged drought.","exCn":"这座城市在公元900年左右被遗弃，可能是因为长期干旱。","col":["abandon a city","abandoned site","abandonment"]},{"id":1642,"topic":"history","w":"hieroglyph","ipa":"/ˈhaɪərəɡlɪf/","pos":"n.","cn":"象形文字","pun":"海鸥骨立夫","story":"墙上刻着海鸥、骨头、立着的夫——每个图画都是一个字，就是象形文字。","ex":"Egyptian hieroglyphs remained unreadable until the Rosetta Stone was deciphered.","exCn":"在罗塞塔石碑被破译之前，埃及象形文字一直无人能读。","col":["Egyptian hieroglyphs","hieroglyphic","pictogram"]},{"id":1643,"topic":"history","w":"decipher","ipa":"/dɪˈsaɪfə(r)/","pos":"v.","cn":"破译；辨认","pun":"弟赛佛","story":"de-（解开）+cipher（密码）：弟弟赛过佛，解开了古老密码——decipher 是破译。","ex":"Scholars took more than twenty years to decipher the inscriptions on the stone.","exCn":"学者花了二十多年才破译石碑上的铭文。","col":["decipher a script","decipher the meaning","decode"]},{"id":1644,"topic":"history","w":"chronology","ipa":"/krəˈnɒlədʒi/","pos":"n.","cn":"年表；年代学","pun":"克拉挪了鸡","story":"chron（时间）+logy（学）：克拉按时间顺序把鸡一只只挪好——年表。","ex":"Tree-ring data helped researchers establish a reliable chronology for the settlement.","exCn":"树轮数据帮助研究人员为该定居点建立了可靠的年表。","col":["establish a chronology","chronological order","chronologically"]},{"id":1645,"topic":"history","w":"timeline","ipa":"/ˈtaɪmlaɪn/","pos":"n.","cn":"时间线；年表","pun":"太慢","story":"time（时间）+line（线）：历史老师画线太慢，一件件事排上去——时间线。","ex":"New evidence has forced historians to revise the timeline of human migration into the Americas.","exCn":"新证据迫使历史学家修改人类迁入美洲的时间线。","col":["historical timeline","on the timeline","sequence of events"]},{"id":1646,"topic":"history","w":"millennium","ipa":"/mɪˈleniəm/","pos":"n.","cn":"一千年；千禧年","pun":"米粒你呀","story":"mill（千）：数一千粒米，米粒你呀数了一千年——millennium 是千年。","ex":"The city has been continuously inhabited for more than three millennia.","exCn":"这座城市已连续有人居住三千多年。","col":["the new millennium","over the millennia","millennial"]},{"id":1647,"topic":"history","w":"epoch","ipa":"/ˈiːpɒk/","pos":"n.","cn":"时代；纪元","pun":"一泡壳","story":"地质学家挖出一层壳，说：这一泡壳代表一个时代——epoch。","ex":"The arrival of agriculture marked a new epoch in human history.","exCn":"农业的出现标志着人类历史的新纪元。","col":["a new epoch","geological epoch","epoch-making"]},{"id":1648,"topic":"history","w":"antiquity","ipa":"/ænˈtɪkwəti/","pos":"n.","cn":"古代；古物","pun":"安踢阔踢","story":"anti（古）：安踢阔踢，一脚踢出一堆古代文物——antiquity 是古代或古物。","ex":"Philosophers of antiquity debated questions that remain relevant today.","exCn":"古代哲学家争论的问题至今仍有意义。","col":["classical antiquity","in antiquity","antique"]},{"id":1649,"topic":"history","w":"slavery","ipa":"/ˈsleɪvəri/","pos":"n.","cn":"奴隶制","pun":"死累味儿","story":"奴隶干活干到死累，一身汗味儿——slavery 就是奴隶制。","ex":"The transatlantic trade in enslaved people underpinned the economies of several colonial powers.","exCn":"跨大西洋奴隶贸易支撑了几个殖民强国的经济。","col":["abolish slavery","slavery trade","slave"]},{"id":1650,"topic":"history","w":"independence","ipa":"/ˌɪndɪˈpendəns/","pos":"n.","cn":"独立","pun":"硬地盆等死","story":"in-（不）+depend（依赖）：宁可在硬地上端着盆等死也不靠别人——独立。","ex":"India gained independence from Britain in 1947 after decades of political struggle.","exCn":"经过数十年政治斗争，印度于1947年脱离英国获得独立。","col":["gain independence","declare independence","independent"]},{"id":1651,"topic":"history","w":"nationalism","ipa":"/ˈnæʃnəlɪzəm/","pos":"n.","cn":"民族主义","pun":"那神呐里怎","story":"nation（民族）+ism（主义）：那神呐，里面怎么全是「我民族最强」——民族主义。","ex":"Rising nationalism in the nineteenth century led to the unification of Italy and Germany.","exCn":"十九世纪民族主义的兴起导致了意大利和德国的统一。","col":["rising nationalism","extreme nationalism","nationalist"]},{"id":1652,"topic":"history","w":"imperial","ipa":"/ɪmˈpɪəriəl/","pos":"adj.","cn":"帝国的；皇帝的","pun":"因皮儿肉","story":"皇帝因为一块皮儿肉就发兵抢地——imperial 就是帝国的、皇帝的。","ex":"Imperial expansion was often justified by claims of bringing civilisation to conquered peoples.","exCn":"帝国扩张常以给被征服民族带去文明为借口。","col":["imperial power","imperial rule","imperialism"]},{"id":1653,"topic":"history","w":"exploitation","ipa":"/ˌeksplɔɪˈteɪʃn/","pos":"n.","cn":"剥削；开发","pun":"爱克斯不来推神","story":"ex-（向外）：爱克斯不来干活，把推磨的活全压给别人——剥削。","ex":"Colonial rule relied on the exploitation of local labour and natural resources.","exCn":"殖民统治依赖对当地劳动力和自然资源的剥削。","col":["economic exploitation","exploit","exploitative"]},{"id":1654,"topic":"history","w":"plunder","ipa":"/ˈplʌndə(r)/","pos":"v./n.","cn":"掠夺；抢劫","pun":"扑烂的","story":"海盗扑进城里把东西抢烂了——plunder 就是掠夺。","ex":"Invading armies plundered temples and carried the gold back to their capital.","exCn":"入侵军队洗劫神庙，把黄金运回都城。","col":["plunder a city","plundered treasures","pillage"]},{"id":1655,"topic":"history","w":"annex","ipa":"/əˈneks/","pos":"v.","cn":"吞并；兼并","pun":"饿捏可食","story":"大国饿了，捏起邻国的一块地说可以吃——annex 就是吞并。","ex":"The empire annexed the neighbouring province after a brief military campaign.","exCn":"经过短暂军事行动，帝国吞并了邻近省份。","col":["annex a territory","annexation","annexed"]},{"id":1656,"topic":"history","w":"oppress","ipa":"/əˈpres/","pos":"v.","cn":"压迫","pun":"饿扑来死","story":"op-（对着）+press（压）：百姓饿得扑倒，还被压到死——oppress 是压迫。","ex":"Colonial governments oppressed local populations through forced labour and heavy taxation.","exCn":"殖民政府通过强迫劳动和重税压迫当地民众。","col":["oppress the people","oppression","oppressive"]},{"id":1657,"topic":"history","w":"uprising","ipa":"/ˈʌpraɪzɪŋ/","pos":"n.","cn":"起义；暴动","pun":"啊扑赖赢","story":"up（起）+rising（升）：百姓一起站起来扑向官府，赖着要赢——起义。","ex":"The uprising was crushed within weeks, but it inspired later independence movements.","exCn":"起义几周内就被镇压，却激励了后来的独立运动。","col":["popular uprising","armed uprising","revolt"]},{"id":1658,"topic":"history","w":"liberate","ipa":"/ˈlɪbəreɪt/","pos":"v.","cn":"解放","pun":"李伯锐特","story":"liber（自由）：李伯锐气特足，砸开锁链放人——liberate 是解放。","ex":"Allied forces liberated the city in 1944 after four years of occupation.","exCn":"盟军于1944年解放了被占领四年的城市。","col":["liberate a country","liberation","liberator"]},{"id":1659,"topic":"history","w":"exile","ipa":"/ˈeksaɪl/","pos":"n./v.","cn":"流放；流亡","pun":"爱克赛哦","story":"ex-（向外）：爱克被赛出国门，哦，再也回不来——流放。","ex":"The king was sent into exile after his army was defeated.","exCn":"军队战败后，国王被流放。","col":["live in exile","send into exile","exiled"]},{"id":1660,"topic":"history","w":"displacement","ipa":"/dɪsˈpleɪsmənt/","pos":"n.","cn":"流离失所；移位","pun":"弟死不来死门","story":"dis-（离开）+place（地方）：弟弟死活回不来家门——被迫离开家园就是流离失所。","ex":"War caused the displacement of nearly a quarter of the population.","exCn":"战争导致近四分之一人口流离失所。","col":["forced displacement","mass displacement","displace"]},{"id":1661,"topic":"history","w":"diaspora","ipa":"/daɪˈæspərə/","pos":"n.","cn":"侨民；散居族群","pun":"带啊死泼了","story":"dia-（穿过）+spor（撒种）：一族人像种子被泼向世界各地——散居族群。","ex":"The Greek diaspora spread across the Mediterranean, founding colonies from Spain to the Black Sea.","exCn":"希腊侨民散布地中海各地，从西班牙到黑海建立殖民地。","col":["the Jewish diaspora","diaspora community","scattered"]},{"id":1662,"topic":"history","w":"settler","ipa":"/ˈsetlə(r)/","pos":"n.","cn":"定居者；移民","pun":"塞头了","story":"settle（定居）+er：定居者把行李塞到头了，从此在新大陆安家。","ex":"European settlers cleared forests and established farms along the coast.","exCn":"欧洲定居者砍伐森林，沿海岸建立农场。","col":["early settlers","settler colony","settle"]},{"id":1663,"topic":"history","w":"outpost","ipa":"/ˈaʊtpəʊst/","pos":"n.","cn":"前哨；边远居民点","pun":"奥特泡死","story":"out（外）+post（岗位）：奥特曼在最外面的岗哨泡到死——前哨。","ex":"The fort began as a military outpost and later grew into a major trading town.","exCn":"这座堡垒最初是军事前哨，后来发展为重要的贸易城镇。","col":["military outpost","remote outpost","frontier outpost"]},{"id":1664,"topic":"history","w":"pioneer","ipa":"/ˌpaɪəˈnɪə(r)/","pos":"n./v.","cn":"先驱；开拓","pun":"派我逆儿","story":"派我逆着人流第一个进荒野开路——pioneer 就是先驱、开拓者。","ex":"Pioneers travelled west in covered wagons, often facing hunger and disease.","exCn":"拓荒者乘篷车西行，常常面临饥饿和疾病。","col":["early pioneer","pioneer a technique","pioneering"]},{"id":1665,"topic":"history","w":"rural","ipa":"/ˈrʊərəl/","pos":"adj.","cn":"乡村的","pun":"入了","story":"一出城就入了田野和小村——rural 就是乡村的。","ex":"Before 1800, the vast majority of Europeans lived in rural communities.","exCn":"1800年之前，绝大多数欧洲人生活在乡村社区。","col":["rural areas","rural population","rural-urban migration"]},{"id":1666,"topic":"history","w":"dwelling","ipa":"/ˈdwelɪŋ/","pos":"n.","cn":"住所；住宅","pun":"对我灵","story":"这间小屋对我灵魂来说就是家——dwelling 是住所。","ex":"Archaeologists uncovered stone dwellings dating back more than five thousand years.","exCn":"考古学家发现了五千多年前的石头住所。","col":["stone dwelling","cave dwelling","dwell"]},{"id":1667,"topic":"history","w":"metropolis","ipa":"/məˈtrɒpəlɪs/","pos":"n.","cn":"大都市","pun":"摸错破里死","story":"metro（母）+polis（城）：大都市太大，摸错一条破巷子就迷路到死。","ex":"By the first century AD, Rome had become a metropolis of over a million people.","exCn":"到公元一世纪，罗马已成为百万人口的大都市。","col":["bustling metropolis","modern metropolis","metropolitan"]},{"id":1668,"topic":"history","w":"suburb","ipa":"/ˈsʌbɜːb/","pos":"n.","cn":"郊区","pun":"傻伯","story":"sub-（下面）+urb（城）：傻伯住在城下面的边缘地带——郊区。","ex":"Railways allowed the middle classes to move to suburbs outside the crowded city.","exCn":"铁路使中产阶级得以搬到拥挤城市之外的郊区。","col":["outer suburb","suburban","suburbia"]},{"id":1669,"topic":"history","w":"memorial","ipa":"/məˈmɔːriəl/","pos":"n./adj.","cn":"纪念碑；纪念的","pun":"没摸里儿","story":"memor（记忆）：纪念碑上没摸过的字里儿，都是被记住的名字——memorial。","ex":"The war memorial lists the names of every villager killed in the conflict.","exCn":"战争纪念碑列出了在冲突中牺牲的每一位村民的名字。","col":["war memorial","memorial service","in memory of"]},{"id":1670,"topic":"history","w":"emerge","ipa":"/ɪˈmɜːdʒ/","pos":"v.","cn":"出现；崛起","pun":"一摸只","story":"e-（向外）+merge（沉）：往水里一摸，只见一个新岛冒出来——emerge 是出现。","ex":"Powerful city-states emerged in northern Italy during the late Middle Ages.","exCn":"中世纪晚期，强大的城邦在意大利北部崛起。","col":["emerge from","emerging","emergence"]},{"id":1671,"topic":"history","w":"originate","ipa":"/əˈrɪdʒɪneɪt/","pos":"v.","cn":"起源；发源","pun":"哦里揪内特","story":"origin（起源）：哦，从里面揪出内特的老家——originate 是起源于。","ex":"Paper-making originated in China and spread westward along trade routes.","exCn":"造纸术起源于中国，沿贸易路线向西传播。","col":["originate in","originate from","origin"]},{"id":1672,"topic":"history","w":"evolve","ipa":"/iˈvɒlv/","pos":"v.","cn":"演变；进化","pun":"一我扶","story":"e-（向外）+volve（滚）：一路我扶着它慢慢滚出新样子——evolve 是演变。","ex":"Early villages evolved into complex urban centres over several centuries.","exCn":"早期村庄经过几个世纪演变为复杂的城市中心。","col":["evolve into","evolve from","evolution"]},{"id":1673,"topic":"history","w":"transform","ipa":"/trænsˈfɔːm/","pos":"v.","cn":"改变；转变","pun":"穿死风","story":"trans-（转换）+form（形状）：一阵风穿过，死气沉沉的城变了样——transform。","ex":"The discovery of gold transformed the sleepy town into a booming city within a decade.","exCn":"黄金的发现在十年内把这个沉寂小镇变成了繁荣城市。","col":["transform into","transformation","transformative"]},{"id":1674,"topic":"history","w":"unearth","ipa":"/ʌnˈɜːθ/","pos":"v.","cn":"发掘；揭露","pun":"俺饿死","story":"un-（除去）+earth（土）：俺饿死也要把土刨开，挖出宝贝——unearth 是发掘。","ex":"Workers building the railway unearthed a Roman mosaic in remarkable condition.","exCn":"修铁路的工人挖出了一幅保存极好的罗马马赛克。","col":["unearth a tomb","unearth evidence","dig up"]},{"id":1675,"topic":"history","w":"reconstruct","ipa":"/ˌriːkənˈstrʌkt/","pos":"v.","cn":"重建；重现","pun":"里坑死踹","story":"re-（再）+construct（建）：把里头的坑踹平，重新建起来——reconstruct。","ex":"Using pottery fragments, researchers reconstructed the daily diet of the settlement.","exCn":"研究人员利用陶片重现了该定居点的日常饮食。","col":["reconstruct a building","reconstruct events","reconstruction"]},{"id":1676,"topic":"history","w":"replica","ipa":"/ˈreplɪkə/","pos":"n.","cn":"复制品","pun":"来扑里卡","story":"re-（再）+plic（折叠）：来，扑进模子里再卡一次，就是复制品。","ex":"Visitors view a replica of the cave paintings to protect the fragile originals.","exCn":"游客观看洞穴壁画的复制品，以保护脆弱的原作。","col":["exact replica","a replica of","replicate"]},{"id":1677,"topic":"history","w":"surrender","ipa":"/səˈrendə(r)/","pos":"v./n.","cn":"投降；放弃","pun":"色软的","story":"守城的兵脸色软的，举白旗——surrender 就是投降。","ex":"The garrison surrendered when supplies ran out after months of siege.","exCn":"围城数月补给耗尽后，守军投降。","col":["surrender to","unconditional surrender","give up"]},{"id":1678,"topic":"acad_v","w":"alleviate","ipa":"/əˈliːvieɪt/","pos":"v.","cn":"缓解；减轻","pun":"饿立喂 eat","story":"「饿」了「立」刻「喂」你「eat」——缓解饥饿。","ex":"Building more public housing could alleviate the housing shortage.","exCn":"建更多公共住房可以缓解住房短缺。","col":["alleviate poverty / pressure / pain","alleviation (n.)"]},{"id":1679,"topic":"acad_adj","w":"significant","ipa":"/sɪɡˈnɪfɪkənt/","pos":"adj.","cn":"重要的；显著的","pun":"洗个泥飞坑","story":"sign 是「标志」，有标志性的就是显著的。「洗个泥」也能「飞」出「坑」，很显著！","ex":"There has been a significant increase in the number of international students.","exCn":"国际学生数量显著增加。","col":["a significant increase / impact","significantly (adv.)","significance (n.)"]},{"id":1680,"topic":"acad_adj","w":"consequently","ipa":"/ˈkɒnsɪkwəntli/","pos":"adv.","cn":"因此","pun":"看死快特累","story":"sequence 是「顺序」，跟着前面的顺序来，「因此」。熬夜「看」剧，「死快特累」，因此上课睡着。","ex":"Fuel prices rose sharply; consequently, more people started cycling to work.","exCn":"油价大涨，因此更多人骑车上班。","col":["consequence (n.) 后果","as a consequence","consequent (adj.)"]},{"id":1681,"topic":"acad_adj","w":"inevitable","ipa":"/ɪnˈevɪtəbl/","pos":"adj.","cn":"不可避免的","pun":"一哎我躲不","story":"「一」看到它，「哎」，「我躲不」掉——不可避免。","ex":"Some job losses are inevitable as industries adopt new technology.","exCn":"随着行业采用新技术，部分失业不可避免。","col":["inevitably (adv.)","an inevitable consequence","it is inevitable that..."]},{"id":1682,"topic":"acad_adj","w":"controversial","ipa":"/ˌkɒntrəˈvɜːʃl/","pos":"adj.","cn":"有争议的","pun":"看抓我手","story":"「看」，吵起来了，还「抓我手」——这话题真有争议。","ex":"Nuclear power remains a highly controversial issue.","exCn":"核能仍是一个极具争议的问题。","col":["a controversial issue / topic","controversy (n.)"]},{"id":1683,"topic":"acad_adj","w":"detrimental","ipa":"/ˌdetrɪˈmentl/","pos":"adj.","cn":"有害的","pun":"得追门头","story":"「得」（děi）「追」着人往「门头」上撞——有害。","ex":"Excessive screen time can be detrimental to children's eyesight.","exCn":"屏幕时间过长对儿童视力有害。","col":["detrimental to sth","a detrimental effect / impact"]},{"id":1684,"topic":"acad_adj","w":"prevalent","ipa":"/ˈprevələnt/","pos":"adj.","cn":"普遍的；盛行的","pun":"普瑞我冷特","story":"「普」遍「瑞」雪，「我冷特」（我特别冷）——到处都是，普遍的。","ex":"Obesity is more prevalent in countries with a high intake of fast food.","exCn":"肥胖在快餐摄入量高的国家更普遍。","col":["prevalent among / in","increasingly prevalent","prevalence (n.)"]},{"id":1685,"topic":"acad_n","w":"phenomenon","ipa":"/fəˈnɒmɪnən/","pos":"n.","cn":"现象","pun":"发 no 米能","story":"「发」现家里「no 米」了，还「能」怎么办——先观察这个现象。","ex":"Social media addiction is a relatively new phenomenon.","exCn":"社交媒体成瘾是一个相对较新的现象。","col":["a common / global phenomenon","复数 phenomena"]},{"id":1686,"topic":"acad_n","w":"perspective","ipa":"/pəˈspektɪv/","pos":"n.","cn":"观点；视角","pun":"怕死派克提夫","story":"per（每一）+ spect（看）：每个人看的角度。「怕死」的「派克」和「提夫」看法完全不同。","ex":"Travelling abroad gives students a broader perspective on the world.","exCn":"出国旅行让学生对世界有更广阔的视角。","col":["from a different perspective","put sth into perspective","a broader perspective"]},{"id":1687,"topic":"acad_n","w":"hypothesis","ipa":"/haɪˈpɒθəsɪs/","pos":"n.","cn":"假设；假说","pun":"嗨怕什死死","story":"「嗨，怕什」（怕啥），「死死」地先假设一个，再去验证——假说。","ex":"The researchers tested the hypothesis that sleep improves memory.","exCn":"研究人员检验了「睡眠改善记忆」这一假设。","col":["test a hypothesis","复数 hypotheses","hypothetical (adj.)"]}];
